// ── Sales Nav Board ──────────────────────────────────────────────────────────
let snCurrentEmail = '';
async function loadOperatorEmail() {
  try { const r = await fetch('/api/operator-identity'); const d = await r.json(); snCurrentEmail = (d && d.email) || ''; }
  catch { snCurrentEmail = ''; }
}

// Viewer's LOGIN identity + admin flag (from /api/me, driven by ADMIN_EMAILS).
// Admin sees every cloud campaign + the Conductor filter; everyone else sees
// only their own. Distinct from snCurrentEmail (the per-machine operator).
let _viewerEmail = '';
let _viewerIsAdmin = false;
async function loadViewerIdentity() {
  try { const d = await (await fetch('/api/me')).json(); _viewerEmail = (d && d.email) || ''; _viewerIsAdmin = !!(d && d.admin); }
  catch { _viewerEmail = ''; _viewerIsAdmin = false; }
}

let _snPollTimer = null;
let _snPollInFlight = false; // guard so slow polls don't stack (each poll every 2.5s)
let _snPollStartedAt = 0;    // when the in-flight poll began — see SN_POLL_STUCK_MS
// A poll that never settles used to freeze the board PERMANENTLY. The guard is
// set before the fetch and cleared in `finally`, so a fetch that neither
// resolves nor rejects leaves it true and every later tick returns early —
// no polling, no re-render, until the app is restarted. Observed live on
// 2026-08-13: a direct openSalesNavBoard() call issued no request at all.
// Two independent defences, because one hung request must never cost the
// board its entire session: the fetch has a timeout so it always settles, and
// an in-flight mark older than this is treated as dead and overridden.
const SN_POLL_TIMEOUT_MS = 30000;
const SN_POLL_STUCK_MS = 60000;
let _snEverLoaded = false;   // have we rendered the board successfully at least once?
let _snConsecFail = 0;       // consecutive failed polls before the first success
// Navigate to the Sales Nav board (its own top-level route #/salesnav). The
// router (applyRoute) calls openSalesNavBoard() on entry to load + start polling.
function goSalesNav() {
  window.location.hash = '#/salesnav';
}
window.goSalesNav = goSalesNav;

// Route-entry initializer for the board. View visibility is handled by the
// #/salesnav route (body.route-salesnav in the router + CSS), NOT by toggling
// section display here.
// Last good board, persisted. The campaigns dashboard renders from local files
// and paints instantly; this board has no local state at all — every strip is
// derived from the engine's /api/jobs, which currently ships ~15MB. So opening
// the tab meant staring at "Loading scrapes…" for the length of a cold round
// trip to the VM, every single time.
//
// The cache is DISPLAY ONLY: it paints immediately, then the normal 2.5s poll
// overwrites it with live data. Stored whole (never truncated) because the
// strips' action handlers read search URLs straight off the rendered data — a
// shortened URL here would mean a Re-run firing at the wrong search.
const SN_CACHE_KEY = 'snBoardCache1';

function _snSaveCache(campaigns) {
  // Shrink on quota failure rather than giving up: a handful of scrapes carry
  // 80KB search URLs, so the full board can exceed the localStorage budget on
  // its own. Half the strips cached still beats a cold board.
  for (const cap of [80, 40, 15, 5]) {
    try {
      localStorage.setItem(SN_CACHE_KEY, JSON.stringify({ at: Date.now(), campaigns: campaigns.slice(0, cap) }));
      return;
    } catch (_) { /* quota — try a smaller slice */ }
  }
  try { localStorage.removeItem(SN_CACHE_KEY); } catch (_) { /* */ }
}

function _snLoadCache() {
  try {
    const raw = localStorage.getItem(SN_CACHE_KEY);
    if (!raw) return null;
    const d = JSON.parse(raw);
    return (d && Array.isArray(d.campaigns) && d.campaigns.length) ? d.campaigns : null;
  } catch (_) { return null; }
}

async function openSalesNavBoard() {
  // Paint the cached board BEFORE any await, so the tab is never empty. Guarded
  // so a corrupt cache can't stop the live load that follows.
  const cached = _snLoadCache();
  if (cached && !_snEverLoaded) {
    try {
      renderSalesNavBoard(cached);
      // Don't let cached statuses seed the handover detector — comparing a live
      // poll against a cache from an hour ago fires phantom "X stopped" toasts.
      _snPrevStatus = new Map();
    } catch (_) { /* fall through to the normal cold load */ }
  }
  // Start the poll loop BEFORE the first fetch rather than after it.
  //
  // The engine's /api/jobs takes 5–10s warm, and was measured at 83s while the
  // app was still booting (a trivial 404 on another route took 10.4s in the same
  // window, so the app's own server — not the network — was the bottleneck).
  // Awaiting it here meant the board had NO poll timer for that entire window:
  // the cached strips sat frozen, nothing re-rendered, and expanding a scrape
  // produced an empty shell. Installing the timer first means the board starts
  // updating the moment data is available. _snPollInFlight already stops the
  // ticks stacking up behind a slow fetch.
  clearInterval(_snPollTimer);
  _snPollTimer = setInterval(pollSalesNavBoard, 2500);
  pollSalesNavBoard();
  // The operator email only decides "Your scrapes" vs "Other people's". Worth a
  // re-render when it lands, not worth blocking the whole board on — and the
  // board patches in place now, so the correction costs one cheap diff.
  loadOperatorEmail().then(() => { try { pollSalesNavBoard(); } catch (_) { /* */ } });
}
window.openSalesNavBoard = openSalesNavBoard;

async function pollSalesNavBoard() {
  // Self-cancel once we leave the board route (the poller outlives the view otherwise).
  if (!document.body.classList.contains('route-salesnav')) { clearInterval(_snPollTimer); _snPollTimer = null; return; }
  const host = document.getElementById('sn-board');
  if (!host || document.hidden) return;
  // Don't stack behind a slow engine — but don't trust the flag forever either.
  if (_snPollInFlight && Date.now() - _snPollStartedAt < SN_POLL_STUCK_MS) return;
  _snPollInFlight = true;
  _snPollStartedAt = Date.now();
  // Before the FIRST successful load, show an animated "Loading scrapes…" while the
  // /api/jobs fetch runs (it can take several seconds) so the board reads as loading,
  // not empty/stalled. Only when the board isn't already showing strips.
  if (!_snEverLoaded && !host.querySelector('.sn-strip')) {
    host.innerHTML = '<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Loading scrapes…</div>';
  }
  try {
    // Timeout, so this always settles and the `finally` below always runs.
    const r = await fetch('/api/scrape/campaigns', { signal: AbortSignal.timeout(SN_POLL_TIMEOUT_MS) });
    const d = await r.json();
    if (d && d.error) throw new Error(d.error);
    _snEverLoaded = true; _snConsecFail = 0;
    renderSalesNavBoard(d.campaigns || []);
    _snSaveCache(d.campaigns || []);
  } catch (err) {
    _snConsecFail++;
    // Never blank a board we've already rendered: keep the last render and let the
    // next 2.5s poll recover silently (the engine is just briefly slow/busy). Only
    // show a message BEFORE the first successful load — a friendly "connecting…"
    // first, escalating to the real error after several failures so a genuine
    // outage still surfaces instead of spinning forever.
    if (!_snEverLoaded) {
      host.innerHTML = _snConsecFail >= 4
        ? `<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Still loading — the engine is slow to respond (${escHtml((err && err.message) || 'timeout')}). Retrying…</div>`
        : `<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Loading scrapes…</div>`;
    }
  } finally {
    _snPollInFlight = false;
  }
}

function _snStatusDot(status) {
  const cls = status === 'running' ? 'run' : status === 'queued' ? 'q' : status === 'error' ? 'red' : 'mon';
  return `<span class="dot ${cls}"></span>`;
}

let _snPrevStatus = new Map(); // cid -> status
function _snStampFinished(campaigns) {
  const nowStatus = new Map(campaigns.map((c) => [c.id, c.status]));
  // Stamp the finish time ONLY when we witness a live scrape turn done/error this
  // session (so pre-existing done scrapes stay time-less instead of "just now").
  let stampedAny = false;
  for (const c of campaigns) {
    const prev = _snPrevStatus.get(c.id);
    const isDoneNow = c.status === 'done' || c.status === 'error';
    const wasLive = prev === 'running' || prev === 'queued';
    if (isDoneNow && wasLive && !_snDoneSeen[c.id]) { _snDoneSeen[c.id] = Date.now(); stampedAny = true; }
  }
  if (stampedAny) _snSaveDoneSeen();
  // Scrape ROLLOVER on the Sales Nav board: one scrape finishing as the next one
  // starts. This is a different event from the campaign's local/VM handover
  // (which lives on the card as .vj-live.is-handover), and it shares only the
  // word. It was removed by mistake while moving that other banner and is
  // restored here: without it the board says nothing when the queue advances.
  let stopped = null, started = null;
  for (const [cid, prev] of _snPrevStatus) {
    const cur = nowStatus.get(cid);
    if (prev === 'running' && (cur === 'done' || cur === 'error' || cur === undefined)) stopped = cid;
  }
  for (const c of campaigns) {
    if (_snPrevStatus.get(c.id) === 'queued' && c.status === 'running') started = c.id;
  }
  _snPrevStatus = nowStatus;
  if (stopped || started) _snShowScrapeRollover(campaigns, stopped, started);
}
function _snName(campaigns, cid) { const c = campaigns.find((x) => x.id === cid); return c ? (c.name || 'a scrape') : 'a scrape'; }
function _snShowScrapeRollover(campaigns, stopped, started) {
  const ho = document.getElementById('sn-handover'), txt = document.getElementById('sn-handover-txt');
  if (!ho || !txt) return;
  if (stopped && started) {
    ho.className = 'sn-handover show launching';
    txt.innerHTML = `<b>${escHtml(_snName(campaigns, stopped))}</b> finished, now starting <b>${escHtml(_snName(campaigns, started))}</b>.`;
  } else if (stopped) {
    ho.className = 'sn-handover show stopping';
    txt.innerHTML = `<b>Stopped</b> ${escHtml(_snName(campaigns, stopped))}.`;
  } else {
    ho.className = 'sn-handover show launching';
    txt.innerHTML = `<b>Starting</b> ${escHtml(_snName(campaigns, started))}…`;
  }
  // A scrape rollover is a moment, not a state: it has already happened by the
  // time it is announced, so a timed dismissal is right here. That is the
  // opposite of the campaign handover on the card, which describes something
  // still in progress and so must hold until it genuinely finishes.
  clearTimeout(ho._t); ho._t = setTimeout(() => { ho.className = 'sn-handover'; }, 5000);
}

// cid → { profileIds, tabName, owner, mine } from the last render, so the
// delegated toggle/stop handlers can drive the right engine profiles and gate
// by ownership (strips are engine-derived; there's no local record to look up).
const _snStrips = new Map();

let _snLastCampaigns = null; // last rendered board data — for optimistic re-renders
function renderSalesNavBoard(campaigns) {
  campaigns = (campaigns || []).map(_snEnrich).filter(c => c.mine); // Only this operator’s scrapes, including counts and actions.
  _snLastCampaigns = campaigns;
  _snStampFinished(campaigns);
  _snStrips.clear();
  for (const c of campaigns) _snStrips.set(c.id, { profileIds: c.profileIds || [], tabName: c.tabName || '', owner: c.owner || '', mine: !!c.mine });
  const host = document.getElementById('sn-board');
  const running = campaigns.filter((c) => c.status === 'running');
  const queued = campaigns.filter((c) => c.status === 'queued');
  document.getElementById('sn-qmeta').textContent =
    `${running.length} running · ${queued.length} queued`;
  const rail = (label, list) => list.length
    ? `<div class="sn-railhead">${label}</div>` + list.map(renderStrip).join('') : '';
  // Running → queued → done rails for one subset of scrapes. showClear gates the
  // "Clear done" button so it appears once (under Your scrapes / the flat board),
  // not under someone else's done rail where clearing everyone's reads as wrong.
  const railsFor = (list, { showClear = true } = {}) => {
    const r = list.filter((c) => c.status === 'running');
    const q = list.filter((c) => c.status === 'queued');
    const d = list
      .filter((c) => c.status === 'done' || c.status === 'error')
      .filter((c) => !_snDismissed.has(c.id));
    let h = rail('▶ Now running', r) + rail('• Up next in the queue', q);
    if (d.length) {
      h += `<div class="sn-railhead">✓ Done <span class="sn-railcount">${d.length}</span>`
        + (showClear ? `<button type="button" class="sn-clear-done">Clear done</button>` : '')
        + `</div>` + d.map(renderStrip).join('');
    }
    return h;
  };
  let html = railsFor(campaigns, { showClear: true });
  // Empty state when NO strips are visible — covers both "no scrapes at all"
  // and "all scrapes dismissed / in a non-shown status" (previously blank).
  if (!html) html = _scrapeEmptyState();
  _snPatchBoard(host, html);
  // Fill each expanded strip's cloned card. Only expanded strips have one.
  const _byId = new Map(campaigns.map((c) => [c.id, c]));
  host.querySelectorAll('.sn-strip > .vj-card').forEach((root) => {
    const strip = root.closest('.sn-strip');
    const c = strip && _byId.get(strip.dataset.cid);
    if (c) { try { _snFillStripCard(root, c); } catch (_) { /* a broken card must not blank the board */ } }
  });
  // Refresh log CONTENT in place. The boxes themselves survive the patch above,
  // so each of these is one atomic innerHTML swap on a node that already holds
  // the previous lines — the reader never sees an empty frame.
  _snRefreshLogs(host);
}

// Update every visible log box without destroying it. Only boxes that are
// actually on screen are fetched; a collapsed strip costs nothing.
function _snRefreshLogs(host) {
  const boxes = [
    ...host.querySelectorAll('.sn-pane.on .sn-logbox[data-logsfor]'),
    ...host.querySelectorAll('.sn-strip > .vj-card [data-f="active-log"], .sn-strip > .vj-card .vj-log'),
  ];
  for (const box of boxes) {
    if (!box.dataset.logsfor) continue;
    if (box.closest('.sn-pane') && !_snLogsTab.has(box.dataset.logsfor)) continue;
    try { _snLoadLogs(box); } catch (_) { /* a log failure must not break the board */ }
  }
}

// Patch the board in place instead of replacing its innerHTML.
//
// The board used to do `host.innerHTML = html` on every 2.5s poll. That threw
// away and rebuilt all ~290 strips — including 279 finished ones that had not
// changed in hours — which is what made the board slow to open. Worse, it
// destroyed the live log element inside any expanded strip; the replacement
// started empty, `.vj-log:empty::after` printed "No events yet", and the log
// only came back when an async refetch landed ~350ms later. Measured off a
// screen recording: a blank frame and a refill frame 0.30–0.42s apart, once
// per poll. That is the strobe.
//
// Now: strips are matched by cid, an unchanged data-sig means the node is left
// completely untouched, and a changed strip keeps its live log node by
// transplanting it into the new markup before the swap.
function _snPatchBoard(host, html) {
  const next = document.createElement('div');
  next.innerHTML = html;

  const prevByCid = new Map();
  for (const el of host.children) {
    if (el.dataset && el.dataset.cid) prevByCid.set(el.dataset.cid, el);
  }

  const wanted = [];
  for (const el of [...next.children]) {
    const cid = el.dataset && el.dataset.cid;
    const prev = cid ? prevByCid.get(cid) : null;
    if (prev) {
      prevByCid.delete(cid);
      if (prev.dataset.sig === el.dataset.sig) { wanted.push(prev); continue; } // nothing changed
      _snCarryLiveNodes(prev, el);
    }
    wanted.push(el);
  }

  // Drop anything no longer on the board, then put the survivors in order.
  // insertBefore MOVES a node that is already a child, so a reorder costs no
  // re-render and an untouched strip is never even read.
  const keep = new Set(wanted);
  for (const el of [...host.children]) if (!keep.has(el)) el.remove();
  let ref = host.firstChild;
  for (const node of wanted) {
    if (node === ref) { ref = ref.nextSibling; continue; }
    host.insertBefore(node, ref);
  }
}

// Move the live log element(s) from the outgoing strip into its replacement, so
// a strip whose numbers changed doesn't lose its log. Without this every
// running strip still blanks once per poll — which is the case in the recording.
function _snCarryLiveNodes(prev, next) {
  const SEL = '.sn-logbox, .vj-log, [data-f="active-log"]';
  const olds = [...prev.querySelectorAll(SEL)];
  if (!olds.length) return;
  // Match on class alone, in document order. Keying on data-logsfor as well
  // looked safer and was in fact fatal: the OUTGOING node has been stamped with
  // data-logsfor/data-snWired by _snFillStripCard, while the INCOMING one is a
  // fresh vjCardSkeleton clone that is stamped only later — so the keys could
  // never match ("vj-log|eng_x|" vs "vj-log||"), no node was ever carried, and
  // the log blanked on every strip re-render until a refetch landed. Measured:
  // ~17% of samples blank, in runs of ~4s starting at each swap.
  for (const nb of [...next.querySelectorAll(SEL)]) {
    const i = olds.findIndex((o) => o.className === nb.className);
    if (i === -1) continue;
    const ob = olds.splice(i, 1)[0];
    const top = ob.scrollTop;
    nb.replaceWith(ob);
    ob.scrollTop = top; // a DOM move resets scroll; put the reader back
  }
}

// Every strip is collapsed to a slim summary BY DEFAULT (queued always; running
// & done otherwise) so the board reads as a scannable list, not a wall of job
// rows. This set holds the cids the operator explicitly expanded; it survives
// re-renders (the board rebuilds its innerHTML on every 2.5s poll).
const _snExpanded = new Set();
// Active rows start expanded, but an operator may still fold them. This is
// separate from _snExpanded because inactive rows start collapsed.
const _snCollapsedActive = new Set();
// cids whose strip should show the LOGS tab active (vs the default Jobs tab).
// Persisted like _snExpanded so the 2.5s board re-render doesn't snap the pane
// back to Jobs — set when the operator opens a running scrape's log or clicks
// the Logs tab, cleared when they click back to Jobs.
const _snLogsTab = new Set();

// Done strips the operator has hidden from THEIR board (local only — the board is
// shared, so this never touches the engine or other operators). Persisted to
// localStorage so dismissals survive reloads.
const _snDismissed = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snDismissedDone') || '[]'); } catch (_) { return []; }
})());
function _snSaveDismissed() {
  try { localStorage.setItem('snDismissedDone', JSON.stringify([..._snDismissed])); } catch (_) { /* */ }
}

// Scrapes the operator explicitly stopped. The engine reports a user-stopped
// scrape as plain "done", so we remember the stop action locally to render it red
// as "Stopped" (persisted so it survives reloads).
const _snStopped = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snStopped') || '[]'); } catch (_) { return []; }
})());
function _snSaveStopped() {
  try { localStorage.setItem('snStopped', JSON.stringify([..._snStopped])); } catch (_) { /* */ }
}

// Scrapes the operator PAUSED via the strip's On/Off toggle. The engine doesn't
// report a paused state (pause just signals the pod; the job stays "running"), so
// we track it locally to render the strip as "Paused" instead of "Running".
const _snPaused = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snPaused') || '[]'); } catch (_) { return []; }
})());
function _snSavePaused() {
  try { localStorage.setItem('snPaused', JSON.stringify([..._snPaused])); } catch (_) { /* */ }
}

// Local launch registry — the engine drops campaignName/ownerEmail/profileId from
// its /api/jobs list, so the board can't show the real name or drive toggle/stop
// for our own scrapes. On launch we stash {name, profileId, ownerEmail} keyed by
// each dispatched search URL, then backfill strips in _snEnrich(). localStorage so
// it survives reloads. (Only covers THIS operator's launches — which is exactly
// the set we're allowed to control.)
// Keyed by searchKey(url), not the URL itself: the board list no longer carries
// full search URLs (20.4MB per poll), so the strip can only match on the hash.
// Entries written before this change are re-keyed on load.
const _snLaunchReg = (() => {
  let raw = {};
  try { raw = JSON.parse(localStorage.getItem('snLaunchReg') || '{}'); } catch (_) { return {}; }
  const out = {};
  for (const [k, v] of Object.entries(raw)) out[k.includes('://') ? searchKey(k) : k] = v;
  return out;
})();
function _snSaveLaunchReg() {
  try { localStorage.setItem('snLaunchReg', JSON.stringify(_snLaunchReg)); } catch (_) { /* */ }
}
function _snRegisterLaunch(searchUrl, info) {
  if (!searchUrl) return;
  _snLaunchReg[searchKey(searchUrl)] = { ...info, ts: Date.now() };
  _snSaveLaunchReg();
}
// Backfill a strip from the launch registry when the engine didn't echo the
// real name / owner / profiles.
function _snEnrich(c) {
  let regName = null; const regProfiles = []; let regOwner = null;
  for (const k of (c.searchKeys || (c.searchUrls || []).map(searchKey))) {
    const e = _snLaunchReg[k];
    if (!e) continue;
    regName = regName || e.name;
    regOwner = regOwner || e.ownerEmail;
    if (e.profileId) regProfiles.push(e.profileId);
  }
  if (regName) c.name = regName;
  if (regOwner) { c.owner = regOwner; c.mine = true; }
  if (regProfiles.length) c.profileIds = [...new Set([...(c.profileIds || []), ...regProfiles])];
  return c;
}

// "Done N ago" — prefer a real finish timestamp off the engine jobs if present;
// otherwise stamp when THIS client first saw the scrape as done (localStorage).
const _snDoneSeen = (() => {
  try { return JSON.parse(localStorage.getItem('snDoneSeen2') || '{}'); } catch (_) { return {}; }
})();
function _snSaveDoneSeen() {
  try { localStorage.setItem('snDoneSeen2', JSON.stringify(_snDoneSeen)); } catch (_) { /* */ }
}
// The ONLY trustworthy finish time: the moment we witnessed this scrape turn
// done this session (set in _snStampFinished). We deliberately do NOT read
// timestamps off the engine jobs — the engine sends no reliable finish epoch,
// and guessing fields produced garbage ("20636d ago"). Unknown → 0 → plain "Done".
function _snDoneTs(c) {
  return _snDoneSeen[c.id] || 0;
}
function fmtAgo(ts) {
  const t = Number(ts);
  if (!Number.isFinite(t) || t <= 0) return ''; // no known time → caller shows plain "Done"
  const d = Date.now() - t;
  if (!(d >= 0)) return '';
  const m = Math.floor(d / 60000);
  if (m < 1) return 'just now';
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function renderStrip(c) {
  const isQueued = c.status === 'queued';
  const isDone = c.status === 'done' || c.status === 'error';
  const collapsed = isQueued ? true : !_snExpanded.has(c.id);
  const owner = c.owner || 'unknown';
  const nSearches = c.searchCount != null ? c.searchCount : (c.searchUrls || []).length;
  const nJobs = (c.jobs || []).length || nSearches;
  const flow = `<b>${nSearches} searches</b> → <b>${nJobs} jobs</b> → feeds <b>${escHtml(c.name || c.tabName || '')}</b> · tab "${escHtml(c.tabName || 'Results')}"`;
  const doneAgo = isDone ? fmtAgo(_snDoneTs(c)) : '';
  // "Stopped" (red) only if the operator's stop actually cut short running work.
  // If EVERY job finished ('done'), the scrape completed on its own → show neutral
  // "Done" even though Stop was pressed (it landed after completion). Clean the
  // stale stopped-mark so it doesn't linger red.
  const _jobStates = (c.jobs || []).map((j) => String((j && j.state) || ''));
  const _allJobsDone = _jobStates.length > 0 && _jobStates.every((s) => s === 'done');
  if (isDone && _allJobsDone && _snStopped.has(c.id)) { _snStopped.delete(c.id); try { _snSaveStopped(); } catch (_) {} }
  const wasStopped = isDone && _snStopped.has(c.id) && !_allJobsDone;
  // Paused = the operator toggled it off while it's still active (not terminal).
  const isPaused = !isDone && _snPaused.has(c.id);
  const isBad = c.status === 'error' || wasStopped; // render red
  const doneLabel = c.status === 'error' ? 'Error' : wasStopped ? 'Stopped' : 'Done';
  const statusTxt = isPaused ? 'Paused'
    : isQueued ? `Queued${c.minPosition ? ` · #${c.minPosition}` : ''}${c.etaMs ? ` · ${fmtEta(c.etaMs)}` : ''}`
    : c.status === 'running' ? 'Running'
    : `${doneLabel}${doneAgo ? ` · ${doneAgo}` : ''}`;
  // Running cards show live throughput (rows-so-far only — the engine reports no
  // expected total, so no % bar; see /api/jobs shape). Rendered under the flow.
  const progLine = c.status === 'running'
    ? `<div class="sn-progtxt"><b>${(c.totalProfiles || 0).toLocaleString()}</b> rows so far · ${c.done}/${nJobs} jobs done${c.etaMs ? ` · ${fmtEta(c.etaMs)} left` : ''}</div>`
    : '';
  const jobsPane = (c.jobs || []).map((j) => {
    const label = j.searchLabel || (j.searchUrl ? j.searchUrl.slice(0, 60) : 'search');
    const st = j.state === 'running' ? `<span class="dot run"></span> Running · ${j.profiles || 0} rows`
      : j.state === 'done' ? `<span class="dot mon"></span> Done · ${j.profiles || 0} rows`
      : j.state === 'error' ? `<span class="dot red"></span> Error`
      : `<span class="dot q"></span> Queued`;
    return `<div class="job"><div><div class="jt">${escHtml(label)}</div></div><div class="jstat">${st}</div></div>`;
  }).join('') || '<div class="sn-empty">No jobs.</div>';
  const canOpen = !isQueued || _snCanControl(c);
  // Open → the scrape's setup WIZARD (config populated) with its live Activity log
  // at the bottom — the analogue of a campaign's Open → wizard-with-log. Available
  // for every status (running/queued/done) so you can always inspect config + log.
  const openCls = isDone ? 'mini' : 'mini solid'; // on done strips Re-run is primary
  const openBtn = canOpen
    ? `<button class="${openCls}" title="Open this scrape's wizard (config + log)" onclick="openScrapeSetupFor('${escHtml(c.id)}')">Open</button>`
    : `<button class="mini locked" title="Only ${escHtml(owner)} can open this">Open 🔒</button>`;
  // Re-run → DIRECTLY start the scrape again with the same config (no wizard),
  // for a FINISHED or STOPPED scrape you own (or admin). The engine has no
  // page-offset resume; a re-run restarts from page 1 and the sheet-level dedup
  // skips rows already captured, so it mainly fills in what a stopped run missed.
  // A STOPPED scrape reads "Continue" (re-runs with the same config; sheet dedup
  // skips already-captured rows, so it effectively picks up where it left off).
  // A naturally-FINISHED scrape reads "Re-run" (start it over).
  const rerunLabel = wasStopped ? 'Continue' : 'Re-run';
  const rerunTitle = wasStopped
    ? 'Continue this scrape — re-runs with the same config; already-captured rows are skipped'
    : 'Start this scrape again with the same config';
  const rerunBtn = (isDone && _snCanControl(c))
    ? `<button class="mini solid" title="${rerunTitle}" onclick="rerunScrape('${escHtml(c.id)}',this)">${rerunLabel}</button>`
    : '';
  // 👁 View — live MJPEG of a running job's browser on the VM, exactly like the
  // campaign board's 👁 Show. Views the first running job of this scrape (a scrape
  // can run several browsers; this opens one — the per-job Jobs pane lists the rest).
  const runningJob = (c.jobs || []).find((j) => j.state === 'running' && j.id);
  const viewBtn = runningJob
    ? `<button class="mini" onclick="openScrapeJobView('${escHtml(runningJob.id)}','${escHtml(c.name || c.tabName || 'scrape')}')" title="Watch this scrape running on the VM">👁 View</button>`
    : '';
  // Stop shows while running OR still queued. Anyone can press it, but a
  // "not yours" confirm gates non-owners (handled in stopScrapeCampaign).
  const canStop = c.status === 'running' || isQueued;
  const stopBtn = canStop
    ? `<button class="mini" onclick="stopScrapeCampaign('${escHtml(c.id)}')">Stop</button>` : '';
  // Done strips get a dismiss (✕) that hides them from THIS operator's board only.
  const dismissBtn = isDone
    ? `<button class="mini sn-dismiss" data-cid="${escHtml(c.id)}" title="Hide from your board">✕</button>` : '';
  // Non-queued strips carry the Jobs/Logs pane, folded by default. The expand
  // control is pinned to the strip's top-right corner (CSS-absolute) so it stays
  // put when the pane opens instead of riding the footer down the page.
  const expandBtn = isQueued ? ''
    : `<button class="sn-collapse sn-expand" title="Expand / collapse"><svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6l4 4 4-4"/></svg></button>`;
  // The toggle reads Running/Paused. It's OFF (Paused) when the operator paused it
  // — the engine keeps reporting the job "running", so factor in the local paused
  // mark, else the switch would snap back to Running on the next poll.
  const toggleOn = (c.enabled !== false) && !isPaused;
  // Which tab is active survives re-renders via _snLogsTab (default: Jobs).
  const logsActive = _snLogsTab.has(c.id);
  const switchBlock = isQueued ? '' : `
    <div class="sn-switch">
      <div class="sn-switchtabs"><span class="sn-st ${logsActive ? '' : 'on'}" data-t="jobs">Jobs</span><span class="sn-st ${logsActive ? 'on' : ''}" data-t="logs">Logs</span></div>
      <div class="sn-pane ${logsActive ? '' : 'on'}" data-p="jobs">${jobsPane}</div>
      <div class="sn-pane ${logsActive ? 'on' : ''}" data-p="logs"><div class="sn-logbox" data-logsfor="${escHtml(c.id)}" data-tab="${escHtml(c.tabName || '')}">…</div></div>
    </div>`;
  // Expanded strips render the SAME .vj-card as the campaigns board (app.js:8804)
  // and as Steven's scrape launch card — one shell, no markup drift.
  //
  // Unlike the campaigns board this skips COLLAPSED strips too, not just queued
  // ones. vjCardSkeleton deep-clones #active-card, and this board renders 282
  // strips every 2.5s; cloning a card nobody can see 282 times per tick is a
  // measurable freeze for zero pixels. Expanding a strip re-renders it anyway.
  const richCard = (isQueued || collapsed) ? '' : vjCardSkeleton(c.id);
  // data-sig fingerprints everything this template just rendered, so the board
  // can tell "this strip is unchanged" from "this strip needs new markup"
  // without diffing DOM. It is hashed from the finished string rather than a
  // hand-listed set of fields, so a field added to the template above can never
  // be forgotten here and leave a strip frozen on stale values.
  const _html = `
  <div class="sn-strip ${c.mine ? 'mine' : ''} ${c.status === 'running' && !isPaused ? 'run' : ''} ${isPaused ? 'paused' : ''} ${isQueued ? 'queued' : ''} ${collapsed ? 'sn-collapsed' : ''} ${isDone ? 'done' : ''} ${isBad ? 'stopped' : ''}" data-cid="${escHtml(c.id)}" data-sig="__SIG__">
    ${expandBtn}
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Sales Nav Scraper</span>${c.mine ? '<span class="sn-you">You</span>' : `<span class="sn-owner">· ${escHtml(owner)}</span>`}
      <span class="sn-status">${isPaused ? '<span class="dot paused"></span>' : isBad ? '<span class="dot red"></span>' : _snStatusDot(c.status)} ${escHtml(statusTxt)}</span></div>
    <div class="sn-name">${escHtml(c.name || '')}</div>
    <div class="sn-flow">${flow}</div>
    ${progLine}
    ${switchBlock}
    </div>
    ${richCard}
    <div class="sn-foot">
      <div class="togwrap"><div class="toggle ${toggleOn ? '' : 'off'}" data-owner="${escHtml(owner)}" data-cid="${escHtml(c.id)}" title="${toggleOn ? 'Running — flip to pause' : 'Paused — flip to resume'}"><i></i></div><span class="lbl">${toggleOn ? 'Running' : 'Paused'}</span></div>
      <div class="right">${dismissBtn}${viewBtn}${stopBtn}${openBtn}${rerunBtn}</div>
    </div>
  </div>`;
  return _html.replace('__SIG__', _snHash(_html));
}

// FNV-1a → base36. Not a security hash; it only has to change when the markup
// changes, and it runs ~290 times every 2.5s so it has to be cheap.
function _snHash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(36);
}

// Fill one expanded strip's cloned card with THIS scrape's numbers.
//
// Deliberately not fillVjCard(): that renders campaign controls, the reply-check
// panel and campaign live-activity, none of which a scrape has. Fields are set
// directly, the same way Steven's _setScrapeVjCard fills the launch card, and it
// reuses his _SCRAPE_VJ label map so the board and the launch console say the
// same words for the same state ("Collecting", not "Sending").
// The scrape card's action dock, mirroring the campaign card's: an Open pill
// then an icon toolbar. Every button maps to an action the strip footer already
// had — nothing new is invented, and the same ownership gates apply.
//
// Pause/resume keeps the `.toggle` class and its data-cid/data-owner, because
// that button is driven by a DELEGATED handler that matches `.toggle` and reads
// the `off` class to decide direction. Restyling it as a dock-btn changes how it
// looks, not how it works — including the "this isn't your scrape" confirm.
function _snCardControlsHtml(c) {
  const cid = escHtml(c.id);
  const isQueued = c.status === 'queued';
  const isDone = c.status === 'done' || c.status === 'error';
  const isPaused = _snPaused.has(c.id);
  const canControl = _snCanControl(c);
  const owner = c.owner || '';
  const dib = (svg, tip, onclick, cls = '') =>
    `<button type="button" class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;

  let dock = '';
  if (!isDone && !isQueued) {
    const on = (c.enabled !== false) && !isPaused;
    dock += `<button type="button" class="dock-btn toggle ${on ? '' : 'off'}" data-cid="${cid}" data-owner="${escHtml(owner)}"`
      + ` data-tip="${on ? 'Pause' : 'Resume'}" aria-label="${on ? 'Pause' : 'Resume'}">${on ? V3_SVG_PAUSE : V3_SVG_PLAY}</button>`;
  }

  let actions = '';
  const runningJob = (c.jobs || []).find((j) => j.state === 'running' && j.id);
  if (runningJob) {
    actions += `<button type="button" class="dock-btn" data-tip="Show" aria-label="Show"`
      + ` onclick="openScrapeJobView('${escHtml(runningJob.id)}','${escHtml(c.name || c.tabName || 'scrape')}')">👁</button>`;
  }
  if (c.status === 'running' || isQueued) {
    actions += dib(V3_SVG_STOP, 'Stop', `stopScrapeCampaign('${cid}')`, 'danger');
  }
  if (isDone && canControl) {
    // A stopped scrape reads Continue, a finished one Re-run — same call either
    // way; the engine restarts from page 1 and sheet dedup skips captured rows.
    const stopped = _snStopped.has(c.id) || c.status === 'error';
    actions += dib(stopped ? V3_SVG_PLAY : V3_SVG_RESTART,
      stopped ? 'Continue where it left off' : 'Re-run', `rerunScrape('${cid}',this)`);
  }
  if (isDone) {
    actions += `<button type="button" class="dock-btn sn-dismiss" data-cid="${cid}"`
      + ` data-tip="Hide from your board" aria-label="Hide from your board">${V3_SVG_TRASH}</button>`;
  }

  const openHtml = canControl
    ? `<button class="btn-pill" onclick="openScrapeSetupFor('${cid}')">Open</button>`
    : `<button class="btn-pill" disabled title="Only ${escHtml(owner)} can open this">Open 🔒</button>`;
  return `${openHtml}<div class="dock" role="toolbar" aria-label="Scrape actions">${dock}<div class="dock-actions">${actions}</div></div>`;
}

/**
 * How far along a scrape really is, as a fraction of its searches.
 *
 * The percentage used to count only FINISHED searches, so a one-search scrape
 * read 0% from start to finish and then jumped to 100 — it sat on "0% · 0 of 1
 * searches done" through 1,270 leads and 51 pages, which reads as stuck. The
 * engine now reports each job's page ceiling (maxPages, from the search API's
 * own result count), so a running job counts by its pages instead of counting
 * as nothing.
 *
 * Capped just under 1 so a running job never reads as finished, and a job with
 * no ceiling (maxPages 0 = LinkedIn never gave a total, which the scrape log
 * says out loud) contributes nothing rather than a made-up fraction.
 */
function scrapeProgressUnits(jobs) {
  return (jobs || []).reduce((sum, j) => {
    if (!j) return sum;
    if (j.state === 'done') return sum + 1;
    if (j.state === 'running' && Number(j.maxPages) > 0) {
      return sum + Math.min((Number(j.pages) || 0) / Number(j.maxPages), 0.99);
    }
    return sum;
  }, 0);
}
window.scrapeProgressUnits = scrapeProgressUnits;

function _snFillStripCard(root, c) {
  if (!root || !c) return;
  const strip = root.closest('.sn-strip');
  const isPaused = _snPaused.has(c.id);
  const isBad = _snStopped.has(c.id) || c.status === 'error';
  const state = isBad ? 'error'
    : c.status === 'queued' ? 'queued'
      : c.status === 'done' ? 'done'
        : 'running';
  const V = _SCRAPE_VJ[state] || _SCRAPE_VJ.idle;

  const jobs = c.jobs || [];
  const total = jobs.length || (c.searchCount != null ? c.searchCount : (c.searchUrls || []).length);
  const done = Number(c.done) || 0;
  const leads = Number(c.totalProfiles) || 0;
  const pages = jobs.reduce((n, j) => n + (Number(j && j.pages) || 0), 0);
  const accounts = (c.profileIds || []).length;
  const units = scrapeProgressUnits(jobs);
  const pct = total > 0 ? Math.min(100, Math.round((Math.max(units, done) / total) * 100)) : 0;
  // Only indeterminate when there is genuinely nothing to measure: a running
  // scrape whose jobs carry no page ceiling. With a ceiling the bar moves per
  // page, so it no longer sits on 0% through a thousand leads.
  const indeterminate = c.status === 'running' && units === 0 && total <= 1 && done === 0;

  // Relabel the hero ONCE per clone — the campaign card counts sent/accepted,
  // a scrape counts searches/pages/leads.
  if (!root.dataset.snLabelled) {
    const meta = root.querySelector('.vj-meta');
    if (meta) meta.innerHTML =
      '<span><b data-f="activeSent">0</b> of <span data-f="activeTotal">0</span> searches done</span>'
      + '<span><b data-f="scrapePages">0</b> pages · <b data-f="scrapeLeads">0</b> leads</span>';
    const stats = root.querySelector('.vj-stats');
    if (stats) stats.innerHTML =
      '<span><b data-f="activeAccounts">0</b> accounts</span>'
      + '<span>· <b data-f="sendingLbl">Idle</b></span>';
    root.dataset.snLabelled = '1';
  }

  // The card gets the campaign card's control dock — an Open pill plus an icon
  // toolbar — instead of the strip's text buttons and paused ticker. Same
  // .btn-pill / .dock / .dock-btn markup _vjControlsHtml builds, so the two
  // cards are visually identical; only the actions differ, and every action
  // here is one the strip footer already had.
  const ctrl = root.querySelector('.vj-controls');
  if (ctrl) ctrl.innerHTML = _snCardControlsHtml(c);

  // Fill the card's live log. The strip's log used to live in the Jobs/Logs pane
  // inside .sn-compact, which expanding hides — so the card showed "No events
  // yet" for every scrape. Reuse the strip log loader against the card's box.
  const logBox = root.querySelector('[data-f="active-log"], .vj-log');
  if (logBox && !logBox.dataset.snWired) {
    logBox.dataset.snWired = '1';
    logBox.dataset.logsfor = c.id;
    logBox.dataset.tab = c.tabName || '';
    try { _snLoadLogs(logBox); } catch (_) { /* a log failure must not break the card */ }
  }

  const setF = (f, v) => { const e = root.querySelector(`[data-f="${f}"]`); if (e) e.textContent = String(v); };
  setF('activeName', c.name || c.tabName || 'Sales Nav Scrape');
  setF('activeEyebrow', isPaused ? 'Paused' : V.eyebrow);
  setF('sendingLbl', isPaused ? 'Paused' : V.state);
  setF('activeSent', done);
  setF('activeTotal', total);
  setF('activePct', indeterminate ? '—' : pct);
  setF('scrapePages', pages.toLocaleString());
  setF('scrapeLeads', leads.toLocaleString());
  setF('activeAccounts', accounts);
  const bar = root.querySelector('[data-f="activeBar"]');
  if (bar) bar.style.width = indeterminate ? '100%' : pct + '%';
  root.classList.toggle('sn-indeterminate', indeterminate);
  setF('activeLiveL1', V.l1);
}

function _snIsAdmin() {
  return _isAdminEmail(snCurrentEmail);
}
// Can the viewer control this strip WITHOUT the "not yours" confirm? True when
// it's their own scrape (server-computed `mine`) or they're the admin.
function _snCanControl(c) {
  return !!(c && c.mine) || _snIsAdmin();
}

// The scrape flow spans three real wizard sections: the 2b config, the shared
// account picker (section 3), and the scrape launch console. To show the setup
// INLINE on the board (no navigation), we relocate those DOM nodes into the
// board's #sn-setup-body, leaving a placeholder so we can move them back exactly.
const SN_SETUP_SECTIONS = ['nav-scrape', 'nav-accounts', 'nav-scrape-launch'];
let _snSetupOpen = false;
// The composer borrows the wizard's ONE campaign-mode select. Remember what it
// was so closing puts it back — otherwise the wizard stays in scrape layout
// (2b showing, Throughput/Templates/Sheet/Launch hidden) until the operator
// happens to click a campaign-type tile.
let _snPrevMode = null;

function _snMoveSetupIn() {
  const body = document.getElementById('sn-setup-body');
  if (!body) return;
  SN_SETUP_SECTIONS.forEach((id) => {
    const sec = document.getElementById(id);
    if (!sec) return;
    if (!sec._snPlaceholder) {
      const ph = document.createComment('sn-setup:' + id);
      sec.parentNode.insertBefore(ph, sec);
      sec._snPlaceholder = ph;
    }
    body.appendChild(sec);
  });
}

// Pull the campaign-name field out of the Destination panel and pin it to the
// very top of the composer as the editable hero (drawing 3 / sketch). A comment
// placeholder marks its home so _snRestoreHeroName() puts it back for the wizard.
function _snHeroName() {
  const body = document.getElementById('sn-setup-body');
  const field = document.getElementById('scrape-name-field');
  if (!body || !field || field._snHeroPlaceholder) return;
  const ph = document.createComment('sn-heroname');
  field.parentNode.insertBefore(ph, field);
  field._snHeroPlaceholder = ph;
  body.insertBefore(field, body.firstChild);
}
function _snRestoreHeroName() {
  const field = document.getElementById('scrape-name-field');
  if (field && field._snHeroPlaceholder && field._snHeroPlaceholder.parentNode) {
    field._snHeroPlaceholder.parentNode.insertBefore(field, field._snHeroPlaceholder);
    field._snHeroPlaceholder.remove();
    field._snHeroPlaceholder = null;
  }
}

function _snRestoreSetup() {
  SN_SETUP_SECTIONS.forEach((id) => {
    const sec = document.getElementById(id);
    if (sec && sec._snPlaceholder && sec._snPlaceholder.parentNode) {
      sec._snPlaceholder.parentNode.insertBefore(sec, sec._snPlaceholder);
      sec._snPlaceholder.remove();
      sec._snPlaceholder = null;
    }
  });
}

// Reveal the scrape setup INLINE on the board (blank for a new scrape, or
// prefilled when editing a campaign). No route change.
async function openScrapeSetupFor(cid) {
  const host = document.getElementById('sn-setup');
  if (!host) return;
  _scrapePausedLocal = false; // fresh open — don't inherit a prior scrape's paused state
  const sel = document.getElementById('campaign-mode');
  if (sel) {
    // Only capture on the FIRST open — re-opening the composer must not record
    // 'sales_nav_scrape' as the mode to restore.
    if (_snPrevMode === null && sel.value !== 'sales_nav_scrape') _snPrevMode = sel.value;
    sel.value = 'sales_nav_scrape';
  }
  _snMoveSetupIn();
  if (typeof onModeChange === 'function') onModeChange(); // reveals the scrape sections
  _snHeroName();
  host.style.display = 'block';
  const newBtn = document.getElementById('sn-new-btn');
  if (newBtn) newBtn.style.display = 'none'; // already composing — hide the entry button
  const board = document.getElementById('sn-board');
  if (board) board.style.display = 'none'; // focus this scrape — hide the queue list below
  _snSetupOpen = true;
  if (cid) {
    // BLANK the fields immediately (before the fetch that populates them). The
    // /api/scrape/campaigns round-trip can be slow when the engine is busy; showing
    // the PREVIOUS scrape's config while we wait is worse than showing nothing.
    const urls = document.getElementById('scrape-urls'); if (urls) urls.value = '';
    const sheet = document.getElementById('scrape-sheet'); if (sheet) sheet.value = '';
    const tab = document.getElementById('scrape-tab'); if (tab) tab.value = '';
    const nm = document.getElementById('scrape-name'); if (nm) nm.value = '';
    _setScrapeSetupTitle('Loading scrape…', true);
    _setScrapeSaveVisible(true); // editing an existing scrape → offer Save config
    // Track the opened scrape so pollScrapeLogs shows ITS log (scrape-specific,
    // cross-session) instead of this session's global feed. Clear the console now.
    _snOpenedScrape = { cid, tabName: '' };
    try { scrapeLogLines = []; scrapeLogSince = 0; if (typeof renderScrapeLogPanel === 'function') renderScrapeLogPanel(); } catch (_) { /* */ }
    try {
      // Single record, not the whole board — the list response is ~22MB.
      const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}`);
      const d = await r.json();
      const rec = d.campaign;
      if (rec) {
        if (urls) urls.value = (rec.searchUrls || []).join('\n');
        if (sheet) sheet.value = rec.sheetUrl || '';
        if (tab) tab.value = rec.tabName || 'Results';
        if (nm) nm.value = rec.name || '';
        _snOpenedScrape.tabName = rec.tabName || '';
        _setScrapeSetupTitle(rec.name || rec.tabName || 'Scrape');
        // Pre-select the SAME GoLogin accounts this scrape used (section 3), so a
        // wizard re-run reuses them unless the operator changes them — matching the
        // direct Re-run button. rec.profileIds are the scrape's job profileIds,
        // which are GoLogin profile ids (== p.id in the picker).
        if (Array.isArray(rec.profileIds) && rec.profileIds.length) {
          selectedProfileIds = rec.profileIds.filter(Boolean);
          for (const id of selectedProfileIds) {
            const p = (allProfilesData || []).find((x) => x.id === id);
            if (p) selectedProfileNames[id] = p.name;
          }
          try { if (typeof renderProfiles === 'function' && (allProfilesData || []).length) renderProfiles(allProfilesData); } catch (_) { /* */ }
          try { if (typeof renderSelectedPanel === 'function') renderSelectedPanel(); } catch (_) { /* */ }
        }
      } else {
        _setScrapeSetupTitle('Scrape');
      }
    } catch (_) { _setScrapeSetupTitle('Scrape'); }
    try { if (typeof pollScrapeLogs === 'function') pollScrapeLogs(); } catch (_) { /* */ }
  } else {
    _snOpenedScrape = null; // a genuinely new scrape — global session log applies
    _setScrapeSetupTitle('New scrape');
    _setScrapeSaveVisible(false); // nothing to save-onto yet for a brand-new scrape
  }
  if (typeof updateScrapePairing === 'function') updateScrapePairing();
  try { host.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) { /* */ }
}
// The composer's hero title — "New scrape" for a fresh one, the scrape's name when
// opening an existing running/done scrape (so it never mislabels a live scrape as new).
function _setScrapeSetupTitle(text, loading = false) {
  const el = document.querySelector('#sn-setup .sn-setup-title');
  if (!el) return;
  el.innerHTML = (loading ? '<span class="sn-setup-spinner" aria-hidden="true"></span>' : '') + `<span>${escHtml(text)}</span>`;
}
// Which existing scrape the composer is showing (null = a new scrape). Drives
// pollScrapeLogs to fetch THIS scrape's log instead of the session's global feed.
let _snOpenedScrape = null;
window.openScrapeSetupFor = openScrapeSetupFor;

// Re-run a finished/stopped scrape DIRECTLY (no wizard): re-dispatch the exact same
// config (searchUrls × accounts → sheet/tab) to the engine, mirroring startScrapeJob's
// per-URL /api/scrape/start dispatch. The engine restarts the search from page 1;
// sheet-level dedup skips already-captured rows.
async function rerunScrape(cid, btn) {
  if (btn) btn.disabled = true;
  const toast = (m) => { try { showCampaignToast(m, 4500); } catch (_) { try { alert(m); } catch (_) {} } };
  try {
    // Single record, not the whole board — the list response is ~22MB.
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}`);
    const d = await r.json();
    const rec = d.campaign;
    if (!rec) { toast('Re-run: couldn’t find this scrape’s config — try Open instead.'); return; }
    const urls = (rec.searchUrls || []).filter(Boolean);
    const sheetUrl = rec.sheetUrl || '';
    const baseTab = (rec.tabName || 'Results').trim();
    const campaignName = (rec.name || baseTab).trim();
    const accts = (rec.profileIds || []).filter(Boolean);
    if (!urls.length || !sheetUrl || !accts.length) {
      toast('Re-run: this scrape is missing its URLs, sheet, or accounts — Open it and start manually.');
      return;
    }
    toast(`Re-running “${campaignName}” — ${urls.length} job${urls.length === 1 ? '' : 's'} on ${accts.length} account${accts.length === 1 ? '' : 's'}…`);
    let started = 0; const errors = [];
    for (let i = 0; i < urls.length; i++) {
      const profileId = accts[i % accts.length];              // round-robin URL→account, like startScrapeJob
      const tabName = urls.length > 1 ? `${baseTab} ${i + 1}` : baseTab;
      const _nm = profileLabel(profileId);                    // name for account-level engine errors
      const accountName = (_nm && _nm !== profileId) ? _nm : '';
      try {
        const rr = await fetch('/api/scrape/start', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ searchUrls: [urls[i]], sheetUrl, tabName, profileId, slowMode: false, campaignName, accountName }),
        });
        const res = await rr.json();
        if (res && res.error) errors.push(res.error); else started++;
      } catch (e) { errors.push(e && e.message ? e.message : String(e)); }
    }
    toast(started
      ? `Re-run started — ${started} job${started === 1 ? '' : 's'} dispatched${errors.length ? `, ${errors.length} failed` : ''}. Watch it under “Now running”.`
      : `Re-run failed: ${errors[0] || 'unknown error'}`);
    if (started) {
      // Optimistic move to "Now running" so the strip jumps immediately instead of
      // waiting for the slow /api/jobs poll (~10s). Clear the stopped mark and flip
      // the cached campaign's status; the poll burst below reconciles with the
      // engine as the new jobs register.
      _snStopped.delete(cid); try { _snSaveStopped(); } catch (_) {}
      if (Array.isArray(_snLastCampaigns)) {
        const c = _snLastCampaigns.find((x) => x.id === cid);
        if (c) { c.status = 'running'; c.running = Math.max(1, c.running || 0); c.done = 0; }
        try { renderSalesNavBoard(_snLastCampaigns); } catch (_) { /* */ }
      }
      // Catch-up polls: the board fetch has an in-flight guard, so fire a few over
      // ~12s to reflect the real engine state as soon as the new jobs appear.
      [1500, 4000, 8000, 12000].forEach((ms) => setTimeout(() => { try { pollSalesNavBoard(); } catch (_) { /* */ } }, ms));
    }
  } catch (e) { toast('Re-run failed: ' + (e && e.message ? e.message : e)); }
  finally { if (btn) btn.disabled = false; }
}
window.rerunScrape = rerunScrape;

// Save the current wizard config for the OPENED scrape (keyed by its board id) so
// the edits persist and win on re-open — the server merges saved overrides into
// /api/scrape/campaigns. Only meaningful while viewing an existing scrape.
async function saveScrapeConfig(btn) {
  if (!_snOpenedScrape || !_snOpenedScrape.cid) {
    try { showCampaignToast('Open a scrape first, then Save.', 3500); } catch (_) {}
    return;
  }
  if (btn) btn.disabled = true;
  try {
    const body = {
      searchUrls: (typeof getScrapeInputUrls === 'function' ? getScrapeInputUrls() : []),
      sheetUrl: (document.getElementById('scrape-sheet')?.value || '').trim(),
      tabName: (document.getElementById('scrape-tab')?.value || 'Results').trim(),
      name: (document.getElementById('scrape-name')?.value || '').trim(),
      profileIds: (typeof scrapeSelectedAccounts === 'function' ? scrapeSelectedAccounts() : []),
    };
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(_snOpenedScrape.cid)}/config`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const d = await r.json().catch(() => ({}));
    if (d && d.ok) { _snOpenedScrape.tabName = body.tabName; try { showCampaignToast('✓ Config saved — it’ll be here next time you open this scrape.', 4000); } catch (_) {} }
    else { try { showCampaignToast('Save failed: ' + ((d && d.error) || 'unknown'), 5000); } catch (_) {} }
  } catch (e) { try { showCampaignToast('Save failed: ' + (e && e.message ? e.message : e), 5000); } catch (_) {} }
  finally { if (btn) btn.disabled = false; }
}
window.saveScrapeConfig = saveScrapeConfig;
// Show the Save-config button only while an existing scrape is open (editing it).
function _setScrapeSaveVisible(show) {
  const b = document.getElementById('btn-scrape-save');
  if (b) b.style.display = show ? '' : 'none';
}

function startNewScrapeSetup() {
  _snOpenedScrape = null; // fresh scrape — not viewing an existing one's log
  const urls = document.getElementById('scrape-urls'); if (urls) urls.value = '';
  const nm = document.getElementById('scrape-name'); if (nm) nm.value = '';
  openScrapeSetupFor('');
}
window.startNewScrapeSetup = startNewScrapeSetup;

// Hide the inline setup and move the relocated sections back into the wizard so
// the campaign wizard stays intact for every other mode.
function closeScrapeSetup() {
  const host = document.getElementById('sn-setup');
  if (host) host.style.display = 'none';
  const newBtn = document.getElementById('sn-new-btn');
  if (newBtn) newBtn.style.display = '';
  const board = document.getElementById('sn-board');
  if (board) board.style.display = ''; // restore the queue list
  _snRestoreHeroName();
  _snRestoreSetup();
  _snSetupOpen = false;
  _snOpenedScrape = null; // back to the board — stop showing an opened scrape's log
  _setScrapeSaveVisible(false);
  // Hand the wizard back the mode it had. Restoring the select alone isn't
  // enough — onModeChange() is what re-shows Throughput/Templates/Sheet/Launch
  // and hides 2b, so the wizard was carrying scrape layout into a normal
  // campaign until a type tile was clicked.
  const sel = document.getElementById('campaign-mode');
  if (sel && sel.value === 'sales_nav_scrape') {
    sel.value = _snPrevMode || 'connect_only';
    if (typeof onModeChange === 'function') { try { onModeChange(); } catch (_) { /* */ } }
  }
  _snPrevMode = null;
}
window.closeScrapeSetup = closeScrapeSetup;

document.addEventListener('click', (e) => {
  const tab = e.target.closest('.sn-st');
  if (tab) {
    const sw = tab.closest('.sn-switch');
    sw.querySelectorAll('.sn-st').forEach((x) => x.classList.toggle('on', x === tab));
    sw.querySelectorAll('.sn-pane').forEach((p) => p.classList.toggle('on', p.dataset.p === tab.dataset.t));
    // Remember the choice so the 2.5s re-render keeps this tab active.
    const cid = tab.closest('.sn-strip')?.dataset.cid;
    if (cid) { if (tab.dataset.t === 'logs') _snLogsTab.add(cid); else _snLogsTab.delete(cid); }
    if (tab.dataset.t === 'logs') {
      const box = sw.querySelector('.sn-logbox');
      if (box && box.dataset.logsfor) _snLoadLogs(box);
    }
  }
});
// Fold / unfold a finished-or-running strip's Jobs/Logs pane.
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.sn-collapse');
  if (!btn) return;
  const strip = btn.closest('.sn-strip');
  const cid = strip?.dataset.cid;
  if (!cid) return;
  const active = _snItemsById.get(cid)?.bucket === 'running';
  if (active) {
    if (_snCollapsedActive.has(cid)) _snCollapsedActive.delete(cid); else _snCollapsedActive.add(cid);
    strip.classList.toggle('sn-collapsed', _snCollapsedActive.has(cid));
  } else {
    if (_snExpanded.has(cid)) _snExpanded.delete(cid); else _snExpanded.add(cid);
    strip.classList.toggle('sn-collapsed', !_snExpanded.has(cid));
  }
  // A Sales Nav strip's rich card (and therefore its live log) is built by
  // renderSalesNavBoard, which this handler never called — it called the
  // CAMPAIGNS board's renderer instead. So expanding a scrape only did
  // something on the next 2.5s poll, and nothing at all while a poll was slow
  // or stalled: the strip opened to an empty shell. Render its own board now.
  if (strip.closest('#sn-board')) {
    try { if (_snLastCampaigns) renderSalesNavBoard(_snLastCampaigns); } catch (_) { /* keep the fold responsive */ }
  } else if (typeof renderCampaignsBoard === 'function') {
    renderCampaignsBoard();
  }
  if (_snExpanded.has(cid) && typeof _refreshCloudItems === 'function') _refreshCloudItems();
});

// Dismiss a done strip (local-only) and the "Clear done" bulk action.
document.addEventListener('click', (e) => {
  const x = e.target.closest('.sn-dismiss');
  if (x && x.dataset.cid) {
    // Deleting a scrape must kill any lingering activity on the VM, not just hide
    // it — stop each of its accounts' jobs first (best-effort; a no-op for a scrape
    // that already finished). Then hide it from the board.
    const cid = x.dataset.cid;
    const meta = _snStrips.get(cid) || {};
    (meta.profileIds || []).filter(Boolean).forEach((pid) => {
      fetch('/api/scrape/stop', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ profileId: pid }) }).catch(() => {});
    });
    _snDismissed.add(cid); _snSaveDismissed();
    const strip = x.closest('.sn-strip');
    if (strip) strip.remove(); // instant — the next poll already filters it out
    return;
  }
  const clr = e.target.closest('.sn-clear-done');
  if (clr) {
    const head = clr.closest('.sn-railhead');
    document.querySelectorAll('#sn-board .sn-strip.done').forEach((s) => {
      if (s.dataset.cid) _snDismissed.add(s.dataset.cid);
      s.remove();
    });
    if (head) head.remove();
    _snSaveDismissed();
  }
});

let _snPendingToggle = null;
let _snPendingStop = null;
function _snApplyToggle(el, cid) {
  const goingOn = el.classList.contains('off'); // currently off → turning on
  // Immediate visual feedback — flip the switch and pulse the strip so the
  // operator sees the state change without waiting for the next poll.
  el.classList.toggle('off', !goingOn);
  const lbl = el.parentNode?.querySelector('.lbl');
  if (lbl) lbl.textContent = goingOn ? 'Running' : 'Paused';
  const strip = el.closest('.sn-strip');
  if (strip) {
    strip.classList.remove('starting', 'stopping');
    strip.classList.add(goingOn ? 'starting' : 'stopping');
  }
  // Track the paused state locally so the strip reads "Paused" (the engine keeps
  // reporting the job as running). ON → resume (clear); OFF → pause (mark).
  if (goingOn) _snPaused.delete(cid); else _snPaused.add(cid);
  try { _snSavePaused(); } catch (_) { /* */ }
  const meta = _snStrips.get(cid) || {};
  fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}/toggle`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ on: goingOn, profileIds: meta.profileIds || [] }),
  }).then(() => pollSalesNavBoard()).catch(() => {});
}
document.addEventListener('click', (e) => {
  const t = e.target.closest('.toggle');
  if (!t || !t.dataset.cid) return;
  const cid = t.dataset.cid;
  const strip = _snStrips.get(cid) || {};
  const owner = t.dataset.owner || strip.owner || '';
  if (!_snCanControl({ mine: strip.mine })) {
    _snPendingToggle = { el: t, cid };
    const goingTo = t.classList.contains('off') ? 'ON' : 'OFF';
    document.getElementById('snm-body').innerHTML =
      `This isn't your campaign — it belongs to <b>${escHtml(owner)}</b>. Turning it <b>${goingTo}</b> affects their scrape and its place in the queue. Continue?`;
    document.getElementById('snm-scrim').classList.add('open');
    return;
  }
  _snApplyToggle(t, cid); // owner or admin → immediate
});
document.getElementById('snm-cancel')?.addEventListener('click', () => {
  _snPendingToggle = null; _snPendingStop = null; document.getElementById('snm-scrim').classList.remove('open');
});
document.getElementById('snm-ok')?.addEventListener('click', () => {
  if (_snPendingToggle) _snApplyToggle(_snPendingToggle.el, _snPendingToggle.cid);
  if (_snPendingStop) _snDoStop(_snPendingStop);
  _snPendingToggle = null; _snPendingStop = null; document.getElementById('snm-scrim').classList.remove('open');
});

function _snDoStop(cid) {
  const meta = _snStrips.get(cid) || {};
  _snStopped.add(cid); _snSaveStopped(); // remember so it renders red as "Stopped"
  _snPaused.delete(cid); try { _snSavePaused(); } catch (_) { /* */ } // stopping clears any paused mark
  // Immediate visual feedback: pulse the strip red and show the button working.
  const strip = document.querySelector(`.sn-strip[data-cid="${cid}"]`);
  if (strip) {
    strip.classList.remove('starting');
    strip.classList.add('stopping');
    const btn = strip.querySelector('.sn-foot .right .mini');
    if (btn) { btn.textContent = 'Stopping…'; btn.disabled = true; }
  }
  // Hard STOP each account's job — /api/scrape/stop broadcasts stop to the owning
  // pod AND cancels that profile's queued jobs. (The /toggle endpoint only PAUSES,
  // which left the strip stuck on "RUNNING" — that was the bug.) Once stopped, the
  // jobs go terminal, so the strip's status flips to Done/Stopped and it moves to
  // the Done section on the next board poll.
  const profileIds = (meta.profileIds || []).filter(Boolean);
  const stops = profileIds.length
    // cid rides along so the stop is written to THIS strip's log — stopping a
    // shared board's scrape is the most audit-worthy action there is, and it
    // used to leave no trace at all.
    ? profileIds.map((pid) => fetch('/api/scrape/stop', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ profileId: pid, campaignId: cid }),
      }).catch(() => {}))
    : [];
  Promise.all(stops).then(() => { try { pollSalesNavBoard(); } catch (_) {} }).catch(() => {});
}

function stopScrapeCampaign(cid) {
  const meta = _snStrips.get(cid) || {};
  // Confirm-then-allow: stopping someone else's scrape asks first (admin skips).
  if (!_snCanControl({ mine: meta.mine })) {
    _snPendingStop = cid;
    document.getElementById('snm-body').innerHTML =
      `This isn't your campaign — it belongs to <b>${escHtml(meta.owner || 'another operator')}</b>. Stopping it ends their scrape and frees its queue slot. Continue?`;
    document.getElementById('snm-scrim').classList.add('open');
    return;
  }
  _snDoStop(cid);
}
window.stopScrapeCampaign = stopScrapeCampaign;

function _snFmtLogTime(ts) { try { return new Date(ts).toLocaleTimeString(); } catch (_) { return ''; } }
// Severity: trust the line's own `level` when the app wrote it; fall back to the
// same text sniff the launch console already uses, since the engine's lines
// carry no level (only an emoji prefix).
function _snLogLevel(l) {
  if (l && l.level) return l.level === 'ok' ? 'ok' : (l.level === 'info' ? '' : 'err');
  const m = String((l && l.message) || '');
  if (/error|✗|⛔|fail|🚫|⚠/i.test(m)) return 'err';
  if (/done|✓|Σ|success|complete/i.test(m)) return 'ok';
  return '';
}
function _snLogRow(l) {
  const cls = _snLogLevel(l);
  return `<div><span class="t">${_snFmtLogTime(l.ts)}</span> <span class="${cls}">${escHtml(l.message)}</span></div>`;
}
async function _snLoadLogs(box) {
  const cid = box.dataset.logsfor;
  const meta = _snStrips.get(cid) || {};
  // For the operator's OWN scrape, mirror the SAME live log the launch console
  // shows (the in-memory scrapeLogLines) — that log actually works, and the
  // engine has no reliable per-campaign log to fetch.
  if (meta.mine && Array.isArray(scrapeLogLines) && scrapeLogLines.length) {
    box.innerHTML = scrapeLogLines.map(_snLogRow).join('');
    box.scrollTop = box.scrollHeight;
    return;
  }
  // Fallback for others / prior-session scrapes: the per-campaign server endpoint.
  try {
    const tab = box.dataset.tab ? `?tabName=${encodeURIComponent(box.dataset.tab)}` : '';
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}/logs${tab}`);
    const d = await r.json();
    box.innerHTML = (d.lines || []).map(_snLogRow).join('')
      || 'No stored logs for this scrape. The engine keeps a live log only while a scrape is running.';
    box.scrollTop = box.scrollHeight;
  } catch { box.textContent = 'Logs unavailable.'; }
}
// ── /Sales Nav Board ─────────────────────────────────────────────────────────

// Floating live console — state used by renderLiveConsole(). The previous
// running flag is needed to detect the running → idle transition that
// resets the expanded-state localStorage flag (see Task 7).
let _lcWriteCache = {};
let _engineConfigured = true; // cloud engine reachable? set from /api/health; default true so the VM tab isn't disabled before the check resolves
let selectedProfileIds = [];
let selectedProfileNames = {};
let allProfilesData = [];

// Task 6: multi-tab lead-source guard state
window._chosenSheetGid = '';      // gid of the operator's chosen tab
window._tabsData = [];            // full tab list from last /api/sheet/tabs call
window._tabPickerMulti = false;   // true when workbook has >1 tabs
window._tabLeadOk = true;         // true when chosen tab passes lead-look check
window._savedSheetGid = '';       // gid from the history entry on a rerun — used by the tab-change modal
// #8: store-sourced primary status for the account picker (CC+IC mode).
// Populated by loadPrimaryStatusForPicker() before renderProfiles() renders.
let primaryStatusCache = { key: '', statuses: {} };
async function loadPrimaryStatusForPicker() {
  const url = (document.getElementById('primary-person-url')?.value || '').trim();
  const mode = document.getElementById('campaign-mode')?.value || '';
  if (mode !== 'connect_and_introduce' || !url) { primaryStatusCache = { key: '', statuses: {} }; return; }
  try {
    const r = await fetch('/api/primary-status?primaryUrl=' + encodeURIComponent(url));
    primaryStatusCache = await r.json();
  } catch { primaryStatusCache = { key: '', statuses: {} }; }
}

// ─────────────────────────────────────────────────────────────────────────
// Draft state: activeDraftId is the single source of truth for which draft
// the wizard is currently editing. Set by startNewCampaign(), editDraft(),
// or by clicking the resume pill. Cleared by launching the draft (via
// /api/campaign/queue-only) or by explicit cancel.
//
// 2026-05-27 (drafts-isolation): replaces the brittle `currentDraftIsNew`
// localStorage flag that conflated "is this a new draft?" with "should
// save create a row?". The legacy `currentDraftId` key is still written
// alongside for back-compat with code paths that read it directly (sync
// helpers, edit/delete confirmations, etc.) — both are kept in lock-step
// by the helpers below.
// ─────────────────────────────────────────────────────────────────────────
const ACTIVE_DRAFT_KEY = 'ortus.activeDraftId';

// ─────────────────────────────────────────────────────────────────────────
// Which campaign the wizard is bound to.
//
// Settings used to be written to whatever the ambient pointer happened to be:
// the autosave PATCHed /api/drafts/<activeDraftId> with the whole form on every
// keystroke, and that id survived opening a different campaign. So editing
// CTAX_GUES_MUN wrote CTAX's message — and CTAX's name — into HTECHxGGL's draft
// row. One campaign's settings landing in another's record (operator,
// 2026-09-04).
//
// Now every write NAMES the campaign it belongs to, and the store refuses a
// write whose identity does not match the record it is addressed to. An ambient
// pointer can no longer decide where settings land.
// ─────────────────────────────────────────────────────────────────────────
let _wizardBoundKey = '';
function _campaignKey(name) { return String(name || '').trim().toLowerCase(); }
function _currentWizardName() {
  return (document.getElementById('campaign-name-input')?.value || '').trim();
}
/** Bind the wizard to a campaign. Called by every path that opens one. */
function bindWizardTo(name) { _wizardBoundKey = _campaignKey(name); }
function boundWizardKey() { return _wizardBoundKey; }
if (typeof window !== 'undefined') {
  window.bindWizardTo = bindWizardTo;
  window.boundWizardKey = boundWizardKey;
}

function getActiveDraftId() {
  try {
    // Prefer the new key; fall back to the legacy `currentDraftId` so any
    // residual state from a pre-refactor session still resolves.
    return localStorage.getItem(ACTIVE_DRAFT_KEY)
      || localStorage.getItem('currentDraftId')
      || null;
  } catch { return null; }
}

function setActiveDraftId(id) {
  try {
    if (id) {
      localStorage.setItem(ACTIVE_DRAFT_KEY, id);
      localStorage.setItem('currentDraftId', id); // back-compat mirror
    } else {
      localStorage.removeItem(ACTIVE_DRAFT_KEY);
      localStorage.removeItem('currentDraftId');
    }
  } catch {}
}

function clearActiveDraft() { setActiveDraftId(null); }

// True when the wizard route is showing a campaign that is NOT the currently
// running one — used to blank the live status / log / right-pane / runbar
// identity / button state so the running campaign's data doesn't bleed in.
// True whenever there's an active draft in the wizard (new or loaded). The
// running campaign's own Edit button (from the Active tab) clears the
// active-draft id before navigating so this returns false there and the
// live data shows through. Phase 6.1 of the parallel-campaigns refactor
// replaces this heuristic with proper id comparison once the registry
// tracks per-campaign run state.
function isOnNewCampaignView() {
  try {
    if (typeof location === 'undefined' || location.hash !== '#/new') return false;
    return !!getActiveDraftId();
  } catch { return false; }
}
let localBrowserFirstName = (typeof localStorage !== 'undefined' && localStorage.getItem('localBrowserFirstName')) || '';

// Typed-in first names for accounts with no usable SoO row. 12% of GoLogin
// profiles have no row at all, and without one `{sender first name}` fell
// through to `profileName.split(' ')[0]` at send time (campaign.js:3594) —
// profileName being the GoLogin label, i.e. the account's EMAIL. Those leads
// read "Hi Jerome, nabungaires@gmail.com here".
//
// Keyed by the GoLogin profile NAME (the email), lowercased — not the profile
// id, which changes if the profile is recreated in GoLogin. Per-machine, in
// localStorage: this is a stopgap for the operator sitting in front of the app,
// NOT a substitute for a SoO row (which is what the whole team reads, and what
// carries credits and the in-use reservation besides).
const SENDER_NAME_OVERRIDES_KEY = 'senderFirstNameOverrides';
let senderFirstNameOverrides = (() => {
  try {
    const raw = typeof localStorage !== 'undefined' && localStorage.getItem(SENDER_NAME_OVERRIDES_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : {};
  } catch { return {}; } // corrupt entry must never take the picker down
})();

function overrideKeyForProfile(profileName) {
  return String(profileName || '').trim().toLowerCase();
}

function getSenderNameOverride(profileName) {
  const k = overrideKeyForProfile(profileName);
  return k ? String(senderFirstNameOverrides[k] || '').trim() : '';
}

function setSenderNameOverride(profileName, value) {
  const k = overrideKeyForProfile(profileName);
  if (!k) return;
  const v = String(value || '').trim();
  if (v) senderFirstNameOverrides[k] = v;
  else delete senderFirstNameOverrides[k]; // cleared → back to the SoO/email path
  try { localStorage.setItem(SENDER_NAME_OVERRIDES_KEY, JSON.stringify(senderFirstNameOverrides)); } catch { /* */ }
}

function resolveSenderFirstName(profileId, profileName) {
  if (profileId === 'local-browser') {
    // v2.11.15: manual override wins, but if the operator hasn’t set
    // localBrowserFirstName, auto-resolve to the SoO firstName for the
    // signed-in user — same source the "Good morning, Antonio" greeting
    // uses (app.js:3320). Operator no longer has to type their own name
    // in two places.
    const manual = (localBrowserFirstName || '').trim();
    if (manual) return manual;
    const emailEl = document.getElementById('user-chip-email');
    const email = ((emailEl?.textContent) || '').trim().toLowerCase();
    const sooEntry = email && sooData && sooData[email];
    const raw = sooEntry && sooEntry.firstName ? sooEntry.firstName.trim() : '';
    if (!raw) return '';
    return raw.charAt(0).toUpperCase() + raw.slice(1);
  }
  const soo = findSoOForProfile(profileName);
  const fromSoO = soo ? (soo['First Name'] || soo.firstName || '').toString().trim() : '';
  // SoO wins whenever it actually has a name: it is the shared source of truth,
  // so a row added later silently supersedes a stale typed-in override instead
  // of quietly out-ranking it forever. The override covers the two cases SoO
  // can't — no row at all, and a row whose First Name is blank.
  return fromSoO || getSenderNameOverride(profileName);
}

// ─────────────────────────────────────────────────────────────────────────────
// Message Preview
// ─────────────────────────────────────────────────────────────────────────────

// LinkedIn-imposed length limits. undefined = no hard limit.
const CHAR_LIMITS = {
  connectionNote: 300,
  followUpMessage: undefined,
  inmailSubject: 200,
  inmailBody: 1900,
  opProfileSubject: undefined,
  opProfileBody: undefined,
  introTitle: undefined,
};

// Display labels used in the modal card section headers.
const PREVIEW_FIELD_LABELS = {
  connectionNote: 'Connection Note',
  followUpMessage: 'Follow-up Message',
  inmailSubject: 'InMail Subject',
  inmailBody: 'InMail Body',
  opProfileSubject: 'Open Profile Subject',
  opProfileBody: 'Open Profile Body',
  introTitle: 'Group conversation title',
  primaryIntroBody: 'Intro DM Body',
  // v2.160.127: the CC+IC automated first follow-up. It IS sent (into the group
  // thread, after the last intro), so it belongs in a modal whose job is showing
  // what goes out. Listed after primaryIntroBody because that's the send order.
  followUpBody: 'First follow-up message',
  ccDmBody: 'Post-acceptance DM',
};

// Collects the same form state that startCampaign() sends to /api/campaign/start.
// Mirrors app.js:1122-1185 so the server-side normalization works identically.
function gatherCampaignFormState() {
  const sheetUrl = document.getElementById('sheet-url').value.trim();
  const linkedinColumn = document.getElementById('linkedin-col-select')?.value || '';
  const mode = document.getElementById('campaign-mode').value;
  const addNoteOn = localStorage.getItem('ortus-add-note') === '1';

  // v2.59.x — Per-mode preview suppression. Both intro flows (IC and
  // CC+IC) do NOT use tpl-followup in their actual UI; surfacing leftover
  // Follow-up Message text in the preview confused operators about what
  // gets sent. For IC the body comes from primary-intro-body (with tpl-
  // followup fallback); for CC+IC the body also comes from primary-intro-
  // body (sent post-acceptance via runAutoIntros).
  const _isIc   = mode === 'introduce_back';
  const _isCcIc = mode === 'connect_and_introduce';
  const _isCcDm = mode === 'connect_and_message';
  const _isIntroFlow = _isIc || _isCcIc;
  const _tplFollow = document.getElementById('tpl-followup').value;
  const _primaryIntro = document.getElementById('primary-intro-body')?.value || '';
  const _icResolvedBody = _primaryIntro || _tplFollow; // mirror startCampaign:2668
  // ICB full-mirror: the primary's name comes from the Primary Person block now,
  // falling back to the legacy intro-name so saved ICB campaigns don't lose it.
  const _icPrimaryName = (document.getElementById('primary-person-name')?.value?.trim() || '')
    || (document.getElementById('intro-name')?.value?.trim() || '');

  const templates = {
    // v2.59: drop addNoteOn gate — textarea value IS the note.
    connectionNote: document.getElementById('tpl-note').value,
    // Intro flows suppress Follow-up Message because the body is shown
    // separately as Intro DM Body. Other modes pass tpl-followup through.
    followUp1: _isIntroFlow ? '' : _tplFollow,
    inmailSubject: document.getElementById('tpl-inmail-subject').value,
    inmailBody: document.getElementById('tpl-inmail-body').value,
    openProfileSubject: document.getElementById('tpl-op-subject')?.value || '',
    openProfileBody: document.getElementById('tpl-op-body')?.value || '',
    opChannel: document.getElementById('tpl-op-channel')?.value || 'sn_first',
    opSpendInMail: !!document.getElementById('tpl-op-spend-inmail')?.checked,
    // 2.8.50: Introduction Messages sub-mode of message_only
    // v2.11.13: read from introModeActive (in-memory) instead of localStorage
    // because Chrome enterprise/privacy enforcement can block storage reads.
    introMode: _isIc,
    introName: _isIc ? _icPrimaryName : (document.getElementById('intro-name')?.value?.trim() || ''),
    // v2.13.x — Group conversation title is an intro-flow field only. Without
    // this gate it was sent (and previewed) in every mode — even falling back
    // to the hardcoded default — so CC+DM showed a phantom "Group conversation
    // title" with {first name}/{intro name} warnings. Mirror the primary-* gating.
    introTitle: _isIntroFlow
      ? (document.getElementById('intro-title')?.value || 'Introduction: {firstName} <> {primaryFirstName}')
      : '',
    // For IC, send the resolved body (primary-intro-body OR tpl-followup
    // fallback). For CC+IC and any other mode that uses it, send the raw
    // primary-intro-body value.
    // v2.59.2: CC+DM never uses primary/intro fields — blank them so a
    // leftover CC+IC config can't leak "Antonio Varlese" into the DM run's
    // campaign.templates (which the bulk-check path read to send an IC).
    primaryIntroBody: _isIc ? _icResolvedBody : (_isCcDm ? '' : _primaryIntro),
    // v2.59.x — Route the right name into templates.primaryName based on
    // mode so primary-* token substitution matches what outreach.js does
    // at send time. In IC mode the operator fills `intro-name` (Sam Adcock);
    // in CC+IC they fill `primary-person-name`. The chip vocabulary is the
    // same in both modes ({primary first name}, etc.) so we just route the
    // active source. Prevents stale leftover values from one mode leaking
    // into the other's preview.
    primaryName: _isIc
      ? _icPrimaryName
      : (_isCcDm ? '' : (document.getElementById('primary-person-name')?.value?.trim() || '')),
    primaryUrl:  _isCcDm
      ? ''
      : (document.getElementById('primary-person-url')?.value?.trim() || ''),
    // v2.91: CC+IC auto-accept + automated first follow-up. DOM-read, gated to
    // intro flows so leftover CC+IC config can't leak into other modes.
    autoAcceptPrimary: _isIntroFlow ? !!document.getElementById('auto-accept-toggle')?.checked : false,
    autoAcceptAllPending: _isIntroFlow ? !!document.getElementById('auto-accept-all-toggle')?.checked : false,
    followUpEnabled: _isIntroFlow ? !!document.getElementById('follow-up-toggle')?.checked : false,
    // v2.160.127: previewed as its own card (PREVIEW_FIELD_LABELS.followUpBody).
    // Gated on the toggle as well as the mode: with follow-ups OFF this message
    // is never sent, and a preview that shows an unsent message is the exact bug
    // the ccDmBody gate above just fixed.
    followUpBody: (_isIntroFlow && document.getElementById('follow-up-toggle')?.checked)
      ? (document.getElementById('follow-up-body')?.value || '')
      : '',
    followUpDelayMinutes: _isIntroFlow ? (Number(document.getElementById('follow-up-delay')?.value) || 10) : 10,
    primarySource: _isIntroFlow ? readPrimarySource() : 'local-browser',
    // v2.62: CC+DM post-acceptance body. Only meaningful when
    // mode === 'connect_and_message'; campaign.js reads templates.ccDmBody
    // from runAutoDms. Other modes ignore it.
    // v2.160.126: mode-gate it, like every other cross-mode field above.
    // Ungated, a half-typed leftover in the hidden #tpl-cc-dm-body textarea
    // rendered a phantom "Post-acceptance DM" card in a CC+IC preflight
    // preview (the modal shows any field that isn't empty, app.js:1196) —
    // operator report 2026-08-03: "Hi Bach, my name is" on a CC+IC campaign.
    ccDmBody: _isCcDm ? (document.getElementById('tpl-cc-dm-body')?.value || '') : '',
  };

  const senderFirstNames = {};
  // {senderName} resolves at send time to the GoLogin account's NAME
  // (campaign.js: profileNameCache[profileId]). The preview server has no live
  // GoLogin session, so it used to stand the raw profile id in for the name and
  // an operator's preview signed off "Thanks, 6a5ee8d17da88c4708b30689"
  // (2026-09-01). We already know every selected account's name here — send it,
  // and never send an id dressed up as a name.
  const senderNames = {};
  for (const id of selectedProfileIds) {
    const pName = profileLabel(id);
    senderFirstNames[id] = resolveSenderFirstName(id, pName);
    if (pName && pName !== id) senderNames[id] = pName;
  }

  // v2.59.x — Send mode + senderColumn so the backend preview can do per-
  // row sender lookups for IC and message_only (where the sender comes
  // from the sheet, not the wizard's profile picker). senderColumn mirrors
  // startCampaign's IC-only override at app.js:2708-2710.
  // v2.61: Extended to message_only (Direct Messages) — same #ic-extras
  // sender-column dropdown is shared.
  const senderColumn = (mode === 'introduce_back' || mode === 'message_only')
    ? (document.getElementById('ic-sender-col-select')?.value || '')
    : '';

  return {
    sheetUrl,
    linkedinColumn,
    templates,
    profileIds: [...selectedProfileIds],
    senderFirstNames,
    senderNames,
    mode,
    senderColumn,
  };
}

function refreshPreviewButtonState() {
  // Bug 6: the Preview button is ALWAYS enabled now. The old enable/disable
  // gating (on sheet URL + which template fields had content) was a recurring
  // source of "locked until you type X" bugs across modes. Instead the button
  // is always clickable and handlePreviewClick() shows a friendly message in
  // the modal when there's nothing to render yet.
  const btn = document.getElementById('btn-preview-messages');
  if (!btn) return;
  btn.disabled = false;
  btn.title = 'Render your templates against sample rows from the sheet';
}

async function handlePreviewClick() {
  const btn = document.getElementById('btn-preview-messages');
  if (!btn) return;
  // Always openable. Need a sheet to render against real rows — if it's missing,
  // open the modal with guidance instead of silently doing nothing.
  const sheetUrl = document.getElementById('sheet-url')?.value?.trim() || '';
  if (!sheetUrl) {
    renderPreviewModal([], 'Enter a Google Sheet URL first — the preview renders your templates against real rows from your sheet.');
    return;
  }

  const state = gatherCampaignFormState();
  const originalText = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Loading…';

  try {
    const res = await fetch('/api/templates/preview', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(state),
    });
    const data = await res.json();
    if (!res.ok) {
      renderPreviewModal([], data.error || `Request failed (${res.status})`);
    } else {
      renderPreviewModal(data.previews || [], data.error || null);
    }
  } catch (err) {
    renderPreviewModal([], err.message || 'Network error');
  } finally {
    btn.textContent = originalText;
    refreshPreviewButtonState();
  }
}

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function renderPreviewModal(previews, error) {
  const modal = document.getElementById('preview-modal');
  const body = document.getElementById('preview-modal-body');
  const closeBtn = document.getElementById('preview-modal-close');
  const backdrop = document.getElementById('preview-modal-backdrop');
  if (!modal || !body) return;

  let html = '';
  if (error) {
    html += `<div class="preview-modal__error">Error: ${escapeHtml(error)}</div>`;
  }
  if (!error && previews.length === 0) {
    html += `<div class="preview-modal__empty">No leads with LinkedIn URLs found in the sheet.</div>`;
  }

  for (const p of previews) {
    const leadName = [p.lead.firstName, p.lead.lastName].filter(Boolean).join(' ') || '(no name)';
    html += `<div class="preview-card">`;
    html += `  <div class="preview-card__lead">`;
    html += `    <strong>${escapeHtml(leadName)}</strong>`;
    if (p.lead.company) html += ` <span class="preview-card__company">— ${escapeHtml(p.lead.company)}</span>`;
    if (p.lead.url) html += ` <a href="${escapeHtml(p.lead.url)}" target="_blank" rel="noopener" class="preview-card__url">${escapeHtml(p.lead.url)}</a>`;
    html += `  </div>`;

    for (const key of Object.keys(PREVIEW_FIELD_LABELS)) {
      const text = p.rendered?.[key];
      if (!text) continue;
      const limit = CHAR_LIMITS[key];
      const len = text.length;
      const over = limit !== undefined && len > limit;
      const countLabel = limit !== undefined ? `${len} / ${limit} chars` : `${len} chars`;
      html += `<div class="preview-card__field">`;
      html += `  <div class="preview-card__field-header">`;
      html += `    <span class="preview-card__field-name">${escapeHtml(PREVIEW_FIELD_LABELS[key])}</span>`;
      html += `    <span class="preview-card__count ${over ? 'preview-card__count--over' : ''}">${escapeHtml(countLabel)}</span>`;
      html += `  </div>`;
      html += `  <pre class="preview-card__text">${escapeHtml(text)}</pre>`;
      html += `</div>`;
    }

    if (p.warnings && p.warnings.length) {
      html += `<div class="preview-card__warnings">`;
      html += `  <div class="preview-card__warnings-title">Warnings</div>`;
      html += `  <ul>${p.warnings.map(w => `<li>${escapeHtml(w)}</li>`).join('')}</ul>`;
      html += `</div>`;
    }
    html += `</div>`; // .preview-card
  }

  body.innerHTML = html;
  modal.hidden = false;

  const onClose = () => {
    modal.hidden = true;
    closeBtn.removeEventListener('click', onClose);
    backdrop.removeEventListener('click', onClose);
    document.removeEventListener('keydown', onKey);
  };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); onClose(); } };
  closeBtn.addEventListener('click', onClose);
  backdrop.addEventListener('click', onClose);
  document.addEventListener('keydown', onKey);
}

// Keep the Preview button state in sync as the user types / changes selections.
document.addEventListener('DOMContentLoaded', () => {
  refreshPreviewButtonState();
  const watchIds = [
    'sheet-url',
    'tpl-note', 'tpl-followup',
    'tpl-inmail-subject', 'tpl-inmail-body',
    'tpl-op-subject', 'tpl-op-body',
    // v2.59.x — IC / CC+IC fields. Without these, typing into Intro DM Body
    // didn't update the Preview button state until something else (mode
    // change, etc.) re-ran refreshPreviewButtonState.
    'primary-intro-body', 'intro-title',
    // v2.59.8 — CC+DM post-acceptance DM body. Its own oninput= calls
    // saveCcDmFields (not refreshPreviewButtonState), so without this the
    // Preview button wouldn't re-enable live as the operator typed the DM.
    'tpl-cc-dm-body',
  ];
  for (const id of watchIds) {
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', refreshPreviewButtonState);
  }
  // 2.8.29 / 2.8.32: refresh coverage preview when sheet URL changes (debounced).
  let csDebounce = null;
  const sheetEl = document.getElementById('sheet-url');
  if (sheetEl) sheetEl.addEventListener('input', () => {
    const m = document.getElementById('campaign-mode').value;
    clearTimeout(csDebounce);
    if (m === 'check_status') {
      csDebounce = setTimeout(refreshCheckStatusPreview, 600);
    } else if (m === 'message_only') {
      csDebounce = setTimeout(refreshMessageOnlyPreview, 600);
    }
  });
  // Phase 2.8.12: poll status once on load so the cockpit picks up an
  // already-running campaign across page refreshes. If a campaign is live,
  // this also kickstarts continuous polling via the running-detect path.
  pollStatus().then(() => {
    // Monitoring campaigns poll too. See pollgate.mjs for why this used to
    // render once and freeze.
    if (shouldPoll(__cockpit)) startPolling();
  }).catch(() => {});

  // Phase 2.8.14: relocate the Throughput section (#nav-pace) to sit right
  // under the Accounts section (#nav-accounts) so the live total recalculation
  // is contextual to the account selection above it.
  const pace = document.getElementById('nav-pace');
  const accounts = document.getElementById('nav-accounts');
  if (pace && accounts && pace.parentElement && pace.parentElement === accounts.parentElement) {
    accounts.parentElement.insertBefore(pace, accounts.nextSibling);
  }
  // Sync visible→hidden once and run an initial recalc.
  if (typeof alphaSyncRate === 'function') alphaSyncRate();

  // Onboarding tour — auto-start on first ever app load (no localStorage flag).
  // No-op if flag is already set. Defers internally so layout settles first.
  try { maybeAutoStartTour(); } catch (err) { console.warn('[tour] auto-start failed:', err.message); }
});

let serverLogInterval = null;
let notificationsEnabled = false;

// ─────────────────────────────────────────────────────────────────────────────
// Browser notifications (in-tab only) + server-side email for scheduled events
// ─────────────────────────────────────────────────────────────────────────────
function requestNotificationPermission() {
  if (!('Notification' in window)) {
    alert('This browser does not support in-tab notifications.');
    return;
  }
  if (Notification.permission === 'default') {
    Notification.requestPermission().then((p) => {
      notificationsEnabled = p === 'granted';
      alert(notificationsEnabled
        ? 'In-tab notifications enabled (only fire when the dashboard is open). Scheduled campaigns also send email.'
        : `Notifications are ${p}. Scheduled campaigns will still email you.`);
    });
  } else {
    notificationsEnabled = Notification.permission === 'granted';
    alert(notificationsEnabled
      ? 'In-tab notifications are already enabled.'
      : `Notifications are ${Notification.permission}. To re-enable, clear site permissions in the address bar.`);
  }
}

function notify(title, body) {
  if (notificationsEnabled) {
    try { new Notification(title, { body }); } catch { /* */ }
  }
}

async function sendTestNotification() {
  // Phase 2.8.19 (C4): record result so the sidebar Notifications panel can show
  // "<time> ago · delivered" or "<time> ago · failed" on the Last test row.
  const recordResult = (result) => {
    try { localStorage.setItem('ortus-last-notify-test', JSON.stringify({ at: Date.now(), result })); } catch (_) {}
    if (typeof refreshNotifPanel === 'function') refreshNotifPanel();
  };
  try {
    const res = await fetch('/api/notify/test', { method: 'POST' });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      recordResult('failed');
      alert('Test failed: ' + (data.error || `HTTP ${res.status}`));
      return;
    }
    recordResult('delivered');
    alert(`Test email sent.\nRecipients reached: ${data.sent ?? 0}${data.reason ? '\nNote: ' + data.reason : ''}`);
  } catch (err) {
    recordResult('failed');
    alert('Test failed: ' + err.message);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Electron-safe replacement for window.prompt()
// Electron's BrowserWindow disables window.prompt() by design, so using it
// silently fails (Save Template did nothing in the packaged DMG). This helper
// shows a small modal defined in index.html and resolves with the trimmed
// input string (or null on cancel / ESC / empty). Keep it generic — callers
// pass label + optional defaultValue.
// ─────────────────────────────────────────────────────────────────────────────
function promptModal({ label = 'Enter value:', defaultValue = '', error = '' } = {}) {
  return new Promise((resolve) => {
    const modal = document.getElementById('prompt-modal');
    const labelEl = document.getElementById('prompt-modal-label');
    const input = document.getElementById('prompt-modal-input');
    const saveBtn = document.getElementById('prompt-modal-save');
    const cancelBtn = document.getElementById('prompt-modal-cancel');
    if (!modal || !input || !saveBtn || !cancelBtn || !labelEl) { resolve(null); return; }
    labelEl.textContent = label;
    let errorEl = document.getElementById('prompt-modal-error');
    if (!errorEl) {
      errorEl = document.createElement('p');
      errorEl.id = 'prompt-modal-error';
      errorEl.setAttribute('role', 'alert');
      errorEl.style.color = 'var(--red, #d93025)';
      input.insertAdjacentElement('afterend', errorEl);
    }
    errorEl.textContent = error;
    errorEl.hidden = !error;
    input.setAttribute('aria-invalid', error ? 'true' : 'false');
    input.setAttribute('aria-describedby', 'prompt-modal-error');
    input.value = defaultValue;
    modal.hidden = false;
    setTimeout(() => { try { input.focus(); input.select(); } catch (_) {} }, 0);

    const cleanup = () => {
      modal.hidden = true;
      saveBtn.removeEventListener('click', onSave);
      cancelBtn.removeEventListener('click', onCancel);
      input.removeEventListener('keydown', onKey);
    };
    const onSave = () => { const v = (input.value || '').trim(); cleanup(); resolve(v || null); };
    const onCancel = () => { cleanup(); resolve(null); };
    const onKey = (e) => {
      if (e.key === 'Enter') { e.preventDefault(); onSave(); }
      else if (e.key === 'Escape') { e.preventDefault(); onCancel(); }
    };
    saveBtn.addEventListener('click', onSave);
    cancelBtn.addEventListener('click', onCancel);
    input.addEventListener('keydown', onKey);
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Server Log Panel
// ─────────────────────────────────────────────────────────────────────────────
// Phase 2.8.19 (B3) — unified log: server lines render into a sub-container
// inside #log-panel when the "Show server lines" checkbox is on. The inline
// #server-log-panel was deleted; the sidebar "Open log" button now scrolls to
// Live Status and expands it.
function openUnifiedLog() {
  // v2.86.1 (port): explicit request to see the log — reveal Live Status even
  // when idle, then scroll to it. Without forcing, scrollToSection targets a
  // display:none element and nothing happens.
  _suppressFinishedSection = false;  // explicit "Open log" overrides suppression
  liveStatusForcedOpen = true;
  try { syncLiveStatusVisibility(); } catch (_) { /* */ }
  // Re-uses scrollToSection so the dashboard → wizard route swap happens
  // automatically when the operator clicks "Open log" from outside the wizard.
  scrollToSection('nav-status');
}

async function refreshServerLines() {
  const cb = document.getElementById('show-server-lines');
  if (!cb || !cb.checked) return;
  const panel = document.getElementById('log-panel');
  if (!panel) return;
  try {
    const res = await fetch('/api/server-log');
    if (!res.ok) return;
    const lines = await res.json();
    let container = panel.querySelector('#server-lines-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'server-lines-container';
      panel.appendChild(container);
    }
    container.innerHTML = lines.map((line) => {
      let cls = 'info';
      if (line.includes('[ERR]')) cls = 'err';
      else if (line.includes('[WARN]')) cls = 'warn';
      return `<div class="entry ${cls}" style="opacity:.6"><span style="color:var(--gray); font-size:0.6rem; letter-spacing:0.14em; margin-right:6px; text-transform:uppercase">srv</span>${escHtml(line)}</div>`;
    }).join('');
  } catch (_) { /* */ }
}

document.addEventListener('change', (e) => {
  if (e.target && e.target.id === 'show-server-lines') {
    if (e.target.checked) {
      refreshServerLines();
      if (!serverLogInterval) serverLogInterval = setInterval(refreshServerLines, 4000);
    } else {
      if (serverLogInterval) { clearInterval(serverLogInterval); serverLogInterval = null; }
      const panel = document.getElementById('log-panel');
      const container = panel?.querySelector('#server-lines-container');
      if (container) container.remove();
    }
  }
});

async function clearServerLog() {
  // Backwards-compat name kept in case any other module calls it.
  // Hits the backend ring buffer DELETE and removes the local sub-container.
  try { await fetch('/api/server-log', { method: 'DELETE' }); } catch { /* */ }
  const panel = document.getElementById('log-panel');
  const container = panel?.querySelector('#server-lines-container');
  if (container) container.innerHTML = '';
  try { localStorage.setItem('ortus-log-cleared-at', new Date().toISOString()); } catch (_) {}
}

// Note: the previous standalone server-log helpers were removed in 2.8.19.
// The unified Copy Log / Clear Log buttons handle the campaign log; server lines
// live inside #log-panel so they're included in those operations automatically.

function clearCampaignLog() {
  const el = document.getElementById('log-panel');
  if (!el) return;
  // Persist a cutoff so the log stays cleared across reloads / poll updates.
  try { localStorage.setItem('ortus-log-cleared-at', new Date().toISOString()); } catch (_) {}
  el.innerHTML = '<div class="entry info">Log cleared.</div>';
  const feed = document.getElementById('rp-feed-list');
  if (feed) feed.innerHTML = '<div class="rp-feed-item"><span class="rp-feed-time">—</span><span class="rp-feed-text">Waiting for campaign…</span></div>';
}

function copyCampaignLog() {
  const el = document.getElementById('log-panel');
  if (!el) return;
  const text = Array.from(el.querySelectorAll('.entry')).map(e => e.textContent).join('\n');
  navigator.clipboard.writeText(text).then(() => {
    const btn = el.previousElementSibling?.querySelector('button');
    if (btn) {
      const orig = btn.textContent;
      btn.textContent = 'Copied!';
      setTimeout(() => { btn.textContent = orig; }, 1500);
    }
  });
}
let pollInterval = null;
let wasRunning = false;
let wasErrorCount = 0;

// Dynamic placeholder tags from sheet columns
let sheetColumns = ['firstName', 'lastName', 'company', 'title'];

// SoO (State of Operations) data — email → status mapping
let sooData = {}; // { 'email@ortus.com': { linkedinCredits: 'In Use', linkedinUser: '...', ... } }
let sooLoadState = 'idle'; // 'idle' | 'loading' | 'ok' | 'stale' | 'error'

function setSoOErrorState(isError, message = 'SoO unavailable — click refresh to try again') {
  const pill = document.getElementById('rp-soo-error');
  if (pill) {
    pill.hidden = !isError;
    if (isError) pill.textContent = message;
  }
}

async function loadSoOStatus({ force = false } = {}) {
  sooLoadState = 'loading';
  try {
    const res = await fetch(force ? '/api/soo-status?refresh=1' : '/api/soo-status');
    // Server returns 503 + { error, errorCode } on any failure now.
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const d = await res.json(); if (d && d.error) detail = `${d.errorCode || 'ERR'}: ${d.error}`; } catch {}
      console.warn('[SoO] Endpoint error:', detail);
      const hasLastGood = Object.keys(sooData).length > 0;
      sooLoadState = hasLastGood ? 'stale' : 'error';
      setSoOErrorState(true, hasLastGood
        ? 'Showing the last saved SoO — Google is temporarily unavailable'
        : 'SoO unavailable — account status is unknown');
      return;
    }
    const data = await res.json();
    sooData = {};
    for (const acct of (data.accounts || [])) {
      if (acct.email) sooData[acct.email.toLowerCase()] = acct;
    }
    const stale = data._sooMeta && data._sooMeta.state === 'stale';
    sooLoadState = stale ? 'stale' : 'ok';
    setSoOErrorState(stale, 'Showing the last saved SoO — Google is temporarily unavailable');
    console.log(`[SoO] Loaded ${Object.keys(sooData).length} account statuses`);
  } catch (err) {
    console.warn('[SoO] Failed to load:', err.message);
    const hasLastGood = Object.keys(sooData).length > 0;
    sooLoadState = hasLastGood ? 'stale' : 'error';
    setSoOErrorState(true, hasLastGood
      ? 'Showing the last saved SoO — Google is temporarily unavailable'
      : 'SoO unavailable — account status is unknown');
  }
}

// GoLogin profile name IS the SoO email (team convention). Exact,
// case-insensitive match only — no fuzzy substring matching, which used to
// cause one operator's credit status to appear on a different profile.
// v2.102.0: GoLogin can hold more than one profile with the same login email (a
// profile got duplicated). The picker keys accounts by name (= email), so the
// duplicate shows as two identical cards while SoO has a single row (Sam:
// "two of this guy, only one in SoO"). Keep the first profile per email, hide
// the rest from the picker, and tag the survivor with how many we hid so the
// card can flag it — auto-hidden, but not silently (clean up in GoLogin).
// Keyed by workspace + email, not email alone: the list now spans two GoLogin
// accounts, and the same person can legitimately exist in both. On a bare email
// key the Ortus copy (listed first) would silently hide the Linked Velocity one
// and its owner would lose their account from the picker. A duplicate is only a
// duplicate inside one workspace anyway — that is where the operator goes to
// delete it.
// "Follower Growth and Post Amplification" from the raw mode ids the server
// ships. Only the marketing workspace has a list today; the fallback keeps this
// honest if another restricted workspace is ever added.
const MODE_DISPLAY_NAMES = {
  follower_growth: 'Follower Growth',
  post_amplification: 'Post Amplification',
};
function modeNames(modes) {
  if (!Array.isArray(modes) || !modes.length) return 'nothing';
  const names = modes.map((m) => MODE_DISPLAY_NAMES[m] || m);
  if (names.length === 1) return names[0];
  return names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
}

function dedupeKey(p) {
  const email = ((p && p.name) || '').toLowerCase().trim();
  if (!email) return '';
  return ((p && p.account) || '') + '|' + email;
}

// id → GoLogin label (the account's email), built from the RAW profile list.
// Deliberately NOT from allProfilesData: that one is deduped by email, and the
// duplicates it drops are still perfectly valid ids that a campaign can be
// running on. A selected account whose id was deduped away had no tile to
// backfill its name, so every "|| id" fallback printed a raw 24-hex GoLogin id
// where the operator expects an email (report 2026-08-17: a campaign's existing
// account showed as "690d87f15906fbc1eaedffeb" next to a normal address).
const _profileNameById = new Map();
function _indexProfileNames(profiles) {
  for (const p of (profiles || [])) {
    const nm = String((p && p.name) || '').trim();
    if (p && p.id && nm) _profileNameById.set(p.id, nm);
  }
}

/**
 * What to call a GoLogin profile in the UI. Never invents a name; falls back to
 * the raw id only when nothing anywhere knows this account.
 */
function profileLabel(id) {
  if (!id) return '';
  const picked = selectedProfileNames[id];
  if (picked) return picked;
  const known = _profileNameById.get(id);
  if (known) { selectedProfileNames[id] = known; return known; } // memoise for the next render
  // A cloud campaign's own account list carries the email the engine stamped.
  try {
    for (const accounts of _cloudAccountsById.values()) {
      const hit = (accounts || []).find((a) => a && a.profileId === id && a.email);
      if (hit) return hit.email;
    }
  } catch (_) { /* board snapshot not loaded yet */ }
  return id;
}
window.profileLabel = profileLabel;

function dedupeProfilesByEmail(profiles) {
  const seen = new Map();   // key -> kept profile
  const hidden = new Map(); // key -> count hidden
  const out = [];
  for (const p of (profiles || [])) {
    const key = dedupeKey(p);
    if (!key) { out.push(p); continue; }                 // unnamed → never dedupe away
    if (seen.has(key)) { hidden.set(key, (hidden.get(key) || 0) + 1); continue; }
    seen.set(key, p);
    out.push(p);
  }
  for (const p of out) {
    const key = dedupeKey(p);
    if (hidden.has(key)) p._dupHidden = hidden.get(key);
  }
  return out;
}

// v2.102.0: isRestrictedStatus moved to account-guardrails.mjs (imported above).
// SoO column B "Status" — block accounts the SoO marks unusable.
// Restricted dropdown values: "Identity Restricted", "Identity Restricted II",
// "Unjust Identity Restricted", "Hard Identity Restricted" (all contain
// "restricted"); "Inaccessible" is also unusable. Active/Construction/Rented/?
// stay selectable. getSoO returns every column raw, so soo['Status'] is present.

// v2.102.0: at least one channel (OP/InMail/SN/CC) currently shows 'available'.
function hasAvailableChannel(soo) {
  if (!soo) return false;
  return [soo.linkedinCredits, soo.inmailCredits, soo.salesNavCredits, soo.ccCredits]
    .some((v) => (v || '').toString().toLowerCase().trim() === 'available');
}

// v2.102.0: "Available now" preset = ready to use right now — NOT restricted/
// inaccessible AND has at least one free channel.
function isAvailableNow(soo) {
  if (!soo) return false;
  return !isRestrictedStatus(soo['Status'] || soo['status']) && hasAvailableChannel(soo);
}

function findSoOForProfile(profileName) {
  if (!profileName || Object.keys(sooData).length === 0) return null;
  // lookupSoO matches the bare email first, then the email embedded in a
  // decorated GoLogin name (e.g. "ryan.ceballo@ortus.solutions [1]"). Exact
  // string match alone left those accounts showing FREE.
  return lookupSoO(sooData, profileName);
}

// Manual SoO refresh — wired to the "Refresh SoO" button in the Accounts
// section. Drives a 10-second horizontal progress bar during the fetch.
async function refreshSoO() {
  const btn = document.getElementById('refresh-soo-btn');
  const bar = document.getElementById('refresh-soo-bar');
  if (btn) btn.disabled = true;
  if (bar) {
    bar.style.transition = 'none';
    bar.style.width = '0%';
    // force reflow so the next transition actually animates
    void bar.offsetWidth;
    bar.style.transition = 'width 10s linear';
    bar.style.width = '100%';
  }
  try {
    await loadSoOStatus({ force: true });
    if (allProfilesData.length > 0) renderProfiles(allProfilesData);
    updateChipCounts();
    updateGreeting();
  } finally {
    if (bar) {
      // Snap to 100% (covers early-success case), then reset after a beat
      bar.style.transition = 'width 200ms ease-out';
      bar.style.width = '100%';
      setTimeout(() => {
        if (!bar) return;
        bar.style.transition = 'none';
        bar.style.width = '0%';
      }, 400);
    }
    if (btn) btn.disabled = false;
  }
}

function renderSoOBadges(soo) {
  if (!soo) return '';

  const isPool = (soo.section || '').toLowerCase().includes('pool') ||
                 (soo.section || '').toLowerCase().includes('unassigned');

  // Assignee line
  let assigneeLine = '';
  const assignee = (soo['Assignee'] || '').trim();
  if (isPool) {
    assigneeLine = `<div class="soo-user">Pool — free for all</div>`;
  } else if (assignee && assignee !== '-') {
    assigneeLine = `<div class="soo-user">Assigned: ${escHtml(assignee)}</div>`;
  }

  const segClass = (v) => {
    const s = (v || '').toLowerCase().replace(/\s+/g, '-');
    if (s === 'available') return 'available';
    if (s === 'in-use') return 'in-use';
    if (s === 'used') return 'used';
    if (s === 'n/a' || s === 'na') return 'na';
    return '';
  };
  const title = (label, v) => `${label}: ${v || '—'}`;
  const hasAny = soo.linkedinCredits || soo.inmailCredits || soo.salesNavCredits || soo.ccCredits;
  const bar = hasAny
    ? `<div class="status-bar status-bar-4">
         <div class="status-seg ${segClass(soo.linkedinCredits)}" title="${escHtml(title('OP', soo.linkedinCredits))}"></div>
         <div class="status-seg ${segClass(soo.inmailCredits)}" title="${escHtml(title('InMail', soo.inmailCredits))}"></div>
         <div class="status-seg ${segClass(soo.salesNavCredits)}" title="${escHtml(title('Sales Nav', soo.salesNavCredits))}"></div>
         <div class="status-seg ${segClass(soo.ccCredits)}" title="${escHtml(title('CC', soo.ccCredits))}"></div>
       </div>
       <div class="status-legend"><span>OP</span><span>InM</span><span>SN</span><span>CC</span></div>`
    : '';

  return `${assigneeLine}${bar}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Passover countdowns
// ─────────────────────────────────────────────────────────────────────────────

function getPassoverStatus() {
  // PH time = UTC+8
  const now = new Date();
  const phNow = new Date(now.getTime() + (8 * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));
  const phDay = phNow.getDay();   // 0=Sun … 6=Sat
  const phDate = phNow.getDate(); // 1-31
  const lastDay = new Date(phNow.getFullYear(), phNow.getMonth() + 1, 0).getDate();

  // Monthly (OP / InMail / Sales Nav): ACTIVE 16th → end of month, INACTIVE 1st → 15th
  let monthly;
  if (phDate >= 16) {
    monthly = { active: true, label: `ACTIVE — closes in ${lastDay - phDate + 1}d` };
  } else {
    monthly = { active: false, label: `in ${16 - phDate}d` };
  }

  // Weekly CC: ACTIVE Thu → Sun, INACTIVE Mon → Wed
  const ccIsActive = phDay === 0 || phDay >= 4;
  let cc;
  if (ccIsActive) {
    const daysToMon = (1 - phDay + 7) % 7; // Sun=1, Thu=4, Fri=3, Sat=2
    cc = { active: true, label: `ACTIVE — closes in ${daysToMon}d` };
  } else {
    const daysToThu = (4 - phDay + 7) % 7; // Mon=3, Tue=2, Wed=1
    cc = { active: false, label: `in ${daysToThu}d` };
  }

  return { monthly, cc };
}

function renderPassoverBanner() {
  const container = document.getElementById('passover-banner');
  const { monthly, cc } = getPassoverStatus();

  const fmt = (info) => {
    const cls = info.active ? ' class="passover-active"' : ' class="passover-closed"';
    return `<strong${cls}>Passover ${info.label}</strong>`;
  };

  if (container) {
    container.innerHTML = `
      <span>OP / InMail / Sales Nav — ${fmt(monthly)}</span>
      <span style="margin-left:16px">CC — ${fmt(cc)}</span>
    `;
  }

  // Hero card mirror — two mini pills, one per passover window, so GDs see
  // Monthly and Weekly state at a glance instead of a single misleading label.
  const heroOp = document.getElementById('hero-passover-op');
  const heroCc = document.getElementById('hero-passover-cc');
  if (heroOp) {
    heroOp.className = 'passover-pill ' + (monthly.active ? 'active' : 'closed');
    heroOp.title = `OP · InMail · Sales Nav — ${monthly.label}`;
  }
  if (heroCc) {
    heroCc.className = 'passover-pill ' + (cc.active ? 'active' : 'closed');
    heroCc.title = `CC — ${cc.label}`;
  }

  // Right-pane mirror
  const opState = document.getElementById('rp-op-state');
  const opDetail = document.getElementById('rp-op-detail');
  const ccState = document.getElementById('rp-cc-state');
  const ccDetail = document.getElementById('rp-cc-detail');
  if (opState) {
    opState.textContent = monthly.active ? 'Active' : 'Closed';
    opState.className = 'rp-passover-state ' + (monthly.active ? 'active' : 'closed');
  }
  if (opDetail) opDetail.textContent = monthly.label.replace(/^ACTIVE — /, '').replace(/^in /, 'Opens in ');
  if (ccState) {
    ccState.textContent = cc.active ? 'Active' : 'Closed';
    ccState.className = 'rp-passover-state ' + (cc.active ? 'active' : 'closed');
  }
  if (ccDetail) ccDetail.textContent = cc.label.replace(/^ACTIVE — /, '').replace(/^in /, 'Opens in ');

  // v2.112.10 (Window C): big banner at the top of section 3. Pull the day
  // count out of the label (e.g. "ACTIVE — closes in 12d" / "in 4d" → "12d"),
  // falling back to the raw label if no digit-d match. State = ● Active/Closed
  // with a green/gray class.
  const days = (label) => {
    const m = String(label || '').match(/(\d+d)/);
    return m ? m[1] : (label || '—');
  };
  // Phase-aware: an "active" window = post-passover (accounts not yet used are
  // AVAILABLE/green for everyone); an "inactive" window = start of the cycle
  // (accounts are locked to their assignees, ASSIGNED/blue). The note says the
  // NEXT change, not a misleading "Resets <day>".
  const setBannerWindow = (info, daysId, stateId, noteId, freeDay, lockDay) => {
    const daysEl = document.getElementById(daysId);
    const stateEl = document.getElementById(stateId);
    const noteEl = document.getElementById(noteId);
    if (daysEl) daysEl.textContent = days(info.label);
    if (stateEl) {
      stateEl.textContent = info.active ? 'Available' : 'Assigned';
      stateEl.className = 'acct-cd-s ' + (info.active ? 'pass-on' : 'pass-assigned');
    }
    if (noteEl) noteEl.textContent = info.active ? ('Re-locks ' + lockDay) : ('Frees ' + freeDay);
  };
  setBannerWindow(monthly, 'pass-monthly-days', 'pass-monthly-state', 'pass-monthly-note', 'the 16th', 'the 1st');
  setBannerWindow(cc, 'pass-cc-days', 'pass-cc-state', 'pass-cc-note', 'Thursday', 'Monday');
}

// ─────────────────────────────────────────────────────────────────────────────
// Profiles
// ─────────────────────────────────────────────────────────────────────────────
async function loadProfiles() {
  const loading = document.getElementById('profiles-loading');
  const grid = document.getElementById('profiles-grid');
  loading.textContent = 'Loading profiles…';
  loading.classList.remove('hidden');
  grid.classList.add('hidden');

  try {
    // Fetch profiles first — render immediately, don't wait for SoO
    const profilesRes = await fetch('/api/profiles');
    const profiles = await profilesRes.json();
    if (profiles.error) { loading.textContent = `Error: ${profiles.error}`; return; }
    _indexProfileNames(profiles); // BEFORE the dedupe — hidden duplicates keep their labels
    allProfilesData = dedupeProfilesByEmail(profiles);
    loading.classList.add('hidden');
    grid.classList.remove('hidden');
    await loadPrimaryStatusForPicker();
    renderProfiles(allProfilesData);
    renderPassoverBanner();
    updateChipCounts();

    // SoO loads in background — re-render profiles + refresh counts when it arrives
    loadSoOStatus().then(() => {
      // Repaint on success AND failure: on an initial outage the cards must
      // change from CHECKING SoO to SoO UNAVAILABLE, never NOT IN SoO.
      renderProfiles(allProfilesData);
      // v2.94.x: also refresh the primary-source picker + read-only labels so a
      // restored GoLogin primary shows its badges/name once SoO arrives.
      if (typeof renderPrimarySourcePicker === 'function') renderPrimarySourcePicker(document.getElementById('primary-source-search')?.value || '');
      if (typeof refreshPrimarySourceLabels === 'function') refreshPrimarySourceLabels();
      updateChipCounts();
      // Refresh greeting now that we can look up the GD's real first
      // name from the First Name column of the State of Operations sheet.
      updateGreeting();
      // Replace the email-fallback in "My identifier for Assigned" with the
      // operator's actual first name from SoO, so the "Assigned to me" chip
      // count matches (the Assignee column is first names, not emails).
      refreshIdentifierDefault();
    }).catch(() => {});
    // Refresh countdown every minute — guard against duplicate timers so
    // multiple loadProfiles() calls don't stack intervals.
    if (!window.__passoverInterval) {
      window.__passoverInterval = setInterval(renderPassoverBanner, 60000);
    }
  } catch (err) {
    loading.textContent = `Failed: ${err.message}`;
  }
}

function renderProfiles(profiles) {
  const grid = document.getElementById('profiles-grid');
  grid.innerHTML = '';

  // Local Browser — rendered into a dedicated host above the GoLogin grid.
  // It has unique semantics (local Chromium, not Orbita) and the first-name
  // input is gated behind the checkbox: we only ask once the operator opts in.
  const localHost = document.getElementById('local-browser-host');
  if (localHost) {
    const isSelected = selectedProfileIds.includes('local-browser');
    localHost.innerHTML = '';
    const localItem = document.createElement('label');
    localItem.className = 'profile-item local-browser local-browser-tile' + (isSelected ? ' selected' : '');
    localItem.dataset.profileId = 'local-browser';
    localItem.innerHTML = `
      <input type="checkbox" class="local-cb" value="local-browser" ${isSelected ? 'checked' : ''} />
      <div class="local-browser-body">
        <div class="name">Local Browser</div>
        <div class="id">Your system Chrome. If this is your first time, you will have to log in to LinkedIn when the Chrome browser pops up locally.</div>
        <div class="local-browser-name-row" ${isSelected ? '' : 'hidden'}>
          <label for="local-browser-first-name" class="local-browser-name-label">Your first name (used as {senderFirstName})</label>
          <input type="text" id="local-browser-first-name" placeholder="e.g. Antonio"
            value="${escHtml(localBrowserFirstName)}" />
        </div>
      </div>
    `;
    const localNameRow = localItem.querySelector('.local-browser-name-row');
    const localNameInput = localItem.querySelector('#local-browser-first-name');
    localNameInput.addEventListener('click', (e) => e.stopPropagation());
    localNameInput.addEventListener('input', (e) => {
      localBrowserFirstName = e.target.value;
      try { localStorage.setItem('localBrowserFirstName', localBrowserFirstName); } catch { /* */ }
      renderSelectedPanel();
    });
    const localCb = localItem.querySelector('input.local-cb');
    localCb.addEventListener('change', () => {
      if (localCb.checked) {
        if (!selectedProfileIds.includes('local-browser')) {
          selectedProfileIds.push('local-browser');
          selectedProfileNames['local-browser'] = 'Local Browser';
        }
        localItem.classList.add('selected');
        if (localNameRow) {
          localNameRow.hidden = false;
          // Auto-focus the name input the first time someone ticks the box —
          // makes the "now we need your name" interaction feel obvious.
          if (!localNameInput.value) setTimeout(() => localNameInput.focus(), 0);
        }
      } else {
        selectedProfileIds = selectedProfileIds.filter(id => id !== 'local-browser');
        delete selectedProfileNames['local-browser'];
        localItem.classList.remove('selected');
        if (localNameRow) localNameRow.hidden = true;
      }
      renderSelectedPanel();
      // The Local Browser counts as an account toward the 2+-account parallel
      // unlock and the throughput math — recompute, matching the GoLogin handler.
      updateCampaignSummary();
    });
    localHost.appendChild(localItem);
  }

  // v2.112.10 (Window C, free-first): compute each profile's state ONCE so we can
  // both sort (usable accounts first) and render from the same value. State comes
  // only from classifyAccountState (SoO) — no invented status.
  const _mode = document.getElementById('campaign-mode')?.value || '';
  const _passover = getPassoverStatus();
  const _meId = getMyIdentifier();
  // Breakdown modes (Message Campaign / Direct Messages / InMail Only) don't use
  // CC, so the tile shows every non-CC channel divided; all other modes collapse
  // to one CC/credit verdict (the two-zone tile).
  const _breakdown = isBreakdownMode(_mode);
  const _RANK = { 'free': 0, 'assigned': 1, 'in-use': 2, 'blocked': 3 };
  // Accounts under the SoO "Construction" section never show in the launcher.
  // SoO loads after the first render, so pre-SoO these can't be identified yet;
  // the post-SoO re-render (loadProfiles) drops them once their section is known.
  const _visible = profiles.filter((p) => !isHiddenSection(findSoOForProfile(p.name)));
  // v2.160.138: `available === false` means the profile belongs to a GoLogin
  // workspace this operator isn't in (Linked Velocity vs Ortus — see
  // src/gologin-accounts.js). Those tiles stay in the roster so the account list
  // reads the same for everyone, but they sort below everything usable and can
  // never be picked. The server re-checks on launch; this is only the UI half.
  const _ordered = _visible
    .map((p, i) => {
      const soo = findSoOForProfile(p.name);
      // Unusable-here tiles sink below everything selectable. Wrong-mode sorts
      // above wrong-workspace because switching campaign type brings it back.
      const foreignBump = p.available === false ? 10
        : (Array.isArray(p.allowedModes) && !p.allowedModes.includes(_mode)) ? 5 : 0;
      // Ortus Basics 1.0: breakdown tiles are disabled (_showBreakdown = false),
      // so every profile needs a `st` for the two-zone tile renderer. Skip the
      // breakdown sorting path entirely — classifyAccountState handles all modes.
      const st = classifyAccountState(soo, _meId, _mode, _passover);
      return { p, i, soo, st, rank: (_RANK[st.state] ?? 9) + foreignBump };
    })
    .sort((a, b) => (a.rank - b.rank) || (a.i - b.i)); // stable within rank

  _ordered.forEach(({ p, soo: _soo, st: _state, br: _br }) => {
    // 'blocked' / unusable is never selectable (greyed + disabled). Single-verdict
    // modes: blocked when classifyAccountState says so (restricted, or the CC/credit
    // column is NA/Used/etc.). Breakdown modes: blocked when restricted OR no channel
    // is Available (nothing usable for this campaign right now).
    // Another GoLogin workspace's account — visible, never selectable, and
    // locked for a reason SoO knows nothing about, so it's OR'd in separately.
    const _foreign = p.available === false;
    // Right workspace, wrong job: the marketing accounts run Follower Growth
    // and Post Amplification only. Tracked apart from _foreign because it is
    // fixable — switching campaign type unlocks the tile — and the copy has to
    // say so rather than implying the operator lacks access.
    const _wrongMode = !_foreign && Array.isArray(p.allowedModes) && !p.allowedModes.includes(_mode);
    // The SoO governs the ORTUS roster. It does not govern another workspace's
    // accounts, so it does not gate them at all: not the credit columns, not the
    // Status. Measured 2026-09-02: of 58 Linked Velocity profiles, 11 read
    // "Rented / NA" precisely BECAUSE Linked Velocity has them and 8 more carried
    // a stale Ortus Status — every one of them greyed for the only people
    // entitled to use them. Operator decision the same day: the workspace that
    // owns an account is the one that knows its health, so its operators pick
    // freely and the SoO line is shown as information, never as a lock.
    // `guest` covers the other half: an Ortus-owned account handed to another
    // team by a grant. The SoO parks those under "DO NOT USE" with NA credits
    // precisely to keep Ortus operators off them, which must not be enforced
    // against the team they were handed to.
    const _nonOrtusRoster = !_foreign && ((!!p.account && p.account !== 'ortus') || p.guest === true);
    // Ortus Basics 1.0: the per-channel breakdown tile (SN OP / LN OP / INMAIL
    // with their SoO statuses, the availability accent and the assignee lock
    // pill) is never used — the picker shows account names only and the operator
    // decides what is usable. Forcing false here routes every tile through the
    // plain name-only branch below. (was: _breakdown && !!_soo)
    const _showBreakdown = false;
    // Before the first successful snapshot, absence is UNKNOWN rather than
    // proof that this account is missing from SoO. Keep Ortus accounts locked
    // until their credits/restrictions can actually be checked. A stale snapshot
    // remains usable and is visibly labelled at the panel level.
    // Ortus Basics 1.0: the SoO does not gate the picker — the operator
    // decides what is usable. Locking is disabled entirely.
    const _sooLock = false;
    const _locked = _foreign || _wrongMode || _sooLock;
    // Defensive: a restored preset/schedule must not keep a now-unusable account
    // selected — drop it (before building the tile so `checked` reflects reality).
    // Ortus Basics 1.0: nothing is locked in this build, so a re-render (a new
    // search, a roster refresh) must not silently drop an already-picked account.
    // (was: _locked → prune from selectedProfileIds)
    if (selectedProfileIds.includes(p.id)) selectedProfileNames[p.id] = p.name;
    const _checked = selectedProfileIds.includes(p.id) ? 'checked' : '';
    const _disabled = _locked ? 'disabled' : '';
    const _dup = p._dupHidden ? ` <span class="dup-flag" title="${escHtml(p._dupHidden + ' other GoLogin profile(s) share this email — hidden here. Delete the duplicate(s) in GoLogin.')}">⚠ dup</span>` : '';
    // Name the owning workspace on foreign tiles only. On your own accounts the
    // pill would be noise — every tile would carry it.
    const _wsPill = (_foreign || _wrongMode)
      ? ` <span class="ws-flag" title="${escHtml(_foreign
          ? `This account lives in the ${p.accountLabel || 'other'} GoLogin workspace. Sign in with a ${p.accountLabel || 'matching'} email to use it.`
          : `${p.accountLabel || 'This'} accounts run ${modeNames(p.allowedModes)} only.`)}">${escHtml(p.accountLabel || 'other workspace')}</span>`
      : '';

    let _classes, _inner;
    if (_showBreakdown) {
      // Variant C — clean per-channel breakdown: thin accent (green if any channel
      // free) + email + a 3-cell row showing each channel's RAW SoO status verbatim.
      const _cells = (_br.channels || []).map((c) => {
        const v = (c.status || '').toLowerCase().trim();
        const dot = v === 'available' ? 'd-avail'
          : v === 'in use' ? 'd-inuse'
          : (v === 'na' || v === 'n/a' || v.includes('inaccessible')) ? 'd-na'
          : 'd-spent'; // used / - / blank / other
        // Operator preference: don't print the verbose "Partial Inaccessible" —
        // show it as NA (it can't be accessed). Everything else shown verbatim.
        const txt = /inaccessible/i.test(c.status) ? 'NA' : (c.status ? escHtml(c.status) : '—');
        const who = c.who ? ' · ' + escHtml(c.who) : '';
        const title = c.who ? `In use by ${escHtml(c.who)}` : txt;
        return `<div class="brk-col"><div class="brk-k">${escHtml(c.label)}</div>`
          + `<div class="brk-v" title="${title}"><i class="brk-vdot ${dot}"></i><span class="brk-vt">${txt}${who}</span></div></div>`;
      }).join('');
      // locked (no credits anywhere) → heavy mute; selectable-but-no-free-channel
      // (all In Use) → light mute, like a busy Connect tile; has a free channel → full.
      _classes = 'profile-item jt jt-brk'
        + (_checked ? ' selected' : '')
        + (_locked ? ' muted' : (!_br.anyFree ? ' muted-soft' : ''))
        + (_br.blocked ? ' is-restricted' : '');
      // Accent (left "lip") reflects the best channel: green if any Available,
      // else gold if any In Use (even alongside reds), grey only when nothing's active.
      const _accent = _br.anyFree ? ' free' : (_br.anyActive ? ' busy' : '');
      // Owner pill (V1): the account is locked to its SoO Assignee for the monthly
      // cycle (only they should use it until passover frees it on the 16th).
      const _asg = breakdownAssignee(_soo, _meId, _passover);
      const _asgPill = _asg ? `<span class="asg-tag" title="Assigned to ${escHtml(_asg)} until the 16th">\u{1F512} ${escHtml(_asg)}</span>` : '';
      _inner = `
      <div class="brk-accent${_accent}"></div>
      <div class="jt-det">
        <div class="jt-top">
          <input type="checkbox" value="${p.id}" ${_checked} ${_disabled} />
          <span class="jt-email">${escHtml(p.name)}${_dup}${_wsPill}</span>${_asgPill}
        </div>
        <div class="brk-grid">${_cells}</div>
      </div>`;
    } else {
      // Two-zone tile: classifyAccountState collapses SoO assignee + status +
      // live-use + passover into one of four states; tinted stat zone + one sub line.
      const _SMAP = {
        'free':     { cls: 'free',     word: 'FREE' },
        'assigned': { cls: 'assigned', word: 'ASSIGNED' },
        'in-use':   { cls: 'inuse',    word: 'IN USE' },
        'blocked':  { cls: 'stop',     word: 'BLOCKED' },
      };
      // No SoO row at all — 57 of 481 GoLogin profiles on 2026-07-31 (12%), mostly
      // non-LinkedIn profiles that were never meant to be senders (zoominfo_ii,
      // chatgpt/claude, the Luma tabs) plus accounts genuinely missing from the
      // sheet. Without a row there is no first name, no credits and no assignee, so
      // the tile CANNOT be trusted — say so instead of defaulting to a green FREE.
      const _noSoo = !_soo;
      const _sooUnavailable = _noSoo && sooLoadState === 'error';
      const _sooPending = _noSoo && (sooLoadState === 'idle' || sooLoadState === 'loading');
      const _sm = _noSoo
        ? { cls: 'nosoo', word: _sooUnavailable ? 'SoO UNAVAILABLE' : (_sooPending ? 'CHECKING SoO' : 'NOT IN SoO') }
        : (_SMAP[_state.state] || _SMAP.free);
      // 'blocked' worded from what the SoO actually says (no invented copy):
      //   restricted → LinkedIn block · na → CC/credit = NA · unavailable → Used/-/Partial.
      const _reason = (_state.state === 'blocked') ? (_state.reason || 'restricted') : '';
      const _label = escHtml(_state.label || '');
      // An Ortus-ledger verdict no longer locks another workspace's tile, so it
      // must not still read "N/A · no credits" on a tile the operator can pick.
      // The verdict is still worth saying — it is why the account looks odd — so
      // it moves into the sub line, attributed, instead of disappearing.
      const _otherRosterVerdict = _nonOrtusRoster && !_noSoo && _state.state === 'blocked';
      // A foreign-workspace account reads OTHER TEAM, never FREE — its SoO row
      // may well say Available, but not to this operator.
      const _word = _foreign ? 'OTHER TEAM'
        : _wrongMode ? 'WRONG MODE'
          : _otherRosterVerdict ? 'OTHER ROSTER'
            : (_noSoo ? _sm.word : ((_reason === 'na' || _reason === 'unavailable') ? 'N/A' : _sm.word));
      const _statCls = (_foreign || _wrongMode) ? 'stop' : _otherRosterVerdict ? 'nosoo' : _sm.cls;
      let _sub;
      if (_sooUnavailable) _sub = 'Could not check the SoO — status unknown and selection disabled.';
      else if (_sooPending) _sub = 'Checking the SoO now — selection stays disabled until confirmed.';
      else if (_noSoo) _sub = 'Not in the SoO — no first name or credits.';
      else
      // v2.112.27: operator asked to drop "who uses who" from the picker for now —
      // show bare states (the who is still in classifyAccountState/the log if needed).
      if (_state.state === 'assigned') _sub = 'Assigned.';
      else if (_state.state === 'in-use') _sub = 'In use.';
      else if (_state.state === 'blocked') {
        if (_reason === 'na') _sub = 'No credits for this campaign.';
        else if (_reason === 'unavailable') _sub = _label ? `Not available — <b>${_label}</b>.` : 'Not available for this campaign.';
        else _sub = '<b>Identity Restricted</b> in the SoO · selection disabled.';
      } else _sub = 'Anyone can use.';
      // Workspace beats every SoO verdict: an account you cannot drive at all is
      // not "free", whatever its credits say.
      if (_otherRosterVerdict) {
        // Say what Ortus's sheet claims and whose account it actually is, so the
        // operator can act on it. Hiding the verdict would be as wrong as
        // enforcing it.
        const _raw = String((_soo && (_soo.Status || _soo.status)) || '').trim();
        const _said = _reason === 'restricted'
          ? (_raw || 'Restricted')
          : _reason === 'na' ? 'no credits' : (String(_state.label || '').trim() || 'not available');
        _sub = `${escHtml(p.accountLabel || 'This')} workspace runs this account. Ortus's SoO says <b>${escHtml(_said)}</b>.`;
      }
      if (_foreign) _sub = `${escHtml(p.accountLabel || 'Another')} workspace — sign in with a ${escHtml(p.accountLabel || 'matching')} email to use it.`;
      else if (_wrongMode) _sub = `${escHtml(p.accountLabel || 'These')} accounts run ${escHtml(modeNames(p.allowedModes))} only.`;
      const _statZone = `
      <div class="jt-stat s-${_statCls}">
        <span class="jt-dot"></span>
        <span class="jt-word">${_word}</span>
      </div>`;
      // Name-only tiles: no status-derived tinting or locking either.
      _classes = 'profile-item jt' + (_checked ? ' selected' : '');
      // No name resolves for this account (no SoO row, or a row with a blank
      // First Name) — offer to type one, because the send-time fallback is the
      // account's email and it goes out in the message body. Only on tiles the
      // operator can actually pick: on a locked one the input is dead weight.
      const _nameOverride = getSenderNameOverride(p.name);
      const _needsName = !_locked && !resolveSenderFirstName(p.id, p.name);
      const _nameRow = (_needsName || _nameOverride) ? `
        <div class="jt-name-row">
          <input type="text" class="jt-name-input" placeholder="First name for {senderFirstName}"
            value="${escHtml(_nameOverride)}" />
        </div>` : '';
      // Ortus Basics 1.0 (operator ask): the picker shows the GoLogin account name
      // and nothing else — no SoO verdict, no availability word, no sub-line. The
      // status is still computed above (the log and classifyAccountState use it),
      // it is simply not rendered here, and no tile is locked on the strength of it.
      _inner = `
      <div class="jt-det">
        <div class="jt-top">
          <input type="checkbox" value="${p.id}" ${_checked} />
          <span class="jt-email">${escHtml(p.name)}</span>
        </div>
      </div>`;
    }

    const item = document.createElement('label');
    item.className = _classes;
    item.dataset.profileId = p.id;
    item.innerHTML = _inner;
    // Explicit: the tile can now hold a second <input> (the first-name box), and
    // a bare querySelector('input') would bind the campaign's account selection
    // to whichever one the markup happens to put first.
    const cb = item.querySelector('input[type="checkbox"]');
    // Typed-in first name for an account SoO can't name. The tile is a <label>,
    // so a click inside it would otherwise toggle the checkbox — same guard the
    // Local Browser name input uses.
    const nameInput = item.querySelector('.jt-name-input');
    if (nameInput) {
      nameInput.addEventListener('click', (e) => e.stopPropagation());
      nameInput.addEventListener('input', (e) => {
        setSenderNameOverride(p.name, e.target.value);
        renderSelectedPanel();
      });
    }
    cb.addEventListener('change', () => {
      // Ortus Basics 1.0: tiles show the account name only, so nothing is locked
      // on a SoO verdict the operator can no longer see. (was: _locked → refuse)
      try { if (_acctAdd) _acctAddTouched = true; } catch (_) { /* */ }
      if (cb.checked) {
        if (!selectedProfileIds.includes(p.id)) {
          selectedProfileIds.push(p.id);
          selectedProfileNames[p.id] = p.name;
        }
        item.classList.add('selected');
      } else {
        selectedProfileIds = selectedProfileIds.filter(id => id !== p.id);
        delete selectedProfileNames[p.id];
        item.classList.remove('selected');
      }
      renderSelectedPanel();
      updateCampaignSummary();
    });
    grid.appendChild(item);
  });
  renderSelectedPanel();
  updateCampaignSummary();
}

function renderSelectedPanel() {
  // Live "N to add · M to remove" while picking accounts for a running cloud
  // campaign. No-op (and cheap) when that flow isn't active.
  try { if (_acctAdd) _renderAcctAddBanner(); } catch (_) { /* */ }
  const panel = document.getElementById('selected-panel');
  const list = document.getElementById('selected-list');
  const count = document.getElementById('profiles-count');

  // Right-pane mirror
  const rpCount = document.getElementById('rp-selected-count');
  const rpSub = document.getElementById('rp-selected-sub');
  if (rpCount) rpCount.textContent = String(selectedProfileIds.length);
  if (rpSub) {
    const targets = typeof window.sheetTotalRows === 'number' && window.sheetTotalRows > 0 ? window.sheetTotalRows : 0;
    const accountWord = selectedProfileIds.length === 1 ? 'account' : 'accounts';
    rpSub.textContent = `${accountWord} · ${targets} targets`;
  }
  // Chip selected-only counter
  const chipSel = document.getElementById('chip-count-selected');
  if (chipSel) chipSel.textContent = String(selectedProfileIds.length);

  if (selectedProfileIds.length === 0) {
    panel.classList.add('hidden');
    if (count) count.textContent = `0 selected / ${allProfilesData.length} total`;
    return;
  }

  panel.classList.remove('hidden');
  if (count) count.textContent = `${selectedProfileIds.length} selected / ${allProfilesData.length} total`;

  list.innerHTML = selectedProfileIds.map((id, i) => {
    const name = profileLabel(id);
    const first = resolveSenderFirstName(id, name);
    const senderTag = first
      ? `<span class="sender-first" style="color:#3fb950;font-size:11px;margin-left:6px">→ "${escHtml(first)}"</span>`
      : `<span class="sender-first" style="color:#f85149;font-size:11px;margin-left:6px">⚠ no first name</span>`;
    // Benching is gone (operator, 2026-09-04). An account is either in this
    // campaign or it is not: to take one out you stop the campaign, remove it
    // here, and start again. A half-in "selected but benched" state was a third
    // thing to reason about, and it never belonged to a campaign — the Set was
    // module-level, so a bench set in one campaign followed you into the next.
    return `<div class="selected-item">
      <span class="order">${i + 1}</span>
      <span class="name">${escHtml(name)}</span>
      ${senderTag}
      <button class="btn-remove" onclick="removeProfile('${id}')" title="Remove">&times;</button>
    </div>`;
  }).join('');

  // v3.0: keep Post Amp engagement table in sync with profile selection.
  if (typeof renderPostAmpEngagementTable === 'function') {
    renderPostAmpEngagementTable();
  }

  // v2.112 (#5): refresh aggregate guardrail alert on every selection change.
  renderGuardrailAlert();
}

// v2.112 (#5): aggregate guardrail alert — from the currently-SELECTED accounts only.
function renderGuardrailAlert() {
  const el = document.getElementById('guardrail-alert');
  if (!el) return;
  const selected = (selectedProfileIds || []).map(id => {
    const name = profileLabel(id);
    return { email: name, soo: findSoOForProfile(name) };
  });
  const mode = document.getElementById('campaign-mode')?.value || 'connect_only';
  const s = summarizeSelection(selected, getMyIdentifier(), mode, getPassoverStatus());
  // Ortus Basics 1.0: no availability warnings — the operator judges what is
  // usable, so "N of your selected accounts are assigned to / in use" and the
  // passover-cycle notice are not surfaced.
  el.classList.add('hidden'); el.innerHTML = ''; return;
  /* eslint-disable no-unreachable */
  if (!s.hasWarnings) { el.classList.add('hidden'); el.innerHTML = ''; return; }
  const bits = [];
  if (s.flagged.length) bits.push(`<b>${s.flagged.length} of your selected accounts are assigned to / in use</b>`);
  if (s.passover) {
    // v2.112.29: plain, actionable wording (dropped the contradictory "in
    // passover"). CC reopens Thursday; the monthly channels reopen on the 16th.
    // The label already carries the "(in Nd)" countdown. Only shown when an
    // ASSIGNED account is selected, so it reads as "that locked account frees up".
    const _isCc = s.passover.channel === 'cc';
    const _when = _isCc ? 'Thursday' : 'the 16th';
    const _chan = _isCc ? "this week's CC credits" : "this month's OP/InMail/Sales Nav credits";
    bits.push(`<b>${_chan} open ${_when} (${escHtml(s.passover.label)})</b> — that cycle hasn’t started yet (you can still launch)`);
  }
  el.innerHTML = `<span class="big">⚠</span><span class="txt">${bits.join(', and ')}.</span>`;
  el.classList.remove('hidden');
}

function removeProfile(id) {
  selectedProfileIds = selectedProfileIds.filter(pid => pid !== id);
  delete selectedProfileNames[id];
  const cb = document.querySelector(`#profiles-grid input[value="${id}"]`);
  if (cb) { cb.checked = false; cb.closest('.profile-item')?.classList.remove('selected'); }
  renderSelectedPanel();
  // Recompute throughput + the 2+-account parallel unlock — removing via the X
  // chip changes the account count just like unticking the checkbox does.
  if (typeof updateCampaignSummary === 'function') updateCampaignSummary();
}
window.removeProfile = removeProfile;

let activeAccountFilter = 'all';

function filterProfiles() {
  const query = (document.getElementById('profile-search').value || '').trim().toLowerCase();

  let list = allProfilesData;

  // Preset filter (Assigned to me / Unassigned Pool / All)
  if (activePresetFilter && activePresetFilter !== 'all') {
    list = list.filter((p) => matchesPreset(activePresetFilter, findSoOForProfile(p.name)));
  }

  // Chip filter (Available / In use / Selected)
  if (activeAccountFilter !== 'all') {
    list = list.filter((p) => {
      const soo = findSoOForProfile(p.name);
      if (activeAccountFilter === 'selected') return selectedProfileIds.includes(p.id);
      if (!soo) return false;
      const vals = [soo.linkedinCredits, soo.inmailCredits, soo.salesNavCredits, soo.ccCredits].map((v) => (v || '').toLowerCase());
      if (activeAccountFilter === 'available') return vals.some((v) => v === 'available');
      if (activeAccountFilter === 'in-use') return vals.some((v) => v === 'in use' || v === 'in-use' || v === 'used');
      return true;
    });
  }

  // Search by name/email
  if (query) {
    list = list.filter((p) => p.name.toLowerCase().includes(query) || p.id.includes(query));
  }

  renderProfiles(list);
  updateChipCounts();
}

function applyFilter(type) {
  activeAccountFilter = type;
  document.querySelectorAll('.chip[data-filter]').forEach((c) => {
    c.classList.toggle('active', c.dataset.filter === type);
  });
  filterProfiles();
}

function getMyIdentifier() {
  try {
    const saved = localStorage.getItem('ortus-my-identifier');
    if (saved && saved.trim()) return saved.trim().toLowerCase();
  } catch (_) {}
  const chip = document.getElementById('user-chip-email');
  return ((chip?.textContent) || '').trim().toLowerCase();
}

function saveMyIdentifier() {
  const el = document.getElementById('my-identifier');
  if (!el) return;
  // Phase 2.8.19 (C2): a typed save implies the user wants control — set the
  // override flag so refreshIdentifierDefault stops fighting them on later loads.
  if (!el.hasAttribute('readonly')) {
    try {
      localStorage.setItem('ortus-my-identifier', el.value.trim());
      localStorage.setItem('ortus-my-identifier-override', '1');
    } catch (_) {}
  }
  updateChipCounts();
}

function initMyIdentifier() {
  const el = document.getElementById('my-identifier');
  if (!el) return;
  // Always paint the current saved/auto-derived value
  let saved = '';
  try { saved = localStorage.getItem('ortus-my-identifier') || ''; } catch (_) {}
  if (!saved) {
    const chip = document.getElementById('user-chip-email');
    saved = (chip?.textContent || '').trim();
  }
  el.value = saved;
  // Phase 2.8.19 (C2): apply readonly + toggle-link state based on override flag
  applyIdentifierMode();
}

function applyIdentifierMode() {
  const el = document.getElementById('my-identifier');
  const link = document.getElementById('identifier-toggle');
  if (!el) return;
  let overridden = false;
  try { overridden = !!localStorage.getItem('ortus-my-identifier-override'); } catch (_) {}
  if (overridden) {
    el.removeAttribute('readonly');
    if (link) link.textContent = 'Auto';
  } else {
    el.setAttribute('readonly', '');
    if (link) link.textContent = 'Override';
  }
}

function toggleIdentifierMode() {
  let overridden = false;
  try { overridden = !!localStorage.getItem('ortus-my-identifier-override'); } catch (_) {}
  if (overridden) {
    // Switching back to Auto — clear override flag AND clear the saved value so
    // refreshIdentifierDefault / initMyIdentifier can re-populate from SoO/email.
    try {
      localStorage.removeItem('ortus-my-identifier-override');
      localStorage.removeItem('ortus-my-identifier');
    } catch (_) {}
    // Re-derive: re-init from chip, then let SoO refresh take over
    initMyIdentifier();
    if (typeof refreshIdentifierDefault === 'function') refreshIdentifierDefault();
  } else {
    // Entering Override — set flag, keep current value as starting point
    const el = document.getElementById('my-identifier');
    try {
      localStorage.setItem('ortus-my-identifier-override', '1');
      localStorage.setItem('ortus-my-identifier', el?.value?.trim() || '');
    } catch (_) {}
    applyIdentifierMode();
    el?.focus();
  }
  if (typeof updateChipCounts === 'function') updateChipCounts();
}

window.toggleIdentifierMode = toggleIdentifierMode;

/**
 * Defaults the "My identifier for Assigned" input to the operator's SoO
 * first name (e.g. "Antonio") instead of their email. The SoO Assignee
 * column contains short first names, so matching against an email always
 * fails and the "Assigned to me" chip shows 0.
 *
 * Behavior:
 *   - If localStorage has a non-empty custom value that is NOT an email,
 *     respect it (the operator customized it manually).
 *   - Otherwise, if the operator's email resolves to a firstName in sooData,
 *     use that firstName and persist it to localStorage.
 *   - Otherwise, leave the input as-is (the existing email fallback applies).
 *
 * Auto-heal: if localStorage already contains an email from a pre-fix
 * session AND a firstName is now resolvable, overwrite with firstName.
 */
function refreshIdentifierDefault() {
  const el = document.getElementById('my-identifier');
  if (!el) return;
  // Phase 2.8.19 (C2): if user is in Override mode, never auto-overwrite their value.
  let overridden = false;
  try { overridden = !!localStorage.getItem('ortus-my-identifier-override'); } catch (_) {}
  if (overridden) return;
  const emailEl = document.getElementById('user-chip-email');
  const email = ((emailEl?.textContent) || '').trim().toLowerCase();
  if (!email) return;
  const sooEntry = sooData && sooData[email];
  const firstNameRaw = sooEntry && sooEntry.firstName ? sooEntry.firstName.trim() : '';
  if (!firstNameRaw) return; // no SoO match — leave the email fallback alone
  const firstName = firstNameRaw.charAt(0).toUpperCase() + firstNameRaw.slice(1);

  let stored = '';
  try { stored = (localStorage.getItem('ortus-my-identifier') || '').trim(); } catch (_) {}

  // Overwrite only when stored is empty, already an email (auto-heal), or
  // already equals firstName (re-persist canonical casing). A non-empty,
  // non-email stored value that differs from firstName is treated as a
  // deliberate customization and left alone.
  const storedIsEmail = stored.includes('@');
  const shouldOverwrite = !stored || storedIsEmail || stored.toLowerCase() === firstName.toLowerCase();

  if (shouldOverwrite) {
    el.value = firstName;
    try { localStorage.setItem('ortus-my-identifier', firstName); } catch (_) {}
    if (typeof updateChipCounts === 'function') updateChipCounts();
  }
}

let activePresetFilter = 'all';

function matchesPreset(preset, soo) {
  if (!soo) return preset === 'all';
  const section = (soo.section || '').toLowerCase();
  const isPool = section.includes('pool') || section.includes('unassigned');
  if (preset === 'pool') return isPool;
  if (preset === 'assigned') {
    const me = getMyIdentifier();
    if (!me) return false;
    const assignee = (soo['Assignee'] || '').toLowerCase();
    return !isPool && assignee && assignee !== '-' && assignee.includes(me);
  }
  if (preset === 'available-now') return isAvailableNow(soo);
  return true; // 'all'
}

function applyPreset(preset) {
  if (preset === 'assigned') {
    const me = getMyIdentifier();
    if (!me) {
      alert('Set your identifier in the "My identifier" field below the presets first.');
      return;
    }
  }

  activePresetFilter = preset;

  document.querySelectorAll('.preset[data-preset]').forEach((b) => {
    b.classList.toggle('active', b.dataset.preset === preset);
  });

  filterProfiles();
}

function updateChipCounts() {
  // Construction-section accounts are hidden from the grid, so they must not be
  // counted here either — otherwise the totals/pills wouldn't match what's shown.
  const visibleProfiles = allProfilesData.filter((p) => !isHiddenSection(findSoOForProfile(p.name)));
  const counts = { all: visibleProfiles.length, available: 0, 'in-use': 0, selected: selectedProfileIds.length };
  const me = getMyIdentifier();
  let assignedToMeCount = 0, poolCount = 0, availableNowCount = 0;
  visibleProfiles.forEach((p) => {
    const soo = findSoOForProfile(p.name);
    if (!soo) return;
    const vals = [soo.linkedinCredits, soo.inmailCredits, soo.salesNavCredits, soo.ccCredits].map((v) => (v || '').toLowerCase());
    if (vals.some((v) => v === 'available')) counts.available++;
    if (vals.some((v) => v === 'in use' || v === 'in-use' || v === 'used')) counts['in-use']++;
    if (isAvailableNow(soo)) availableNowCount++;
    const isPool = (soo.section || '').toLowerCase().includes('pool') ||
                   (soo.section || '').toLowerCase().includes('unassigned');
    const assignee = (soo['Assignee'] || '').toLowerCase();
    if (isPool) poolCount++;
    else if (assignee && assignee !== '-' && me && assignee.includes(me)) {
      assignedToMeCount++;
    }
  });
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = String(v); };
  set('chip-count-all', counts.all);
  set('chip-count-available', counts.available);
  set('chip-count-in-use', counts['in-use']);
  set('chip-count-selected', counts.selected);
  set('preset-count-assigned', assignedToMeCount);
  set('preset-count-pool', poolCount);
  set('preset-count-available-now', availableNowCount);
  set('preset-count-all-accounts', counts.all);
}

window.openAccountPaste = function() {
  const panel = document.getElementById('account-paste-panel');
  if (!panel) return;
  panel.open = true;
  panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
  document.getElementById('account-paste-list')?.focus({ preventScroll: true });
};

function selectPastedAccounts() {
  const input = document.getElementById('account-paste-list');
  const status = document.getElementById('account-paste-status');
  if (!input.value.trim()) { status.textContent = 'Paste account emails first.'; return; }
  if (!allProfilesData.length) { status.textContent = 'No accounts loaded yet. Add your GoLogin token in Settings, then refresh the account list.'; return; }
  const profiles = allProfilesData.filter(p => !isHiddenSection(findSoOForProfile(p.name)));
  const result = matchAccountList(input.value, profiles);
  let added = 0;
  for (const p of result.matched) {
    if (!selectedProfileIds.includes(p.id)) {
      selectedProfileIds.push(p.id);
      selectedProfileNames[p.id] = p.name;
      added++;
    }
  }
  if (added) { try { if (_acctAdd) _acctAddTouched = true; } catch (_) {} }
  filterProfiles();
  status.textContent = `${result.matched.length} matched · ${added} added · ${selectedProfileIds.length} selected.`
    + (result.missing.length ? ` Not found: ${result.missing.join(', ')}.` : '')
    + (result.ambiguous.length ? ` Multiple profiles found — select manually: ${result.ambiguous.join(', ')}.` : '');
}
window.selectPastedAccounts = selectPastedAccounts;

function selectAllVisible() {
  document.querySelectorAll('#profiles-grid input[type="checkbox"]').forEach(cb => {
    if (!cb.checked) {
      cb.checked = true;
      cb.dispatchEvent(new Event('change'));
    }
  });
}

function deselectAll() {
  selectedProfileIds = [];
  selectedProfileNames = {};
  document.querySelectorAll('#profiles-grid input[type="checkbox"]').forEach(cb => {
    cb.checked = false;
    cb.closest('.profile-item')?.classList.remove('selected');
  });
  renderSelectedPanel();
}

// ─────────────────────────────────────────────────────────────────────────────
// "Add a note while connecting?" toggle
// ─────────────────────────────────────────────────────────────────────────────
// Resolves visibility for the template management UI (Select / Load / Delete /
// Save / Preview Messages). Hidden when:
//   - mode is check_status (no template at all)
//   - mode is connect_only AND the operator answered "No" to "add a note?"
//     (no template = no reason to show the template bar or preview button)
// Called from both onModeChange (mode change) and syncAddNoteUI (Yes/No toggle)
// so both paths agree.
// v2.59: live char counter under the Connection Note textarea so the
// operator can see how close they are to LinkedIn's 300-char cap. Goes
// red at 280+ as a soft warning. Idempotent — safe to call on init.
function updateTplNoteCount() {
  const ta = document.getElementById('tpl-note');
  const out = document.getElementById('tpl-note-count');
  if (!ta || !out) return;
  const n = (ta.value || '').length;
  out.textContent = `${n} / 300`;
  out.style.color = n >= 280 ? '#dc2626' : 'var(--gray)';
  const hint = document.getElementById('tpl-note-hint');
  if (hint) hint.classList.toggle('hidden', !shouldShowNoteHint(ta.value || ''));
}
window.updateTplNoteCount = updateTplNoteCount;
document.addEventListener('DOMContentLoaded', updateTplNoteCount);
if (document.readyState !== 'loading') updateTplNoteCount();

function applyTemplateUIVisibility(_mode, _addNoteOn) {
  // v2.59: template-bar (Select/Save/Create New/Delete) stays hidden — the
  // reusable-template save/load system isn't needed for the current
  // CC+IB / IC flow.
  // v2.62: Preview Messages button is back, surfaced in the visible
  // .tpl-cta-row at the top of Section 5. Visibility is no longer forced
  // here — refreshPreviewButtonState manages disabled state based on
  // sheet URL + template presence.
  const tplBar = document.getElementById('template-bar');
  if (tplBar) tplBar.style.display = 'none';
}

function syncAddNoteUI(on) {
  const yesBtn = document.getElementById('add-note-yes');
  const noBtn = document.getElementById('add-note-no');
  const connect = document.getElementById('tpl-connect-section');
  if (yesBtn) yesBtn.classList.toggle('active', on);
  if (noBtn) noBtn.classList.toggle('active', !on);
  if (connect) connect.style.display = on ? '' : 'none';
  const mode = document.getElementById('campaign-mode')?.value || 'connect_only';
  applyTemplateUIVisibility(mode, on);
}

function setAddNote(on) {
  try { localStorage.setItem('ortus-add-note', on ? '1' : '0'); } catch (_) {}
  syncAddNoteUI(on);
}

