// Delete a finished/stopped campaign from the board (replaces the old Dismiss).
// Local campaigns are truly deleted from history.json; cloud campaigns have no
// engine delete endpoint yet, so they're stopped (if somehow still active) and
// removed from this dashboard durably. Always confirms first.
async function deleteBoardCampaign(id, btn) {
  const it = _boardItemsById.get(id) || (_snItemsById && _snItemsById.get(id));
  const name = (it && it.name) || 'this campaign';
  if (!confirm(`Delete "${name}"?\n\nThis removes it from your dashboard for good.`)) return;
  try {
    if (it?.bucket === 'saved') {
      const response = await fetch('/api/campaign-configs/' + encodeURIComponent(it.name) + (it.campaignId ? '?campaignId=' + encodeURIComponent(it.campaignId) : ''), { method: 'DELETE' });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Could not delete saved campaign.');
      await refreshKnownCampaignNames();
    } else if (it && it.where === 'cloud') {
      // Kill any live engine activity for this campaign FIRST — stop halts sending
      // + monitoring and releases its account locks — THEN durably hide it from the
      // board. Previously delete only hid it, so a running campaign kept sending on
      // the VM (and held its accounts) after being "deleted". Best-effort: hide it
      // even if the stop call fails.
      try { await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/stop`, { method: 'POST' }); } catch (_) { /* still hide it below */ }
      _cloudDismissed.add(id); _cloudSaveDismissed();
    } else if (it && it.id === 'local-active' && it.interrupted) {
      const r = await fetch('/api/campaign/interrupted', { method: 'DELETE' });
      if (!r.ok) {
        const e = await r.json().catch(() => ({}));
        alert('Could not delete: ' + (e.error || r.status));
        return;
      }
      _localDismissed.add(id);
    } else if (it && it.histIdx != null) {
      const r = await fetch('/api/history/' + encodeURIComponent(it.histIdx), { method: 'DELETE' });
      if (!r.ok) {
        const e = await r.json().catch(() => ({}));
        alert('Could not delete: ' + (e.error || r.status));
        return;
      }
    } else {
      _localDismissed.add(id);
    }
  } catch (e) {
    alert('Could not delete: ' + e.message);
    return;
  }
  const strip = btn && btn.closest ? btn.closest('.sn-strip') : null;
  if (strip) strip.remove(); // instant feedback; next poll already filters it
  renderCampaignsBoard();
}
window.deleteBoardCampaign = deleteBoardCampaign;

// Copy a campaign strip's log to the clipboard (⧉ button on the black log box).
// Reads the rendered log's plain text (not HTML) so it pastes clean into a
// message / ticket. Brief ✓ feedback on the button; execCommand fallback for
// any context where the async clipboard API is unavailable.
function copyStripLog(btn) {
  const pane = (btn.closest && btn.closest('.sn-pane')) || btn.parentElement;
  const box = pane && pane.querySelector('.sn-logbox');
  const text = box ? (box.innerText || box.textContent || '').replace(/\s+$/, '') : '';
  if (!text) { if (typeof showCampaignToast === 'function') showCampaignToast('No log to copy yet.', 3000); return; }
  const flash = () => {
    btn.classList.add('copied');
    const lbl = btn.querySelector('.sn-logcopy-lbl');
    if (lbl) { lbl.dataset.orig = lbl.dataset.orig || lbl.textContent; lbl.textContent = 'Copied'; }
    setTimeout(() => {
      btn.classList.remove('copied');
      if (lbl && lbl.dataset.orig) lbl.textContent = lbl.dataset.orig;
    }, 1300);
  };
  const fallback = () => {
    try {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); flash();
    } catch (_) { if (typeof showCampaignToast === 'function') showCampaignToast('Could not copy log.', 3000); }
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(flash).catch(fallback);
  } else { fallback(); }
}
window.copyStripLog = copyStripLog;

// ── Duplicate a campaign (Sam #1) → open + New campaign pre-filled ──────────
const _boardItemsById = new Map();  // strip id → normalized item (for actions)
let _ovfWired = false;

// Build a wizard-config object from a history entry's settings (mirrors
// rerunPastCampaign so a duplicated done campaign carries every setting).
function _configFromSettings(mode, s) {
  s = s || {};
  const gid = s.sheetGid ? String(s.sheetGid) : ((s.sheetUrl || '').match(/[#&?]gid=(\d+)/) || [])[1] || '';
  return {
    mode, sheetUrl: s.sheetUrl || '', sheetGid: gid,
    dailyLimit: s.dailyLimit ?? 50, delayMin: s.delayMin ?? 10, delayMax: s.delayMax ?? 20,
    linkedinColumn: s.linkedinColumn || '', messageOpenProfiles: !!s.messageOpenProfiles,
    addNote: !!(s.templates && s.templates.connectionNote), templates: s.templates || {},
    profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
    concurrency: s.concurrency ?? 1, senderFirstNames: s.senderFirstNames || {},
  };
}

// Resolve the source config for a strip, then open the pre-filled wizard.
async function duplicateCampaign(id) {
  const it = _boardItemsById.get(id);
  if (!it) return;
  let config = null; let srcName = it.name || 'Campaign';
  try {
    if (it.bucket === 'saved') {
      const r = await fetch(it.campaignId ? '/api/campaign-configs/by-id/' + encodeURIComponent(it.campaignId) : '/api/campaign-configs/' + encodeURIComponent(srcName));
      if (r.ok) { const data = await r.json(); config = data.config; }
    } else if (it.where === 'cloud') {
      const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(it.id)}/launch-config`);
      if (r.ok) { const d = await r.json(); config = d.config; srcName = d.name || srcName; }
    } else if (it.bucket === 'queued' && it.rawId) {
      const r = await fetch('/api/queue/' + encodeURIComponent(it.rawId));
      if (r.ok) { const e = await r.json(); config = e.config; srcName = e.name || srcName; }
    } else if (it.bucket === 'done' && it.srcSettings) {
      config = _configFromSettings(it.mode, it.srcSettings);
    } else if (it.id === 'local-active') {
      // Running local campaign: prefer its live settings snapshot (v2.83
      // /api/campaign/active-settings — the exact config it launched with),
      // falling back to the operator's last-used preset.
      const r = await fetch('/api/campaign/active-settings');
      if (r.ok) {
        const d = await r.json();
        if (d && d.ok && d.settings) config = _configFromSettings(it.mode || d.settings.mode, d.settings);
      }
      if (!config) {
        const r2 = await fetch('/api/presets/_last_used');
        if (r2.ok) { const e = await r2.json(); config = e.config || (e.entry && e.entry.config) || null; }
      }
    }
  } catch (_) { /* fall through to the guard below */ }
  if (!config || typeof config !== 'object') {
    alert("Couldn't load this campaign's settings to duplicate.\nOpen ＋ New campaign and set it up manually.");
    return;
  }
  _openDuplicateDraft(srcName, config);
}
window.duplicateCampaign = duplicateCampaign;

// Duplicate a past-campaign row (history entry) into a fresh pre-filled draft.
// Reads from pastCampaignsCache (same source as the details modal / resume).
function duplicatePastCampaign(idx) {
  const entry = (pastCampaignsCache || []).find((e) => e.idx === idx);
  const c = entry && entry.c;
  if (!c || !c.settings) {
    alert("This campaign predates settings snapshots — it can't be duplicated.\nOpen ＋ New campaign and set it up manually.");
    return;
  }
  _openDuplicateDraft(c.name || 'Campaign', _configFromSettings(c.mode, c.settings));
}
window.duplicatePastCampaign = duplicatePastCampaign;

// Duplicate settings into a new named draft; never start sending on duplication.
let _duplicateWizardPending = false;
window.duplicateWizardCampaign = async function() {
  if (_duplicateWizardPending) return;
  _duplicateWizardPending = true;
  const btn = document.getElementById('btn-duplicate-campaign');
  if (btn) btn.disabled = true;
  try {
    const name = (document.getElementById('campaign-name-input')?.value || '').trim() || 'Campaign';
    const config = collectCurrentConfig();
    await _openDuplicateDraft(name, config);
  } finally {
    _duplicateWizardPending = false;
    if (btn) btn.disabled = false;
  }
};

async function _openDuplicateDraft(srcName, config) {
  config = { ...config, campaignId: undefined };
  let proposed = `${srcName} II`;
  let label = 'What would you like to call the duplicate campaign?';
  let error = '';
  const knownNames = typeof refreshKnownCampaignNames === 'function' ? await refreshKnownCampaignNames() : [];
  const boardNames = typeof _existingMineCampaignNames === 'function' ? _existingMineCampaignNames() : [];
  const taken = new Set([srcName, ...knownNames, ...boardNames].map(n => String(n).trim().toLowerCase()));
  let draft;
  while (!draft) {
    const name = await promptModal({ label, defaultValue: proposed, error });
    if (!name) return;
    proposed = name;
    // The source may be unsaved, but its name still belongs to this campaign.
    if (taken.has(name.trim().toLowerCase())) {
      error = label = 'That campaign name already exists. Please choose a different name.';
      continue;
    }
    try {
      const r = await fetch('/api/drafts', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, config, uniqueName: true }),
      });
      const data = await r.json();
      if (r.status === 409) {
        error = label = data.message || 'That campaign name already exists. Please choose a different name.';
        continue;
      }
      if (!r.ok || !data.draft?.id) throw new Error(data.message || data.error || 'Could not save the duplicate.');
      draft = data.draft;
    } catch (err) {
      showCampaignToast(`Could not duplicate campaign: ${err.message}`);
      return;
    }
  }
  if (typeof flushAutosaveImmediate === 'function') await flushAutosaveImmediate();
  clearCloudEditMode();
  unlockCampaignType();
  stopViewingCloudCampaign();
  window.__viewingActiveCampaign = false;
  liveStatusForcedOpen = false;
  _editingExistingCampaign = false;
  try { localStorage.removeItem('wizardStoppedFromContext'); } catch (_) {}
  _openedCampaignId = draft.campaignId || null;
  _openedCampaignName = draft.name;
  config = { ...config, campaignId: _openedCampaignId };
  setActiveDraftId(draft.id);
  goCreateCampaign();
  const ni = document.getElementById('campaign-name-input');
  if (ni) ni.value = draft.name;
  applyPresetConfig(config);
  try { localStorage.setItem('campaignName', draft.name); } catch (_) {}
  syncSidebarCampaignName();
  syncLiveStatusVisibility();
  renderLiveConsole(_localLive || {});
  showCampaignToast(`Created “${draft.name}” as a new draft.`);
}

// Delegated open/close + Duplicate action for the strip ⋯ menus.
function _wireStripOverflow() {
  if (_ovfWired) return;
  _ovfWired = true;
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('#campaigns-board .ovf-btn');
    if (btn) {
      const o = btn.closest('.ovf'); const wasOpen = o.classList.contains('open');
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
      if (!wasOpen) o.classList.add('open');
      return;
    }
    const act = e.target.closest('#campaigns-board .ovf-item[data-act="duplicate"]');
    if (act) {
      const cid = act.closest('.sn-strip')?.dataset.cid;
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
      if (cid) duplicateCampaign(cid);
      return;
    }
    if (!e.target.closest('#campaigns-board .ovf')) {
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
    }
  });
}

// ── Campaigns board: filter by type (Sam) ──────────────────────────────────
// A compact dropdown on the header narrows the board to one campaign type.
let _campaignsTypeFilter = 'All';   // 'All' | badge (CC, C+I, C+D, DM, IB, FG…)
let _typeFilterOpen = false;        // menu open — don't rebuild it mid-interaction
let _typeFilterWired = false;

// Rebuild the dropdown control. counts come from ALL items (unfiltered).
function renderCampaignsTypeFilter(allItems) {
  const host = document.getElementById('campaigns-typefilter');
  if (!host) return;
  if (_typeFilterOpen) { _updateTypeFilterTrigger(allItems); return; } // don't clobber open menu
  // Distinct types present, in a stable order, each with its live count.
  const order = ['CC', 'C+I', 'C+D', 'DM', 'IB', 'FG', 'IM', 'OP', 'CS'];
  const present = [];
  for (const it of allItems) { const b = _cloudBadge(it.mode); if (b && !present.includes(b)) present.push(b); }
  present.sort((a, b) => order.indexOf(a) - order.indexOf(b));
  const types = ['All', ...present];
  const count = (t) => t === 'All' ? allItems.length : allItems.filter((x) => _cloudBadge(x.mode) === t).length;
  // If the active filter no longer exists (its campaigns ended), fall back to All.
  if (_campaignsTypeFilter !== 'All' && !present.includes(_campaignsTypeFilter)) _campaignsTypeFilter = 'All';
  const items = types.map((t) =>
    `<div class="fdrop-item ${t === _campaignsTypeFilter ? 'on' : ''}" data-t="${escHtml(t)}">`
    + `<span><span class="tick">${t === _campaignsTypeFilter ? '✓' : ''}</span> ${escHtml(t)}</span>`
    + `<span class="n">${count(t)}</span></div>`).join('');
  host.innerHTML =
    `<button type="button" class="fdrop-btn" id="typeFilterBtn"><span class="cur">Type: <b>${escHtml(_campaignsTypeFilter)}</b> · ${count(_campaignsTypeFilter)}</span>`
    + `<svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6l4 4 4-4"/></svg></button>`
    + `<div class="fdrop-menu" id="typeFilterMenu">${items}</div>`;
  host.classList.toggle('open', _typeFilterOpen);
  _wireTypeFilter();
}

function _updateTypeFilterTrigger(allItems) {
  const btn = document.querySelector('#typeFilterBtn .cur');
  if (!btn) return;
  const count = _campaignsTypeFilter === 'All'
    ? allItems.length : allItems.filter((x) => _cloudBadge(x.mode) === _campaignsTypeFilter).length;
  btn.innerHTML = `Type: <b>${escHtml(_campaignsTypeFilter)}</b> · ${count}`;
}

function _wireTypeFilter() {
  if (_typeFilterWired) return;
  _typeFilterWired = true;
  document.addEventListener('click', (e) => {
    const host = document.getElementById('campaigns-typefilter');
    if (!host) return;
    if (e.target.closest('#typeFilterBtn')) {
      _typeFilterOpen = !_typeFilterOpen; host.classList.toggle('open', _typeFilterOpen); return;
    }
    const item = e.target.closest('.fdrop-item');
    if (item && host.contains(item)) {
      _campaignsTypeFilter = item.dataset.t; _typeFilterOpen = false;
      renderCampaignsBoard();
      return;
    }
    if (!host.contains(e.target)) { _typeFilterOpen = false; host.classList.remove('open'); }
  });
}

// ── Conductor filter (admin only) ──────────────────────────────────────────
let _campaignsConductorFilter = 'Everyone'; // 'Everyone' | owner email
let _conductorFilterOpen = false;
let _conductorFilterWired = false;
const _ownerOf = (it) => it.owner || (it.mine ? _viewerEmail : '') || '';
const _shortOwner = (o) => o === 'Everyone' ? 'Everyone' : String(o).split('@')[0];

function renderCampaignsConductorFilter(allItems) {
  const host = document.getElementById('campaigns-conductorfilter');
  if (!host) return;
  if (!_viewerIsAdmin) { host.style.display = 'none'; host.innerHTML = ''; return; }
  host.style.display = '';
  if (_conductorFilterOpen) { return; } // don't clobber open menu
  const owners = [];
  for (const it of allItems) { const o = _ownerOf(it); if (o && !owners.includes(o)) owners.push(o); }
  owners.sort();
  if (_campaignsConductorFilter !== 'Everyone' && !owners.includes(_campaignsConductorFilter)) _campaignsConductorFilter = 'Everyone';
  const opts = ['Everyone', ...owners];
  const count = (o) => o === 'Everyone' ? allItems.length : allItems.filter((x) => _ownerOf(x) === o).length;
  const items = opts.map((o) =>
    `<div class="fdrop-item ${o === _campaignsConductorFilter ? 'on' : ''}" data-o="${escHtml(o)}">`
    + `<span><span class="tick">${o === _campaignsConductorFilter ? '✓' : ''}</span> ${escHtml(_shortOwner(o))}</span>`
    + `<span class="n">${count(o)}</span></div>`).join('');
  host.innerHTML =
    `<button type="button" class="fdrop-btn" id="conductorFilterBtn"><span class="cur">Conductor: <b>${escHtml(_shortOwner(_campaignsConductorFilter))}</b></span>`
    + `<svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6l4 4 4-4"/></svg></button>`
    + `<div class="fdrop-menu" id="conductorFilterMenu">${items}</div>`;
  host.classList.toggle('open', _conductorFilterOpen);
  _wireConductorFilter();
}

function _wireConductorFilter() {
  if (_conductorFilterWired) return;
  _conductorFilterWired = true;
  document.addEventListener('click', (e) => {
    const host = document.getElementById('campaigns-conductorfilter');
    if (!host) return;
    if (e.target.closest('#conductorFilterBtn')) {
      _conductorFilterOpen = !_conductorFilterOpen; host.classList.toggle('open', _conductorFilterOpen); return;
    }
    const item = e.target.closest('.fdrop-item');
    if (item && host.contains(item)) {
      _campaignsConductorFilter = item.dataset.o; _conductorFilterOpen = false;
      renderCampaignsBoard();
      return;
    }
    if (!host.contains(e.target)) { _conductorFilterOpen = false; host.classList.remove('open'); }
  });
}

// ── Skipped-leads panel state ──────────────────────────────────────────────
// Shared across the board; the panel is only shown for the one local-active strip.
let _skipPanelExpanded = false;
let _skipData = []; // array of skip objects from /api/campaign/skips
let _skipPollTimer = null;

const _SKIP_REASON_LABELS = {
  already_processed:   'Already processed',
  identity_unconfirmed:'Identity unconfirmed',
  watchdog_timeout:    'Watchdog timeout',
  malformed_url:       'Malformed URL',
  duplicate_row:       'Duplicate row',
  failed_repeatedly:   'Failed repeatedly',
  terminal_stage:      'Terminal stage',
  other:               'Other',
};

function _skipReasonLabel(r) {
  return _SKIP_REASON_LABELS[r] || r || 'Other';
}

async function _fetchSkips() {
  try {
    const r = await fetch('/api/campaign/skips');
    const d = await r.json();
    _skipData = Array.isArray(d.skips) ? d.skips : [];
  } catch { /* best-effort */ }
}

function _startSkipPoll() {
  if (_skipPollTimer) return;
  _skipPollTimer = setInterval(_fetchSkipsAndRefresh, 5000);
}

function _stopSkipPoll() {
  if (_skipPollTimer) { clearInterval(_skipPollTimer); _skipPollTimer = null; }
}

// Stop both skip-panel pollers (campaigns-board strip + active-card).
function _stopAllSkipPollers() {
  _stopSkipPoll();
  _stopSkipsPoller();
}

async function _fetchSkipsAndRefresh() {
  await _fetchSkips();
  _renderSkipPanelInPlace();
}

function _renderSkipPanelInPlace() {
  const panel = document.getElementById('skip-panel-body');
  if (!panel) return;
  panel.innerHTML = _buildSkipTableHtml();
}

function _buildSkipTableHtml() {
  if (!_skipData.length) return '<p class="skip-empty">No skips recorded yet.</p>';
  const rows = _skipData.map((sk) => {
    const lead = escHtml(sk.leadName || sk.url || '—');
    const account = escHtml(sk.profileName || '—');
    const reason = escHtml(_skipReasonLabel(sk.reason));
    const detail = escHtml(sk.detail || '');
    return `<tr>
      <td class="skip-rowno">${escHtml(String(sk.rowNumber || '—'))}</td>
      <td>${lead}</td>
      <td>${account}</td>
      <td class="skip-reason"><b>${reason}</b>${detail ? ' — ' + detail : ''}</td>
    </tr>`;
  }).join('');
  return `<table class="skiptab">
    <thead><tr><th>Row</th><th>Lead</th><th>Account</th><th>Reason</th></tr></thead>
    <tbody>${rows}</tbody>
  </table>`;
}

window.toggleSkipPanel = async function toggleSkipPanel() {
  _skipPanelExpanded = !_skipPanelExpanded;
  if (_skipPanelExpanded) {
    await _fetchSkips();
    _startSkipPoll();
  } else {
    _stopSkipPoll();
  }
  // Re-render the board so the toggle takes effect immediately.
  // renderCampaignsBoard is async and will pick up _skipPanelExpanded.
  renderCampaignsBoard();
};

window.copySkipList = function copySkipList() {
  if (!_skipData.length) return;
  const lines = _skipData.map((sk) =>
    [sk.rowNumber || '—', sk.leadName || sk.url || '—', _skipReasonLabel(sk.reason), sk.detail || ''].join('\t')
  );
  navigator.clipboard.writeText(lines.join('\n')).catch(() => {});
};

// Reset skip state when a new campaign starts (called on campaign end detection).
function _clearSkipPanel() {
  _skipPanelExpanded = false;
  _skipData = [];
  _stopSkipPoll();
}

// Build the skipped block HTML for the strip.
function _buildSkippedSection(it) {
  if (!it || it.where !== 'local') return '';
  const n = it.skippedCount || 0;
  if (!n) return '';
  if (!_skipPanelExpanded) {
    return `<div class="skipped-mini">
      <span class="skip-pill">Skipped so far: ${n}</span>
      <a class="skip-view-link" onclick="toggleSkipPanel()">view</a>
    </div>`;
  }
  // Expanded — render from cached _skipData. The expanded flag persists across
  // campaign runs while the pollers get stopped on idle, so re-arm the fetch +
  // poll here: without this, a panel left open before a run renders "No skips
  // recorded yet" forever even as skippedCount climbs.
  _startSkipPoll();
  if (!_skipData.length && n > 0) _fetchSkipsAndRefresh();
  const tableHtml = _buildSkipTableHtml();
  return `<div class="skipped">
    <div class="skipped-head">
      Skipped · <span class="skip-n">${n} leads</span>
      <a class="skip-view-link skip-collapse" onclick="toggleSkipPanel()">Collapse</a>
    </div>
    <div id="skip-panel-body">${tableHtml}</div>
    <div class="skipped-actions">
      <button type="button" class="mini" onclick="copySkipList()">Copy list</button>
      <span class="skipped-note">Skipped rows remain untouched on the sheet.</span>
    </div>
  </div>`;
}
// ── End skipped-leads panel ────────────────────────────────────────────────

// Render one normalized item as an sn-strip. Item shape:
//   { where:'cloud'|'local', id, name, mode, isFG, bucket:'running'|'queued'|'done',
//     sent, total, accounts, mine, owner, bad, paused, sheetUrl }
// ── Expanded-strip card #2 parity ───────────────────────────────────────────
// An expanded dashboard strip renders the SAME .vj-card as the campaign-tab
// live-status card (card #2). vjCardSkeleton clones the real #active-card node
// (id→data-f so ids don't collide) — zero markup drift. fillVjCard populates it
// per-campaign, scoped by data-f. Active campaigns never fall back to the old
// compact renderer: collapse is reserved for queue/archive rows. See
// docs/superpowers/specs/2026-07-11-expanded-strip-card2-parity-design.md
let _snItemsById = new Map();

function vjCardSkeleton(cid) {
  const src = document.getElementById('active-card');
  if (!src) return '';
  const clone = src.cloneNode(true);
  clone.removeAttribute('id');
  clone.classList.add('sn-vjcard', 'is-detailed');
  clone.classList.remove('in-wizard', 'is-empty', 'is-preflight', 'is-monitor', 'is-waiting', 'is-local', 'is-mini');
  clone.setAttribute('data-cid', cid);
  clone.removeAttribute('aria-hidden');
  // The singleton carries an inline `display:none` while idle (app.js sets
  // card.style.display directly); the clone inherits it, so clear it — the base
  // .vj-card grid rule then makes the expanded card visible.
  clone.style.removeProperty('display');
  // Convert every id → data-f so the clone can't duplicate ids in the document.
  clone.querySelectorAll('[id]').forEach((el) => { el.setAttribute('data-f', el.id); el.removeAttribute('id'); });
  // Strip the LOCAL singleton's live content out of the skeleton. #active-card is
  // kept populated with the local campaign (or "No campaign running") by the 2s
  // pollStatus loop; cloning it verbatim is why expanding a VM strip flashed the
  // local template before fillVjCard ran. Blank every value field + the local
  // controls/bulk panel so an unfilled clone is neutral, never local-looking.
  ['activeName', 'activeEyebrow', 'activePct', 'activeSent', 'activeTotal', 'activeAccounts',
   'activeAccepted', 'sendingLbl', 'activeLiveIco', 'activeLiveL1', 'activeLiveL2', 'monCount', 'monLine',
   'stageVerb', 'stageName', 'stageSub', 'stageSafety', 'stageFacts', 'stageMiles', 'stageBeatTxt', 'stageBeatRight',
   'stageSideLabel', 'stageSideValue', 'stageSideHelp', 'stageMetricAccepted', 'stageMetricIntroduced',
   'stageMetricRemaining', 'stageNextLabel', 'stageNextTitle', 'stageNextDetail', 'active-retry']
    .forEach((fld) => {
      const el = clone.querySelector(`[data-f="${fld}"]`);
      if (!el) return;
      el.textContent = '';
      // stageFacts/stageMiles cache their last rendered markup here. Keeping
      // this cache while deleting the DOM makes renderLiveStage conclude the
      // blank clone is already current, so the expanded dashboard loses the
      // exact progress detail still visible in Campaign Builder.
      delete el.dataset.html;
    });
  // The live stage arrives carrying the singleton's person, phase glyph and
  // render-guard dataset. Blank it so an unfilled clone can never show someone
  // else's lead, and so renderLiveStage redraws it from scratch for THIS card.
  const _cstage = clone.querySelector('[data-f="active-stage"]');
  if (_cstage) {
    _cstage.hidden = true;
    _cstage.dataset.phase = ''; _cstage.dataset.glyphphase = ''; _cstage.dataset.who = '';
    _cstage.dataset.acctkey = ''; _cstage.dataset.cid = '';
    const _cg = _cstage.querySelector('[data-f="stageGly"]'); if (_cg) _cg.innerHTML = '';
    const _ca = _cstage.querySelector('[data-f="stageAccts"]'); if (_ca) _ca.innerHTML = '';
    const _cd = _cstage.querySelector('[data-f="stageDrawer"]'); if (_cd) _cd.innerHTML = '';
    const _cf = _cstage.querySelector('[data-f="stageFix"]'); if (_cf) _cf.innerHTML = '';
  }
  // Same reason: the clone arrives carrying the local campaign's account
  // columns. Blank + hide them so renderRunPanel redraws from THIS campaign.
  const _cpanel = clone.querySelector('.sp'); if (_cpanel) { _cpanel.hidden = true; _cpanel.innerHTML = ''; }
  const _cbar = clone.querySelector('[data-f="activeBar"]'); if (_cbar) _cbar.style.width = '0%';
  const _clog = clone.querySelector('[data-f="active-log"]'); if (_clog) _clog.innerHTML = '';
  const _cctrl = clone.querySelector('.vj-controls'); if (_cctrl) _cctrl.innerHTML = '';
  const _cbulk = clone.querySelector('.vj-bulk'); if (_cbulk) _cbulk.style.display = 'none';
  return clone.outerHTML;
}

// "2 identical runs" beside the title. Sits next to the name span rather than
// inside it so the name stays a plain string everywhere else it is read.
function _setDupeChip(root, n) {
  const nameEl = root.querySelector('[data-f="activeName"]');
  if (!nameEl) return;
  let chip = nameEl.parentElement.querySelector('.vj-dupe');
  const count = Number(n) || 0;
  if (count < 1) { if (chip) chip.remove(); return; }
  if (!chip) {
    chip = document.createElement('span');
    chip.className = 'vj-dupe';
    nameEl.parentElement.appendChild(chip);
  }
  chip.textContent = `${count} identical run${count === 1 ? '' : 's'}`;
  chip.title = 'Another campaign for the same page, the same list and the same accounts was launched within minutes of this one. They compete for the same LinkedIn invite credits, so between them they send less than one would.';
}

function _fillVjMonitorHero(root, status) {
  // This card is a cloneNode(true) of card #2's LIVE DOM, so it arrives carrying
  // whatever caption and state class card #2 happened to be showing when it was
  // cloned. Updating only the number left those frozen — a gold "now" caption
  // beside a ticking countdown (operator screenshot 2026-07-31). Render all three
  // from one decision, exactly as v3RenderMonitorHero does.
  const view = monitorHeroView(status, v3FmtCountdown);
  const countEl = root.querySelector('[data-f="monCount"]');
  if (countEl) countEl.textContent = view.count;
  const capEl = root.querySelector('.vj-mon-cap');
  if (capEl) capEl.textContent = view.cap;
  const heroElB = root.querySelector('.vj-mon-hero');
  if (heroElB) {
    heroElB.classList.toggle('is-checking', view.state === 'checking');
    heroElB.classList.toggle('is-waking', view.state === 'waking');
  }
  const lineEl = root.querySelector('[data-f="monLine"]');
  if (lineEl) {
    const sent = Number(status.totalProcessed) || 0;
    const accepted = status.acceptedCount ?? '—';
    const cadMin = Number(status.checkIntervalMinutes) || 60;
    const cad = cadMin >= 60 ? (cadMin / 60) + 'h' : cadMin + ' min';
    let ends = '—';
    if (status.monitoringUntil) ends = new Date(status.monitoringUntil).toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' });
    lineEl.innerHTML = _monLineHtml(sent, accepted, cad, ends, status.followUp);
  }
  // v2.160.35: follow-up dual hero on the strip clone (mirrors card #2).
  const fu = status.followUp;
  const fuHero = root.querySelector('[data-f="active-fu-hero"]');
  if (fuHero) {
    if (fu && fu.count > 0) { _setFuDual(root.querySelector('[data-f="fuCount"]'), fu.dueAt); fuHero.hidden = false; }
    else fuHero.hidden = true;
  }
}

function _vjControlsHtml(c, status, options = {}) {
  const active = !!options.active;
  const dib = (svg, tip, onclick, cls = '', id = '') => `<button type="button"${id ? ` id="${id}"` : ''} class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;
  let dock = '';
  const interrupted = status && (status.state === 'interrupted' || status.interrupted || status.waitingForLocal);
  if (c.pause && !interrupted) dock += dib(status.paused ? V3_SVG_PLAY : V3_SVG_PAUSE, status.paused ? 'Resume' : 'Pause', c.pause.onclick, c.pause.once ? 'one-shot' : '', active ? 'dock-active-pause' : '');
  let actions = '';
  if (c.restart) actions += dib(V3_SVG_RESTART, 'Restart', c.restart.onclick);
  if (c.copy) actions += dib(V3_SVG_COPY, 'Copy to queue', c.copy.onclick);
  // v3.1.48.71: the go-again action leaves the dock and becomes a labelled
  // pill. As an unlabelled ▶ next to an unlabelled ■ it was unreadable — an
  // operator looking at a stopped campaign with 92 leads left could not tell
  // which glyph sent them. Its wording already comes from the matrix
  // ("Resume sending" / "Start now" / "Continue where it left off").
  let goHtml = '';
  for (const e of (c.extra || [])) {
    if (e.kind === 'show') actions += dib(V3_SVG_EYE, 'Show', e.onclick);
    else if (e.kind === 'play' || e.kind === 'queue') {
      goHtml += `<button class="btn-pill go${e.once ? ' one-shot' : ''}" onclick="${e.onclick}">${escHtml(e.tip || 'Resume sending')}</button>`;
    } else {
      const svg = e.kind === 'debrief' ? V3_SVG_DOC : e.kind === 'dup' ? V3_SVG_COPY
        : e.kind === 'restart' ? V3_SVG_RESTART
        : e.kind === 'delete' ? V3_SVG_TRASH : V3_SVG_XMARK;
      actions += dib(svg, e.tip, e.onclick, e.once ? 'one-shot' : '');
    }
  }
  // Same reasoning for Stop: a red square is a warning shape, not a sentence.
  // The matrix already says which stop this is (Stop check / Stop monitoring /
  // End campaign); a bare "Stop" becomes "Stop campaign".
  const stopTip = (c.stop && c.stop.tip) || 'Stop';
  const stopHtml = c.stop
    ? `<button class="btn-pill stop"${active ? ' id="btn-active-stop"' : ''} onclick="${c.stop.onclick}">${escHtml(stopTip === 'Stop' ? 'Stop campaign' : stopTip)}</button>`
    : '';
  const openHtml = c.open ? `<button class="btn-pill" onclick="${c.open.onclick}">Open campaign tab</button>` : '';
  const sheetHtml = c.sheet ? `<button class="btn-pill" onclick="${c.sheet.onclick}">Open sheet</button>` : '';
  const detailsHtml = active
    ? `<button class="vj-toggle-btn" data-tip="Show details" aria-label="Show details" onclick="window.toggleActiveDetails(this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg></button>`
    : '';
  const autoHtml = c.monAuto
    ? `<label class="sn-mon-auto" title="When off, automatic acceptance checks stay off; Run check now still works."><input type="checkbox" ${c.monAuto.checked ? 'checked' : ''} onclick="event.stopPropagation()" onchange="${c.monAuto.onclick}"> Auto checks</label>`
    : '';
  const resumeHtml = interrupted && c.pause
    ? `<button class="btn-pill go one-shot" onclick="${c.pause.onclick}">Resume ${status.interruption?.phase === 'monitoring' || status.monitoringPhase ? 'checks' : 'campaign'}</button>`
    : '';
  const resumeSendingHtml = interrupted && c.resumeSending
    ? `<button class="btn-pill go one-shot" onclick="${c.resumeSending.onclick}">Resume sending</button>`
    : '';
  const deleteForeverHtml = interrupted && c.deleteForever
    ? `<button class="btn-pill delete-forever" onclick="${c.deleteForever.onclick}">Delete for good</button>`
    : '';
  const dockHtml = (dock || actions)
    ? `<div class="dock"${active ? ' id="dock-active"' : ''} role="toolbar" aria-label="Campaign actions">${dock}<div class="dock-actions">${actions}</div></div>`
    : '';
  return `${resumeHtml}${resumeSendingHtml}${deleteForeverHtml}${openHtml}${detailsHtml}${sheetHtml}${goHtml}${autoHtml}${stopHtml}${dockHtml}`;
}

// One renderer owns the controls on BOTH campaign surfaces. The Dashboard's
// expanded card and the Campaign tab's large card may have different layouts,
// but Pause, Resume, Stop, Check, Copy, Open and monitoring controls must always
// come from the same state matrix and carry the same campaign id.
function _renderVjCardControls(root, status, options = {}) {
  if (!root || !status) return null;
  const c = vjCardControlsFor(status);
  const controls = root.querySelector('.vj-controls');
  if (controls) controls.innerHTML = _vjControlsHtml(c, status, options);

  const logActs = root.querySelector('.vj-log-acts');
  if (logActs) {
    logActs.querySelectorAll('.vj-log-act').forEach((b) => {
      const txt = (b.textContent || '').toLowerCase();
      if (b.getAttribute('data-f') === 'wiz-log-more' || b.id === 'wiz-log-more') {
        b.style.display = options.active ? '' : 'none';
        return;
      }
      if (txt.includes('copy')) b.setAttribute('onclick', options.active ? 'window.dashCopyLog(this)' : 'copyVjCardLog(this)');
      // Open sheet has one canonical, campaign-bound home in the main row.
      if (txt.includes('open sheet')) b.style.display = 'none';
    });
  }

  const bulkWrap = root.querySelector('.vj-bulk');
  if (bulkWrap) {
    bulkWrap.style.display = c.bulk ? '' : 'none';
    const bb = root.querySelector('[data-f="vj-bulk-btn"], #vj-bulk-btn');
    if (bb && c.bulk) {
      bb.setAttribute('onclick', c.bulk.onclick);
      bb.disabled = !!status.monitoringCheckInProgress;
      bb.setAttribute('aria-disabled', bb.disabled ? 'true' : 'false');
    }
    const lbl = root.querySelector('[data-f="vj-bulk-btn-label"], #vj-bulk-btn-label');
    if (lbl && c.bulk) lbl.textContent = status.monitoringCheckInProgress ? 'Check in progress' : (c.bulk.label || 'Run check now');
  }

  if (options.active && typeof _setActiveDetails === 'function') {
    _setActiveDetails(root.classList.contains('is-detailed'));
  }
  return c;
}

// The banner is the SAME .vj-live band, promoted. One component, four tones, so
// checking, waking, stopping and sending all read alike. Both card fillers call
// this one function (#active-card and the board strip's clone are the same
// markup) so the two surfaces cannot drift.
//
// It never un-hides the band: .vj-live and .vj-stage share one grid slot and are
// mutually exclusive, so whichever the caller chose stays chosen.
function applyLiveBanner(live, status) {
  if (!live) return;
  const liveCard = live.closest('.vj-card');
  const move = _hoFor(status);
  // Mid-fade: leave the banner exactly where it is. A poll landing inside the
  // 460ms fade would otherwise rebuild it and restart the animation.
  if (move && move.out && live.classList.contains('is-handover')) return;
  // Torn down and rebuilt every render, never reused: the fillers run on every
  // 2s poll, and appending without removing stacks a new beacon every 2 seconds.
  live.classList.remove('is-checking', 'is-sending', 'is-waking',
    'is-handover', 'to-cloud', 'to-local', 'landed', 'out');
  live.querySelector('.ck-beacon')?.remove();
  live.querySelector('.ck-right')?.remove();
  live.querySelector('.ck-stop')?.remove();
  live.querySelector('.ho-track')?.remove();
  live.querySelector('.ho-right')?.remove();
  // A move between this Mac and the VM outranks every other tone: it is the
  // moment the operator is most likely to think the app has hung, and while it
  // is on the wire nothing else on the card is true yet.
  if (move) { _paintHandover(live, move); return; }
  if (liveCard) liveCard.classList.remove('is-handover-active');
  const b = bannerFor(status);
  if (!b) return;
  const l1 = live.querySelector('.vj-live-l1');
  const l2 = live.querySelector('.vj-live-l2');
  if (l1) l1.textContent = b.l1;
  if (l2) l2.textContent = b.l2;
  live.classList.add(b.tone === 'wake' ? 'is-waking' : 'is-checking');
  if (b.tone === 'send') live.classList.add('is-sending');
  const beacon = document.createElement('i');
  beacon.className = 'ck-beacon';
  live.prepend(beacon);
  if (b.big) {
    const right = document.createElement('div');
    right.className = 'ck-right';
    right.innerHTML = `<b>${escHtml(b.big)}</b><span>${escHtml(b.cap)}</span>`;
    live.append(right);
  }
  // A check can be stopped wherever it runs. The local route reaches into this
  // Mac's own campaign; the cloud one raises a flag the VM's sweep consumes at
  // its next account boundary. Offering it only on local was why the button was
  // missing on exactly the campaigns most operators watch — the ones on the VM.
  if (b.tone === 'check') {
    const onCloud = !!(status && status._cloud);
    const cid = String((status && (status.rawId || status.id)) || '');
    if (!onCloud || cid) {
      const stop = document.createElement('button');
      stop.className = 'btn-pill ck-stop';
      stop.textContent = 'Stop the check';
      stop.onclick = async () => {
        stop.disabled = true;
        const url = onCloud
          ? `/api/campaign/cloud/${encodeURIComponent(cid)}/check/stop`
          : '/api/campaign/check/stop';
        try {
          const r = await fetch(url, { method: 'POST' });
          const d = await r.json().catch(() => ({}));
          if (!r.ok || d.error) {
            stop.disabled = false;
            if (typeof showCampaignToast === 'function') {
              showCampaignToast(d.error && !/HTTP 404/.test(d.error)
                ? d.error
                : 'Stopping a VM check isn’t live yet — engine update pending.', 6000);
            }
            return;
          }
          // The VM finishes the account it is on before it stops, so say that
          // rather than letting a dead button imply it already has.
          if (onCloud && typeof showCampaignToast === 'function') {
            showCampaignToast(d.wasRunning === false
              ? 'Nothing was running — no check to stop.'
              : '🛑 Stopping — the VM will finish the account it is on, then stop.', 5000);
          }
          if (onCloud) _cloudCheckAsked.delete(cid);
        } catch (_) { stop.disabled = false; }
      };
      live.append(stop);
    }
  }
}

// ── The per-account panel ───────────────────────────────────────────────────
// One column per account, three visible, the account that is working centred.
// Both card fillers call this one function, exactly like applyLiveBanner above:
// #active-card and the board strip's clone are the same markup, so the two
// surfaces cannot drift.
//
// Everything here comes from accountColumns(); nothing is invented. An account
// with no turn size shows no batch counter at all rather than a confident "of
// 8", and an account this campaign never selected shows no daily cap rather
// than "0 of 0 sent today".

// Only these four step marks have a mark glyph in the CSS. The engine only ever
// sends 'now' today, but a class straight off the payload could land unstyled.
const SP_STEP_MARKS = new Set(['ok', 'now', 'wait', 'miss']);

function _spStateClass(state) {
  // The state vocabulary is a fixed set of lowercase words; anything else would
  // be an unstyled class at best and a broken attribute at worst.
  return String(state || '').toLowerCase().replace(/[^a-z-]/g, '');
}

function _spColHtml(c) {
  const cls = _spStateClass(c.state);
  const steps = c.steps.length
    ? `<div class="sp-steps">${c.steps.map((s) => {
        const mark = SP_STEP_MARKS.has(s[0]) ? s[0] : 'now';
        return `<div class="sp-step ${mark}"><i class="sp-mk"></i><span>${escHtml(s[1] || '')}</span>`
          + `<span class="sp-t">${escHtml(s[2] || '')}</span></div>`;
      }).join('')}</div>`
    : '';
  // The turn. An absent size means the mode drains everything in one go, so
  // there is no turn to be N of, and the day counter carries the whole story.
  const batch = c.batchSize == null ? '' :
    `<div class="sp-count"><b>${c.batchDone} of ${c.batchSize}</b><span>this batch</span></div>`
    + `<div class="sp-cbar">${batchPips(c.batchDone, c.batchSize, c.live).map((k) => `<i class="${k}"></i>`).join('')}</div>`;
  // The day. A zero cap means a sweep found this account but the campaign never
  // selected it, so it gets said plainly instead of an invented "0 of 0".
  const day = c.dailyLimit > 0
    ? `<div class="sp-day"><b>${c.sentToday}</b> of <b>${c.dailyLimit}</b> sent today<span>${escHtml(c.sub)}</span></div>`
    : `<div class="sp-day"><span>Not one of this campaign's accounts.</span><span>${escHtml(c.sub)}</span></div>`;
  const miss = c.missed.length
    ? `<div class="sp-miss"><div class="sp-miss-h">Nobody reached, and why</div>${c.missed.map((m) =>
        `<div class="sp-miss-r"><b>${escHtml(m.who)}</b><span>${escHtml(m.why)}</span></div>`).join('')}</div>`
    : '';
  const res = c.result ? `<div class="sp-res">${escHtml(c.result)}</div>` : '';
  return `<div class="sp-col ${cls}">`
    + `<div class="sp-who">${escHtml(c.email)}</div>`
    + `<div class="sp-state">${escHtml(c.state)}</div>`
    // People already reached are historical events and belong in the shared
    // live log. Repeating them here pushed the current batch position below
    // the fold, exactly when an operator most needs to see it.
    + steps + batch + day + miss + res
    + '</div>';
}

function renderRunPanel(card, status) {
  const panel = card && card.querySelector('.sp');
  if (!panel) return;
  const cols = accountColumns(status);
  if (!cols.length) {
    panel.hidden = true;
    if (panel.innerHTML) panel.innerHTML = '';
    panel._spHtml = ''; panel._spIdx = null;
    return;
  }
  panel.hidden = false;

  const idx = railIndex(cols);
  const html = `<div class="sp-head"><span class="sp-pos">‹ ${idx + 1} of ${cols.length} ›</span></div>`
    + `<div class="sp-grid">${cols.map(_spColHtml).join('')}</div>`;

  // This runs on every 2s poll. Rebuilding identical markup would drop the
  // operator's scroll on the floor for nothing, so an unchanged panel is left
  // completely alone.
  if (panel._spHtml !== html) {
    // The working account's timer ticks, so the panel DOES change on most
    // polls. Carry the operator's scroll across the rebuild; only the centring
    // below may move it, and only when the working account changes.
    const prev = panel.querySelector('.sp-grid');
    const keep = prev ? prev.scrollLeft : 0;
    panel.innerHTML = html;
    panel._spHtml = html;
    const railNow = panel.querySelector('.sp-grid');
    // The rail's CSS scroll-behavior is smooth, which is right for a drag and
    // wrong for us: every scrollLeft we set below would animate from 0, once a
    // second, and read as the panel twitching. Ours are instant.
    if (railNow) railNow.style.scrollBehavior = 'auto';
    if (railNow && keep) railNow.scrollLeft = keep;
  }

  // Centre the working account. The first one sits flush left instead, because
  // there is no previous account to show beside it. Done only when the working
  // account CHANGES: doing it every poll would drag the rail back every two
  // seconds while the operator was scrolling through the other accounts.
  if (panel._spIdx !== idx) {
    const rail = panel.querySelector('.sp-grid');
    if (rail) {
      const w = rail.scrollWidth / cols.length;
      rail.scrollLeft = idx <= 0 ? 0 : Math.max(0, (idx - 1) * w);
    }
    panel._spIdx = idx;
  }
}

// One appearance contract for every incarnation of a live campaign card.
// Both the Campaign Builder singleton and every expanded dashboard clone call
// this on every paint. Removing the full set first prevents a reused DOM node
// from carrying a VM/LM or lifecycle tint from its previous state.
function applyVjCardAppearance(root, status, fields) {
  if (!root) return;
  const f = fields || vjCardFields(status || {});
  const phase = String((status && status.phase) || '').toLowerCase();
  const state = String((status && status.state) || '').toLowerCase();
  const interrupted = !!(f.isInterrupted || state === 'interrupted' || (status && status.interrupted));
  const _resumingNow = !!(status && status.resuming) || _isResumingId(status && status.id, state);
  const monitoring = !_resumingNow
    && !!(f.isMonitor || state === 'monitoring' || phase === 'monitoring' || phase === 'checking');
  const queued = !!(status && (status.queued || state === 'queued'));
  const starting = phase === 'starting' || phase === 'preflight' || state === 'launching';
  const waiting = !!(f.isWaiting || state === 'waiting');
  const paused = !!(status && (status.paused || status._paused || state === 'paused'));
  // The stop is in flight: the operator clicked, the VM has not confirmed yet.
  // Until v3.1.48.112 the card stayed green through the whole wait, with step
  // 01 still reading "running", so a click that had registered looked identical
  // to one that had not.
  const stopping = !!(status && (status.stopping || state === 'stopping' || state === 'pausing'
    || phase === 'stopping' || String(status.engineStatus || '').toLowerCase() === 'stopping'));
  // The resume is in flight: the operator clicked, the VM has not confirmed yet.
  // Set optimistically on the click and cleared by the next poll rebuild. Without
  // it the card kept the blue monitoring tint for the whole round-trip, so a
  // click that HAD registered looked identical to one that had not (operator,
  // 2026-09-01). Green is the default tone, so dropping `monitoring` is the whole
  // colour change — no new palette.
  const resuming = _resumingNow;
  // Older/local payloads may only retain logs after completion rather than an
  // explicit finished state. Keep those legacy shapes on the same visual path.
  const inferredDone = !!(status && !status.running && !monitoring && !interrupted
    && !queued && !starting && Array.isArray(status.logs) && status.logs.length > 0);
  const done = !!(status && (state === 'done' || state === 'finished' || phase === 'done' || inferredDone));
  const terminal = done ? terminalPresentation(status) : null;
  const local = _whSide(status || {}) === 'local';

  root.classList.remove('is-monitor', 'is-monitoring', 'is-waiting',
    'is-interrupted', 'is-error', 'is-queued', 'is-starting', 'is-paused',
    'is-done', 'is-stopped', 'is-stopping', 'is-resuming', 'is-local');
  root.classList.toggle('is-monitor', monitoring);
  root.classList.toggle('is-monitoring', monitoring);
  root.classList.toggle('is-waiting', waiting);
  root.classList.toggle('is-interrupted', interrupted);
  root.classList.toggle('is-error', state === 'error' || phase === 'error');
  root.classList.toggle('is-queued', queued);
  root.classList.toggle('is-starting', starting);
  root.classList.toggle('is-paused', paused);
  root.classList.toggle('is-done', done);
  root.classList.toggle('is-stopped', !!(done && terminal && !terminal.complete));
  // Not while done: a finished stop owns 'is-stopped', this is only the wait.
  root.classList.toggle('is-stopping', stopping && !done);
  root.classList.toggle('is-resuming', resuming && !done);
  root.classList.toggle('is-local', local);
}

// An errored campaign's one big way back in. Both card renderers call this —
// the #active-card singleton and every expanded strip clone — so the wording
// and the action cannot drift apart. Everything it decides (which restart is
// safe, and what to call it) lives in failedStartRetry; this only paints.
function renderFailedStartRetry(root, status) {
  const el = root && (root.querySelector('#active-retry') || root.querySelector('[data-f="active-retry"]'));
  if (!el) return false;
  // The live line and this panel share one grid slot; the CSS hides the live
  // line whenever this one is showing, so neither renderer's ordering can put
  // them on top of each other.
  const r = status ? failedStartRetry(status) : null;
  if (!r) { el.hidden = true; el.innerHTML = ''; el.dataset.html = ''; return false; }
  const html = `<div class="t"><b>${escHtml(r.headline)}</b><span>${escHtml(r.detail)}</span></div>`
    + `<button type="button" onclick="${r.onclick}">${escHtml(r.label)}</button>`;
  if (el.dataset.html !== html || !el.firstElementChild) { el.innerHTML = html; el.dataset.html = html; }
  el.hidden = false;
  return true;
}

// The newest line is at the BOTTOM of the log, and the box shows about six of
// its fifteen lines. Nothing ever scrolled it, so the operator only ever saw
// the OLDEST six — and because the dashboard board rebuilds its whole innerHTML
// on every poll (app.js, `board.innerHTML = final`) the box was a brand new
// node each time with scrollTop back at 0, which reads as the log jumping
// upwards every two seconds. Measured 2026-08-28: height 200, scrollHeight 400
// to 469, scrollTop 0 on every sample, and the node identity lost on each poll.
//
// So: stick to the newest line by default, and remember per campaign when the
// operator has scrolled up to read something, because that intent has to
// survive a rebuild that throws the element away.
const _vjLogPin = new Map(); // campaign id → { bottom, top }
// A WeakSet, not a data- attribute: every board card is a CLONE of the
// dashboard's #active-card, so an attribute set on the template's log box is
// inherited by every clone. Flagged that way, the clones all believed they were
// already wired and none of them ever recorded a scroll (measured: the memory
// map stayed empty and a scrolled-up log snapped back within two seconds).
const _vjLogWired = new WeakSet();
function _pinLogToNewest(logEl, key) {
  if (!logEl) return;
  const atBottomNow = () => logEl.scrollHeight - logEl.scrollTop - logEl.clientHeight < 8;
  if (!_vjLogWired.has(logEl)) {
    _vjLogWired.add(logEl);
    logEl.addEventListener('scroll', () => {
      // A scroll event can land on a box that is mid-rebuild and not laid out
      // yet, where every measurement is 0 and "am I at the bottom" answers YES.
      // That false yes overwrote the operator's scrolled-up position about
      // three seconds after they scrolled, snapping the log back down.
      if (!logEl.clientHeight) return;
      _vjLogPin.set(key, { bottom: atBottomNow(), top: logEl.scrollTop });
    }, { passive: true });
  }
  const mem = key ? _vjLogPin.get(key) : null;
  if (!mem || mem.bottom) logEl.scrollTop = logEl.scrollHeight;
  else logEl.scrollTop = Math.min(mem.top, logEl.scrollHeight);
}

function fillVjCard(root, status) {
  if (!root || !status) return;
  root.dataset.campaignId = String(status.rawId || status.id || '');
  root.dataset.sheetUrl = String(status.sheetUrl || status.sheet_url
    || _cloudSheetUrls.get(String(status.rawId || status.id || '')) || '');
  const f = vjCardFields(status);
  const set = (name, text) => { const el = root.querySelector(`[data-f="${name}"]`); if (el) el.textContent = text; };
  applyVjCardAppearance(root, status, f);
  root.classList.add('is-detailed');
  root.classList.remove('is-empty', 'is-preflight');

  set('activeName', f.name);
  _setDupeChip(root, status.dupes);
  set('activeEyebrow', f.eyebrow);
  set('activePct', String(f.pct));
  set('activeSent', String(f.done));
  set('activeTotal', String(f.total));
  set('activeAccounts', String(f.accountsCount));
  set('activeAccepted', f.accepted);
  set('sendingLbl', f.sendingLbl);
  const bar = root.querySelector('[data-f="activeBar"]'); if (bar) bar.style.width = `${f.pct}%`;
  const glyph = root.querySelector('[data-f="activeGlyph"]'); if (glyph && typeof _cloudBadge === 'function') glyph.textContent = _cloudBadge(status.mode);

  try {
    const la = buildLiveActivity(status);
    const live = root.querySelector('[data-f="active-live"]');
    if (live) {
      live.hidden = (la.state === 'idle');
      live.classList.toggle('is-checking', la.state === 'checking');
      live.classList.toggle('is-waking', la.state === 'waking');
      live.classList.toggle('is-paused', la.state === 'paused');
      set('activeLiveIco', la.icon); set('activeLiveL1', la.l1); set('activeLiveL2', la.l2);
    }
    const staged = renderLiveStage(root, status);
    if (live && staged) live.hidden = true;
    // A finished FG run explains itself in the same slot the live line uses —
    // it's the one place the operator already looks for "what is going on".
    const note = _fgFinishedNote(status);
    if (live && note) {
      // Same slot, so taking it back from the stage means hiding the stage —
      // otherwise this note draws on top of it (see the guard in renderLiveStage).
      if (staged) _hideStage(root);
      live.hidden = false;
      live.classList.remove('is-checking', 'is-waking', 'is-paused');
      live.classList.add('is-outcome');
      set('activeLiveIco', note.icon); set('activeLiveL1', note.l1); set('activeLiveL2', note.l2);
    } else if (live) live.classList.remove('is-outcome');
    // Promote the band into the loud banner whenever something is genuinely in
    // flight. Last, so it wins over the plain one-line text above it, and
    // unconditional so a finished card clears the beacon a running one left.
    applyLiveBanner(live, status);
  } catch (_) { /* live line best-effort */ }

  try { renderFailedStartRetry(root, status); } catch (_) { /* retry panel is best-effort */ }

  // The per-account panel, from the same builder the dashboard card uses.
  try { renderRunPanel(root, status); } catch (_) { /* panel is best-effort */ }

  if (f.isMonitor) _fillVjMonitorHero(root, status);

  // Same RUNNING ON control as #active-card — the board strip's clone is the
  // other place an operator asks "which machine is doing this".
  try { renderWhereControl(root, status); } catch (_) { /* handover control is best-effort */ }

  const logEl = root.querySelector('[data-f="active-log"]');
  if (logEl) {
    const lines = Array.isArray(status.logs) ? status.logs.slice(-15) : [];
    logEl.innerHTML = lines.map((l) => v3RenderLogLine(l)).join('');
    const head = root.querySelector('.vj-log-head .vj-details-head');
    if (head) head.textContent = `Live log · last ${lines.length} events`;
    _pinLogToNewest(logEl, String(status.id || (root.closest('.sn-strip') || {}).dataset?.cid || ''));
  }

  // The cloned log-action buttons carry singleton-targeting onclicks
  // (openRunningSheet / dashCopyLog read the local cockpit campaign). Rewire
  // "Copy all" and "Open sheet" act on THIS card. Only the wizard-specific
  // show-more button remains hidden on board clones.
  const logActs = root.querySelector('.vj-log-acts');
  if (logActs) {
    logActs.querySelectorAll('.vj-log-act').forEach((b) => {
      const txt = (b.textContent || '').toLowerCase();
      if (b.getAttribute('data-f') === 'wiz-log-more') { b.style.display = 'none'; return; }
      if (txt.includes('copy')) b.setAttribute('onclick', 'copyVjCardLog(this)');
      // Open sheet has one canonical home in the main control row. Keeping a
      // second copy here made the same action appear twice beside each other.
      if (txt.includes('open sheet')) { b.style.display = 'none'; return; }
    });
  }

  // The Campaign tab calls this same renderer. State and campaign identity now
  // decide every action once; the surface displaying the card does not.
  _renderVjCardControls(root, status);
}

// Copy an expanded strip card's OWN log (not the singleton's __activeFullLogs).
window.copyVjCardLog = function (btn) {
  const card = btn && btn.closest('.sn-vjcard');
  const log = card && card.querySelector('[data-f="active-log"]');
  const text = log ? [...log.children].map((c) => c.textContent.trim()).join('\n') : '';
  try { navigator.clipboard.writeText(text); } catch (_) { /* clipboard best-effort */ }
  const orig = btn.textContent; btn.textContent = 'Copied'; setTimeout(() => { btn.textContent = orig; }, 1200);
};

// Open the sheet belonging to the card that contains the clicked control.
// Expanded board cards must never inherit the singleton campaign's handler.
window.openVjCardSheet = function (btn) {
  const card = btn && btn.closest('.vj-card');
  const url = String((card && card.dataset.sheetUrl) || '').trim();
  if (url) {
    try { window.open(url, '_blank', 'noopener'); } catch (_) { location.href = url; }
    return;
  }
  if (card && card.id === 'active-card') {
    try { openRunningSheet(); return; } catch (_) { /* fall through */ }
  }
  if (typeof showCampaignToast === 'function') showCampaignToast('This campaign has no Google Sheet URL saved yet.', 4500);
};

// Board-strip monitoring countdowns, ticked once a second.
//
// This used to be an interval started from _fillVjCards and stopped by itself
// whenever a tick found no EXPANDED monitor card — which deadlocked. The two
// halves disagreed about when the ticker should exist: _fillVjCards started it
// for any monitoring campaign (collapsed included), the tick required an
// expanded one and destroyed the interval when it found none. So with every
// strip collapsed the ticker killed itself one second in; expanding a strip is
// a local class toggle that doesn't re-render the board; and the board's
// anti-jank skip (`final === _lastBoardHtml → return`) meant _fillVjCards —
// the only thing that could restart it — never ran again. Countdowns froze
// until something else changed the board HTML. The campaign-tab card never had
// this because its ticker is a plain module-level interval.
//
// So: one module-level interval that no-ops when there is nothing to tick,
// never stops, and is never coupled to the render path.
//
// The countdown source is _snItemsById (assigned BEFORE the anti-jank early
// return, so it's fresh even on a skipped render) with the card's dataset as
// the fallback — otherwise a skipped render would leave a stale nextcheck
// ticking past zero into a permanent "now".
function _tickVjCards() {
  // `.sn-board` (class), NOT `#sn-board` (id). There are TWO boards: the
  // dashboard renders into #campaigns-board, the Sales Nav Scraper page into
  // #sn-board — and both carry class="sn-board". The id selector meant this
  // never matched a single dashboard card, so the strip countdown never ticked
  // there at all: what looked like a 5-second tick was the board poll
  // re-rendering the strip, and the freeze was that redraw being skipped.
  const cards = document.querySelectorAll('.sn-board .sn-strip:not(.sn-collapsed) .sn-vjcard.is-monitor');
  if (!cards.length) return; // nothing on screen to tick — NOT a reason to stop
  cards.forEach((card) => {
    const cid = card.closest('.sn-strip')?.dataset.cid;
    const it = cid ? _snItemsById.get(cid) : null;
    let status = null;
    try { status = it ? statusFromItem(it) : null; } catch (_) { status = null; }
    const heroB = card.querySelector('.vj-mon-hero');
    const busy = !!(heroB && (heroB.classList.contains('is-checking') || heroB.classList.contains('is-waking')));
    const text = monitorTickText({
      nextCheckAt: (status && status.nextCheckAt) || card.dataset.nextcheck || null,
      busy,
      fmtCountdown: v3FmtCountdown,
    });
    const el = card.querySelector('[data-f="monCount"]');
    if (el && text !== null) el.textContent = text;
    const fd = (status && status.followUp && status.followUp.dueAt) || card.dataset.fudue;
    if (fd) _setFuDual(card.querySelector('[data-f="fuCount"]'), Number(fd));
  });
}
setInterval(_tickVjCards, 1000);

// Fill every strip's cloned card from its board item. Called after each board
// render. We fill COLLAPSED cards too (cheap text sets on a display:none node):
// that way a strip's clone already holds ITS OWN campaign data before it's ever
// revealed, so expanding a VM strip shows the VM card instantly instead of
// flashing the local #active-card template the skeleton was cloned from.
function _fillVjCards(board) {
  const cards = board.querySelectorAll('.sn-strip .sn-vjcard');
  cards.forEach((card) => {
    const cid = card.closest('.sn-strip')?.dataset.cid;
    const it = cid ? _snItemsById.get(cid) : null;
    if (!it) return;
    const status = statusFromItem(it);
    card.dataset.nextcheck = status.nextCheckAt || '';
    card.dataset.fudue = (status.followUp && status.followUp.dueAt) || '';
    try { fillVjCard(card, status); } catch (_) { /* per-card best-effort */ }
  });
  // No ticker wiring here on purpose — _tickVjCards runs on its own module-level
  // interval. Starting/stopping it from the render path is exactly what froze
  // every board countdown once the anti-jank skip stopped calling this.
}

function renderSavedCampaignStrip(it) {
  const id = escHtml(it.id);
  const action = (icon, label, handler, cls = '') => `<button type="button" class="dock-btn ${cls}" data-tip="${label}" aria-label="${label}" onclick="${handler}">${icon}</button>`;
  if (it.campaignId) {
    const controls = campaignActionSpecs(it).map(spec => spec.action === 'open' || spec.action === 'queue'
      ? `<button class="mini${spec.action === 'open' ? ' solid' : ''}" onclick="${spec.onclick}">${spec.action === 'open' ? 'Open' : 'Queue'}</button>`
      : action(spec.kind === 'dup' ? V3_SVG_COPY : spec.kind === 'delete' ? V3_SVG_TRASH : V3_SVG_PLAY, spec.label, spec.onclick, spec.kind === 'delete' ? 'danger' : '')).join('');
    return `<div class="sn-strip done sn-collapsed"><div class="sn-top"><span class="sn-type">Saved campaign</span></div><div class="sn-name">${escHtml(it.name)}</div><div class="sn-foot"><div class="right">${controls}</div></div></div>`;
  }
  return `<div class="sn-strip done sn-collapsed"><div class="sn-top"><span class="sn-type">Saved campaign</span></div><div class="sn-name">${escHtml(it.name)}</div><div class="sn-foot"><div class="right">`
    + action(V3_SVG_PLAY, 'Start campaign', `openSavedCampaignStart('${id}')`)
    + action(V3_SVG_TRASH, 'Delete', `deleteBoardCampaign('${id}', this)`, 'danger')
    + action(V3_SVG_COPY, 'Duplicate', `duplicateCampaign('${id}')`)
    + `<button class="mini solid" onclick="openCampaignForEdit('${id}')">Open</button></div></div></div>`;
}
window.openSavedCampaignStart = async function(id, action = 'start') {
  await openCampaignForEdit(id);
  scrollToSection('nav-launch');
  document.getElementById(action === 'queue' ? 'btn-queue' : 'btn-start')?.focus({ preventScroll: true });
};

function renderUnifiedStrip(it) {
  if (it.bucket === 'saved') return renderSavedCampaignStrip(it);
  const cloud = it.where === 'cloud';
  const running = it.bucket === 'running';
  const queued = it.bucket === 'queued';
  const done = it.bucket === 'done';
  // Monitoring is a lifecycle, not a location. Local monitoring must use the
  // same blue state and controls as VM monitoring instead of looking paused.
  const monitoring = !!(it.monitoring || it.monitoringPhase || it.engineStatus === 'monitoring');
  const locallyOwnedMonitoring = monitoring && String(it.runsOn || (cloud ? 'vm' : 'local')) === 'local';
  // Asleep on blocked_until: sending is gated until a real unblock time, but the
  // DB status stays 'running' SO THE MONITOR SWEEP KEEPS RUNNING. The chip must
  // report the truth about SENDING, not echo the raw status word — a green
  // "Running" sitting above a card that says every account is capped is the same
  // lie as the "Working…" this card was built to kill. Bucket stays `running` on
  // purpose: the controls and the acceptance sweep both depend on it.
  const waiting = !!(it.currentAction && it.currentAction.phase === 'waiting');
  const scheduled = queued && !!it.scheduledAt;
  const whenTxt = scheduled && typeof v3FormatScheduledAt === 'function' ? v3FormatScheduledAt(it.scheduledAt) : '';
  // One active campaign, one component. A previously-unexpanded live row used
  // the legacy compact markup, then swapped to the canonical card on expand.
  // Besides looking unrelated, the two paths derived WAITING/RUNNING differently.
  // Every active lifecycle state now stays on the literal #active-card clone.
  const collapsed = queued ? true : running ? _snCollapsedActive.has(it.id) : !_snExpanded.has(it.id);
  const badge = _cloudBadge(it.mode);
  const acctWord = it.accounts === 1 ? 'account' : 'accounts';

  // Rail (sketch A · muted archive): colour = live + errors only. running cloud →
  // green (.run); running local → pink (.local.run); monitoring → blue
  // (.monitoring, wins over .run); scheduled → gold (.sched); done → ink
  // (.done rail); ERROR → red (.stopped); CANCELLED / operator-Stopped → faded
  // gray (.cancelled, NOT red). Only a genuine LinkedIn/send error is red now.
  // Terminal states keep .done too for the slim collapsed layout; the colour
  // classes override its rail via :not(.stopped):not(.cancelled).
  const errored = it.bad && it.badLabel === 'Error';
  const cancelled = it.bad && !errored;            // 'Cancelled' / 'Stopped' — benign
  // Ownership, not provenance — same rule as the "This machine" pill below. A
  // cloud campaign handed over to this Mac RUNS here, so it gets the pink local
  // rail; keying the rail off `where` alone painted it cloud-green while the
  // pill on the same row said This machine (operator, 2026-08-28).
  const _ownedLocal = it.where === 'local' || String(it.runsOn || '') === 'local';
  const stateCls = [
    _ownedLocal ? 'local' : '',
    running && !monitoring && !waiting ? 'run' : '',
    (monitoring || waiting) ? 'monitoring' : '',
    queued ? 'queued' : '',
    scheduled ? 'sched' : '',
    done ? 'done' : '',
    'sn-collapsed',
    errored ? 'stopped' : '',
    cancelled ? 'cancelled' : '',
  ].filter(Boolean).join(' ');

  // Saying "☁︎ VM" on a campaign running here is the exact lie the handover
  // feature exists to kill. runsOn is absent on pre-handover campaigns ⇒ VM.
  const wherePill = _ownedLocal
    ? '<span class="sn-where local">💻 This machine</span>'
    : '<span class="sn-where cloud">☁︎ VM</span>';
  const whenPill = scheduled ? '<span class="sn-when-pill">⏰ Scheduled</span>' : '';
  const dot = errored ? '<span class="dot red"></span>'
    : it.bad ? '<span class="dot cancel"></span>'   // cancelled / stopped — gray, not red
    : (monitoring || waiting) ? '<span class="dot mon"></span>'
    // Pink dot follows the pink rail: where it RUNS, not where it came from.
    : running ? (_ownedLocal ? '<span class="dot runlocal"></span>' : '<span class="dot run"></span>')
    : scheduled ? '<span class="dot gold"></span>'
    : queued ? '<span class="dot q"></span>'
    : '<span class="dot done"></span>';            // done — ink (black light / white dark)
  // #17: a cloud campaign sits `queued` from dispatch until a worker picks it up
  // (~2–3 min cold start). Show "warming up" for that window so operators aren't
  // staring at a dead-looking "Queued". After 3 min, fall back to plain "Queued"
  // (a genuinely-stuck queue shouldn't claim it's warming up forever). Reuses the
  // existing queued dot — no new colour (mono design system).
  const warming = cloud && queued && it.createdAt
    && (Date.now() - new Date(it.createdAt).getTime()) < 3 * 60 * 1000;
  let statusTxt = scheduled ? whenTxt
    : warming ? '⏳ Warming up (~2 min)'
    : queued ? 'Queued'
    : monitoring ? 'Monitoring'
    : waiting ? 'Waiting'
    : running ? (it.paused && !locallyOwnedMonitoring ? 'Paused' : (it.isFG ? 'Inviting' : 'Running'))
    : it.bad ? (it.badLabel || 'Stopped')
    : 'Done';
  // Phase 0 primary-handshake lock (Task 3.4): the engine pauses a cloud
  // campaign in 'awaiting_primary_accept' while this Mac accepts the
  // primary's connection requests as the local primary. Dormant until the
  // engine ships `state` + `senders` on the campaign detail — until then
  // both stay undefined and this never fires (graceful degradation).
  const hsAwaiting = cloud && it.state === 'awaiting_primary_accept' && Array.isArray(it.senders);
  if (it.campaignId && !cloud) statusTxt = campaignLifecycle(it).label;
  if (hsAwaiting) statusTxt = '🔒 Primary handshake';
  // A launch still running on THIS Mac (handshake → dispatch). Reuses the same
  // handshake panel, but says where it actually is — "Primary handshake" would be
  // a lie once the handshake is done and we're reading the sheet.
  if (it.launching) statusTxt = it.launchPhase === 'dispatching' ? '☁︎ Handing over to the VM…' : '🤝 Connecting to primary';

  // Primary needs-login (Task 9) — only fires when the engine's
  // c.primarySession.state is 'needs_login' (see /js/primary-session-render.mjs).
  // Repeated on every affected strip BY DESIGN.
  const psBadge = primarySessionBadge(it.primarySession);
  const psBadgeHtml = psBadge.show ? `<div class="${psBadge.cls}">${escHtml(psBadge.text)}</div>` : '';

  // An account LinkedIn logged out stops THIS campaign and no other, so it is
  // said on this campaign's card and nowhere else — a dashboard-wide banner
  // nagged operators about accounts that were none of their business. Only
  // while the campaign is live: a finished run's dead account is history.
  const _loggedOut = (running || queued)
    ? ((_cloudAccountsById.get(it.id) || []).filter((a) => a && a.needsLogin))
    : [];
  const acctBadgeHtml = _loggedOut.length
    ? `<div class="sn-acctwarn">`
      + `<span class="sn-acctwarn-txt">${_loggedOut.length === 1 ? 'This account is' : `These ${_loggedOut.length} accounts are`} logged out of LinkedIn — ${_loggedOut.length === 1 ? 'it sends' : 'they send'} nothing until you log back in on GoLogin</span>`
      + `<span class="sn-acctwarn-pills">${_loggedOut.map((a) => _stageAcctPill(a, false, null)).join('')}</span>`
      + `</div>`
    : '';

  // Why a queued campaign hasn't started. "Queued" alone covers a two-minute
  // cold start, someone else's campaigns holding every slot, and a campaign
  // whose own accounts cannot send — see /js/queue-state.mjs for which is which.
  const _qs = queued
    ? queueState({ id: it.id, status: 'queued', leadCount: it.leadCount || it.total || 0 },
      _cloudCapacity, _cloudAccountsById.get(it.id) || null)
    : null;
  const queueHtml = _qs
    ? `<div class="sn-mon sn-queue sn-queue-${_qs.kind}">`
      + `<span class="sn-mon-badge">● ${escHtml(_qs.badge)}</span>`
      + `<span class="sn-mon-line">${_qs.line}</span>`
      + `<span class="sn-queue-note">${_qs.note}</span>`
      + `</div>`
    : '';

  const flow = it.isFG
    ? `<b>${it.total || '—'} invites</b> → <b>${it.accounts || 1} account${(it.accounts || 1) === 1 ? '' : 's'}</b> → page · Follower Growth`
    : `<b>${it.total || 0} leads</b> → <b>${it.accounts || 0} ${acctWord}</b> → feeds <b>${escHtml(it.name || '')}</b> · ${escHtml(_cloudModeLabel(it.mode))}`;
  const whereNote = _ownedLocal ? 'runs on this machine — closing the app stops it'
    : 'runs in the cloud — keeps going if you close the app';
  const progLine = running
    ? `<div class="sn-progtxt"><b>${it.sent || 0}</b> of ${it.total || 0} ${it.isFG ? 'invites' : 'sent'} · ${whereNote}</div>`
    : '';

  const expandBtn = ''; // Open the campaign to see live status and logs.
  let logHtml;
  if (cloud && it.logs && it.logs.length) {
    // Real per-lead rows from the engine (GET /api/campaign/:id/leads).
    logHtml = `<div class="sn-logbox">${it.logs.slice(-8).map((l) => escHtml(l)).join('<br>')}</div>`;
  } else if (cloud) {
    const note = it.sent ? 'Live per-lead log — expand to watch it fill.' : 'Per-lead log appears here as the cloud engine sends.';
    logHtml = `<div class="sn-logbox">${note} Status: <span class="ok">${it.sent || 0}/${it.total || 0} ${it.isFG ? 'invites' : 'sent'}</span>.</div>`;
  } else if (it.logs && it.logs.length) {
    logHtml = `<div class="sn-logbox">${it.logs.slice(-8).map((l) => escHtml(l)).join('<br>')}</div>`;
  } else if (done && it.histIdx != null) {
    // Done strip from history — the live log is gone from memory; pull the
    // persisted campaign.log lines lazily (cache-first; fetch fills the box
    // in place, next board render inlines from cache).
    const cached = _histLogCache.get(it.histIdx);
    logHtml = cached != null
      ? `<div class="sn-logbox">${cached}</div>`
      : `<div class="sn-logbox" data-histlog="${it.histIdx}">Loading log…</div>`;
  } else {
    logHtml = `<div class="sn-logbox">Live log appears here while this local campaign runs.</div>`;
  }
  const _copyBtn = `<button type="button" class="sn-logcopy" title="Copy log" aria-label="Copy log" onclick="event.stopPropagation(); copyStripLog(this)"><svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"></rect><path d="M5 15V5a2 2 0 0 1 2-2h10"></path></svg><span class="sn-logcopy-lbl">Copy</span></button>`;
  const switchBlock = queued ? '' : `<div class="sn-switch"><div class="sn-pane on">${_copyBtn}${logHtml}</div></div>`;

  // Task 3 — cloud monitoring card (parity with local renderMonitoringCard):
  // ● MONITORING / ENDING SOON badge + live "Next check · ends in" countdown
  // from the engine's next_check_at / monitoring_until. Stop monitoring works
  // now (engine stop endpoint); Check-now + auto-toggle arrive with the engine
  // endpoints (Part B), so no dead buttons here yet.
  let monBlock = '';
  if (monitoring) {
    const now = Date.now();
    const next = it.nextCheckAt ? new Date(it.nextCheckAt) : null;
    const until = it.monitoringUntil ? new Date(it.monitoringUntil) : null;
    const remMs = until ? until.getTime() - now : 0;
    const endingSoon = remMs > 0 && remMs <= 24 * 60 * 60 * 1000;
    const hhmm = (dd) => dd ? `${String(dd.getHours()).padStart(2, '0')}:${String(dd.getMinutes()).padStart(2, '0')}` : '—';
    const fmtRem = (ms) => {
      if (ms <= 0) return '0m';
      const d1 = Math.floor(ms / 86400000), h1 = Math.floor((ms % 86400000) / 3600000), m1 = Math.floor((ms % 3600000) / 60000);
      return d1 > 0 ? `${d1}d ${h1}h` : h1 > 0 ? `${h1}h ${m1}m` : `${m1}m`;
    };
    // `every 60m` when the campaign is on the operator's own interval (unchanged
    // wording), `slowed to 4h` when the engine has backed the cadence off — the
    // hero caption's words, from the same helper, so the strip can't state a
    // temporary slowdown as if the operator had chosen it.
    const cad = stripCadence(it);
    const line = endingSoon
      ? `Window ends in <b>${fmtRem(remMs)}</b> — then still-pending leads stay <i>Connection Request Sent</i>`
      : `Next check <b>${escHtml(hhmm(next))}</b> · ends in <b>${escHtml(fmtRem(remMs))}</b> · ${cad.label} <b>${escHtml(cad.value)}</b>`;
    const resume = it.resumeAt ? new Date(it.resumeAt) : null;
    const resumeLine = resume && !isNaN(resume.getTime()) && Number(it.pendingCount || 0) > 0
      ? `<span class="sn-mon-resume"><b>Sending paused · no sender available for 15+ min.</b> Monitoring continues; sending retries automatically at ${escHtml(_wakeWhenText(resume.getTime()))}.</span>`
      : '';
    monBlock = `<div class="sn-mon${endingSoon ? ' ending' : ''}">`
      + `<span class="sn-mon-badge">${endingSoon ? '● ENDING SOON' : '● MONITORING'}</span>`
      + `<span class="sn-mon-line">${line}</span>`
      + (cloud ? `<span class="sn-mon-ctl">`
      + `<button type="button" class="mini sn-mon-btn" onclick="event.stopPropagation();promptCloudCheckScope('${escHtml(it.id)}',this)" title="Run an acceptance check now">Check now</button>`
      + `<label class="sn-mon-auto" title="When off, the VM won't run automatic checks — use ⚡ Check now."><input type="checkbox" ${it.autoChecksEnabled ? 'checked' : ''} onclick="event.stopPropagation()" onchange="setCloudAutoChecks('${escHtml(it.id)}',this.checked,this)"> Auto</label>`
      + `</span>` : '') + resumeLine + `</div>`;
  }

  // Handshake lock panel — replaces the log switchBlock while
  // state==='awaiting_primary_accept'. Two row states only (done/waiting):
  // the engine's senders[] carry only accepted:true|false, no in-progress
  // signal, so there is no "Accepting…" spinner state to render. Targeted
  // accepts only — no accept-all line (would be false; see Task 3.3 reconciler).
  let handshakeBlock = '';
  if (hsAwaiting) {
    const senders = it.senders;
    const accepted = senders.filter((s) => s && s.accepted).length;
    const total = senders.length;
    const pct = total ? Math.round((accepted / total) * 100) : 0;
    const pname = escHtml((it.primary && it.primary.name) || 'the primary');
    const rows = senders.map((s) => {
      const done = !!(s && s.accepted);
      return `<div class="hs-row ${done ? 'done' : ''}">`
        + `<span class="ic">${done ? '<span class="chk">✓</span>' : '<span class="dotwait"></span>'}</span>`
        + `<span class="who">${escHtml((s && s.name) || 'account')}</span>`
        + `<span class="st">${done ? 'Accepted' : 'Waiting'}</span></div>`;
    }).join('');
    const _launching = !!it.launching;
    const _dispatching = _launching && it.launchPhase === 'dispatching';
    handshakeBlock = `
      <div class="hs-panel">
        <div class="hs-eyebrow"><span class="lk">🔒</span> Phase 0 · Primary handshake${_launching ? '' : ' — locked'} <span class="cnt"><span class="hs-count">${accepted}</span> / ${total}</span></div>
        <div class="hs-head">${_dispatching
          ? 'Handshake done — reading your lead sheet and handing the campaign to the VM'
          : _launching
            ? 'Sending connection requests to the primary account, then accepting them here'
            : "Your Mac is accepting the primary's invitations"}</div>
        <div class="hs-bar"><i style="width:${pct}%"></i></div>
        <div class="hs-expl">${_launching
          ? `Your Mac opens each sender in turn, sends <b>${pname}</b> a connection request, then accepts them in your local browser. This is the only step that runs on this machine — the campaign then moves entirely to the VM. It takes a couple of minutes.`
          : `Each account sent <b>${pname}</b> a connection request from the VM. Accepting them in <b>your local browser</b> is the only step that runs on this machine — then the campaign continues entirely on the VM.`}</div>
        <div class="hs-list">${rows}</div>
        <div class="hs-keep">◈ Keep this app open — it's the only local step this campaign needs.</div>
      </div>`;
  }

  // Controls — icon buttons (dock-btn: tooltip via data-tip, .danger = red).
  // Running LOCAL: Pause/Resume + Stop (local supports resume). Running CLOUD:
  // Stop only — the engine has no resume, so a cloud "pause" would strand the
  // campaign. Open (②/③) stays a labeled primary pill → Campaign view. Done:
  // Duplicate + Debrief + ✕ dismiss, all as icons.
  const _dib = (svg, tip, onclick, cls = '') =>
    `<button type="button" class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;
  const _openPill = `<button class="mini solid" onclick="viewRunningCampaign()">Open</button>`;
  // Cloud campaigns have no local cockpit to restore, so their Open must NOT
  // call viewRunningCampaign() (which drops the operator in the blank New-
  // Campaign wizard). openCloudLive() focuses the campaign's live strip instead.
  const _cloudOpen = `<button class="mini solid" onclick="openCloudLive('${escHtml(it.id)}')">Open</button>`;
  let foot = '';
  if (it.launching) {
    // No controls: there is nothing on the VM yet to stop, pause, watch or open,
    // and every cloud control here would be called with a placeholder id. The
    // handshake modal owns Cancel / Dispatch anyway while it's up.
    foot = '';
  } else if (it.where === 'local' && it.interrupted) {
    foot = _dib(V3_SVG_PLAY, 'Continue where it left off', `window.openCampaignResumeDecision('local-active','sending','local',this)`)
      + _dib(V3_SVG_TRASH, 'Delete', `deleteBoardCampaign('${escHtml(it.id)}', this)`, 'danger')
      + _dib(V3_SVG_COPY, 'Duplicate', `duplicateCampaign('${escHtml(it.id)}')`)
      + `<button class="mini solid" onclick="openCampaignForEdit('${escHtml(it.id)}')">Open</button>`;
  } else if (running && it.where === 'local') {
    foot = (monitoring
      ? _dib(V3_SVG_STOP, 'Stop monitoring', 'window.dashStopActive && window.dashStopActive()', 'danger')
      : (it.paused
        ? _dib(V3_SVG_PLAY, 'Resume', 'window.dashPauseActive && window.dashPauseActive()')
        : _dib(V3_SVG_PAUSE, 'Pause', 'window.dashPauseActive && window.dashPauseActive()'))
        + _dib(V3_SVG_STOP, 'Stop', 'window.dashStopActive && window.dashStopActive()', 'danger'))
      + _dib(V3_SVG_COPY, 'Duplicate', `duplicateCampaign('${escHtml(it.id)}')`)
      + _openPill;
  } else if (running && cloud) {
    // "Show campaign happening" — watch the VM's browser live. Shown in BOTH
    // sending AND monitoring: cloud browsers are short-lived (a few seconds per
    // send/check), so the viewer waits and auto-streams the moment one opens.
    // The green LIVE dot lights when the engine reports an active browser this
    // poll (it.live) — a hint there's something to watch right now.
    const _vLabel = String(it.name || it.id).replace(/['"\\<>]/g, '');
    const _showBtn = `<button class="mini${it.live ? ' live-on' : ''}" onclick="openCloudCampaignView('${escHtml(it.id)}','${escHtml(_vLabel)}')" title="Watch the campaign's browser live">${it.live ? '<span class="live-dot"></span>' : ''}👁 Show</button>`;
    // v2.160.46: OPEN on an active campaign → read-only wizard (its config,
    // locked while it runs) instead of the live sheet. "👁 Show" remains the way
    // to watch the VM browser live.
    const _openRO = `<button class="mini solid" onclick="openRunningCampaignReadOnly('${escHtml(it.id)}')">Open</button>`;
    if (monitoring) {
      foot = _showBtn + _dib(V3_SVG_STOP, 'Stop monitoring', `stopCloudCampaignUI('${escHtml(it.id)}')`, 'danger') + _openRO;
    } else {
      // Pause/Resume — 1:1 with the local running cluster (engine resume flips
      // status paused→running; pause halts sending after the current lead).
      const _pauseBtn = it.paused
        ? _dib(V3_SVG_PLAY, 'Resume', `pauseCloudCampaignUI('${escHtml(it.id)}', true)`)
        : _dib(V3_SVG_PAUSE, 'Pause', `pauseCloudCampaignUI('${escHtml(it.id)}', false)`);
      foot = _showBtn + _pauseBtn + _dib(V3_SVG_STOP, 'Stop', `stopCloudCampaignUI('${escHtml(it.id)}')`, 'danger') + _openRO;
    }
  } else if (queued) {
    if (cloud) {
      // v2.160.46: a cloud "queued"/warming-up campaign has already been
      // dispatched to the engine, so OPEN behaves like a running one — the
      // read-only wizard (its config, locked), NOT the Google Sheet.
      // A SCHEDULED one hasn't started, so the same engine stop reads as "Cancel"
      // (it flips the campaign to cancelled; the due start_campaign task then
      // finds a non-'scheduled' status and declines to start it).
      foot = `<button class="mini" onclick="stopCloudCampaignUI('${escHtml(it.id)}')">${scheduled ? 'Cancel' : 'Stop'}</button><button class="mini solid" onclick="openRunningCampaignReadOnly('${escHtml(it.id)}')">Open</button>`;
    } else if (scheduled) {
      // Local scheduled — Reschedule (edit) / Cancel (remove) / Open (edit).
      foot = `<button class="mini" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Reschedule</button>`
        + `<button class="mini" onclick="window.cancelQueuedCampaign && window.cancelQueuedCampaign('${escHtml(it.rawId)}')">Cancel</button>`
        + `<button class="mini solid" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Open</button>`;
    } else {
      foot = `<button class="mini" onclick="window.cancelQueuedCampaign && window.cancelQueuedCampaign('${escHtml(it.rawId)}')">Cancel</button>`
        + `<button class="mini solid" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Open</button>`;
    }
  } else { // done — Duplicate + Debrief + 🗑 Delete (icons), Open pill.
    const dismiss = _dib(V3_SVG_TRASH || V3_SVG_XMARK, 'Delete', `deleteBoardCampaign('${escHtml(it.id)}', this)`, 'danger');
    const dup = _dib(V3_SVG_COPY, 'Duplicate', `duplicateCampaign('${escHtml(it.id)}')`);
    // Debrief — local done strips only (the snapshot lives on the history entry).
    const debriefBtn = (!cloud && it.hist)
      ? _dib(V3_SVG_DOC, 'Debrief', `window.openDebrief('${escHtml(it.id)}')`)
      : '';
    // Restart — only for a STOPPED/CANCELLED/ERRORED campaign (it.bad), never a
    // cleanly-completed one. ▶ Continue where it left off · ⟲ Restart from the
    // beginning. Both skip already-done rows/leads (no double-outreach).
    const restartBtns = it.bad
      ? _dib(V3_SVG_PLAY, 'Continue where it left off', cloud ? `restartCloudCampaignUI('${escHtml(it.id)}', false)` : `restartLocalFromItem('${escHtml(it.id)}', false)`)
        + _dib(V3_SVG_RESTART, 'Restart from the beginning', cloud ? `restartCloudCampaignUI('${escHtml(it.id)}', true)` : `restartLocalFromItem('${escHtml(it.id)}', true)`)
      : '';
    // OPEN routing for a finished strip: STOPPED/cancelled cloud → prefilled
    // editable setup wizard (edit & re-launch); cleanly-done cloud → live view;
    // local → its cockpit. Mirrors vjcard.mjs's card-#2 routing.
    // A local campaign's Open used to be _openPill — viewRunningCampaign(),
    // which takes NO id. Every local campaign's Open called the same
    // argument-less function and showed one shared cockpit, so opening CTAX and
    // opening Test did exactly the same thing and the wizard kept whichever
    // campaign was there before (operator, 2026-09-04). A finished or stopped
    // local campaign now opens BY ID, like its cloud counterpart, which loads
    // that campaign's own saved settings by name.
    const _doneOpen = cloud
      ? (it.bad
        ? `<button class="mini solid" onclick="openCampaignForEdit('${escHtml(it.id)}')">Open</button>`
        : _cloudOpen)
      : `<button class="mini solid" onclick="openCampaignForEdit('${escHtml(it.id)}')">Open</button>`;
    // ⚡ Check now on a FINISHED/STOPPED cloud connect_and_* strip — late
    // acceptances still need a sweep + intro/DM backlog flush after the campaign
    // was stopped overall. One-shot on the engine: no re-arm, no resumed sending.
    const _cloudCheck = (cloud && (it.mode === 'connect_and_introduce' || it.mode === 'connect_and_message'))
      ? `<button type="button" class="mini" onclick="event.stopPropagation();promptCloudCheckScope('${escHtml(it.id)}',this)" title="Run an acceptance check now">Check now</button>`
      : '';
    foot = _cloudCheck + restartBtns + dismiss + dup + debriefBtn + _doneOpen;
  }

  if (it.campaignId && !cloud) {
    const specs = campaignActionSpecs(it);
    foot = specs.map(spec => spec.action === 'open'
      ? `<button class="mini solid" onclick="${spec.onclick}">Open</button>`
      : _dib(spec.kind === 'dup' ? V3_SVG_COPY : spec.kind === 'delete' ? V3_SVG_TRASH : spec.kind === 'restart' ? V3_SVG_RESTART : spec.kind === 'debrief' ? V3_SVG_DOC : spec.kind === 'pause' ? V3_SVG_PAUSE : spec.kind === 'stop' ? V3_SVG_STOP : V3_SVG_PLAY,
        spec.label, spec.onclick, spec.kind === 'delete' || spec.kind === 'stop' ? 'danger' : '')).join('');
  }

  // Active and expanded historical strips render card #2 (.sn-vjcard) instead
  // of the compact body. Active strips never switch renderer when clicked.
  // No card #2 clone for a launch: it has no campaign status to fill, and
  // _fillVjCards would paint the generic "running" hero over the handshake panel.
  const richCard = ''; // Dashboard cards remain compact.
  return `
  <div class="sn-strip ${stateCls}" data-cid="${escHtml(it.id)}">
    ${expandBtn}
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Campaign · ${escHtml(badge)}</span>${it.mine ? '<span class="sn-you">You</span>' : (it.owner ? `<span class="sn-owner">· ${escHtml(it.owner)}</span>` : '')}${wherePill}${whenPill}
      <span class="sn-status">${dot} ${escHtml(statusTxt)}</span></div>
    <div class="sn-name">${escHtml(it.name || '(unnamed)')}</div>
    <div class="sn-flow">${flow}</div>
    ${psBadgeHtml}
    ${acctBadgeHtml}
    ${queueHtml}
    ${progLine}
    ${monBlock}
    ${hsAwaiting ? handshakeBlock : switchBlock}
    ${_buildSkippedSection(it)}
    <div class="sn-foot"><div class="right">${foot}${_stripOverflow()}</div></div>
    </div>
    ${richCard}
  </div>`;
}

// Draft strip — a saved-but-not-launched wizard config, surfaced on the board
// inside "Your campaigns" under the DRAFTS rail (railhead CSS uppercases the
// label). Slim collapsed-style strip: Open → wizard (editDraft), 🗑 → delete.
function renderDraftStrip(d) {
  const name = d.name || '(unnamed draft)';
  const created = (typeof dashboardFormatDate === 'function' && dashboardFormatDate(d.createdAt)) || '';
  return `
  <div class="sn-strip done sn-collapsed draft" data-cid="draft:${escHtml(d.id)}">
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Campaign · Draft</span><span class="sn-you">You</span>
      <span class="sn-status"><span class="dot q"></span> Draft</span></div>
    <div class="sn-name">${escHtml(name)}</div>
    <div class="sn-flow">Saved as a draft${created ? ` · created <b>${escHtml(created)}</b>` : ''} · not launched yet</div>
    <div class="sn-foot"><div class="right">`
    + `<button type="button" class="dock-btn danger" data-tip="Delete draft" aria-label="Delete draft" onclick="deleteDraftStrip('${escHtml(d.id)}', this)">${V3_SVG_TRASH || V3_SVG_XMARK}</button>`
    + `<button class="mini solid" onclick="editDraft('${escHtml(d.id)}')">Open</button>`
    + `</div></div>
    </div>
  </div>`;
}

// Delete a draft from its board strip — optimistic strip removal (the 4s board
// poll would otherwise show the stale row), then the same API + wizard-reference
// cleanup as deleteDraft (Drafts & Stops tab), then re-render both surfaces.
async function deleteDraftStrip(id, btn) {
  if (!id) return;
  if (!confirm('Delete this draft?')) return;
  const strip = btn && btn.closest('.sn-strip');
  if (strip) strip.remove();
  try {
    await fetch('/api/drafts/' + encodeURIComponent(id), { method: 'DELETE' });
  } catch (err) { alert('Failed: ' + err.message); return; }
  try { if (getActiveDraftId() === id) clearActiveDraft(); } catch { /* not the active draft */ }
  try { if (typeof refreshDashboardDrafts === 'function') refreshDashboardDrafts(); } catch { /* */ }
  try { renderCampaignsBoard(); } catch { /* next poll repaints */ }
}
window.deleteDraftStrip = deleteDraftStrip;

// The ⋯ overflow menu on each strip (currently: Duplicate → pre-filled draft).
// The ⋯ overflow menu used to hold a single "Duplicate" item; that action now
// has its own visible icon in the strip footer, so the menu is redundant —
// render nothing. (The delegated duplicate handler below stays inert with no
// .ovf elements to match; harmless.)
function _stripOverflow() {
  return '';
}

// ── Campaign debrief overlay ───────────────────────────────────────────────
// Opens from the Debrief pill on local done strips. Data = the history entry
// (incl. the persisted `debrief` snapshot taken at campaign end). Only fields
// that exist on the entry are rendered — no invented stats.

const _DB_PARK_LABELS = { // mirrors prettyParkReason in src/campaign.js
  session_expired:   'logged out / session expired',
  weekly_limit_429:  'suspected weekly invite limit (HTTP 429)',
  suspected_weekly_limit: 'suspected weekly invite limit (HTTP 429)',
  consecutive_skips: 'too many consecutive skips / failures',
  op_credit_limit:   'suspected OP credits limit reached',
  challenge:         'LinkedIn checkpoint — needs a human',
  throttle_paused:   'throttled (429) — paused',
};
const _DB_END_LABELS = {
  completed: 'Completed', stopped: 'Stopped by operator', errored: 'Stopped by error',
};
function _dbParkLabel(r) { return _DB_PARK_LABELS[r] || r || 'parked'; }
function _dbDuration(sec) {
  const s = Number(sec) || 0;
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60), h = Math.floor(m / 60);
  return h ? `${h}h ${m % 60}m` : `${m}m ${s % 60}s`;
}
function _dbDate(iso) {
  const d = new Date(iso || 0);
  return Number.isFinite(d.getTime()) && d.getTime() > 0
    ? d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) : '';
}
let _dbCopyText = '';

window.openDebrief = async function openDebrief(stripId) {
  const it = _boardItemsById.get(stripId);
  const h = it && it.hist;
  const scrim = document.getElementById('db-scrim');
  if (!h || !scrim) return;
  const db = h.debrief || null;
  const tpl = (h.settings && h.settings.templates) || {};

  document.getElementById('db-title').textContent = h.name || '(unnamed)';
  const endLbl = _DB_END_LABELS[h.endReason] || h.endReason || '';
  document.getElementById('db-sub').innerHTML =
    `Ran <b>${escHtml(_dbDate(h.date) || '—')}</b> · mode <b>${escHtml(_cloudModeLabel(h.mode))}</b>`
    + ` · <b>${(h.profiles || []).length} account${(h.profiles || []).length === 1 ? '' : 's'}</b>`
    + ` · duration <b>${escHtml(_dbDuration(h.duration))}</b>`
    + (endLbl ? ` · <b>${escHtml(endLbl)}</b>` : '');

  let body = '';

  // Totals — sent / processed / errors / skipped (all real history fields).
  const skipTotal = db ? db.skipTotal : null;
  body += `<div class="db-sec"><div class="db-sec-head">Totals</div><div class="db-funnel">`
    + `<div class="funnel-stage"><div class="st-lbl">Sent</div><div class="st-num">${h.successCount || 0}</div><div class="st-drop">of <b>${h.totalProcessed || 0}</b> processed</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Skipped</div><div class="st-num">${skipTotal != null ? skipTotal : '—'}</div><div class="st-drop">${skipTotal != null ? 'left untouched on the sheet' : 'no snapshot for this run'}</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Errors</div><div class="st-num">${h.errorCount || 0}</div><div class="st-drop">during the run</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Duration</div><div class="st-num">${escHtml(_dbDuration(h.duration))}</div><div class="st-drop">${escHtml(endLbl || '')}</div></div>`
    + `</div></div>`;

  // Per-account — Sent + end reason only. We do NOT track per-lead
  // accepted/replied for a normal run, so nothing else is shown here.
  if (db && Array.isArray(db.perAccount) && db.perAccount.length) {
    const rows = db.perAccount.map((a) =>
      `<tr><td class="db-acc">${escHtml(a.name || a.profileId)}</td>`
      + `<td class="db-num">${a.sent}</td>`
      + `<td class="db-reason">${escHtml(a.endReason || '—')}</td></tr>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Per account</div>`
      + `<table class="db-table"><thead><tr><th>Account</th><th>Sent</th><th>Ended</th></tr></thead>`
      + `<tbody>${rows}</tbody></table></div>`;
  }

  // vs your last 5 — factual SENT counts only, no accept/reply comparison.
  let _dbPriorsLine = '';
  try {
    const raw = await (await fetch('/api/history')).json();
    const hist = Array.isArray(raw) ? raw : (raw.history || []);
    const currentHistIdx = it && Number.isFinite(it.histIdx) ? it.histIdx : -1;
    const others = hist
      .map((p, i) => ({ p, i }))
      .filter(({ i }) => i !== currentHistIdx)
      .sort((a, b) => new Date(b.p.date).getTime() - new Date(a.p.date).getTime())
      .slice(0, 5)
      .map(({ p }) => p);
    if (others.length) {
      const avg = Math.round(others.reduce((s, e) => s + (e.successCount || 0), 0) / others.length);
      const mine = h.successCount || 0;
      const delta = mine - avg;
      const arrow = delta > 0 ? '▲' : (delta < 0 ? '▼' : '·');
      body += `<div class="db-sec"><div class="db-sec-head">vs your last ${others.length}</div>`
        + `<div class="db-compare">This run sent <b>${mine}</b> — your last ${others.length} averaged <b>${avg}</b> `
        + `<span class="db-delta">${arrow} ${Math.abs(delta)}</span></div></div>`;
      _dbPriorsLine = `vs last ${others.length}: sent ${mine} (avg ${avg}, ${arrow}${Math.abs(delta)})`;
    }
  } catch (_) { /* history fetch best-effort — comparison section just omitted */ }

  // Why it ended — from the persisted endNotice.
  if (db && db.endNotice && (db.endNotice.reason || db.endNotice.detail)) {
    body += `<div class="db-sec"><div class="db-sec-head">Why it ended</div>`
      + `<div class="db-skipped"><b>${escHtml(db.endNotice.reason || '')}</b>`
      + (db.endNotice.detail ? ` <span class="why">— ${escHtml(db.endNotice.detail)}</span>` : '')
      + `</div></div>`;
  }

  // Skipped leads — reason tallies + expandable capped row list.
  if (db && db.skipTotal > 0) {
    const reasons = Object.entries(db.skipReasons || {})
      .sort((a, b) => b[1] - a[1])
      .map(([r, n]) => `${n} ${_skipReasonLabel(r).toLowerCase()}`).join(' · ');
    const rows = (db.skips || []).map((s) =>
      `<tr><td>${s.rowNumber != null ? 'Row ' + s.rowNumber : ''}</td>`
      + `<td>${escHtml(s.leadName || '(no name)')}</td>`
      + `<td>${escHtml(_skipReasonLabel(s.reason))}</td>`
      + `<td class="dim">${escHtml(s.detail || '')}</td></tr>`).join('');
    const capNote = db.skipTotal > (db.skips || []).length
      ? `<div class="db-empty" style="margin-top:8px">Showing first ${(db.skips || []).length} of ${db.skipTotal}.</div>` : '';
    body += `<div class="db-sec"><div class="db-skipped"><b>${db.skipTotal} skipped</b>`
      + (reasons ? ` <span class="why">— ${escHtml(reasons)}</span>` : '')
      + ` · <a onclick="this.closest('.db-sec').querySelector('.db-skip-rows').classList.toggle('open')">view rows</a></div>`
      + `<div class="db-skip-rows"><table class="db-table"><thead><tr><th>Row</th><th>Lead</th><th>Reason</th><th>Detail</th></tr></thead><tbody>${rows}</tbody></table>${capNote}</div></div>`;
  } else if (db) {
    body += `<div class="db-sec"><div class="db-skipped"><b>0 skipped</b></div></div>`;
  }

  // Parked accounts.
  if (db && (db.parked || []).length) {
    const rows = db.parked.map((p) =>
      `<tr><td>${escHtml(p.pName || p.profileId || 'Account')}</td>`
      + `<td><span class="db-park${p.reason === 'weekly_limit_429' || p.reason === 'throttle_paused' ? ' gold' : ''}">${escHtml(_dbParkLabel(p.reason))}${p.parkedAt ? ' · ' + escHtml(_dbDate(p.parkedAt)) : ''}</span></td></tr>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Parked accounts</div>`
      + `<table class="db-table"><thead><tr><th>Account</th><th>Parked</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }

  // Errors — count + last samples from the snapshot.
  if (db && db.errors && db.errors.count > 0) {
    const lines = (db.errors.samples || []).map((e) => `<div class="e-msg">· ${escHtml(e.message)}</div>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Errors · ${db.errors.count}</div><div class="db-errs">${lines || '<span class="db-empty">No samples recorded.</span>'}</div></div>`;
  }

  // Template used — real strings from the settings snapshot.
  const tplParts = [];
  if (tpl.connectionNote) tplParts.push(['Connection note', tpl.connectionNote]);
  if (tpl.followUpMessage) tplParts.push(['Follow-up message', tpl.followUpMessage]);
  if (tpl.primaryIntroBody) tplParts.push(['Intro DM body', tpl.primaryIntroBody]);
  if (tpl.inmailBody) tplParts.push(['InMail', (tpl.inmailSubject ? tpl.inmailSubject + '\n' : '') + tpl.inmailBody]);
  if (tpl.openProfileBody) tplParts.push(['Open-profile message', (tpl.openProfileSubject ? tpl.openProfileSubject + '\n' : '') + tpl.openProfileBody]);
  if (tplParts.length) {
    const first = tplParts[0][1].split('\n')[0];
    const full = tplParts.map(([k, v]) => `${k}: ${v}`).join('\n\n');
    body += `<div class="db-sec"><div class="db-sec-head">Template used · ${escHtml(tplParts[0][0].toLowerCase())}</div>`
      + `<div class="db-tpl" onclick="this.classList.toggle('open')">`
      + `<div class="tpl-first">${escHtml(first)}</div>`
      + `<div class="tpl-more">click to expand ▾</div>`
      + `<div class="tpl-full">${escHtml(full)}</div></div></div>`;
  }

  if (!db) {
    body += `<div class="db-sec"><div class="db-empty">No debrief snapshot was recorded for this run — snapshots are saved for campaigns finished on v2.135+.</div></div>`;
  }

  document.getElementById('db-body').innerHTML = body;

  // Plain-text summary for the Copy button.
  _dbCopyText = [
    `${h.name || '(unnamed)'} — debrief`,
    `Ran ${_dbDate(h.date)} · ${_cloudModeLabel(h.mode)} · ${(h.profiles || []).length} accounts · ${_dbDuration(h.duration)} · ${endLbl}`,
    `Sent ${h.successCount || 0} of ${h.totalProcessed || 0} processed · ${h.errorCount || 0} errors`
      + (db ? ` · ${db.skipTotal} skipped` : ''),
    db && db.endNotice ? `Ended: ${db.endNotice.reason}${db.endNotice.detail ? ' — ' + db.endNotice.detail : ''}` : '',
    db && db.skipTotal > 0 ? `Skips: ${Object.entries(db.skipReasons || {}).map(([r, n]) => `${n} ${_skipReasonLabel(r)}`).join(', ')}` : '',
    db && (db.parked || []).length ? `Parked: ${db.parked.map((p) => `${p.pName || p.profileId} (${_dbParkLabel(p.reason)})`).join(', ')}` : '',
    db && Array.isArray(db.perAccount) && db.perAccount.length
      ? `Per account: ${db.perAccount.map((a) => `${a.name || a.profileId} — ${a.sent} sent${a.endReason ? ' (' + a.endReason + ')' : ''}`).join('; ')}`
      : '',
    _dbPriorsLine,
  ].filter(Boolean).join('\n');

  scrim.style.display = 'flex';
};

window.closeDebrief = function closeDebrief() {
  const scrim = document.getElementById('db-scrim');
  if (scrim) scrim.style.display = 'none';
};

(function _wireDebriefOverlay() {
  const scrim = document.getElementById('db-scrim');
  if (!scrim) return;
  scrim.addEventListener('click', (e) => { if (e.target === scrim) window.closeDebrief(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && scrim.style.display !== 'none') window.closeDebrief();
  });
  const closeBtn = document.getElementById('db-close');
  if (closeBtn) closeBtn.addEventListener('click', () => window.closeDebrief());
  const copyBtn = document.getElementById('db-copy');
  if (copyBtn) copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(_dbCopyText);
      copyBtn.textContent = 'Copied ✓';
      setTimeout(() => { copyBtn.textContent = 'Copy summary'; }, 1600);
    } catch (_) { /* clipboard best-effort */ }
  });
  // Email to me — MANUAL operator click only. No automatic/background send;
  // this fires exclusively in response to the click handler below.
  const emailBtn = document.getElementById('db-email');
  if (emailBtn) emailBtn.addEventListener('click', async () => {
    const titleEl = document.getElementById('db-title');
    const subject = `Debrief — ${(titleEl && titleEl.textContent) || 'campaign'}`;
    try {
      const res = await fetch('/api/debrief/email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ subject, body: _dbCopyText }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.ok) {
        if (typeof showCampaignToast === 'function') showCampaignToast('Debrief emailed.');
      } else {
        if (typeof showCampaignToast === 'function') showCampaignToast(`Email failed: ${data.error || res.statusText}`);
      }
    } catch (err) {
      if (typeof showCampaignToast === 'function') showCampaignToast(`Email failed: ${err.message}`);
    }
  });
})();
// ── End campaign debrief overlay ───────────────────────────────────────────

// One-time handshake modal: pops the first time a cloud campaign enters the
// primary-accept lock, so the operator keeps the app open for the local accept.
// Shown once per campaign id per session (_hsModalShown); dismissable. Inert
// until the engine ships state:'awaiting_primary_accept'.
const _hsModalShown = new Set();
let _hsModalCurrentId = null;
function maybeOpenHandshakeModal(items) {
  const scrim = document.getElementById('hs-scrim');
  if (!scrim) return;
  if (scrim.classList.contains('open')) return; // don't hijack an already-open modal for a different campaign
  const it = (items || []).find((x) => x && x.where === 'cloud'
    // A pre-dispatch launch is represented on the board by a synthetic
    // `__launching__` item. runHandshakeWizard already owns that state. Opening
    // this legacy post-dispatch modal over it hid the real progress UI, and its
    // Stop button sent `__launching__` to the engine → HTTP 404 not found.
    && !x.launching && x.id !== '__launching__'
    && x.state === 'awaiting_primary_accept' && Array.isArray(x.senders) && !_hsModalShown.has(x.id));
  if (!it) return;
  _hsModalShown.add(it.id);
  _hsModalCurrentId = it.id;
  const accepted = it.senders.filter((s) => s && s.accepted).length;
  const total = it.senders.length;
  const pname = escHtml((it.primary && it.primary.name) || 'the primary');
  document.getElementById('hs-modal-count').textContent = String(accepted);
  document.getElementById('hs-modal-sub').textContent = `${accepted} of ${total} accepted`;
  document.getElementById('hs-modal-body').innerHTML =
    `Accepting <b>${pname}</b>'s connection requests in <b>your local browser</b> is the only step that runs on this machine — then <b>${escHtml(it.name || 'the campaign')}</b> runs entirely in the cloud. Keep this app open.`;
  scrim.classList.add('open');
}
function closeHandshakeModal() {
  const scrim = document.getElementById('hs-scrim');
  if (scrim) scrim.classList.remove('open');
  _hsModalCurrentId = null;
}
document.addEventListener('DOMContentLoaded', () => {
  const keep = document.getElementById('hs-modal-keep');
  const stop = document.getElementById('hs-modal-stop');
  const scrim = document.getElementById('hs-scrim');
  if (keep) keep.addEventListener('click', closeHandshakeModal);
  if (stop) stop.addEventListener('click', () => { const id = _hsModalCurrentId; closeHandshakeModal(); if (id && typeof stopCloudCampaignUI === 'function') stopCloudCampaignUI(id); });
  if (scrim) scrim.addEventListener('click', (e) => { if (e.target === scrim) closeHandshakeModal(); });
});

// ── Campaigns board sections (admin split) ──────────────────────────────────
// Per-group collapse state persisted to localStorage. Keys: 'sec:<name>' for
// top-level sections (default expanded), 'sub:<section>:<bucket>' for the Done /
// Cancelled sub-groups (default collapsed). The default lives at the call site
// (defCollapsed arg) so a never-touched group follows its natural default.
const _CB_COLLAPSE_KEY = 'campaignsBoardCollapse_v1';
let _cbCollapse = null;
function _cbState() {
  if (_cbCollapse) return _cbCollapse;
  try { _cbCollapse = JSON.parse(localStorage.getItem(_CB_COLLAPSE_KEY) || '{}') || {}; }
  catch { _cbCollapse = {}; }
  return _cbCollapse;
}
function _cbIsCollapsed(key, defCollapsed) {
  const m = _cbState();
  return key in m ? !!m[key] : defCollapsed;
}
window.toggleBoardGroup = function (key, defCollapsed) {
  const m = _cbState();
  const cur = key in m ? !!m[key] : defCollapsed;
  m[key] = !cur;
  try { localStorage.setItem(_CB_COLLAPSE_KEY, JSON.stringify(m)); } catch { /* non-fatal */ }
  renderCampaignsBoard();
};

// Collapse/expand chevron. A real SVG (not a ▸ glyph, which stays tiny at any
// font-size) so the minimise affordance is unmistakable. Points down when open,
// rotates to point right when collapsed (via CSS .cl).
function _cbCaretSvg(collapsed, big) {
  const sz = big ? 26 : 18;
  return `<svg class="cb-caretsvg${collapsed ? ' cl' : ''}" width="${sz}" height="${sz}" viewBox="0 0 24 24"`
    + ` fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"`
    + ` aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>`;
}

// Per-section user search (Other users' campaigns). Debounced re-render so the
// input keeps focus while typing.
let _otherUserSearch = '';
let _otherSearchTimer = null;
window.onOtherUserSearch = function (val) {
  _otherUserSearch = val || '';
  if (_otherSearchTimer) clearTimeout(_otherSearchTimer);
  _otherSearchTimer = setTimeout(() => { renderCampaignsBoard(); }, 180);
};

// Render one top-level board section: header (caret + title + count) with the
// four buckets inside. Running/Idle are always-visible rails; Done/Cancelled are
// collapsible sub-groups (default collapsed). `opts`:
//   flat        — no section header (non-admin single board)
//   headExtra   — HTML appended into the header (e.g. the user-search input)
//   subtitle    — small muted label after the title
//   alwaysShow  — render the section header even when empty
function _renderBoardSection(key, title, secItems, opts = {}) {
  const running   = secItems.filter((x) => x.bucket === 'running' && !x.paused);
  const paused    = secItems.filter((x) => x.bucket === 'running' && x.paused);
  const idle      = secItems.filter((x) => x.bucket === 'queued');
  const done      = secItems.filter((x) => x.bucket === 'done' && !x.bad);
  const cancelled = secItems.filter((x) => x.bucket === 'done' && x.bad);

  // One bad strip must never abort the whole board render — that would freeze
  // every group (a collapsed sub-group would look un-expandable). Isolate each.
  const _safeStrip = (it) => {
    try { return renderUnifiedStrip(it); }
    catch (e) {
      try { console.error('[board] strip render failed for', it && it.id, e); } catch { /* */ }
      return `<div class="sn-strip"><div class="sn-name">${escHtml((it && it.name) || 'Campaign')}</div>`
        + `<div class="sn-progtxt">Could not render this campaign — see console.</div></div>`;
    }
  };

  const rail = (label, arr) => arr.length
    ? `<div class="sn-railhead">${label}</div>` + arr.map(_safeStrip).join('') : '';
  const subGroup = (bucketKey, label, arr, extra = '') => {
    if (!arr.length) return '';
    const gk = `sub:${key}:${bucketKey}`;
    const collapsed = _cbIsCollapsed(gk, true); // Done/Cancelled default collapsed
    const head = `<div class="sn-railhead cb-subhead" onclick="toggleBoardGroup('${gk}', true)">`
      + `<span class="cb-caret">${_cbCaretSvg(collapsed, false)}</span> ${label} <span class="sn-railcount">${arr.length}</span>${extra}</div>`;
    return head + (collapsed ? '' : arr.map(_safeStrip).join(''));
  };

  // Saved drafts (Sam 2026-07-23): surface under a DRAFTS rail inside this
  // section — pre-rendered strips arrive via opts.draftsHtml (renderDraftStrip),
  // since drafts aren't board items (no bucket / no engine id).
  // Categorized bulk "Delete all" (operators asked for it back, split by
  // category). stopPropagation so it doesn't toggle the group's collapse.
  const clearBtn = (fn, n) => n
    ? `<button type="button" class="sn-clear-cat" onclick="event.stopPropagation(); ${fn}">Delete all</button>` : '';

  // Ortus Basics 1.0: Drafts collapses like Done and Stopped. It used to be a
  // plain rail with no caret; the operator wants the same open/close affordance
  // on all three. Same toggleBoardGroup key shape as subGroup, but defaulting
  // to OPEN — a draft you are coming back to should be visible.
  const _draftsKey = `sub:${key}:drafts`;
  const _draftsCollapsed = _cbIsCollapsed(_draftsKey, false);
  const draftsRail = opts.draftsHtml
    ? `<div class="sn-railhead cb-subhead" onclick="toggleBoardGroup('${_draftsKey}', true)">`
      + `<span class="cb-caret">${_cbCaretSvg(_draftsCollapsed, false)}</span> Drafts `
      + `<span class="sn-railcount">${opts.draftsCount || ''}</span>`
      + `${clearBtn('clearAllDrafts()', opts.draftsCount || 0)}</div>`
      + (_draftsCollapsed ? '' : opts.draftsHtml)
    : '';

  // Non-collapsible rails carry NO caret glyph — only genuinely collapsible
  // groups (sections + Done/Cancelled) show a caret, so the affordance reads true.
  const body = rail('Running', running)
    + rail('Paused', paused)
    + rail('Queued', idle)
    + rail('Saved campaigns', secItems.filter(x => x.bucket === 'saved'))
    + draftsRail
    + subGroup('done', 'Done', done, clearBtn("clearBoardCat('finished')", done.length))
    + subGroup('cancelled', 'Stopped', cancelled, clearBtn("clearBoardCat('cancelled')", cancelled.length));

  // Non-admin flat board: no header, just the buckets.
  if (opts.flat) return body;

  if (!secItems.length && !opts.alwaysShow) return '';

  const secKey = `sec:${key}`;
  const collapsed = _cbIsCollapsed(secKey, false);
  const subtitle = opts.subtitle ? `<span class="cb-secsub">${escHtml(opts.subtitle)}</span>` : '';
  const head = `<div class="cb-sectionhead" onclick="toggleBoardGroup('${secKey}', false)">`
    + `<span class="cb-caret">${_cbCaretSvg(collapsed, true)}</span>`
    + `<span class="cb-sectitle">${title}</span>${subtitle}`
    + `<span class="cb-seccount">${secItems.length + (opts.draftsCount || 0)}</span>`
    + `<span class="cb-headextra">${opts.headExtra || ''}</span></div>`;
  const emptyMsg = opts.emptyMsg || 'There are no campaigns to show at the moment.';
  const inner = collapsed ? ''
    : `<div class="cb-secbody">${body || `<div class="cb-secempty">${escHtml(emptyMsg)}</div>`}</div>`;
  return `<div class="cb-section${collapsed ? ' cb-collapsed' : ''}">${head}${inner}</div>`;
}

let _campaignsBoardTimer = null;
let _lastBoardHtml = '';  // anti-jank: skip the 4s re-render when nothing changed
const _cloudDetailCache = new Map();  // id → detail; terminal campaigns cached (never change)
let _boardRenderInFlight = false;     // don't stack renders (each does N cloud fetches)
let _cloudRaw = [];                   // background snapshot of cloud details; render builds from this
// True once that snapshot has been attempted at least once. Before it, the
// board renders history only, so "nothing is live" is ignorance, not a fact —
// and anything that reasons about which campaigns are running must wait.
let _cloudSnapshotTried = false;
let _cloudRefreshInFlight = false;
let _cloudRefreshController = null;   // cancelled when Electron wakes from sleep
// Successful handovers update ownership immediately. The board snapshot can be
// five seconds old, which is too stale to decide which poller owns the card.
const _handoverOwner = new Map();

// Does a Check now for this cloud campaign run on THIS Mac? A check runs where
// the campaign runs, so this reads the same ownership field the card's RUNNING ON
// control shows. Absent means the VM: every campaign that predates the handover
// feature was cloud-dispatched, and it is also the safe default, since a check
// that opens no browser here is a wasted click rather than a surprise.
function _checkRunsLocally(id) {
  if (_handoverOwner.has(String(id))) return _handoverOwner.get(String(id)) === 'local';
  const hit = (_cloudRaw || []).find((c) => c && (c.id === id || (c.campaign && c.campaign.id === id)));
  const c = hit && hit.campaign ? hit.campaign : hit;
  const side = String((c && (c.runs_on || c.runsOn)) || "").toLowerCase();
  return side === "local";
}

// Cloud data comes from the remote engine (0.5–2s per call) — fetching it inside
// the 4s render made every render block ~1.5s. Fetch it on a BACKGROUND timer
// into _cloudRaw instead; the render builds cloud strips from that cache with no
// network wait. Dismiss/ownership filtering still runs live in the render, so
// those stay instant.
// Bounded-concurrency map. Chromium allows only SIX connections per host, so an
// unbounded Promise.all over cloud campaigns (1-3 requests each, 13-16s apiece
// through the engine proxy) saturates the pool and starves every OTHER poller in
// the page. Measured 2026-08-13: 7 requests open at once, and the Sales Nav
// board's 2.5s poll managed ONE request in 75 seconds — its timer was ticking
// fine, its fetch just never got a socket. Cap the fan-out so the rest of the app
// always has connections left.
async function _mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  const worker = async () => {
    while (next < items.length) {
      const i = next++;
      out[i] = await fn(items[i], i);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}
const CLOUD_FANOUT_LIMIT = 3;

// When the cloud engine first stopped answering, 0 while it is answering. Drives
// both the NO LINK tile and the banner; reset on the first successful list.
let _cloudOfflineSince = 0;

async function _refreshCloudItems() {
  if (_cloudRefreshInFlight) return;
  _cloudRefreshInFlight = true;
  const controller = new AbortController();
  _cloudRefreshController = controller;
  const cloudFetch = (input, init = {}) => fetch(input, { ...init, signal: controller.signal });
  // Only the LIST decides reachability. Everything after it is per-campaign
  // detail with its own fallback, and a throw from one of those says nothing
  // about the engine being up — flagging it offline would put a false banner
  // over a board that is perfectly live.
  let listOk = false;
  try {
    const _res = await cloudFetch('/api/campaign/cloud-board-summary');
    const cl = await _res.json();
    // The engine answers a failed list with 502 + {error}, which fetch does NOT
    // throw on. Reading `.campaigns` off it yields undefined, and the old `|| []`
    // turned that into "there are no cloud campaigns": every strip vanished from
    // the board and the VM tile printed ASLEEP. An unreachable engine rendered as
    // everything-is-fine. Throw instead, so the catch below keeps the last good
    // snapshot on screen, and flag it so the tile and banner say it is stale.
    if (!_res.ok || (cl && cl.error)) throw new Error((cl && cl.error) || `engine ${_res.status}`);
    listOk = true;
    _cloudOfflineSince = 0;
    const cloudCamps = (cl && cl.campaigns) || [];
    cloudCamps.forEach((c) => {
      const side = String((c && c.runs_on) || '').toLowerCase();
      if (side === 'local' || side === 'vm') _handoverOwner.set(String(c.id), side);
    });
    // One reading per poll for the whole board: the queue is global, so every
    // waiting strip asks the same question and the answer is memoised server
    // side. Only worth the request when something is actually waiting.
    // Also while anything is LIVE, for the header's VM tile. Widened from
    // queued-only on purpose and no further: when nothing is live the pods are
    // zero BY DEFINITION, so the tile can say "asleep" without a request. This
    // poll already sits near the browser's six-connections-per-host limit — the
    // ceiling that froze the board once — so an unconditional fetch here would
    // cost a connection every 2.5s to re-learn a constant.
    const _vmLive = cloudCamps.some((c) => ['queued', 'running', 'monitoring', 'paused'].includes(c.status));
    if (_vmLive) _cloudCapacity = cl.capacity || { queue: [], unavailable: true };
    renderVmTile(_vmLive);
    // Everything that still needs refreshing comes back in ONE request. Asking
    // per campaign meant 89 of them, which pinned the browser at its six
    // connections per host and starved every other poller in the page.
    const _isFresh = (c) => {
      if (!['done', 'cancelled', 'error'].includes(c.status) || _snExpanded.has(c.id)) return false;
      const cached = _cloudDetailCache.get(c.id);
      return Boolean(cached && cached.campaign && ['done', 'cancelled', 'error'].includes(cached.campaign.status));
    };
    const _needIds = cloudCamps.filter((c) => !_isFresh(c)).map((c) => c.id);
    let _bulk = (cl && cl.details) || {};
    if (_needIds.length) {
      const _missingIds = _needIds.filter((id) => !_bulk[id]);
      try {
        if (!_missingIds.length) throw new Error('summary complete');
        const br = await (await cloudFetch(`/api/campaign/cloud-details?ids=${encodeURIComponent(_missingIds.join(','))}`)).json();
        _bulk = { ..._bulk, ...((br && br.details) || {}) };
      } catch { /* summary was complete, or per-id fallback runs below */ }
    }
    _cloudSnapshotTried = true;
    _cloudRaw = await _mapLimit(cloudCamps, CLOUD_FANOUT_LIMIT, async (c) => {
      let d;
      if (_isFresh(c)) return _cloudDetailCache.get(c.id);
      if (_bulk[c.id]) d = _bulk[c.id];
      else {
        try { d = await (await cloudFetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}`)).json(); }
        catch { d = { campaign: c, leadCounts: {} }; }
      }
      _cloudDetailCache.set(c.id, d);
      _cloudPolledAt.set(c.id, Date.now()); // feeds the live stage's heartbeat
      // A STALLED campaign needs its per-account states on the board, not just
      // in the opened campaign's panel — that's where the stage names which
      // account is capped and which is benched, and offers Retry. Fetched only
      // while it's stalled, so a healthy board costs no extra request.
      // Refreshed on a TTL rather than once: after a Retry the counts and park
      // reasons change, and advice computed from a stale snapshot would keep
      // telling the operator to fix something they just fixed.
      const _acctAge = Date.now() - (_cloudAccountsAt.get(c.id) || 0);
      const _ca = _cloudCurrentAction(d);
      // Also while it is SENDING, not only while stalled. The account pills are
      // built from this payload, so fetching it only in the waiting phase meant a
      // healthy running campaign showed no per-account breakdown at all — you
      // could see 88 of 1567 sent but not which of the 66 accounts sent them.
      // A paused campaign still needs the same account rail as Campaign
      // Builder: who sent today, who is paused, and who needs attention. The
      // old running-only gate left the expanded dashboard card with no account
      // payload, so its cloned .sp panel correctly hid itself.
      const _liveStatus = ((d && d.campaign) || c).status;
      // 'monitoring' belongs here too. Sending pauses when an account hits its
      // daily limit, and the campaign sits in 'monitoring' — exactly when the
      // operator most needs to see WHY. Without it this fetch never ran, the
      // accounts map stayed empty, _cloudAccountPanel fell back to its
      // placeholder rows (dailyCount: 0), and both pills read "0/50" on a
      // campaign whose first account had sent 50/50 and whose second was at a
      // weekly cap (operator, 2026-09-01: "I might assume that it sent zero
      // connections"). The weekly-cap state was lost with the same payload.
      // 'stopping' for the same reason: the numbers must survive the wind-down.
      const _live = ['running', 'paused', 'monitoring', 'stopping'].includes(String(_liveStatus || ''));
      // A FINISHED FG run needs them exactly once, to say why it stopped short.
      // Once fetched the run is over and the answer can't change, so this never
      // repeats — `has()` is the whole gate.
      const _fgDone = ((d && d.campaign) || c).mode === 'follower_growth'
        && !_live && !_cloudAccountsById.has(c.id);
      if (((_ca && _ca.phase === 'waiting') || _live || _fgDone) && _acctAge > 30000) {
        _cloudAccountsAt.set(c.id, Date.now());
        try {
          const ar = await (await cloudFetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}/accounts`)).json();
          if (ar && Array.isArray(ar.accounts)) _cloudAccountsById.set(c.id, ar.accounts);
        } catch (_) { /* the stage degrades to the reason line alone */ }
      }
      const st = ((d && d.campaign) || c).status;
      // Monitoring is live work too. Excluding it here made the dashboard lose
      // the lead-derived acceptance/introduction history and render "0 events"
      // immediately after a successful sweep. Cache the engine event stream on
      // every board refresh as well; previously that happened only after OPEN.
      if (d && Array.isArray(d.monitorLog)) _cloudMonitorLog.set(c.id, d.monitorLog);
      if (st === 'running' || st === 'paused' || st === 'monitoring' || _snExpanded.has(c.id)) {
        try {
          const lr = await (await cloudFetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}/leads`)).json();
          if (lr && Array.isArray(lr.leads)) {
            d._leads = lr.leads;
            _recordCloudProgress(c.id, d);
            d._logLines = _mergeCloudLog(
              _cloudLeadsToLog(lr.leads, ((d && d.campaign) || c).mode === 'follower_growth', (d && d.campaign) || c),
              _combineCloudEvents(c.id));
            _cloudAcctCounts.set(c.id, _cloudCountsByAccount(lr.leads));
            d._fgLast = _fgLastActivity(lr.leads);
          }
        } catch { /* best-effort */ }
      }
      return d;
    });
  } catch (_) {
    // Superseded deliberately by the wake recovery above. Do not turn a
    // cancelled pre-sleep request into a false "engine offline" warning.
    if (controller.signal.aborted) return;
    // Keep the last snapshot — a stale board is far more useful than an empty
    // one — but never let it pass for live. Both signals are the same fact said
    // twice: the tile for whoever is looking at the header, the banner for
    // whoever is looking at the strips.
    if (!listOk) {
      if (!_cloudOfflineSince) _cloudOfflineSince = Date.now();
      _cloudCapacity = { unreachable: true };
      try { renderVmTile(true); } catch { /* */ }
    }
  }
  finally {
    // A wake may already have replaced this request with a newer refresh.
    // Only the current controller is allowed to release the shared lock.
    if (_cloudRefreshController === controller) {
      _cloudRefreshController = null;
      _cloudRefreshInFlight = false;
    }
  }
  try { _renderCloudOfflineBanner(); } catch { /* */ }
  try { renderCampaignsBoard(); } catch { /* */ }
}

// Operator actions must not wait behind a board poll that began before the
// action. Cancel that obsolete snapshot, invalidate the changed campaign and
// immediately request a post-action snapshot. This is shared by VM and
// local-owned cloud rows because both render from the cloud board source.
async function _forceCloudItemsAfterAction(id) {
  if (id) _cloudDetailCache.delete(id);
  if (_cloudRefreshController) _cloudRefreshController.abort();
  for (let i = 0; i < 50 && _cloudRefreshInFlight; i += 1) {
    await new Promise((resolve) => setTimeout(resolve, 20));
  }
  await _refreshCloudItems();
}


function _renderCloudOfflineBanner() {
  const el = document.getElementById('cloud-offline-banner');
  if (!el) return;
  // Ortus Basics 1.0: this build never reaches the cloud engine on purpose
  // (campaigns-client short-circuits every request), so "can't reach it" is not
  // a fault worth reporting — it is the intended state. Always keep it hidden.
  el.hidden = true; el.textContent = '';
  return;
  /* eslint-disable no-unreachable */
  if (!_cloudOfflineSince) { el.hidden = true; el.textContent = ''; return; }
  const since = new Date(_cloudOfflineSince)
    .toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  // Says what is known and what is not. It deliberately does NOT claim the
  // campaigns have stopped: the engine runs on the VM and keeps sending whether
  // or not this laptop can reach it.
  el.textContent = `⚠ Can't reach the cloud engine since ${since} — showing the last state we saw. Campaigns on the VM keep running; this board is not live.`;
  el.hidden = false;
}
window._refreshCloudItems = _refreshCloudItems;

// Wrapper: the 4s poll must not start a new render while the previous is still
// fetching from the remote engine — overlapping renders fired 2–3× the cloud
// requests and made the fetch time climb to 20s+. Skip the tick instead.
async function renderCampaignsBoard() {
  if (_boardRenderInFlight) return;
  _boardRenderInFlight = true;
  try { await _renderCampaignsBoardInner(); }
  finally { _boardRenderInFlight = false; }
}
// A local campaign is stored by name; history contains one entry per run.
// Keep original indices for history actions, but show only its latest run.
function localDashboardLifecycle(status) {
  const lifecycle = campaignLifecycle(status);
  return { lifecycle, bucket: lifecycle.bucket,
    paused: lifecycle.status === 'paused',
    bad: lifecycle.status === 'stopped' || lifecycle.status === 'failed',
    badLabel: lifecycle.label };
}

function unlistedSavedCampaigns(configs, items, drafts) {
  const key = item => item.campaignId || String(item.name || '').trim().toLowerCase();
  const present = new Set([...items, ...drafts].map(key));
  return configs.filter(item => key(item) && !present.has(key(item)));
}

function latestLocalCampaignHistory(hist, currentItems = []) {
  const key = name => String(name || '').trim().toLowerCase();
  const seen = new Set(currentItems.filter(it => it.where === 'local' && key(it.name)).map(it => it.campaignId || key(it.name)));
  const latest = [];
  for (let i = hist.length - 1; i >= 0; i--) {
    const p = hist[i];
    const name = p.campaignId || key(p.name);
    if (name && seen.has(name)) continue;
    if (name) seen.add(name);
    latest.push({ p, histIdx: i });
  }
  return latest;
}

// Fetch local (status/queue/history) + cloud campaigns, normalize, render.
async function _renderCampaignsBoardInner() {
  const board = document.getElementById('campaigns-board');
  if (!board) return;
  // Keep the legacy dashboard hidden on EVERY cycle (defeats route/render races).
  _hideLegacyDashboardSections();
  const items = [];

  // 0) A cloud launch in flight — no row exists in Postgres or the local cockpit
  // yet, so without this the board shows only the (not-yet-consumed) draft while
  // the handshake + dispatch run. First, so it sits at the top of "Running".
  try {
    const _lit = (typeof cloudLaunchBoardItem === 'function') ? cloudLaunchBoardItem() : null;
    if (_lit) items.push(_lit);
  } catch (_) { /* never let the launch strip break the board */ }

  // 1) Local running campaign (0 or 1) — from /api/campaign/status.
  // A campaign that ENDED this session still holds its full log in the status
  // payload (in-memory, until the next run or an app restart) — stash it so
  // step 4 can attach it to the matching done strip instead of the
  // "Live log appears here…" placeholder.
  let _endedLogs = null, _endedName = '';
  try {
    // Feed the dashboard the same normalized local snapshot used by Campaign
    // Builder card #2. Consuming the raw payload here bypassed the synthesized
    // five-stage recorder after reopening the app.
    const _cachedLocal = _localLive && (Date.now() - Number(_localLive.lastVerifiedAt || 0) < 5000)
      ? _localLive
      : null;
    const s = _decorateLocalLiveStatus(_cachedLocal || await (await fetch('/api/campaign/status')).json());
    s.lastVerifiedAt = s.lastVerifiedAt || Date.now();
    _localLive = s;
    if (s && !s.running && s.state !== 'monitoring' && s.state !== 'waiting_daily_reset' && Array.isArray(s.logs) && s.logs.length) {
      _endedLogs = s.logs; _endedName = s.name || '';
    }
    // An ADOPTED cloud campaign lives on this Mac but still has its row in
    // Postgres, so step 3 already lists it. Pushing it here too put the same
    // campaign on the board twice with contradictory states: one strip
    // RUNNING/"Working…"/"next batch in 39m" (this builder hardcodes
    // bucket:'running' and carries no monitoring fields) beside one strip
    // MONITORING/VM. The cloud strip is the real one; card #2 already overlays
    // the live local state onto it.
    const _adopted = s && s.id && s.id !== 'legacy-singleton';
    if (s && (s.running || s.state === 'monitoring' || s.state === 'interrupted' || s.state === 'waiting_daily_reset') && !_adopted) {
      items.push({
        where: 'local', id: 'local-active', campaignId: s.campaignId, lifecycle: campaignLifecycle(s), name: s.name, mode: s.mode, isFG: s.mode === 'follower_growth',
        ...localDashboardLifecycle(s), sent: s.totalProcessed || 0, total: s.totalTargets || 0,
        startedAt: Date.parse(s.startedAt || s.started_at || '') || Number(s.startedAt) || 0,
        pending: Math.max(0, (Number(s.totalTargets) || 0) - (Number(s.totalProcessed) || 0)),
        interrupted: s.state === 'interrupted' || !!s.interrupted,
        dailyWait: s.state === 'waiting_daily_reset',
        resumeAt: s.resumeAt || null,
        engineStatus: s.state || '',
        interruption: s.interruption || null,
        accounts: (s.profileIds || []).length, mine: true,
        profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
        participatingProfileIds: Array.isArray(s.participatingProfileIds) && s.participatingProfileIds.length
          ? s.participatingProfileIds : (Array.isArray(s.profileIds) ? s.profileIds : []),
        // A monitoring snapshot restored after an app restart is represented by
        // the native local row (legacy-singleton), not the cloud-row overlay.
        // Carry the same phase→pause mapping here or that one render path falls
        // back to RUNNING / Working even though only scheduled checks remain.
        monitoringPhase: s.state === 'monitoring',
        monitoring: s.state === 'monitoring',
        paused: campaignLifecycle(s).status === 'paused',
        monitoringCheckInProgress: !!s.monitoringCheckInProgress,
        live: !!s.live,
        liveAccount: s.liveAccount || s.currentProfile || '',
        currentAction: s.currentAction || null,
        batchDone: s.batchDone,
        batchSize: s.batchSize,
        nextCheckAt: s.nextCheckAt || null,
        monitoringUntil: s.monitoringUntil || null,
        acceptedCount: s.acceptedCount,
        logs: Array.isArray(s.logs) ? s.logs : [],
        skippedCount: s.skippedCount || 0,
        // v2.160.35: carry the follow-up summary so the strip clone's monitor
        // hero shows the same dual countdown as card #2.
        followUp: s.followUp || null,
        // statusFromItem now defaults an absent runsOn to 'vm' (every campaign
        // that pre-dates this feature was cloud-dispatched) — a genuinely local
        // campaign MUST say so explicitly here or the board's RUNNING ON control
        // would show it as VM-owned while it is actually running on this Mac.
        // The server already defaults this to 'local'; this just carries it.
        runsOn: s.runsOn || 'local',
        handoverAt: s.handoverAt || null,
        // The per-account panel. statusFromItem whitelists it, so without this
        // line the board strip's card renders no panel at all.
        accountPanel: Array.isArray(s.accountPanel) ? s.accountPanel : [],
      });
    }
  } catch (_) { /* local status best-effort */ }

  // 2) Local queued — from /api/queue.
  try {
    const q = await (await fetch('/api/queue')).json();
    for (const it of (q.queue || [])) {
      if (it.dailyContinuation && _localLive?.state === 'waiting_daily_reset') continue;
      items.push({ where: 'local', id: 'q-' + it.id, rawId: it.id, campaignId: it.campaignId, lifecycle: it.lifecycle, name: it.name, mode: it.mode,
        isFG: it.mode === 'follower_growth', bucket: it.dailyContinuation ? 'running' : 'queued', accounts: (it.profileIds || []).length,
        mine: true, scheduledAt: it.scheduledAt || null, dailyWait: !!it.dailyContinuation,
        resumeAt: it.scheduledAt || null, engineStatus: it.dailyContinuation ? 'waiting_daily_reset' : 'queued' });
    }
  } catch (_) { /* */ }

  // 3) Cloud campaigns — built from the BACKGROUND snapshot (_cloudRaw), not
  // fetched here, so the render never blocks on the slow remote engine.
  try {
    // Identical runs. Three FG campaigns with the same name and the same
    // accounts were dispatched 1 and 3 minutes apart on 8 Aug (a double-clicked
    // Start); on the board they were three indistinguishable cards, and the two
    // later ones sent almost nothing because the first had already spent the
    // accounts' credits. Naming them is not the fix — the launch guard is — but
    // an operator looking at the board should not have to work this out.
    //
    // The SHEET is part of the identity, matching what the server's guard keys
    // on. The name carries the page and the run day but not the source, so two
    // different lists fired to the same page on the same day share a name and
    // a roster — legitimately different runs that would otherwise be labelled
    // identical, which is how a badge teaches people to ignore it.
    const _dupeKey = (c) => `${c.mode}|${c.name}|${c.sheet_url || ''}|${(c.profile_ids || []).slice().sort().join(',')}`;
    const _dupeSeen = new Map();
    for (const d of _cloudRaw) {
      const k = _dupeKey(d.campaign || {});
      _dupeSeen.set(k, (_dupeSeen.get(k) || 0) + 1);
    }
    for (const rawDetail of _cloudRaw) {
      const stoppingNow = _stoppingCloudIds.has(String((rawDetail.campaign || {}).id || ''));
      const d = stoppingNow
        ? { ...rawDetail, live: false, liveProgress: null,
          campaign: { ...(rawDetail.campaign || {}), status: 'stopping' } }
        : rawDetail;
      const c = d.campaign || {}; const lc = d.leadCounts || {};
      const _dupes = (_dupeSeen.get(_dupeKey(c)) || 1) - 1;
      if (['done', 'cancelled', 'error'].includes(c.status) && _cloudDismissed.has(c.id)) continue;
      if (c.sheet_url) _cloudSheetUrls.set(c.id, c.sheet_url);
      const mine = !!(snCurrentEmail && c.owner && String(c.owner).toLowerCase() === String(snCurrentEmail).toLowerCase());
      // Ownership gate: normal accounts see only their OWN cloud campaigns;
      // admins see everyone's. (Local campaigns are always the viewer's.)
      if (!_viewerIsAdmin && !mine) continue;
      // 'monitoring' (post-send acceptance-watch — exactly like a local CC+IC /
      // CC+DM run) is an ACTIVE state: keep it in NOW RUNNING, not DONE. Task 3.
      // 'paused' is a still-ACTIVE state (sending held, resumable) — keep it in
      // NOW RUNNING with the Pause/Resume+Stop cluster, exactly like a paused
      // local campaign (which stays running:true, paused:true).
      // 'scheduled' — dispatched to the VM with a start time; the engine holds it
      // and starts it itself. Same bucket as queued, and scheduledAt makes the
      // strip read "Scheduled · <when>" (the shape the local queue already uses).
      const bucket = (c.status === 'running' || c.status === 'monitoring' || c.status === 'paused' || c.status === 'stopping' || c.status === 'pausing' || c.status === 'waiting_daily_reset' || c.status === 'needs_review') ? 'running'
        : (c.status === 'pending' || c.status === 'queued' || c.status === 'scheduled') ? 'queued' : 'done';
      items.push({
        where: 'cloud', id: c.id, name: c.name, mode: c.mode, isFG: c.mode === 'follower_growth',
        // When this campaign began. A LinkedIn account outlives the campaign
        // that used it, so a follow-up queued BEFORE this one started was never
        // its own — without this date the strip and the card both fall back to
        // the account alone and an old orphan gets adopted by today's campaign.
        startedAt: Date.parse(c.started_at || c.created_at || '') || 0,
        identityKey: `${c.mode || ''}|${c.name || ''}|${c.sheet_url || ''}|${(c.profile_ids || []).slice().sort().join(',')}`,
        paused: c.status === 'paused',
        dailyWait: c.status === 'waiting_daily_reset',
        needsReview: c.status === 'needs_review',
        engineStatus: c.status || '',
        resumeAt: c.resumeTaskDueAt || null,
        resumeReason: c.resumeTaskReason || null,
        stopping: c.status === 'stopping' || c.status === 'pausing',
        monitoringPhase: c.status === 'monitoring' && String(c.runs_on || '') === 'local',
        pausedAt: c.paused_at || null,
        // Live-browser flag from the engine (top-level of the /:id detail, NOT
        // inside d.campaign) — drives the green LIVE dot on the Show button.
        live: !!(d && d.live), liveAccount: (d && d.liveAccount) || '',
        // The engine's per-person phase tick → the strip card's live stage.
        currentAction: _cloudCurrentAction(d),
        batchDone: _cloudSendingTurn(c.id, d).done,
        batchSize: _cloudSendingTurn(c.id, d).total,
        // _preActioned (Sam 2026-07-23): leads whose sheet row already carried a
        // Connection Request Status on import — the engine parks them in
        // status='sent' so they're never re-opened, but they aren't part of this
        // run. Exclude them from BOTH sides of "X of Y sent".
        // Unsent leads. Drives the ▶ Resume sending control on a monitoring card:
        // a campaign that stopped sending early has leads waiting, one that
        // finished has none, and only the first should offer the button.
        pending: Number(lc.pending || 0),
        bucket, sent: Math.max(0, Number(lc.sent || 0) - Number(lc._preActioned || 0)),
        total: Object.entries(lc).reduce((a, [k, b]) => a + (k.startsWith('_') ? 0 : (Number(b) || 0)), 0) - Number(lc._preActioned || 0),
        accounts: (c.profile_ids || []).length, profileIds: c.profile_ids || [], mine,
        // Per-account states — feeds _fgFinishedNote's "why it stopped short".
        benchAccounts: _cloudAccountsById.get(c.id) || null,
        // Same contract as the local runner: this makes board strips render the
        // identical working / waiting / stopped account rail on the VM.
        accountPanel: _cloudAccountPanel(c.id, d, d._leads || []),
        dupes: _dupes,
        // When the VM will start it — the engine reads this off the pending
        // start_campaign task itself, so it can't drift from the real timer.
        scheduledAt: c.scheduled_start_at || null,
        owner: c.owner || '', bad: c.status === 'error' || c.status === 'cancelled',
        badLabel: c.status === 'cancelled' ? 'Stopped' : 'Error',
        endReason: c.status === 'done' ? 'completed' : c.status,
        endNotice: c.end_notice || null,
        stopReason: c.stop_reason || '',
        createdAt: c.created_at, // #17: drives the "warming up (~2 min)" window
        logs: Array.isArray(d._logLines) && d._logLines.length
          ? d._logLines
          : _mergeCloudLog(
            _cloudLeadsToLog(d._leads || [], c.mode === 'follower_growth', c),
            _combineCloudEvents(c.id)),
        // Phase 0 handshake lock (Task 3.4) — undefined until the engine ships
        // them, in which case the lock panel in renderUnifiedStrip stays dormant.
        state: c.state, senders: c.senders, primary: c.primary,
        // Task 9 — primary needs-login surfacing (Task 5's c.primarySession).
        primarySession: c.primarySession,
        // Task 3 — monitoring card (parity with local renderMonitoringCard). The
        // engine carries these top-level; nextCheckAt/monitoringUntil drive the
        // "Next check · ends in" countdown, exactly like the local mon-card.
        // Older handovers can retain status='running' after sending was stopped,
        // but a durable next-check/deadline exists only for monitoring. Preserve
        // that stronger phase evidence across sleep/restart recovery.
        // An old monitoring deadline may remain on a campaign after sending is
        // resumed. The engine's active status is authoritative: stale timers
        // must never turn a running sender back into a monitoring card.
        monitoring: c.status === 'monitoring'
          || (c.status !== 'running' && c.status !== 'paused'
            && (!!c.next_check_at || !!c.monitoring_until)),
        nextCheckAt: c.next_check_at, monitoringUntil: c.monitoring_until,
        autoChecksEnabled: c.auto_checks_enabled !== false,
        checkIntervalMinutes: c.check_interval_minutes || 60,
        checkIntervalBaseMinutes: c.check_interval_base_minutes || c.check_interval_minutes || 60,
        emptyCheckStreak: c.empty_check_streak || 0,
        // v2.160.35: follow-up dual countdown — lights up once the engine
        // exposes c.follow_up {count,dueAt,sender} on the cloud detail.
        followUp: c.follow_up || null,
        // Which side owns it, mirrors _buildCloudActiveStatus. Absent on an
        // older engine ⇒ the VM owns it, which is also statusFromItem's default,
        // but set it explicitly here rather than leaning on that default.
        runsOn: c.runs_on || 'vm',
        handoverAt: c.handover_at || null,
        // A sweep running ON THE VM. Card #2 reads these three off the same `c`
        // (see _buildCloudActiveStatus) and says "Checking now"; this row never
        // carried them, so the board card said "nothing running right now" while
        // its own log, built from these very fields, printed "Check in progress".
        // Two sentences from one object, disagreeing. The started/completed pair
        // is the same test the log line uses, so they cannot drift again.
        monitorTaskStatus: c.monitorTaskStatus || null,
        monitorTaskDueAt: c.monitorTaskDueAt || null,
        monitorCheckStartedAt: c.monitor_check_started_at || null,
        monitorCheckCompletedAt: c.monitor_check_completed_at || null,
        monitorCheckError: c.monitor_check_error || '',
        monitorCheckId: c.monitor_check_id || '',
        monitorCheckStatus: c.monitor_check_status || '',
        monitorCheckExpected: Number(c.monitor_check_expected) || 0,
        monitorCheckAccountsChecked: Number(c.monitor_check_accounts_checked) || 0,
        monitorCheckCurrentAccount: c.monitor_check_current_account || '',
        monitorCheckHeartbeatAt: c.monitor_check_heartbeat_at || null,
        monitorTaskError: c.monitorTaskError || '',
        monitoringCheckInProgress: String(c.monitor_check_status || '').toLowerCase() === 'running'
          || (!c.monitor_check_id && !!(c.monitor_check_started_at && !c.monitor_check_completed_at))
          || _cloudCheckAskedActive(c),
      });
      // Handed to this Mac: the checks run HERE, so the engine's copy of the
      // monitor state froze at handover. Same overlay card #2 gets.
      // Only the cloud row that was actually adopted by the singleton on this
      // Mac may receive its live state. Several historical/duplicate rows can
      // retain runs_on='local'; overlaying the singleton onto all of them made
      // stopped campaigns display the current campaign's monitoring schedule.
      // Ownership says where a row last ran. The campaign id says WHICH row is
      // running now, and both must match.
      //
      // The canonical engine snapshot is applied FIRST, before the local
      // overlay below, and that order is load-bearing. It used to run last, so
      // `overlayCampaignStatus` put the engine's `next.checkAt` back over the
      // live local one. Measured 2026-08-28 on COLL_CHI_ANTONIO2: monitoring
      // had moved to this Mac, the local runtime and the log both said the next
      // check was 17:12, and the card's countdown panel said 19:08 — the VM's
      // schedule, frozen at handover. Two times on one card, from two sources.
      // When this Mac owns the campaign its runtime is authoritative, so it
      // must be the LAST writer, not the first.
      const _canonicalIndex = items.length - 1;
      items[_canonicalIndex] = _withCanonicalCampaignStatus(items[_canonicalIndex], d && d.campaignStatus);
      const _isCurrentLocalCampaign = String(c.runs_on || '') === 'local'
        && _localLive
        && String(_localLive.id || '') === String(c.id || '');
      if (_isCurrentLocalCampaign) {
        const _row = items[items.length - 1];
        const _localInterrupted = _localLive.state === 'interrupted' || !!_localLive.interrupted;
        const _localRuntimeActive = !!(_localLive.running || _localLive.state === 'monitoring' || _localInterrupted);
        if (!_localRuntimeActive) {
          // The engine deliberately keeps its released row alive, and older
          // rows can therefore still say status='running' after the local
          // singleton has stopped. Ownership alone is not execution. Without
          // this reconciliation the dashboard says RUNNING / Working while no
          // browser, sender loop or monitoring watcher exists on this Mac.
          const _interruptedPhase = (_row.monitoring || _row.monitoringPhase
            || c.status === 'monitoring' || !!c.next_check_at || !!c.monitoring_until)
            ? 'monitoring' : 'sending';
          _row.waitingForLocal = true;
          _row.interrupted = true;
          _row.interruption = {
            phase: _interruptedPhase,
            title: _interruptedPhase === 'monitoring'
              ? 'Monitoring stopped because this Mac became unavailable'
              : 'Campaign stopped because this Mac became unavailable',
            detail: _interruptedPhase === 'monitoring'
              ? 'Sending remains stopped. Scheduled acceptance checks stopped when this Mac went to sleep. Resume checks here or move monitoring to the Cloud VM.'
              : 'Nothing is running on this Mac. The remaining leads are safe. Choose where to continue.',
            reason: 'local-runtime-missing',
          };
          _row.monitoringPhase = _interruptedPhase === 'monitoring';
          _row.monitoring = false;
          _row.paused = true;
          _row.live = false;
          _row.liveAccount = '';
          _row.currentAction = null;
          if (!Array.isArray(_row.logs) || !_row.logs.length) {
            _row.logs = [_interruptedPhase === 'monitoring'
              ? 'INFO Monitoring on this Mac stopped when the local runtime became unavailable. Sending remains stopped; scheduled checks can be resumed safely.'
              : 'INFO Campaign work on this Mac stopped when the local runtime became unavailable. No queued lead was consumed.'];
          }
        }
        // Once handed to this Mac, the local runtime is authoritative for the
        // whole live card, not only monitoring. Keeping the frozen VM counts and
        // omitting currentAction produced "12 of 0", "0 accounts" and the old
        // one-line "Working…" placeholder even though /api/campaign/status had
        // the full roster, target count, live account, action and recorder log.
        if (_localRuntimeActive) {
          _row.waitingForLocal = false;
          _row.monitoringPhase = _localLive.state === 'monitoring';
          _row.monitoring = _row.monitoringPhase;
          // v3.1.48.75: the engine row can sit at status='stopping'/'pausing'
          // long after the stop landed — the campaign is MONITORING on this Mac,
          // and every other part of the card says so. Ownership is local, so the
          // local runtime's phase is the truth. Left as it was, 'stopping'
          // outranks 'monitoring' in statusFromItem: the card read "Stopping…",
          // took the sending control set, and 92 queued leads had no Resume
          // sending button anywhere (operator, 2026-08-28).
          if (_row.monitoringPhase) _row.stopping = false;
          _row.paused = !!(_localLive.paused || _localLive._paused) && _localLive.state !== 'monitoring';
        }
        const localDone = Number(_localLive.totalProcessed);
        const localTotal = Number(_localLive.totalTargets);
        if (Number.isFinite(localDone) && (localDone > 0 || (Number.isFinite(localTotal) && localTotal > 0))) _row.sent = localDone;
        if (Number.isFinite(localTotal) && localTotal > 0) _row.total = localTotal;
        _row.pending = Math.max(0, _row.total - _row.sent);
        if (Array.isArray(_localLive.profileIds) && _localLive.profileIds.length) _row.profileIds = _localLive.profileIds;
        _row.accounts = _row.profileIds.length;
        if (_localRuntimeActive) {
          _row.live = !!_localLive.live;
          _row.liveAccount = _localLive.liveAccount || _localLive.currentProfile || '';
          _row.currentAction = _localLive.currentAction || null;
          _row.interrupted = _localInterrupted;
          _row.interruption = _localLive.interruption || null;
        }
        _row.batchDone = _localLive.batchDone;
        _row.batchSize = _localLive.batchSize;
        _row.sentToday = _localLive.sentToday;
        _row.dailyLimit = _localLive.dailyLimit;
        _row.monitoringCheckInProgress = !!_localLive.monitoringCheckInProgress;
        if (_localLive.nextCheckAt) _row.nextCheckAt = _localLive.nextCheckAt;
        if (_localLive.emptyCheckStreak != null) _row.emptyCheckStreak = _localLive.emptyCheckStreak;
        if (_localRuntimeActive && Array.isArray(_localLive.logs) && _localLive.logs.length) _row.logs = _localLive.logs;
        if (_localRuntimeActive && Array.isArray(_localLive.accountPanel) && _localLive.accountPanel.length) _row.accountPanel = _localLive.accountPanel;
      }
    }
  } catch (_) { /* cloud best-effort */ }

  // A handover/re-run can leave an older engine row owned by This Mac while a
  // newer identical run is actively monitoring on the VM. The local singleton
  // cannot own both. Once its runtime is gone, that older row is terminal—not a
  // permanently paused browser that still needs closing. Keep it visible under
  // Stopped so the operator can inspect its log or delete it normally.
  const activeVmKeys = new Set(items.filter((item) => item.where === 'cloud'
    && item.bucket === 'running' && item.runsOn === 'vm' && !item.interrupted)
    .map((item) => item.identityKey).filter(Boolean));
  for (const item of items) {
    if (item.where !== 'cloud' || !item.interrupted || !item.identityKey || !activeVmKeys.has(item.identityKey)) continue;
    item.bucket = 'done';
    item.paused = false;
    item.interrupted = false;
    item.waitingForLocal = false;
    item.monitoring = false;
    item.monitoringPhase = false;
    item.bad = true;
    item.badLabel = 'Stopped duplicate';
    item.engineStatus = 'cancelled';
    item.endReason = 'stopped';
    item.stopReason = 'A newer identical run is active on the Cloud VM.';
    item.currentAction = null;
    item.live = false;
  }

  // 4) Local done — recent history (limit 8).
  try {
    const h = await (await fetch('/api/history')).json();
    const hist = Array.isArray(h) ? h : (h.history || []);
    for (const { p, histIdx } of latestLocalCampaignHistory(hist, items).slice(0, 8)) {
      const stopped = p.endReason === 'stopped' || p.fullStop;
      const hid = 'h-' + (p.date || p.name);
      if (_localDismissed.has(hid)) continue;
      // Attach the in-memory log of the campaign that just ended this session
      // (matched by name, most-recent entry only) so the strip keeps showing
      // its log after the running → done transition.
      const endedLogs = (_endedLogs && _endedName && p.name === _endedName) ? _endedLogs : null;
      if (endedLogs) _endedLogs = null; // only the newest matching strip gets it
      items.push({ where: 'local', id: hid, campaignId: p.campaignId, name: p.name, mode: p.mode,
        isFG: p.mode === 'follower_growth', bucket: 'done', sent: p.totalProcessed || 0,
        total: p.totalProcessed || 0, accounts: (p.profiles || []).length, mine: true,
        bad: stopped, badLabel: 'Stopped', srcSettings: p.settings || null, histIdx,
        hist: p,
        logs: endedLogs });
    }
  } catch (_) { /* */ }

  // Named settings outlive queue/history entries. Keep these campaigns visible
  // even when no run or draft currently represents them on the board.
  try {
    const [savedData, draftData] = await Promise.all([
      fetch('/api/campaign-configs').then(r => { if (!r.ok) throw new Error('Saved campaigns unavailable'); return r.json(); }),
      fetch('/api/drafts').then(r => { if (!r.ok) throw new Error('Drafts unavailable'); return r.json(); }),
    ]);
    for (const saved of unlistedSavedCampaigns(savedData.configs || [], items, draftData.drafts || [])) {
      items.push({ id: 'saved-' + (saved.campaignId || encodeURIComponent(saved.name)), campaignId: saved.campaignId, name: saved.name,
        where: 'local', mine: true, bucket: 'saved', hasRun: false });
    }
  } catch (err) { console.warn('[board] saved campaigns:', err.message); }

  // Lookup for per-strip actions (Duplicate) — keyed by strip id.
  _boardItemsById.clear();
  for (const it of items) _boardItemsById.set(it.id, it);

  // Type filter (Sam): a dropdown on the header narrows the board to one
  // campaign type. Counts on the menu reflect ALL items; the board shows only
  // the selected type. 'All' shows everything.
  renderCampaignsTypeFilter(items);
  // Conductor filter (admin only): narrow to one operator's campaigns.
  renderCampaignsConductorFilter(items);
  let shown = _campaignsTypeFilter === 'All'
    ? items : items.filter((x) => x.bucket === 'saved' || _cloudBadge(x.mode) === _campaignsTypeFilter);
  if (_viewerIsAdmin && _campaignsConductorFilter !== 'Everyone') {
    shown = shown.filter((x) => (x.owner || (x.mine ? _viewerEmail : '')) === _campaignsConductorFilter);
  }

  const running = shown.filter((x) => x.bucket === 'running');
  const queued = shown.filter((x) => x.bucket === 'queued');
  const done = shown.filter((x) => x.bucket === 'done');

  // If no local campaign is running, the detail card has nothing to show —
  // drop the "open" flag so it stops being revealed.
  if (!items.some((x) => x.bucket === 'running' && x.where === 'local')) _localDetailOpen = false;

  const schedCount = queued.filter((x) => x.scheduledAt).length;
  const qmeta = document.getElementById('campaigns-qmeta');
  if (qmeta) {
    const bits = [`${running.length} running`];
    const plainQ = queued.length - schedCount;
    if (plainQ > 0) bits.push(`${plainQ} queued`);
    if (schedCount > 0) bits.push(`${schedCount} scheduled`);
    qmeta.textContent = bits.join(' · ');
  }

  _lastCampaignsDone = done;

  // Saved drafts (Sam 2026-07-23): fetched here so the board's "Your campaigns"
  // section can show them under a DRAFTS rail. Drafts are this machine's own
  // staging area, so they always land in "mine" (never other-users/admin) and
  // hide when a type filter narrows the board (a draft has no committed type).
  let _draftRows = [];
  if (_campaignsTypeFilter === 'All') {
    try {
      const dj = await fetch('/api/drafts').then((r) => r.json());
      if (Array.isArray(dj?.drafts)) _draftRows = dj.drafts;
      _draftRows.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    } catch { /* drafts rail is best-effort — board renders without it */ }
  }
  let _draftsHtml = '';
  for (const d of _draftRows) {
    try { _draftsHtml += renderDraftStrip(d); }
    catch (e) { try { console.error('[board] draft strip render failed for', d && d.id, e); } catch { /* */ } }
  }
  const _draftOpts = _draftsHtml ? { draftsHtml: _draftsHtml, draftsCount: _draftRows.length } : {};

  // ── Board layout ──────────────────────────────────────────────────────────
  // Admins get three minimisable sections (Your / Other users / Admin = Follower
  // Growth); each orders Running → Idle → Done → Cancelled, with Done and
  // Cancelled as collapsible sub-groups. Non-admins keep a single flat board
  // with the same bucket ordering. Cancelled strips are NOT greyed (see CSS
  // .sn-board.cb-nogrey .sn-strip.cancelled).
  board.classList.add('cb-nogrey');
  let html;
  if (_viewerIsAdmin) {
    const mineItems  = shown.filter((x) => !x.isFG && x.mine);
    const adminItems = shown.filter((x) => x.isFG);
    html = _renderBoardSection('mine', 'Your campaigns', mineItems, { alwaysShow: true, ..._draftOpts })
      + _renderBoardSection('admin', 'Admin campaigns', adminItems, { subtitle: 'Follower Growth' });
  } else {
    html = _renderBoardSection('mine', '', shown, { flat: true, ..._draftOpts });
  }
  _snItemsById = new Map(items.map((x) => [x.id, x]));
  // Anti-jank: the 4s poll used to blow away the whole board every tick — killing
  // clicks/scroll/expanded panes mid-interaction. Skip the rebuild when the
  // rendered HTML is byte-identical to last time (the common case: a board of
  // done/cancelled strips is static). Live strips whose countdowns tick still
  // differ each render, so they keep updating.
  const final = html || _campaignsEmptyState();
  // The strip is computed from these items but lives OUTSIDE the board, and it
  // keeps its own byte-identical check. Running it before the board's anti-jank
  // early-return is what lets it appear at all: a static board of done strips
  // renders identical markup forever, and the strip would wait behind it.
  try { renderStaleFollowups(items); } catch (_) { /* never let it break the board */ }
  if (board.dataset.rendered === '1' && final === _lastBoardHtml) return;
  _lastBoardHtml = final;
  board.dataset.rendered = '1';
  // Keep the user-search caret alive across the re-render: note whether it held
  // focus BEFORE we blow away innerHTML, then restore after.
  const _searchHadFocus = document.activeElement
    && document.activeElement.classList
    && document.activeElement.classList.contains('cb-usersearch');
  board.innerHTML = final;
  if (_searchHadFocus) {
    const inp = board.querySelector('.cb-usersearch');
    if (inp) { inp.focus(); const n = inp.value.length; try { inp.setSelectionRange(n, n); } catch { /* */ } }
  }
  maybeOpenHandshakeModal(items);
  _fillHistLogBoxes(board);
  _fillVjCards(board); // expanded strips → card #2 parity
}

// ── Follow-ups nobody can see ────────────────────────────────────────────────
// A follow-up whose campaign is still on the board belongs to that campaign's
// card. One whose campaign has left the board had nowhere to appear at all: it
// sat in the local queue, counted into every card's totals, and was never
// listed anywhere an operator could act on it. This strip is that missing place.
//
// It is grouped by campaign and it shows the MESSAGE, on request, because the
// message is the only thing that answers the real question. "Our dinner on 4
// September" is worth sending on the 2nd and worthless on the 5th, and no count
// or timestamp tells you which case you are in.
let _staleFuOpen = false;
let _staleFuLastHtml = '';
let _staleFuUndo = null;

function _fuWhen(ms) {
  if (!Number.isFinite(ms)) return '';
  return new Date(ms).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
}

// The board scope the visible strip was computed from, so Discard applies the
// identical ownership test rather than a second guess at it.
let _staleFuLiveScope = [];
async function renderStaleFollowups(items) {
  const mount = document.getElementById('stale-followups');
  if (!mount) return;
  // EVERY campaign on the board, not only the one being viewed. Both live status
  // cards render per campaign, so each strip's card #2 needs its own follow-up
  // numbers — asking only for the viewed campaign would leave every other
  // strip's follow-up row blank, which is a different way of showing the wrong
  // thing. One request covers the whole board plus the stale groups.
  const live = (items || []).filter((it) => it && ['running', 'queued', 'idle'].includes(it.bucket));
  const campaigns = _staleFuLiveScope = [...new Map(live
    .filter((it) => it.id)
    .map((it) => [String(it.id), {
      id: String(it.id), profileIds: it.profileIds || [], startedAt: it.startedAt || 0,
    }])).values()];
  // The board paints history before the cloud snapshot lands. On that first
  // pass NO campaign looks live, so every stuck follow-up would look orphaned:
  // measured, the strip flashed "8 follow-ups did not send" and then emptied
  // itself a second later. Zero live campaigns is only a fact once the snapshot
  // has been tried.
  if (!_cloudSnapshotTried) return;
  let groups = [];
  try {
    const r = await (await fetch('/api/followups/board', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ campaigns }),
    })).json();
    if (!r || !r.ok) return;
    groups = r.groups || [];
    for (const [cid, h] of Object.entries(r.health || {})) _followupHealthById.set(String(cid), h);
  } catch (_) { return; } // the strip simply does not appear

  if (!groups.length) { mount.replaceChildren(); _staleFuLastHtml = ''; return; }

  const total = groups.reduce((a, g) => a + g.count, 0);
  const oldest = Math.min(...groups.map((g) => g.firstQueuedAt || Infinity));
  const n = (c, w) => `${c} ${w}${c === 1 ? '' : 's'}`;

  const body = groups.map((g) => {
    const name = g.campaignName
      ? `<span class="fu-nm">${escHtml(g.campaignName)}</span>`
      : '<span class="fu-nm unnamed">Campaign name not recorded</span>';
    const why = g.reason === 'signed-out'
      ? 'the follow-up browser is signed out of LinkedIn'
      : (g.lastError || 'LinkedIn did not open the message box');
    const who = g.leadNames.length
      ? `<div class="fu-who">${escHtml(g.leadNames.slice(0, 6).join(' · '))}${g.leadNames.length > 6 ? ` and ${g.leadNames.length - 6} more` : ''}</div>`
      : '';
    const login = g.reason === 'signed-out'
      ? '<button class="mini" onclick="openFollowupLogin(this)">Open the follow-up browser</button>' : '';
    return `<div class="fu-grp" data-key="${escHtml(g.key)}">
      <div class="fu-top">${name}
        <span class="fu-dt">queued ${escHtml(_fuWhen(g.firstQueuedAt))}</span>
        <span class="fu-cnt">${g.count} waiting</span>
        <button class="mini fu-x" onclick="toggleStaleFollowupMessage(this)">Show message</button>
      </div>
      <div class="fu-meta">${escHtml(g.accounts.join(', '))}${g.accounts.length ? ' · ' : ''}${escHtml(why)}</div>
      <div class="fu-open" hidden>
        <div class="fu-msg">${escHtml(g.message)}</div>
        ${who}
        <div class="sn-foot"><div class="right">
          ${login}
          <button class="mini danger" onclick="discardStaleFollowups('${escHtml(g.key)}', ${g.count}, this)">Discard ${n(g.count, 'follow-up')}</button>
          <button class="mini solid" onclick="retryFollowups(this)">Send ${g.count === 1 ? 'it' : 'these ' + g.count} now</button>
        </div></div>
      </div>
    </div>`;
  }).join('');

  const markup = `<div class="fu-strip-outer">
    <div class="fu-bar" onclick="toggleStaleFollowups(this)">
      <b>${n(total, 'follow-up')} did not send</b>
      <span class="fu-sub">${n(groups.length, 'campaign')} no longer on your board · oldest ${escHtml(_fuWhen(oldest))}</span>
      <span class="chev">${_staleFuOpen ? 'Hide ▴' : 'Show ▾'}</span>
    </div>
    <div class="fu-body" ${_staleFuOpen ? '' : 'hidden'}>${body}</div>
  </div>`;
  // The board repaints every few seconds. Identical markup is left alone, and
  // when it HAS changed (a count moved, a group cleared) the messages the
  // operator had open are reopened afterwards — otherwise reading a long
  // message while a campaign ticks would slam it shut under them.
  if (markup === _staleFuLastHtml) return;
  const wasOpen = new Set([...mount.querySelectorAll('.fu-grp')]
    .filter((el) => { const o = el.querySelector('.fu-open'); return o && !o.hidden; })
    .map((el) => el.dataset.key));
  _staleFuLastHtml = markup;
  mount.innerHTML = markup;
  for (const el of mount.querySelectorAll('.fu-grp')) {
    if (!wasOpen.has(el.dataset.key)) continue;
    const open = el.querySelector('.fu-open');
    const btn = el.querySelector('.fu-x');
    if (open) open.hidden = false;
    if (btn) btn.textContent = 'Hide message';
  }
}

window.toggleStaleFollowups = function (bar) {
  const body = bar.parentElement.querySelector('.fu-body');
  _staleFuOpen = body.hidden;
  body.hidden = !_staleFuOpen;
  bar.querySelector('.chev').textContent = _staleFuOpen ? 'Hide ▴' : 'Show ▾';
  _staleFuLastHtml = ''; // the next repaint must re-render with the new state
};

window.toggleStaleFollowupMessage = function (btn) {
  const open = btn.closest('.fu-grp').querySelector('.fu-open');
  open.hidden = !open.hidden;
  btn.textContent = open.hidden ? 'Show message' : 'Hide message';
  _staleFuLastHtml = '';
};

// Discard, with Undo. Nothing is deleted: the tasks are marked discarded, and
// selectDue() only ever takes 'pending', so they can never be sent — while Undo
// can still put them back exactly as they were.
window.discardStaleFollowups = async function (key, count, btn) {
  if (btn) { btn.disabled = true; btn.textContent = 'Discarding…'; }
  try {
    const r = await fetch('/api/followups/discard', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      // The same board scope the strip was built from. A legacy group is keyed
      // by its message and sibling campaigns reuse one template, so without it
      // Discard could reach into a campaign still running.
      body: JSON.stringify({ keys: [key], campaigns: _staleFuLiveScope }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || d.error) throw new Error(d.error || `HTTP ${r.status}`);
    _staleFuUndo = d.undo || [];
    _staleFuLastHtml = '';
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(
        `${d.discarded} follow-up${d.discarded === 1 ? '' : 's'} discarded. ${d.discarded === 1 ? 'It will' : 'They will'} never be sent.`,
        10000,
        { label: 'Undo', onClick: () => undoDiscardFollowups() },
      );
    }
    try { await renderCampaignsBoard(); } catch (_) { /* next poll repaints */ }
  } catch (e) {
    if (btn) { btn.disabled = false; btn.textContent = `Discard ${count} follow-up${count === 1 ? '' : 's'}`; }
    if (typeof showCampaignToast === 'function') showCampaignToast(`Could not discard: ${e.message}`, 6000);
  }
};

window.undoDiscardFollowups = async function () {
  const undo = _staleFuUndo;
  if (!undo || !undo.length) return;
  _staleFuUndo = null;
  try {
    const r = await fetch('/api/followups/restore', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ undo }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || d.error) throw new Error(d.error || `HTTP ${r.status}`);
    _staleFuLastHtml = '';
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(`${d.restored} follow-up${d.restored === 1 ? '' : 's'} back in the queue.`, 5000);
    }
    try { await renderCampaignsBoard(); } catch (_) { /* next poll repaints */ }
  } catch (e) {
    if (typeof showCampaignToast === 'function') showCampaignToast(`Could not undo: ${e.message}`, 6000);
  }
};

// Lazy-fill done-strip log boxes from the persisted campaign log. Cached per
// history index so the 5s board re-render doesn't refetch; in-flight guard so
// overlapping renders don't double-fetch.
const _histLogCache = new Map();
const _histLogInFlight = new Set();
function _fillHistLogBoxes(board) {
  board.querySelectorAll('[data-histlog]').forEach(async (box) => {
    const idx = Number(box.dataset.histlog);
    if (!Number.isInteger(idx) || _histLogInFlight.has(idx)) return;
    _histLogInFlight.add(idx);
    try {
      const d = await (await fetch(`/api/history/${idx}/log`)).json();
      const lines = Array.isArray(d.lines) ? d.lines.slice(-8) : [];
      const html = lines.length
        ? lines.map((l) => escHtml(l)).join('<br>')
        : 'No stored log lines for this campaign.';
      _histLogCache.set(idx, html);
      // Fill in place if the box is still on screen (board may have re-rendered).
      const live = board.querySelector(`[data-histlog="${idx}"]`);
      if (live) { live.innerHTML = html; live.removeAttribute('data-histlog'); }
    } catch {
      _histLogCache.set(idx, 'Log unavailable.');
    } finally {
      _histLogInFlight.delete(idx);
    }
  });
}

// Bulk-dismiss every Done strip on the campaigns board (local → _localDismissed,
// cloud → _cloudDismissed). Mirrors the Sales Nav "Clear done".
let _lastCampaignsDone = [];
function clearCampaignsDone() {
  for (const it of _lastCampaignsDone) {
    if (it.where === 'cloud') _cloudDismissed.add(it.id);
    else _localDismissed.add(it.id);
  }
  renderCampaignsBoard();
}
window.clearCampaignsDone = clearCampaignsDone;

// App-styled confirm (replaces the native OS dialog). Returns a Promise<bool>.
// Reuses the existing .modal-backdrop/.modal-card design so it matches the app.
function appConfirm(message, opts = {}) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    back.innerHTML = `<div class="modal-card${opts.machineChoice ? ' machine-choice-card' : (opts.resumeConfirm ? ' resume-confirm-card' : '')}" role="dialog" aria-modal="true" style="max-width:${opts.machineChoice ? '620px' : (opts.resumeConfirm ? '480px' : '420px')}">
      <h3 class="modal-title">${escHtml(opts.title || 'Are you sure?')}</h3>
      <div class="modal-body">${escHtml(message)}</div>
      <div class="modal-actions${opts.machineChoice ? ' machine-choice-actions' : ''}" style="justify-content:flex-end;gap:10px;margin-top:18px">
        <button type="button" class="${opts.machineChoice ? 'machine-choice-option' : 'modal-cancel-link'} ac-cancel">${escHtml(opts.cancelLabel || 'Cancel')}</button>
        <button type="button" class="${opts.machineChoice ? 'machine-choice-option is-current' : 'btn btn-primary'} ac-ok">${escHtml(opts.okLabel || 'Delete all')}</button>
      </div></div>`;
    const done = (v) => { document.removeEventListener('keydown', onKey); back.remove(); resolve(v); };
    const onKey = (e) => { if (e.key === 'Escape') done(opts.machineChoice ? null : false); else if (e.key === 'Enter') done(true); };
    back.querySelector('.ac-ok').onclick = () => done(true);
    back.querySelector('.ac-cancel').onclick = () => done(false);
    back.onclick = (e) => { if (e.target === back) done(opts.machineChoice ? null : false); };
    document.body.appendChild(back);
    document.addEventListener('keydown', onKey);
    setTimeout(() => { try { back.querySelector('.ac-ok').focus(); } catch { /* */ } }, 0);
  });
}
window.appConfirm = appConfirm;

// Categorized bulk clear. Campaigns are cloud/local (engine keeps cloud data on
// its own lifecycle) → "clear" hides them from THIS board. Drafts get a real
// soft-delete + 1-week purge via clearAllDrafts.
async function clearBoardCat(cat) {
  const items = [..._snItemsById.values()];
  const targets = cat === 'cancelled'
    ? items.filter((x) => x.bucket === 'done' && x.bad)
    : items.filter((x) => x.bucket === 'done' && !x.bad);
  if (!targets.length) return;
  const word = cat === 'cancelled' ? 'stopped / cancelled' : 'finished';
  if (!(await appConfirm(`Clear all ${targets.length} ${word} campaign(s) from your board?`, { title: 'Clear campaigns', okLabel: 'Clear all' }))) return;
  for (const it of targets) {
    if (it.where === 'cloud') _cloudDismissed.add(it.id);
    else if (it.where === 'email' && typeof dismissEmailDone === 'function') dismissEmailDone(it.id);
    else _localDismissed.add(it.id);
  }
  try { _cloudSaveDismissed(); } catch { /* */ }
  renderCampaignsBoard();
}
window.clearBoardCat = clearBoardCat;

// Soft-delete every draft (hidden now, kept 1 week, then server-purged).
async function clearAllDrafts() {
  let n = 0;
  try { n = ((await (await fetch('/api/drafts')).json()).drafts || []).length; } catch { /* */ }
  if (!n) return;
  if (!(await appConfirm(`Delete all ${n} draft(s)? They stay recoverable for 1 week, then are removed for good.`, { title: 'Delete drafts', okLabel: 'Delete all' }))) return;
  // ONE bulk request (not N deletes) — server trashes them all in a single write.
  try { await fetch('/api/drafts/trash-all', { method: 'POST' }); } catch { /* */ }
  try { if (typeof refreshDashboardDrafts === 'function') refreshDashboardDrafts(); } catch { /* */ }
  renderCampaignsBoard();
}
window.clearAllDrafts = clearAllDrafts;

// Shared prettier empty state for the sn-boards. cfg: { icon, title, sub,
// ctaLabel, ctaFn, legend? }.
function _snEmptyStateHtml(cfg) {
  const legend = cfg.legend
    ? `<div class="sn-emptyx-legend">${cfg.legend}</div>` : '';
  return `
  <div class="sn-emptyx">
    <div class="sn-emptyx-mark" aria-hidden="true">${cfg.icon}</div>
    <div class="sn-emptyx-title">${cfg.title}</div>
    <div class="sn-emptyx-sub">${cfg.sub}</div>
    <button type="button" class="sn-emptyx-cta" onclick="${cfg.ctaFn}">${cfg.ctaLabel}</button>
    ${legend}
  </div>`;
}

const _SN_ICON_CLOUD = `<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6.5 18a3.5 3.5 0 0 1-.4-6.98A5 5 0 0 1 16 10.2a3.4 3.4 0 0 1 1.5 6.8"/><path d="M9 21h9a2 2 0 0 0 2-2v-2"/></svg>`;
const _SN_ICON_SEARCH = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>`;

// Prettier empty state for the campaigns board.
function _campaignsEmptyState() {
  return _snEmptyStateHtml({
    icon: _SN_ICON_CLOUD,
    title: 'No campaigns yet',
    sub: 'Launch outreach and it lands here as a live strip — locally or on the cloud VM.',
    ctaLabel: '＋ New campaign',
    ctaFn: 'window.startNewCampaign && window.startNewCampaign()',
    legend: '<span><i class="sw green"></i>Cloud · runs on the VM</span><span><i class="sw pink"></i>Local · runs on this machine</span>',
  });
}

// Prettier empty state for the Sales Nav scraper board.
function _scrapeEmptyState() {
  return _snEmptyStateHtml({
    icon: _SN_ICON_SEARCH,
    title: 'No scrapes yet',
    sub: 'Start a Sales Navigator scrape to pull leads into a sheet. Live jobs show up here.',
    ctaLabel: '＋ New scrape',
    ctaFn: 'window.startNewScrapeSetup && window.startNewScrapeSetup()',
  });
}
window.renderCampaignsBoard = renderCampaignsBoard;

// Start the board (hide legacy sections, render, poll every 4s). Idempotent.
let _cloudRefreshTimer = null;
function startCampaignsBoard() {
  _hideLegacyDashboardSections();
  _wireStripOverflow();
  renderCampaignsBoard();
  _refreshCloudItems();   // kick a background cloud fetch (renders again when it lands)
  if (_campaignsBoardTimer) clearInterval(_campaignsBoardTimer);
  _campaignsBoardTimer = setInterval(() => {
    if (!document.hidden) renderCampaignsBoard();
  }, 4000);
  // Cloud snapshot refreshes on its own slower timer — off the render path.
  if (_cloudRefreshTimer) clearInterval(_cloudRefreshTimer);
  _cloudRefreshTimer = setInterval(() => {
    if (!document.hidden) _refreshCloudItems();
  }, 5000);
}
window.startCampaignsBoard = startCampaignsBoard;

// macOS suspends Chromium timers and may leave a fetch pending while the lid is
// closed. A pending cloud refresh used to keep `_cloudRefreshInFlight` true
// forever after wake, so the dashboard kept rendering yesterday's snapshot
// even though the VM continued working. Recover from every observable wake
// path: visibility, window focus/pageshow, and a wall-clock jump (the fallback
// for macOS versions that emit neither event reliably).
let _lastRendererHeartbeat = Date.now();
let _lastWakeRefreshAt = 0;
function _refreshAfterRendererWake() {
  const now = Date.now();
  if (now - _lastWakeRefreshAt < 1000) return;
  _lastWakeRefreshAt = now;

  if (_cloudRefreshController) {
    try { _cloudRefreshController.abort(); } catch (_) { /* already settled */ }
  }
  _cloudRefreshController = null;
  _cloudRefreshInFlight = false;

  // Wake the local monitoring scheduler too. This duplicates Electron's native
  // powerMonitor hook intentionally: Chromium visibility is the reliable
  // fallback on Macs where the native resume event is missed.
  fetch('/api/monitoring/wake', { method: 'POST' }).catch(() => {});
  if (typeof startPolling === 'function') startPolling();
  if (typeof pollStatus === 'function') pollStatus().catch(() => {});
  _refreshCloudItems();
  try { renderCampaignsBoard(); } catch (_) { /* fresh fetch repaints shortly */ }
}

document.addEventListener('visibilitychange', () => {
  if (!document.hidden) _refreshAfterRendererWake();
});
window.addEventListener('focus', _refreshAfterRendererWake);
window.addEventListener('pageshow', _refreshAfterRendererWake);
setInterval(() => {
  const now = Date.now();
  const elapsed = now - _lastRendererHeartbeat;
  _lastRendererHeartbeat = now;
  if (elapsed > 15_000) _refreshAfterRendererWake();
}, 5000);

// The board is the top-level Campaigns view — it must start on page load
// REGARDLESS of whether a campaign is running. (Previously it was only kicked
// off from startPolling(), which doesn't fire when nothing is active — so the
// board never rendered and the legacy dashboard leaked through.)
function _bootCampaignsBoard() {
  try { startCampaignsBoard(); } catch (_) { /* board best-effort */ }
  // Learn admin status, then re-render so the admin-only controls appear.
  loadViewerIdentity().then(() => { try { renderCampaignsBoard(); } catch (_) { /* */ } });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _bootCampaignsBoard);
} else {
  _bootCampaignsBoard();
}

// Which campaign the shared stop-choice-modal is acting on. cloud:true means the
// two pills route to the ENGINE (keepMonitoring vs cancel) instead of the local
// campaign. Reset whenever the modal closes so a dismissed cloud stop can't leak
// into a later local stop.
let _stopChoiceTarget = { cloud: false, id: null };

// Stop a cloud campaign from the panel. For CC+IC / CC+DM that are still sending,
// show the SAME "stop everything vs. keep monitoring" choice as a local campaign
// (1:1). Other modes — or a campaign already in monitoring/done — get the plain
// confirm → cancel.
async function stopCloudCampaignUI(id) {
  let mode = '', status = '', liveProgress = null, sentCount = 0;
  try {
    const d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`, { cache: 'no-store' })).json();
    mode = (d && d.campaign && d.campaign.mode) || '';
    status = (d && d.campaign && d.campaign.status) || '';
    liveProgress = d && d.liveProgress;
    sentCount = Number(d && d.leadCounts && d.leadCounts.sent) || 0;
  } catch { /* fall through to plain confirm */ }
  // A campaign with invitations already out can still be watched for
  // acceptances, so what happens to them is the operator's call. That question
  // is about the SENT invites and has nothing to do with whichever lead happens
  // to be mid-flight — but it used to be reachable ONLY through the in-flight
  // branch below. Press Stop in the gap between two account turns and the code
  // fell straight through to keepMonitoring:false, answering it for you.
  //
  // 2026-08-27, cmp_13s04kukmt7b0ro6: Stop landed at 15:46 between "browser
  // closed, resting" and the next lead being claimed. 106 sent invites were
  // cancelled without a prompt, and the row still carries monitor_state
  // 'monitoring' with next_check_at 15:59 — a schedule that can never fire,
  // because campaign-monitor-tick bails on any status that isn't 'monitoring'.
  const stillSending = status === 'running' || status === 'queued';
  if (usesMonitoringCadence(mode) && stillSending && sentCount > 0) {
    _stopChoiceTarget = { cloud: true, id };
    const sub = document.getElementById('stop-choice-sub');
    if (sub) {
      sub.textContent = `${sentCount} invitation${sentCount === 1 ? '' : 's'} `
        + `${sentCount === 1 ? 'is' : 'are'} still waiting on acceptance — choose what happens to them.`;
    }
    document.getElementById('stop-choice-modal')?.classList.remove('hidden');
    return;
  }
  // Stop means stop. A current lead no longer opens a second wait-or-cut modal.
  // The monitoring choice above is still necessary because it decides what
  // survives after sending stops; either answer cuts sending immediately.
  await _doStopCloud(id, { keepMonitoring: false, immediate: true });
}
window.stopCloudCampaignUI = stopCloudCampaignUI;

async function _cloudMutationRequest(url, verb) {
  const res = await fetch(url, { method: 'POST' });
  const raw = await res.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch (_) { data = {}; }
  if (!res.ok || data.error) {
    const detail = data.error || raw || `HTTP ${res.status}`;
    const err = new Error(detail);
    err.status = res.status;
    throw err;
  }
  return data;
}

// Fire the actual engine stop (shared by the plain confirm + both choice pills).
async function _doStopCloud(id, { keepMonitoring = false, scope = 'campaign', immediate = true } = {}) {
  if (_stoppingCloudIds.has(String(id))) return false;
  immediate = true;
  _markCloudStopping(id, true);
  // Say it the moment the operator clicks, NOT after the VM answers. The engine
  // call below retries a timeout up to three times, which left the card reading
  // "STOPPING…" for a full minute with nothing whatsoever in the log — the
  // operator had no way to tell a slow VM from a click that never registered.
  _pushCloudEventNow(id, keepMonitoring
      ? '⏹️ Stop requested — sending stops now; acceptance monitoring remains.'
      : '⏹️ Stop requested — stopping now; no next person can start.');
  try {
    // `immediate` used to be dropped the moment keepMonitoring was set, so
    // "Stop sending, keep monitoring" could never stop now — it always finished
    // the person in flight first. The two are independent: keepMonitoring says
    // what happens AFTER the stop, immediate says how fast the stop is.
    const qs = keepMonitoring
      ? `?keepMonitoring=1&monitoringScope=${scope === 'sheet' ? 'tab' : 'campaign'}&immediate=1`
      : '?immediate=1';
    await _cloudMutationRequest(`/api/campaign/cloud/${encodeURIComponent(id)}/stop${qs}`, 'stop');
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(keepMonitoring
        ? 'Sending stopped — the VM keeps monitoring for acceptances (7 days).'
        : 'Cloud campaign stopped.', 5000);
    }
    _pushCloudEvent(id, keepMonitoring ? '⏹️ Sending stopped — VM keeps monitoring for acceptances' : '⏹️ Campaign stopped');
    _forceCloudItemsAfterAction(id).finally(() => {
      _markCloudStopping(id, false);
      // The forced refresh fetched the real terminal/monitoring row while the
      // optimistic Stop overlay was active. Paint that saved row once more now
      // that the overlay is gone, then update the campaign-tab card as well.
      try { renderCampaignsBoard(); } catch (_) { /* */ }
      _refreshCloudActiveStatus(id).catch(() => {});
    });
  } catch (e) {
    _markCloudStopping(id, false);
    const message = `Stop was not confirmed by the VM: ${e.message}. The last displayed campaign state has been kept; retry after the connection recovers.`;
    // The toast disappears. A stop that did not take must survive in the log,
    // or the campaign looks stopped while the VM is still sending.
    _pushCloudEventNow(id, `⚠️ The VM did not confirm the stop (${e.message}). Sending may still be running — press Stop again once the connection recovers.`);
    if (typeof showCampaignToast === 'function') showCampaignToast(message, 9000);
    else alert(message);
    if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
    return false;
  }
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  return true;
}

// Pause / Resume a cloud campaign — 1:1 with the local Pause/Resume. isPaused is
// the CURRENT state: true → resume (paused→running, scheduler continues from
// where it left off); false → pause (stop?pause=1; the engine worker re-checks
// status between leads, so sending stops after the lead in flight).
// Which campaigns have already had the 48h warning. Per machine, not per
// engine: it is a fact about what this operator has been told, and the operator
// is the one sitting at this laptop.
const PAUSE_WARNED_KEY = 'pauseWarnedCampaigns';
function _pauseWarned() {
  try { return new Set(JSON.parse(localStorage.getItem(PAUSE_WARNED_KEY) || '[]')); }
  catch (_) { return new Set(); }
}
function _markPauseWarned(id) {
  try {
    const seen = _pauseWarned();
    seen.add(String(id));
    // Bounded: the newest 200 campaigns is far more than anyone pauses, and it
    // stops a years-old board from growing this key without limit.
    localStorage.setItem(PAUSE_WARNED_KEY, JSON.stringify([...seen].slice(-200)));
  } catch (_) { /* private mode / quota — the toast still says it */ }
}

/**
 * The first time a campaign is paused, say the 48h rule in a dialog that has to
 * be acknowledged. Every pause after that gets the toast instead: the rule is
 * worth one interruption per campaign, and a modal on every press of a
 * reversible action only teaches the operator to click through it.
 *
 * Resolves true to go ahead, false if they chose Keep sending. Missing markup
 * (older shell) resolves true — a warning that cannot render must never be the
 * reason a pause does not happen.
 */
function _confirmFirstPause(id) {
  const modal = document.getElementById('pause-warn-modal');
  const ok = document.getElementById('pause-warn-confirm');
  if (!modal || !ok || _pauseWarned().has(String(id))) return Promise.resolve(true);

  // What the operator is really asking about: the leads that have not gone out.
  const pending = Number(((_cloudDetailCache.get(id) || {}).leadCounts || {}).pending) || 0;
  ok.textContent = pending
    ? `Pause · ${pending.toLocaleString()} lead${pending === 1 ? '' : 's'} stay queued`
    : 'Pause · got it';

  return new Promise((resolve) => {
    let done = false;
    const finish = (val) => {
      if (done) return;
      done = true;
      modal.classList.add('hidden');
      ok.onclick = null;
      modal.removeEventListener('click', onScrim);
      document.removeEventListener('keydown', onKey);
      window.closePauseWarnModal = _closePauseWarnModal;
      resolve(val);
    };
    // Scrim, Escape and "Keep sending" all mean the same thing: do not pause.
    // Answering the dialog by dismissing it must never be read as consent.
    const onScrim = (e) => { if (e.target === modal) finish(false); };
    const onKey = (e) => { if (e.key === 'Escape') finish(false); };
    ok.onclick = () => { _markPauseWarned(id); finish(true); };
    modal.addEventListener('click', onScrim);
    document.addEventListener('keydown', onKey);
    window.closePauseWarnModal = () => finish(false);
    modal.classList.remove('hidden');
    ok.focus();
  });
}

function _closePauseWarnModal() {
  const m = document.getElementById('pause-warn-modal');
  if (m) m.classList.add('hidden');
}
window.closePauseWarnModal = _closePauseWarnModal;

async function pauseCloudCampaignUI(id, isPaused) {
  const path = isPaused ? 'resume' : 'stop?pause=1';
  const verb = isPaused ? 'resume' : 'pause';
  if (!isPaused && !(await _confirmFirstPause(id))) return;   // they chose to keep sending
  try {
    await _cloudMutationRequest(`/api/campaign/cloud/${encodeURIComponent(id)}/${path}`, verb);
    if (typeof showCampaignToast === 'function') {
      // The 48h rule is said HERE, at the press, as well as on the card. A rule
      // the operator only meets when their campaign is already gone is not a
      // rule they were told. Cloud only — a local pause has no such deadline.
      showCampaignToast(isPaused
        ? 'Resuming…'
        : 'Pausing — sending stops after the current lead. Left paused for 48h it stops for good and releases its accounts.', 7000);
    }
    _pushCloudEvent(id, isPaused
      ? '▶️ Resumed'
      : '⏸️ Paused — sending stops after the current lead. Auto-stops after 48h paused.');
  } catch (e) {
    const network = /fetch failed|network|abort|timeout/i.test(String(e && e.message));
    const message = network
      ? `The app temporarily lost its connection to the development VM. The campaign was not ${verb === 'pause' ? 'paused' : 'resumed'} by this request. The tunnel reconnects automatically — try ${verb === 'pause' ? 'Pause' : 'Resume'} again in a few seconds.`
      : `Could not ${verb}: ${e.message}`;
    if (typeof showCampaignToast === 'function') showCampaignToast(message, 9000);
    else alert(message);
    return false;
  }
  // Refresh the viewed card immediately, plus the board.
  if (typeof _refreshCloudActiveStatus === 'function' && _viewingCloudId === id) { try { await _refreshCloudActiveStatus(id); } catch {} }
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  return true;
}
window.pauseCloudCampaignUI = pauseCloudCampaignUI;

// ── Cloud campaign OPEN → edit ──────────────────────────────────────────────
// OPEN on a RUNNING cloud campaign drops the operator into the wizard,
// prefilled with the campaign's saved launch config, every field locked, and a
// banner explaining edits need a pause. Pausing unlocks the form; "Save edits
// & resume" re-enters the normal wizard launch path, and submitStartCampaign
// diverts the body to /api/campaign/cloud/:id/edit-redispatch (stop the paused
// original + redispatch its still-pending leads with the edited config).
let _cloudEdit = null; // { cloudId, name, paused }

function _cloudEditBannerEls() {
  return {
    banner: document.getElementById('wizard-cloud-edit-banner'),
    title: document.getElementById('cloud-edit-banner-title'),
    detail: document.getElementById('cloud-edit-banner-detail'),
    pauseBtn: document.getElementById('btn-cloud-edit-pause'),
    saveBtn: document.getElementById('btn-cloud-edit-save'),
    rename: document.getElementById('cloud-edit-rename'),
    newName: document.getElementById('cloud-edit-new-name'),
    swap: document.getElementById('cloud-edit-swap'),
  };
}

// How many of this campaign's leads would actually move to the replacement.
// Read off the board's own snapshot — no extra request, and '' when the
// snapshot hasn't landed yet, because a wrong number here is worse than none.
function _cloudEditPendingCount(id) {
  try {
    const d = (_cloudRaw || []).find((x) => ((x && x.campaign) || {}).id === id);
    const n = Number(((d || {}).leadCounts || {}).pending);
    return Number.isFinite(n) && n > 0 ? n : null;
  } catch (_) { return null; }
}

function _renderCloudEditBanner() {
  const { banner, title, detail, pauseBtn, saveBtn, rename, newName, swap } = _cloudEditBannerEls();
  if (!banner) return;
  if (!_cloudEdit) { banner.style.display = 'none'; return; }
  banner.style.display = '';
  // Only the paused (redispatch) branch names a replacement — hide it everywhere
  // else, including the 5s poll's re-render of a still-running campaign.
  if (rename && !(_cloudEdit.paused && !_cloudEdit.readOnly)) rename.style.display = 'none';
  if (swap && !(_cloudEdit.paused && !_cloudEdit.readOnly)) swap.textContent = '';
  if (_cloudEdit.readOnly) {
    // v2.160.46: OPEN on an ACTIVE campaign → read-only view. No pause/save
    // path here — to edit, the operator stops it from the dashboard (→ Stopped,
    // which OPEN then edits). The banner just explains why fields are locked.
    if (title) title.textContent = `"${_cloudEdit.name || 'This campaign'}" is active.`;
    if (detail) detail.textContent = 'Its configuration is read-only while it runs. Stop the campaign from the dashboard to edit it.';
    if (pauseBtn) pauseBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    return;
  }
  if (_cloudEdit.paused) {
    // Saving REPLACES this campaign — it does not resume it (server.js
    // edit-redispatch). Say that at the top, and name the replacement here so
    // the operator sees two distinct campaigns before committing.
    const oldName = _cloudEdit.name || 'This campaign';
    const pending = _cloudEditPendingCount(_cloudEdit.cloudId);
    const leads = pending ? `Its ${pending.toLocaleString()} unsent lead${pending === 1 ? '' : 's'} move` : 'Its unsent leads move';
    if (title) title.textContent = `Editing "${oldName}" — this replaces it.`;
    if (detail) detail.textContent = `"${oldName}" stops for good. ${leads} to a new campaign:`;
    if (rename) rename.style.display = '';
    if (newName && !newName.value.trim()) newName.value = nextReplacementName(_cloudEdit.name) || _cloudEdit.name || '';
    _renderCloudEditSwap();
    if (pauseBtn) pauseBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = '';
  } else {
    if (title) title.textContent = `"${_cloudEdit.name || 'This campaign'}" is running.`;
    if (detail) detail.textContent = 'Fields are locked while it sends — pause it to make edits.';
    if (pauseBtn) { pauseBtn.style.display = ''; pauseBtn.disabled = false; pauseBtn.textContent = 'Pause campaign'; }
    if (saveBtn) saveBtn.style.display = 'none';
  }
}

// old → new, so the two campaigns read as two campaigns before committing.
// textContent per node (never innerHTML): the campaign name is operator input.
function _renderCloudEditSwap() {
  const { newName, swap } = _cloudEditBannerEls();
  if (!swap || !_cloudEdit) return;
  swap.textContent = '';
  const oldEl = document.createElement('span');
  oldEl.className = 'old';
  oldEl.textContent = _cloudEdit.name || 'this campaign';
  const arrow = document.createElement('span');
  arrow.textContent = ' → ';
  const newEl = document.createElement('span');
  newEl.textContent = ((newName && newName.value) || '').trim() || '(name the replacement)';
  swap.append(oldEl, arrow, newEl);
}
window.cloudEditSwapChanged = _renderCloudEditSwap;

// Lock/unlock every control in the wizard EXCEPT the banner's own buttons and
// the back link. Only elements THIS lock disabled get re-enabled (via the
// data flag) so other disable-owners (setCampaignButtons, validation) are
// never stomped.
function _setCloudEditLock(locked) {
  const root = document.getElementById('wizard-view');
  if (!root) return;
  root.classList.toggle('cloud-edit-locked', !!locked);
  root.querySelectorAll('input, select, textarea, button').forEach((el) => {
    // Never lock the banner's own buttons, any "back to dashboard" link (top
    // .wizard-back-row OR bottom .back-link), or the Live Status card's controls
    // (#nav-status — Run check now / pause / show are campaign controls, not
    // config-edit fields; they must stay usable while viewing an active campaign).
    if (el.closest('#wizard-cloud-edit-banner') || el.closest('.wizard-back-row') || el.closest('.back-link') || el.closest('#nav-status')) return;
    // Picking accounts for a live campaign is a campaign CONTROL, not a config
    // edit — the same reason #nav-status is exempt. Without this the read-only
    // lock (re-asserted by the 5s cloud poll) disabled the very picker the
    // operator was sent to, and every click just toasted "stop it first".
    try { if (_acctAdd && (el.closest('#nav-accounts') || el.closest('#wizard-acct-add-banner'))) return; } catch (_) { /* */ }
    if (locked) {
      if (!el.disabled) { el.disabled = true; el.dataset.cloudEditLocked = '1'; }
    } else if (el.dataset.cloudEditLocked) {
      el.disabled = false; delete el.dataset.cloudEditLocked;
    }
  });
}

async function openRunningCampaignEditor(id) {
  let d = null;
  try {
    const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/launch-config`);
    if (r.ok) d = await r.json();
  } catch (_) { /* fall through to the live view below */ }
  if (!d || !d.config) {
    // Pre-2.133 campaigns have no snapshotted wizard config → old behavior.
    try { await openCloudLive(id); } catch (_) {}
    return;
  }
  // Already paused? Land straight in editable mode.
  let paused = false;
  try {
    const s = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`).then((r) => r.json());
    paused = String(((s && s.campaign) || s || {}).status || '') === 'paused';
  } catch (_) { /* treat as running — the lock is the safe default */ }
  _cloudEdit = { cloudId: id, name: d.name || '', paused };
  const nameInput = document.getElementById('campaign-name-input');
  if (nameInput) nameInput.value = d.name || '';
  // Clear any replacement name left from the LAST campaign opened — the banner
  // only auto-fills an empty field, so a stale value would silently name this
  // campaign's replacement after a different one.
  const { newName: _rn } = _cloudEditBannerEls();
  if (_rn) _rn.value = '';
  try { clearActiveDraft(); } catch (_) { /* editing a live campaign, not a draft */ }
  if (typeof applyPresetConfig === 'function') applyPresetConfig(d.config);
  goCreateCampaign();
  _renderCloudEditBanner();
  _setCloudEditLock(!paused);
  // applyPresetConfig renders some sections async (account picker, tab list) —
  // re-assert the lock once they've landed so late fields don't stay editable.
  if (!paused) setTimeout(() => { if (_cloudEdit && !_cloudEdit.paused) _setCloudEditLock(true); }, 900);
}
window.openRunningCampaignEditor = openRunningCampaignEditor;

async function cloudEditPauseNow() {
  if (!_cloudEdit) return;
  const { pauseBtn } = _cloudEditBannerEls();
  if (pauseBtn) { pauseBtn.disabled = true; pauseBtn.textContent = 'Pausing…'; }
  await pauseCloudCampaignUI(_cloudEdit.cloudId, false);
  // Wait for the engine to actually pause (it finishes the current lead first).
  for (let i = 0; i < 40 && _cloudEdit; i++) {
    try {
      const s = await fetch(`/api/campaign/cloud/${encodeURIComponent(_cloudEdit.cloudId)}`).then((r) => r.json());
      const st = String(((s && s.campaign) || s || {}).status || '');
      if (st && st !== 'running') break;
    } catch (_) { /* transient — keep polling */ }
    await new Promise((r) => setTimeout(r, 1500));
  }
  if (!_cloudEdit) return; // operator navigated away mid-pause
  _cloudEdit.paused = true;
  _renderCloudEditBanner();
  _setCloudEditLock(false);
}
window.cloudEditPauseNow = cloudEditPauseNow;

function cloudEditSaveResume() {
  // The banner's name field is what the operator actually looked at, so it wins.
  // The wizard's own name input is the single source the launch body reads
  // (app.js:6879), so copy it across rather than threading a second name down.
  const { newName } = _cloudEditBannerEls();
  const chosen = ((newName && newName.value) || '').trim();
  if (chosen) {
    const ni = document.getElementById('campaign-name-input');
    if (ni) ni.value = chosen;
    // Beat the same name-restore race openCampaignForEdit guards against.
    window._openEditNameOverride = chosen;
  }
  // Same wizard entry as a real launch so every validation runs; the body is
  // diverted to edit-redispatch inside submitStartCampaign.
  if (typeof startCampaign === 'function') startCampaign({ cloud: true });
}
window.cloudEditSaveResume = cloudEditSaveResume;

function clearCloudEditMode() {
  if (!_cloudEdit) return;
  _cloudEdit = null;
  _setCloudEditLock(false);
  _renderCloudEditBanner();
}
window.clearCloudEditMode = clearCloudEditMode;

// v2.160.46: bind the wizard's LIVE STATUS panel to a specific campaign, so OPEN
// (edit or read-only) shows THAT campaign's card — never a previously-viewed one
// (bug: opening "…_b" still showed "…_a" at the bottom).
// v2.160.51: also KEEP that campaign's log on display — force the Live Status
// section open (liveStatusForcedOpen) and expand it, so the opened campaign's log
// is always visible at the bottom of the wizard, under section 6 (Launch).
function _bindLiveStatusToCampaign(id, seed = null) {
  stopViewingCloudCampaign();
  const item = _boardItemsById.get(id) || _snItemsById.get(id);
  const name = item?.name || seed?.name || document.getElementById('campaign-name-input')?.value || '';
  const sameLocal = sameCampaign(_localLive, { campaignId: item?.campaignId || seed?.campaignId, name });
  const snapshot = item?.bucket === 'saved' ? { name, state: 'draft', hasRun: false, running: false }
    : sameLocal ? _localLive : (item ? statusFromItem(item) : seed);
  _viewingLocalCampaign = {
    id, name, campaignId: item?.campaignId || seed?.campaignId,
    status: { ...(snapshot || {}), _cloud: false, runsOn: 'local', queued: false,
      name, campaignId: item?.campaignId || seed?.campaignId, id: sameLocal ? 'local-active' : id,
      running: !!snapshot?.running, state: snapshot?.state || (snapshot?.running ? null : 'done'),
      connectionUnknown: false },
  };
  liveStatusForcedOpen = true;
  renderActiveCard(_viewingLocalCampaign.status);
  syncLiveStatusVisibility();
  startPolling();
  // Refresh only the Mac's status. Never send a native campaign ID to the cloud API.
  pollStatus();
}

function localCampaignViewStatus(incoming) {
  if (!_viewingLocalCampaign || location.hash !== '#/new') return incoming;
  const selected = _viewingLocalCampaign;
  if (!incoming?._cloud && sameCampaign(incoming, selected)) {
    selected.status = { ...incoming, _cloud: false, runsOn: 'local', id: 'local-active' };
  }
  return selected.status;
}

// v2.160.46: OPEN on an ACTIVE (running/paused/monitoring) cloud campaign → the
// setup wizard, prefilled but READ-ONLY. To edit, the operator stops it from the
// dashboard (→ Stopped, which OPEN then edits). No pause/redispatch path here.
async function openRunningCampaignReadOnly(id) {
  return openCampaignForEdit(id);
}
window.openRunningCampaignReadOnly = openRunningCampaignReadOnly;

// Re-assert the cloud read-only view's invariants idempotently. No-op unless we're
// actually viewing a cloud campaign read-only. Called on open, on wizard route
// entry, and on every cloud-card poll tick so the view can't drift back to a
// "This machine / no Live Status" state after an async re-render.
function _enforceCloudReadOnlyView() {
  if (!(_viewingCloudId && _cloudEdit && _cloudEdit.readOnly)) return;
  // Only reset the run-target on actual drift so the 5s poll doesn't needlessly
  // re-render the wizard (setRunTarget → refreshRunTarget cascade).
  try {
    if (typeof getRunTarget === 'function' && typeof setRunTarget === 'function' && getRunTarget() !== 'cloud') setRunTarget('cloud');
  } catch (_) { /* */ }
  liveStatusForcedOpen = true;
  try { if (typeof syncLiveStatusVisibility === 'function') syncLiveStatusVisibility(); } catch (_) { /* */ }
  try { _setCloudEditLock(true); } catch (_) { /* */ }
}
window._enforceCloudReadOnlyView = _enforceCloudReadOnlyView;

// v2.160.46: while an active campaign is open read-only, any attempt to touch a
// field tells the operator to stop it first. The fields are already disabled
// (_setCloudEditLock), so this fires on the surrounding cards/labels/gaps; the
// banner is the always-visible backstop. Throttled so it toasts once per burst.
let _readOnlyToastAt = 0;
function _wireReadOnlyEditGuard() {
  const root = document.getElementById('wizard-view');
  if (!root || root._readOnlyGuardWired) return;
  root._readOnlyGuardWired = true;
  root.addEventListener('mousedown', (e) => {
    if (!(_cloudEdit && _cloudEdit.readOnly)) return;
    if (e.target.closest('#wizard-cloud-edit-banner') || e.target.closest('.wizard-back-row') || e.target.closest('.back-link') || e.target.closest('#nav-status')) return;
    try { if (_acctAdd && (e.target.closest('#nav-accounts') || e.target.closest('#wizard-acct-add-banner'))) return; } catch (_) { /* */ }
    if (!e.target.closest('.mode-card, input, select, textarea, button, label, #mode-grid, .launch-actions')) return;
    const now = (window.performance && performance.now) ? performance.now() : 0;
    if (now - _readOnlyToastAt < 1200) return;
    _readOnlyToastAt = now;
    if (typeof showCampaignToast === 'function') showCampaignToast('This campaign is active — stop it from the dashboard to edit its configuration.', 3800);
  }, true);
}

// OPEN on a STOPPED / cancelled / done cloud campaign → the setup wizard,
// prefilled with its saved launch config (same name at the top, campaign type,
// message, accounts, sheet, delays…), FULLY editable. Launching starts a fresh
// campaign with the (possibly edited) config; the original is left as-is. The
// unique-name rule runs at launch, so re-running the same name auto-suffixes.
// Campaigns launched before the launch-config snapshot existed fall back to the
// live view.
async function openCampaignForEdit(id) {
  const _it = (_boardItemsById && _boardItemsById.get(id)) || (_snItemsById && _snItemsById.get(id));
  const d = _it?.srcSettings ? { name: _it.name, config: _configFromSettings(_it.mode, _it.srcSettings) } : null;
  const displayName = (_it && _it.name) || (d && d.name) || '';
  const mode = (d && d.config && d.config.mode) || (_it && _it.mode) || '';

  // v2.160.42 bug fix: entering the wizard (#/new) fires syncCampaignNameInput(),
  // whose async /api/draft-name + localStorage fallbacks resolve AFTER we set the
  // name and would clobber it with the *previously* opened campaign's name (e.g.
  // opening "OPiii" showed the earlier "ASII_Inmail"). A one-shot override makes
  // syncCampaignNameInput honor the opened campaign's name and win that race;
  // localStorage is seeded too so a Cmd+R on the wizard keeps this name.
  const _seedName = () => {
    window._openEditNameOverride = displayName;
    try { localStorage.setItem('campaignName', displayName); } catch (_) { /* private mode */ }
    const ni = document.getElementById('campaign-name-input');
    if (ni) ni.value = displayName;
  };

  // A campaign's settings live under its NAME (src/campaign-configs.js). That is
  // the store the wizard writes on every Save, and the only one that is keyed
  // per campaign.
  //
  // The id-keyed launch snapshot fetched above is a record of one RUN, and its
  // `name` can be stale: cloud-launch-configs.json held two records both named
  // CTAX_GUES_MUN_CCVI, one of them carrying a different campaign's message, so
  // two different campaign cards resolved into the same snapshot and showed one
  // message no matter which you opened (operator, 2026-09-04). Asking it first
  // is what made every downstream fix look like it had not worked.
  //
  // So: the named record wins. The run snapshot is only a fallback for a
  // campaign that has never been saved by name.
  try { clearCloudEditMode(); } catch (_) { /* not in running-edit lock mode */ }
  try { clearActiveDraft(); } catch (_) { /* editing a saved campaign, not a draft */ }
  _seedName();

  let _loaded = false;
  if (displayName && typeof loadCampaignConfigByName === 'function') {
    try { _loaded = await loadCampaignConfigByName(displayName, _it?.campaignId); } catch (_) { _loaded = false; }
    if (_loaded) {
      // loadCampaignConfigByName writes the name too; re-assert the board's
      // capitalisation so the field reads as the operator named it.
      _seedName();
      // A saved campaign is not a draft — keep the autosave detached so
      // keystrokes cannot land in some other campaign's draft row.
      try { clearActiveDraft(); } catch (_) { /* nothing attached */ }
    }
  }

  if (!_loaded && d && d.config) {
    // Never saved by name — fall back to the snapshot of its last run.
    if (typeof applyPresetConfig === 'function') applyPresetConfig(d.config);
    _seedName();
    _loaded = true;
  }

  if (!_loaded) {
    // Nothing recorded anywhere: a clean wizard seeded with the name and type
    // we do know from the board.
    await startNewCampaign();
    _seedName();
    const select = document.getElementById('campaign-mode');
    if (select && mode) { select.value = mode; if (typeof onModeChange === 'function') onModeChange(); }
  }
  goCreateCampaign();

  // Lock the campaign type — an existing campaign's type is fixed; everything
  // else stays editable. Runs last so it survives any nav-triggered re-render.
  if (mode) lockCampaignType(mode);
  // Editing an existing campaign → the save action becomes "Save changes"
  // (writes the edits back onto this campaign; it stays in the Stopped section).
  _editingExistingCampaign = true;
  _editingCampaignId = id;
  _updateSaveButtonLabel();
  // v2.160.47: a cloud campaign re-opened for edit should default back to the
  // Cloud VM (else a re-launch would silently run on This machine).
  if (_it && _it.where === 'cloud') {
    try { if (typeof setRunTarget === 'function') setRunTarget('cloud'); } catch (_) { /* */ }
  }
  // v2.160.46: bind the LIVE STATUS panel to THIS campaign so it shows the one
  // just opened (not a previously-viewed campaign leaking in from below).
  _bindLiveStatusToCampaign(id);
}
window.openCampaignForEdit = openCampaignForEdit;

// ── Live campaign-name collision warning ─────────────────────────────────────
function _checkCampaignNameCollision() {
  const input = document.getElementById('campaign-name-input');
  const warn = document.getElementById('campaign-name-warn');
  if (!input || !warn) return;
  const name = (input.value || '').trim();
  if (!name) { warn.style.display = 'none'; input.classList.remove('has-warning'); return; }
  // Editing an existing campaign keeps its own name — that is not a clash.
  if (typeof _editingExistingCampaign !== 'undefined' && _editingExistingCampaign
      && name.toLowerCase() === String(_openedCampaignName || '').trim().toLowerCase()) {
    warn.style.display = 'none'; input.classList.remove('has-warning'); return;
  }
  const taken = new Set((_knownCampaignNames || []).map(n => String(n).toLowerCase()));
  if (taken.has(name.toLowerCase())) {
    warn.textContent = 'A campaign with this name already exists';
    warn.style.display = '';
    input.classList.add('has-warning');
  } else {
    warn.style.display = 'none';
    input.classList.remove('has-warning');
  }
}

// ── Unique campaign names within "Your campaigns" ───────────────────────────
// Names of the viewer's OWN non-FG campaigns from the last board render — the
// set a new/edited campaign must be unique against.
function _existingMineCampaignNames() {
  const out = [];
  try {
    for (const it of (_snItemsById ? _snItemsById.values() : [])) {
      if (it && it.mine && !it.isFG && it.name) out.push(String(it.name).trim());
    }
  } catch (_) { /* best-effort */ }
  return out;
}
// Spreadsheet-style letter increment: a→b, z→aa, az→ba.
function _incSeq(s) {
  if (!s) return 'a';
  const arr = s.split(''); let i = arr.length - 1;
  while (i >= 0) {
    if (arr[i] === 'z') { arr[i] = 'a'; i--; } else { arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1); break; }
  }
  if (i < 0) arr.unshift('a');
  return arr.join('');
}
// Return `desired` if free; else append/bump a `_<letters>` suffix until unique.
// "MESSAGE" → "MESSAGE_a"; an existing "…_d" bumps to "…_e".
function _uniqueCampaignName(desired, taken) {
  const raw = String(desired || '').trim();
  // Ortus Basics 1.0: the name IS the campaign. Starting a run means "save these
  // settings under this name and go", so re-running must keep the name and
  // overwrite — auto-suffixing produced PoopPa → PoopPa_a → PoopPa_b and split
  // one campaign's settings across three names. (Was: bump a _<letters> suffix
  // until unique.)
  return raw;
  /* eslint-disable no-unreachable */
  if (!raw) return raw; // empty name is allowed (row shows "Add name")
  const set = new Set((taken || []).map((n) => String(n).trim().toLowerCase()));
  if (!set.has(raw.toLowerCase())) return raw;
  const m = raw.match(/^(.*)_([a-z]+)$/i);
  const base = m ? m[1] : raw;
  let seq = m ? _incSeq(m[2].toLowerCase()) : 'a';
  let candidate = `${base}_${seq}`;
  while (set.has(candidate.toLowerCase())) { seq = _incSeq(seq); candidate = `${base}_${seq}`; }
  return candidate;
}

async function _submitCloudEditRedispatch(body) {
  const id = _cloudEdit && _cloudEdit.cloudId;
  if (!id) return;
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/edit-redispatch`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const txt = await res.text();
    let data; try { data = JSON.parse(txt); } catch { data = { error: txt }; }
    if (!res.ok || data.error) {
      alert(`Could not save edits:\n\n${data.error || txt}`);
      return;
    }
    clearCloudEditMode();
    if (typeof showCampaignToast === 'function') showCampaignToast(`☁︎ Edits saved — ${data.leadsAdded} remaining lead(s) redispatched with the new settings.`, 6000);
    if (data.id) { try { await openCloudLive(data.id); } catch (_) { /* board still shows it */ } }
  } catch (e) {
    alert('Could not save edits: ' + e.message);
  }
}

// Restart a STOPPED/CANCELLED local campaign from its saved settings snapshot.
// fromStart=false → Continue (seed resumeContext so the counter picks up where it
// left off; the sheet's already-sent rows are skipped). fromStart=true → Restart
// from the beginning (counter resets to 0; the sheet STILL skips already-done
// rows, so no double-outreach). Reuses the exact /api/campaign/start path the
// resume flow uses — no new backend.
const _localRestartsPending = new Set();
async function restartLocalFromItem(id, fromStart, reviewed = null) {
  if (_localRestartsPending.has(id)) return false;
  _localRestartsPending.add(id);
  try {
    const selected = _viewingLocalCampaign?.id === id ? _viewingLocalCampaign : null;
    const it = _boardItemsById.get(id) || _snItemsById.get(id) || selected;
    let name = it?.name || '';
    let s = it?.srcSettings;
    // History cards need not include settings. The named saved configuration
    // is authoritative, just as it is when opening the campaign editor.
    if (name) {
      const saved = await fetch(it?.campaignId ? `/api/campaign-configs/by-id/${encodeURIComponent(it.campaignId)}` : `/api/campaign-configs/${encodeURIComponent(name)}`);
      if (saved.ok) {
        const data = await saved.json();
        if (!data.config || typeof data.config !== 'object') throw new Error('Saved campaign settings could not be read.');
        s = data.config;
        name = data.name || name;
      } else if (saved.status !== 404) {
        throw new Error(`Could not load saved settings (${saved.status}). Please try again.`);
      }
    }
    if (!s) throw new Error('Saved settings could not be found for this campaign. Open it and save its settings, then resume.');
    const mode = s.mode || it?.mode;
    const templates = { ...s.templates };
    // Saved wizard configurations use the primary-person fields for IC.
    if (mode === 'introduce_back') {
      templates.introName = templates.primaryName || templates.introName || '';
      templates.followUp1 = templates.primaryIntroBody || templates.followUp1 || templates.followUpMessage || '';
    }
    const payload = {
      ...s,
      profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
      sheetUrl: s.sheetUrl || '', templates,
      dailyLimit: s.dailyLimit ?? 50, mode,
      delayMin: s.delayMin ?? 10, delayMax: s.delayMax ?? 20,
      concurrency: s.concurrency ?? 1, name,
      primaryCheckTiming: s.primaryCheckTiming ?? templates.primaryCheckTiming,
    };
    delete payload.resumeContext;
    if (!fromStart) {
      const live = sameCampaign(_localLive, { campaignId: s.campaignId || it?.campaignId, name }) ? _localLive : selected?.status;
      payload.resumeContext = { totalProcessed: Number(live?.totalProcessed ?? it?.hist?.totalProcessed ?? it?.hist?.successCount ?? 0) || 0 };
    }
    // Resume uses the same review dialog as a new launch. Continue submits
    // the exact reviewed configuration, not unrelated current wizard fields.
    let launchPayload = payload;
    if (reviewed) {
      launchPayload = { ...reviewed.payload, preflightAck: reviewed.ack };
    } else {
      const pf = await runPreflight(payload);
      if (pf.findings.blockers.length || pf.findings.warnings.length) {
        _pfState = {
          findings: pf.findings, ack: pf.ack, payload,
          onLaunch: ack => restartLocalFromItem(id, fromStart, { payload, ack }),
        };
        renderPreflight(pf);
        return false;
      }
      launchPayload.preflightAck = pf.ack;
    }
    window.__localLaunchName = launchPayload.name || '';
    const r = await fetch('/api/campaign/start', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(launchPayload) });
    if (!r.ok) {
      const raw = await r.text().catch(() => '');
      let message = raw;
      try { message = JSON.parse(raw).error || raw; } catch {}
      throw new Error(message || r.statusText);
    }
    if (typeof showCampaignToast === 'function') showCampaignToast(fromStart ? 'Restarted from the beginning — already-done rows are skipped.' : 'Continuing where it left off…', 4500);
    if (typeof startPolling === 'function') startPolling();
    if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
    return true;
  } catch (e) {
    if (typeof showCampaignToast === 'function') showCampaignToast(`Restart failed: ${e.message}`, 6000);
    return false;
  } finally {
    _localRestartsPending.delete(id);
  }
}
window.restartLocalFromItem = restartLocalFromItem;

// Restart a STOPPED/CANCELLED/ERRORED cloud campaign — re-activates the SAME
// record on the engine (status → running; leads already sent carry sentAt and
// are skipped). Both buttons hit the same endpoint; fromStart is passed for
// parity (the engine skips done leads either way). Degrades gracefully with a
// clear toast until the engine ships /restart (404).
// startAt (ISO, optional): schedule the restart instead of running it now. The
// engine parks the campaign in 'scheduled' behind a durable task and restarts it
// itself at that instant — this app can be closed.
async function restartCloudCampaignUI(id, fromStart, startAt, resumeSending = false) {
  // Say it before the VM is asked, exactly like the stop does. The card is
  // log-driven, and this line classifies as 'sending-resumed' (live-log-banner),
  // so it also switches the card off the monitoring view immediately — the
  // countdown to the next acceptance check used to keep ticking for ten seconds
  // after the click, which reads as "nothing happened" (operator recording,
  // 2026-09-01 18:12). A failure below puts the card back.
  if (!startAt) {
    _markCloudResuming(id, true);
    _pushCloudEventNow(id, fromStart
      ? '▶️ Started (from the beginning) — waiting for the VM to confirm…'
      : '▶️ Started (continuing where it left off) — waiting for the VM to confirm…');
  }
  try {
    // Carry the wizard's (possibly edited) daily limit so a change made while the
    // campaign was stopped actually takes effect on the engine when it restarts.
    const dlRaw = parseInt(document.getElementById('daily-limit')?.value, 10);
    const dailyLimit = Number.isFinite(dlRaw) && dlRaw > 0 ? dlRaw : undefined;
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/restart`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        fromStart: !!fromStart,
        resumeSending: !!resumeSending,
        ...(dailyLimit ? { dailyLimit } : {}),
        ...(startAt ? { startAt } : {}),
      }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      if (typeof showCampaignToast === 'function') showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Restart isn’t live yet — engine update pending.', 6000);
      _markCloudResuming(id, false);
      _pushCloudEventNow(id, `⚠️ The VM did not accept the restart (${d.error || `HTTP ${res.status}`}). Nothing was resumed — try again once the connection recovers.`);
      if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
      return false;
    }
    if (d.alreadyRunning) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Already sending — nothing to resume.', 4000);
      return true;
    }
    if (d.scheduled) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast(`⏰ Scheduled on the VM for ${_fmtCloudStartAt(d.startAt)} — ${d.pending || 0} lead(s) waiting. The laptop can stay shut.`, 7000);
      }
      _pushCloudEvent(id, `⏰ Scheduled to restart ${_fmtCloudStartAt(d.startAt)}`);
      window.location.hash = '#/'; // back to the dashboard, where it shows as Scheduled
      if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
      return true;
    }
    const left = Number(d.pending) || 0;
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(fromStart ? 'Restarting the cloud campaign from the beginning…'
        : `Resuming — the VM will send the ${left ? `${left} remaining` : 'remaining'} lead(s).`, 4500);
    }
    // The optimistic line above already said this; confirm it as fact.
    _pushCloudEvent(id, fromStart ? '▶️ Started (from the beginning)' : '▶️ Started (continuing where it left off)');
  } catch (e) {
    if (typeof showCampaignToast === 'function') showCampaignToast('Could not reach the engine: ' + e.message, 6000);
    _markCloudResuming(id, false);
    _pushCloudEventNow(id, `⚠️ Could not reach the VM to resume (${e.message}). Nothing was resumed — try again once the connection recovers.`);
    if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
    return false;
  }
  // Paint the accepted restart and its new log event immediately. The normal
  // board poll then replaces this optimistic transition with engine truth.
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  await _forceCloudItemsAfterAction(id);
  return true;
}
window.restartCloudCampaignUI = restartCloudCampaignUI;

// Manual acceptance checks are intentionally optimistic in the UI: the click
// must replace the old "waiting" card before a cold VM or GoLogin browser has
// had time to answer. The next server poll replaces this temporary description
// with measured progress.
function _paintAcceptanceCheckStartingNow(id, current = 'vm') {
  const action = {
    phase: 'checking',
    label: 'Starting acceptance check now',
    sub: current === 'vm'
      ? 'The Cloud VM is opening the campaign accounts.'
      : 'This Mac is opening the campaign accounts.',
    safety: 'Sending stays stopped. Only accepted connections are being checked.',
    facts: [['Requested', 'now'], ['Sending', 'stays stopped'], ['Checking', 'starting']],
    milestones: [['Choice', 'acceptance checking', 'done'], ['Browser', 'opening now', 'active'], ['Results', 'reported here', 'future']],
  };
  const active = window.__cloudActiveStatus;
  if (active && String(active.id || '') === String(id || '')) {
    window.__cloudActiveStatus = {
      ...active,
      monitoringCheckInProgress: true,
      monitorCheckStatus: 'starting',
      currentAction: action,
    };
    try { if (typeof renderActiveCard === 'function') renderActiveCard(window.__cloudActiveStatus); } catch (_) { /* board copy still repaints */ }
  }
  try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* next poll repaints */ }
}

// Task 3 Part B — cloud monitoring controls (parity with local ⚡ Check now /
// Automatic checks). Degrade gracefully until the engine ships the routes: a
// 404/HTTP error → a clear "engine update pending" toast, no throw.
async function cloudCheckNow(id, btn, scope) {
  scope = scope === 'all' ? 'all' : 'campaign';
  const existingAsk = _cloudCheckAsked.get(id);
  if (existingAsk && Date.now() - existingAsk < CLOUD_CHECK_ASK_TTL_MS) {
    if (btn) btn.disabled = true;
    return false;
  }
  // A check runs where the campaign runs. The guard lives HERE, not in each
  // caller, because a caller that forgets it fires a VM sweep on a campaign
  // sitting on this Mac: the card said RUNNING ON = THIS MAC while the toast
  // said "the VM is opening a browser". Worse than cosmetic for CC+IC, where
  // two sweeps both read a blank Introduction Status and send two intro DMs.
  if (_checkRunsLocally(id)) return cloudCheckLocal(id, btn, scope);
  if (btn) btn.disabled = true;
  // Optimistic UI belongs before the network await. The engine may take 20–30s
  // to wake/queue a worker, but the operator's click was accepted locally now.
  // _cloudCurrentAction reads this marker, so both dashboard and builder copies
  // switch to the same "Starting acceptance check" card in this tick.
  const askedAt = Date.now();
  _cloudCheckAsked.set(id, askedAt);
  _paintAcceptanceCheckStartingNow(id, 'vm');
  let queued = false;
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/check-now`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ scope }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      if (_cloudCheckAsked.get(id) === askedAt) _cloudCheckAsked.delete(id);
      try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
      showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Check now isn’t live yet — engine update pending.', 6000);
    } else {
      queued = true;
      _pushCloudEvent(id, scope === 'all' ? '⚡ Check now — every account in the Account Used column' : '⚡ Check now — this campaign’s accounts');
      showCampaignToast(scope === 'all'
        ? '⚡ Check queued — the VM will sweep every account in the sheet’s Account Used column…'
        : '⚡ Check queued — the VM is opening a browser to sweep… (takes ~10s)', 4500);
    }
  } catch (e) {
    if (_cloudCheckAsked.get(id) === askedAt) _cloudCheckAsked.delete(id);
    try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
    showCampaignToast('Could not reach the engine: ' + e.message, 6000);
  }
  finally { if (btn && !queued) btn.disabled = false; }
  if (!queued) return false;

  // Real feedback tied to the actual browser (fixes "no indication when it
  // starts / no logs"): poll the live flag so the operator SEES the sweep begin
  // ("VM checking now") and finish, instead of silence. The VM opens a browser
  // for only a few seconds, so this narrates that short window.
  (async () => {
    let sawLive = false;
    for (let i = 0; i < 120; i++) {                // ~3 min cold-start window
      await new Promise((r) => setTimeout(r, 1500));
      let dd = {};
      try { dd = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`)).json(); } catch { /* */ }
      if (i === 39 && !dd.live && !sawLive) {
        showCampaignToast('The VM worker is still waking. No account has started yet; cold starts normally take about two minutes.', 7000);
      }
      if (dd.live && !sawLive) {
        sawLive = true;
        showCampaignToast('🟢 VM checking now — browser is open. Click 👁 Show to watch it live.', 6000);
      } else if (!dd.live && sawLive) {
        _cloudCheckAsked.delete(id);
        showCampaignToast('✓ VM check complete.', 4000);
        if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
        return;
      }
    }
    if (!sawLive && _cloudCheckAsked.get(id) === askedAt) {
      _cloudCheckAsked.delete(id);
      showCampaignToast('The VM did not start the check within three minutes. The request remains queued; use Stop check to cancel it.', 8000);
      try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
    }
  })();
  return true;
}
window.cloudCheckNow = cloudCheckNow;

async function stopCloudCheckUI(id, btn) {
  if (btn) btn.disabled = true;
  try {
    const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/check/stop`, { method: 'POST' });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || d.error) throw new Error(d.error || `HTTP ${r.status}`);
    _cloudCheckAsked.delete(id);
    showCampaignToast(d.wasQueued
      ? 'Queued check cancelled. No browser was opened; monitoring remains active.'
      : d.wasRunning === false
      ? 'Nothing was queued or running — no check to stop.'
      : 'Stopping the check now. The current browser is closing; unconfirmed work will retry next time. Monitoring remains active.', 7000);
    if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
    return true;
  } catch (e) {
    if (btn) btn.disabled = false;
    showCampaignToast('Could not stop the check: ' + e.message, 7000);
    return false;
  }
}
window.stopCloudCheckUI = stopCloudCheckUI;

// Local check of a CLOUD campaign (v2.160.87) — runs the app's OWN GoLogin
// sweep (/api/bulk-check-now — the exact engine local campaigns use: opens each
// account's browser here, stamps Connected, fires intros where Introduction
// Status is blank) against the cloud campaign's sheet. Accounts whose GoLogin
// profile can't open on this machine are skipped and reported, never fatal.
// Afterwards, mirrors the sheet's statuses into the engine (fill-only) so the
// VM's next sweep won't double-intro anyone this local check already handled.
async function cloudCheckLocal(id, btn, scope) {
  if (!id) return;
  scope = scope === 'all' ? 'all' : 'campaign';
  if (btn) btn.disabled = true;
  // Same immediate state transition as the VM path. Opening a local GoLogin
  // browser can also take several seconds; never leave the old waiting card on
  // screen after the operator has explicitly started a check.
  const askedAt = Date.now();
  _cloudCheckAsked.set(id, askedAt);
  _paintAcceptanceCheckStartingNow(id, 'local');
  showCampaignToast('🖥 Local check starting — opening GoLogin browsers on this machine. Keep the app open…', 7000);
  _pushCloudEvent(id, scope === 'all'
    ? '🖥 Local check — every account in the Account Used column (on this machine)'
    : '🖥 Local check — this campaign’s accounts (on this machine)');
  try {
    const d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`)).json();
    const camp = d && d.campaign;
    if (!camp || !camp.sheet_url) {
      showCampaignToast('Could not load this campaign (or its sheet) from the engine.', 7000);
      return;
    }
    const cfg = camp.config || {};
    const body = {
      sheetUrl: camp.sheet_url,
      linkedinColumn: cfg.linkedinColumn || '',
      // The local `campaign` singleton may hold an unrelated config — pass the
      // CLOUD campaign's mode + templates so the sweep behaves identically to a
      // local campaign configured the same way.
      mode: camp.mode,
      primaryName: cfg.primaryName || '',
      primaryIntroBody: cfg.primaryIntroBody || '',
      primaryUrl: cfg.primaryUrl || '',
      introTitle: cfg.introTitle || '',
      autoAcceptPrimary: cfg.autoAcceptPrimary,
      primarySource: cfg.primarySource,
      ccDmBody: cfg.ccDmBody || '',
      senderFirstNames: cfg.senderFirstNames || {},
    };
    if (scope === 'all') body.allSenders = true;
    else body.profileIds = camp.profile_ids || camp.profileIds || [];
    const _sweepReq = fetch('/api/bulk-check-now', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    // The request above is dispatched, not awaited yet: the sweep runs for
    // 30-120s and the card must not wait that long to admit it started. The
    // server flips its checking flag on route entry, so a short burst of polls
    // catches it within a few hundred ms instead of on the next 2s tick. These
    // ask the server what is true, they do not paint an optimistic guess, so a
    // request that fails simply never flips the card.
    [120, 400, 900, 1800].forEach((ms) => setTimeout(() => {
      try { if (typeof pollStatus === 'function') pollStatus(); } catch (_) { /* */ }
    }, ms));
    const res = await _sweepReq;
    const j = await res.json().catch(() => ({}));
    if (!res.ok || j.error) {
      showCampaignToast('Local check failed: ' + (j.error || `HTTP ${res.status}`), 9000);
      return;
    }
    const per = Array.isArray(j.perProfile) ? j.perProfile : [];
    const failed = per.filter((p) => p && p.error);
    const okCount = per.length - failed.length;
    const matched = (j.result && j.result.matched) || 0;
    // Write-back: mirror the sheet's statuses into the engine (fill-only there)
    // so a later VM check never re-introduces someone this check handled.
    let synced = 0;
    try {
      const sr = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/sync-sheet-status`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ linkedinColumn: cfg.linkedinColumn || '' }),
      });
      const sj = await sr.json().catch(() => ({}));
      if (sr.ok && !sj.error) synced = sj.matched || 0;
    } catch { /* best-effort — the sheet already has the truth */ }
    const bits = [`${okCount}/${per.length} account${per.length === 1 ? '' : 's'} checked`, `${matched} newly Connected`];
    if (failed.length) bits.push(`${failed.length} couldn’t open on this machine (skipped)`);
    if (synced) bits.push(`${synced} lead${synced === 1 ? '' : 's'} synced to the engine`);
    showCampaignToast(`🖥 Local check done — ${bits.join(' · ')}.`, 12000);
    _pushCloudEvent(id, `🖥 Local check done — ${bits.join(' · ')}`);
    if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
    if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  } catch (e) {
    showCampaignToast('Local check failed: ' + e.message, 9000);
  } finally {
    // The local sweep has completed (successfully or not), so the optimistic
    // "starting/checking" marker must not survive until its 90-second TTL.
    // Keeping it around made the hero disagree with the completed live log.
    if (_cloudCheckAsked.get(id) === askedAt) _cloudCheckAsked.delete(id);
    try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
    if (btn) btn.disabled = false;
  }
}
window.cloudCheckLocal = cloudCheckLocal;

// Cloud "Run check now" → first ask the same scope question the local check asks:
// this campaign's accounts, or every account in the sheet's "Account Used" column.
// Reuses the shared solo-check scope modal; maps its 'sheet' choice to the engine's
// 'all' scope (Account Used column) and 'campaign' to this campaign's accounts.
function promptCloudCheckScope(id, btn) {
  if (!id) return;
  // Scope only: this campaign's accounts, or every account in the sheet's
  // Account Used column. WHERE it runs is no longer asked, it follows the
  // campaign's own side. See _checkRunsLocally.
  _soloCheckHandler = (mode) => {
    const scope = mode === 'sheet' ? 'all' : 'campaign';
    if (_checkRunsLocally(id)) cloudCheckLocal(id, btn, scope);
    else cloudCheckNow(id, btn, scope);
  };
  _showSoloCheckModal();
}
window.promptCloudCheckScope = promptCloudCheckScope;

async function setCloudAutoChecks(id, enabled, el) {
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/auto-checks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: !!enabled }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Auto-checks toggle isn’t live yet — engine update pending.', 6000);
      if (el) el.checked = !enabled; // revert the switch — the change didn't stick
    } else {
      showCampaignToast(`Automatic checks ${enabled ? 'on' : 'off'}.`, 4000);
    }
  } catch (e) { showCampaignToast('Could not reach the engine: ' + e.message, 6000); if (el) el.checked = !enabled; }
}
window.setCloudAutoChecks = setCloudAutoChecks;

// Start/stop polling when the Cloud Campaigns section is opened/closed.
window.onCloudSectionToggle = function onCloudSectionToggle() {
  const section = document.getElementById('cloud-campaigns-section');
  const open = section && !section.classList.contains('collapsed');
  if (_cloudPollTimer) { clearInterval(_cloudPollTimer); _cloudPollTimer = null; }
  // Ortus Basics 1.0: no cloud board refresh — cloud campaigns are discontinued.
  // (was: if (open) { renderCloudCampaigns(); _cloudPollTimer = setInterval(renderCloudCampaigns, 8000); })
};

async function _runIcPreflight(sheetUrl, senderColumn) {
  try {
    const res = await fetch('/api/campaign/preflight-ic-senders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sheetUrl, senderColumn: senderColumn || '' }),
    });
    const data = await res.json();
    if (data.error) {
      alert(`Could not validate sender column:\n\n${data.error}`);
      return false;
    }
    if (data.ok) return true;
    _showIcPreflightModal(data);
    return false;
  } catch (err) {
    alert(`Preflight check failed: ${err.message}`);
    return false;
  }
}

function _showIcPreflightModal(data) {
  const modal = document.getElementById('ic-preflight-modal');
  const title = document.getElementById('ic-preflight-title');
  const bodyEl = document.getElementById('ic-preflight-body');
  const primary = document.getElementById('ic-preflight-primary');
  const secondary = document.getElementById('ic-preflight-secondary');
  if (!modal || !title || !bodyEl || !primary || !secondary) return;

  modal.dataset.reason = data.reason || '';

  if (data.reason === 'no_column') {
    title.textContent = 'No sender column selected';
    bodyEl.innerHTML =
      `<p>All ${data.totalRows} rows in your sheet have a blank sender value.</p>` +
      `<p style="color: var(--gray); font-size: 0.85rem; margin-top: 10px;">` +
      `Pick the column that contains the LinkedIn 1st connections in Section 2, then try again.</p>`;
    primary.textContent = 'Take me to the column picker';
    secondary.classList.add('hidden');
  } else {
    // no_match
    const list = (data.unmatched || []).map(u =>
      `<li><code>${escHtml(u.name)}</code> &mdash; ${u.count} row${u.count === 1 ? '' : 's'}</li>`
    ).join('');
    const extra = (data.unmatched || []).length === 5 ? ' (top 5 shown)' : '';
    title.textContent = 'No matching GoLogin profile';
    bodyEl.innerHTML =
      `<p>Your sheet has sender values, but none match a GoLogin profile in this workspace.</p>` +
      (list ? `<ul style="margin: 12px 0 0; padding-left: 20px; font-size: 0.85rem; color: var(--ink);">${list}</ul>` : '') +
      `<p style="color: var(--gray); font-size: 0.8rem; margin-top: 10px;">` +
      `${data.totalRows} total row${data.totalRows === 1 ? '' : 's'}${extra}. Check that the Sender column values exactly match your GoLogin profile display names (case-sensitive).</p>`;
    primary.textContent = 'Open sheet to fix';
    secondary.classList.remove('hidden');
  }

  modal.classList.remove('hidden');
}

function closeIcPreflightModal() {
  const modal = document.getElementById('ic-preflight-modal');
  if (modal) modal.classList.add('hidden');
}

function _icPreflightPrimary() {
  const modal = document.getElementById('ic-preflight-modal');
  const reason = modal?.dataset?.reason || '';
  closeIcPreflightModal();
  if (reason === 'no_match') {
    // Open the sheet so the operator can fix the Sender column values
    if (typeof openSheetInBrowser === 'function') openSheetInBrowser();
  } else {
    // no_column → scroll + focus the IC column dropdown
    _icPreflightScrollToColumnPicker();
  }
}

function _icPreflightSecondary() {
  closeIcPreflightModal();
  _icPreflightScrollToColumnPicker();
}

// v2.58.x — Called from the IC sender-column dropdown's onchange. Marks
// the picker as "manually chosen" so subsequent previewSheet() runs don't
// stomp on the operator's pick, and hides the gold "Auto-detected" badge.
function _icSenderColManualPick() {
  const sel = document.getElementById('ic-sender-col-select');
  const badge = document.getElementById('ic-auto-detected-badge');
  if (sel) {
    sel.dataset.manualPick = '1';
    sel.classList.remove('is-detected');
  }
  if (badge) badge.classList.add('hidden');
}

function _icPreflightScrollToColumnPicker() {
  const sel = document.getElementById('ic-sender-col-select');
  if (!sel) {
    // The IC extras block is rendered by previewSheet(); if not present,
    // scroll to the sheet section so the operator can press Preview first.
    document.getElementById('nav-sheet')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }
  sel.scrollIntoView({ behavior: 'smooth', block: 'center' });
  setTimeout(() => sel.focus(), 350);
}

// Cloud dispatch: run the campaign on the GKE engine instead of locally. Fully
// self-contained + returns early, so the local path below is untouched. The
// ── Launch-in-progress live state (Path A) ──────────────────────────────────
// Between pressing Start on a cloud CC+IC campaign and the engine acknowledging
// the dispatch, two slow steps run with NO campaign row existing anywhere: the
// local primary handshake (minutes — it drives a GoLogin browser per sender) and
// the start-cloud POST (reads the whole lead sheet, builds leads). The handshake
// modal covered the first step and nothing covered the second.
//
// Operator report 2026-08-06: "that handshake disappeared and it was with nothing
// for two minutes… I went back to the dashboard and it says it's just still a
// draft. The hell?" — the draft row is only deleted once start-cloud returns, so
// the board legitimately still showed a draft while the launch was in flight.
//
// Fix: publish the launch as a live state on BOTH surfaces the operator watches —
// the shared #active-card (card #1 on the dashboard / card #2 in the campaign
// tab; one element, relocated by placeLiveCard) and a board strip. Neither needs
// new markup: the card reuses its gold `is-preflight` state (v2.105) and the
// strip reuses the `awaiting_primary_accept` handshake panel.
let _cloudLaunch = null;

// handshake sender state → the pf-list vocabulary renderActiveCard already
// speaks. `error` maps to 'unverified' rather than a hard failure: the operator
// can still Dispatch anyway, and the row should read as unconfirmed, not dead.
const _HS_STATE_TO_PF = {
  pending: 'pending', connecting: 'pending', sent: 'sent',
  'sent-no-identity': 'sent', accepting: 'accepting', connected: 'connected',
  error: 'unverified',
};

// `handshake:false` (every cloud mode except CC+IC-with-local-primary) skips
// straight to the dispatch phase — those launches have no per-sender step, and
// claiming a "Primary handshake" that never runs would be a worse lie than the
// blank screen this replaces.
function beginCloudLaunch({ name, profileIds, handshake = true } = {}) {
  _cloudLaunch = {
    phase: handshake ? 'handshake' : 'dispatching',
    hasHandshake: !!handshake,
    name: name || 'New campaign',
    // 'local-browser' is the primary itself, not a sender — it never appears as
    // a handshake row (same filter the pf-list renderer applies).
    profileIds: (profileIds || []).filter((id) => id && id !== 'local-browser'),
    conn: {},
    logs: [],
    leadsRead: null,
    startedAt: Date.now(),
  };
  // A launch is operational status immediately, even before an engine campaign
  // row exists. Reveal section 7 now so the handshake/dispatch card cannot sit
  // hidden below the Launch form until a later poll discovers the real row.
  liveStatusForcedOpen = true;
  try { syncLiveStatusVisibility(); } catch (_) { /* */ }
  try { placeLiveCard(); } catch (_) { /* */ }
  paintCloudLaunch();
  setTimeout(() => {
    const sec = document.getElementById('nav-status');
    if (sec) { sec.classList.remove('collapsed'); try { sec.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) {} }
  }, 100);
}

// Narrate one launch step into the live log.
//
// Operator ask, 2026-08-27: "it needs to have costant updates, literally as
// much as possible, also in the log". A VM launch spends up to a minute reading
// the sheet, running the pre-flight gate and dispatching, and the log rail read
// LIVE LOG · LAST 0 EVENTS for the whole of it, because cloudLaunchStatus()
// returned a hardcoded empty array. Every step now says what it is ABOUT TO DO
// before it blocks, so a slow step is a step you can name rather than a frozen
// card, and says its result after.
function launchLog(line) {
  if (!_cloudLaunch || !line) return;
  if (!Array.isArray(_cloudLaunch.logs)) _cloudLaunch.logs = [];
  const at = new Date();
  const clock = `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`;
  // A STRING, not { t, line }. v3RenderLogLine takes strings, and String(obj)
  // is "[object Object]" — which matches its own `[timestamp] message` pattern,
  // so it read "object Object" as the time and the EMPTY remainder as the
  // message. Every launch line was written, counted in the header, and rendered
  // as a blank row (operator recording, 2026-08-28 11:59: eleven blank rows).
  _cloudLaunch.logs.push(`${line} · ${clock}`);
  // A launch is a minute or two, but a retry loop must never grow this forever.
  if (_cloudLaunch.logs.length > 60) _cloudLaunch.logs.splice(0, _cloudLaunch.logs.length - 60);
  paintCloudLaunch();
}
window.launchLog = launchLog;

// The handshake wizard's poll snapshot → our per-sender map. Same data the modal
// paints, so the modal and the two cards can never disagree.
function updateCloudLaunchSenders(senders) {
  if (!_cloudLaunch || !Array.isArray(senders)) return;
  for (const s of senders) {
    if (s && s.profileId) _cloudLaunch.conn[s.profileId] = s.state;
  }
  paintCloudLaunch();
}

// 'handshake' → 'dispatching'. The second phase has no per-sender progress to
// show (the app is reading the sheet and POSTing), so the rows freeze at their
// final handshake state and the copy changes instead.
function setCloudLaunchPhase(phase) {
  if (!_cloudLaunch) return;
  _cloudLaunch.phase = phase;
  paintCloudLaunch();
}

// A launch the server refused. The card stays up, in a failed state, until the
// operator dismisses it — see failedStartRetry({ launchFailed:true }).
function failCloudLaunch(message, fixes = []) {
  if (!_cloudLaunch) return;
  _cloudLaunch.phase = 'failed';
  _cloudLaunch.failure = { message: String(message || 'The launch was refused.'), fixes: fixes || [] };
  paintCloudLaunch();
}

// Stop pressed while a cloud launch is still in flight. The launch is one long
// server call — read the sheet, resolve the GoLogin profiles, POST the engine —
// that cannot be interrupted half way, and Stop used to fall straight through to
// the LOCAL campaign stop instead. Measured 2026-08-28 15:08: two "■ Stop
// requested (full halt)" lines against some other campaign, and then this one
// "dispatched to engine — 4 leads, 2 account(s)" seven seconds later. So record
// the intent here and let the submit path cancel the campaign the moment it
// exists — the one promise we can actually keep is that nothing is left running.
function cancelCloudLaunch() {
  if (!_cloudLaunch || _cloudLaunch.failure) return false;
  if (_cloudLaunch.stopRequested) {
    if (typeof showCampaignToast === 'function') showCampaignToast('Already cancelling this launch — hang on.', 4000);
    return true;
  }
  _cloudLaunch.stopRequested = true;
  launchLog('■ Cancel requested — this launch will not be left running.');
  paintCloudLaunch();
  if (typeof showCampaignToast === 'function') {
    showCampaignToast('Cancelling this launch. If it has already reached the VM it is stopped straight away.', 6000);
  }
  return true;
}
window.cancelCloudLaunch = cancelCloudLaunch;

// Force-clear a failed launch card once the operator has read it.
function dismissCloudLaunch() {
  if (_cloudLaunch) _cloudLaunch.failure = null;
  endCloudLaunch();
}
window.dismissCloudLaunch = dismissCloudLaunch;

function endCloudLaunch() {
  if (!_cloudLaunch) return;
  // A failed launch is the one case the card must OUTLIVE the launch: the
  // `finally` below runs on every exit path, and it used to wipe the only place
  // the failure was written down.
  if (_cloudLaunch.failure) { paintCloudLaunch(); return; }
  _cloudLaunch = null;
  // Repaint both surfaces once more so the synthetic strip/card are replaced by
  // the real campaign (or by the idle state if the launch was cancelled).
  paintCloudLaunch();
}

// The synthetic status object. Shaped for renderActiveCard's `is-preflight`
// branch: phase 'preflight' + primaryConn/profileIds/profileNames.
function cloudLaunchStatus() {
  const L = _cloudLaunch;
  if (!L) return null;
  const nameOf = (id) => {
    const picked = (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || '';
    if (picked) return picked;
    // profileLabel() falls back to the raw id, so guard against handing the
    // operator a 24-hex hash where an account name belongs (2026-09-01: the
    // handshake wizard named a sender "6a5f1605f264c576fd2fcabf").
    const label = (typeof profileLabel === 'function' ? profileLabel(id) : '') || '';
    return (label && label !== id) ? label : 'this account';
  };
  const primaryConn = {};
  for (const id of L.profileIds) primaryConn[id] = _HS_STATE_TO_PF[L.conn[id]] || 'pending';
  const doneN = L.profileIds.filter((id) => primaryConn[id] === 'connected').length;
  if (L.failure) {
    const fixes = (L.failure.fixes || []).map((f) => String(f.label || '')).filter(Boolean);
    return {
      running: false, paused: false, state: 'error', phase: 'done',
      bad: true, badLabel: 'Error', launchFailed: true,
      id: '__launching__', name: L.name, mode: 'connect_and_introduce',
      profileIds: L.profileIds.slice(), profileNames: L.profileIds.map(nameOf),
      totalTargets: 0, totalProcessed: 0, acceptedCount: '—',
      endNotice: fixes.length ? `${L.failure.message} Try: ${fixes.join(', ')}.` : L.failure.message,
      logs: (L.logs || []).slice(), skippedCount: 0, _launching: true,
    };
  }
  return {
    running: true, paused: false, state: 'preflight', phase: 'preflight',
    // Whether Phase 0 actually runs. A launch that sends the primary handshake
    // to the VM has NO local phase 0, and labelling it "Phase 0 · Primary
    // handshake / handshake started" describes work that is not happening.
    hasHandshake: !!L.hasHandshake,
    mode: 'connect_and_introduce',
    name: L.name,
    profileIds: L.profileIds.slice(),
    profileNames: L.profileIds.map(nameOf),
    primaryConn,
    totalTargets: 0, totalProcessed: 0, acceptedCount: '—',
    logs: (L.logs || []).slice(), skippedCount: 0,
    // What the step strip advances on. 'handshake' → 'dispatching' → 'accepted'.
    launchPhase: L.phase || '',
    leadsRead: L.leadsRead == null ? null : L.leadsRead,
    sendersDone: doneN,
    preflightL1: L.phase === 'handshake'
      ? 'Sending connections to the primary account'
      : 'Handing the campaign over to the VM',
    preflightSub: L.phase !== 'handshake'
      ? (L.hasHandshake
        ? 'Handshake done — reading your lead sheet and handing the campaign to the VM…'
        : 'Reading your lead sheet and dispatching to the VM…')
      : `${doneN} of ${L.profileIds.length} connected · your Mac is doing this locally, then the campaign moves to the cloud.`,
    _launching: true,
  };
}

// Repaint the card and the board immediately rather than waiting for their 2s /
// 4s polls — during a launch those polls have nothing new to say anyway.
function paintCloudLaunch() {
  try { syncLiveStatusVisibility(); } catch (_) { /* */ }
  try { placeLiveCard(); } catch (_) { /* */ }
  try { if (typeof window.renderActiveCard === 'function') window.renderActiveCard(null); } catch (_) { /* */ }
  try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
}

// The board strip for a launch-in-flight. Same normalized item shape the board
// builds for real campaigns, plus `launching` (suppresses every control — there
// is nothing on the VM yet to stop, pause or watch) and the `senders` /
// `awaiting_primary_accept` pair the strip's handshake panel already renders.
function cloudLaunchBoardItem() {
  const L = _cloudLaunch;
  if (!L) return null;
  const nameOf = (id) => {
    const picked = (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || '';
    if (picked) return picked;
    // profileLabel() falls back to the raw id, so guard against handing the
    // operator a 24-hex hash where an account name belongs (2026-09-01: the
    // handshake wizard named a sender "6a5f1605f264c576fd2fcabf").
    const label = (typeof profileLabel === 'function' ? profileLabel(id) : '') || '';
    return (label && label !== id) ? label : 'this account';
  };
  return {
    where: 'cloud', id: '__launching__', rawId: '__launching__',
    name: L.name, mode: 'connect_and_introduce', isFG: false,
    bucket: 'running', sent: 0, total: 0, accounts: L.profileIds.length,
    mine: true, owner: '', live: false, launching: true,
    launchPhase: L.phase,
    // Only a real handshake gets the handshake panel; a plain cloud launch falls
    // through to the normal strip body with the "handing over" status text.
    state: L.hasHandshake ? 'awaiting_primary_accept' : '',
    senders: L.profileIds.map((id) => ({
      name: nameOf(id),
      accepted: L.conn[id] === 'connected',
    })),
  };
}

// ── Cloud primary-handshake wizard (Path A) ─────────────────────────────────
// Before a cloud CC+IC campaign with a LOCAL-ONLY primary is dispatched, the app
// connects each GoLogin sender to the primary and accepts the invites in the
// local primary browser (the engine can't — no operator Chrome on the VM). This
// modal shows live per-sender progress by polling the status endpoint. Resolves
// { ok:true } on success, { ok:false, proceedAnyway:true } if the operator
// dispatches without the handshake, or { ok:false, proceedAnyway:false } on
// Cancel (dispatch is aborted). See feedback_two_live_status_cards / the Path A
// spec (docs/superpowers/specs/2026-07-11-cloud-handshake-path-a-...).
// ── Connecting the senders to the primary (operator ask, 2026-08-27/28) ─────
// This used to offer a choice: run the handshake on this Mac, or "on the VM".
// The second one did nothing. It set templates.primaryHandshakeOn='vm', the app
// then skipped the handshake (handshake-gate.mjs), and the engine has no code
// that reads that value anywhere — grepped 2026-08-28, zero matches. So the
// senders were never connected to the primary, no local browser opened despite
// the option promising one, and no account could ever earn its "Primary ✓"
// badge (primaryConnected is only ever written by this local handshake).
//
// The honest framing is that this Mac opens EITHER WAY: accepting the
// invitations happens in the primary's browser, and that browser only exists
// here. There was never a second place for this to run, so there is no longer a
// question — just a statement of what is about to happen.
//
// Resolves 'local', or null if the operator backs out of the launch.
function askPrimaryHandshakeLocation({ senderCount = 0, acceptAll = false } = {}) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    const senders = `${senderCount} sender${senderCount === 1 ? '' : 's'}`;
    back.innerHTML = `
      <div class="modal-card" role="dialog" aria-modal="true" aria-label="Connecting your senders to the primary">
        <div class="stop-choice-eyebrow">Before the campaign starts</div>
        <h3 class="modal-title">Connecting your senders to the primary</h3>
        <div class="modal-body">
          Two steps on this Mac: your ${escHtml(senders)} invite the primary, the primary accepts.
          Then the campaign moves to the cloud.
        </div>
        <label class="phl-accept-all">
          <input type="checkbox" class="phl-all"${acceptAll ? ' checked' : ''}>
          <span>
            <b>Accept all pending invitations</b>
            <em>Clears the primary's whole invitation list, not just your senders'. Also the faster start.</em>
          </span>
        </label>
        <div class="modal-actions" style="display:flex; gap:10px; flex-wrap:wrap">
          <button type="button" class="btn btn-primary phl-go">Start</button>
          <button type="button" class="btn modal-cancel-link phl-cancel">Cancel launch</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    let done = false;
    const finish = (value) => {
      if (done) return;
      done = true;
      try { back.remove(); } catch (_) { /* already gone */ }
      resolve(value);
    };
    back.querySelector('.phl-go').addEventListener('click', () => finish({
      where: 'local', acceptAll: !!back.querySelector('.phl-all')?.checked,
    }));
    back.querySelector('.phl-cancel').addEventListener('click', () => finish(null));
    // Same rule as the handshake wizard: dismissable, never by accident.
    back.addEventListener('click', (e) => { if (e.target === back) finish(null); });
  });
}
window.askPrimaryHandshakeLocation = askPrimaryHandshakeLocation;

function _hsRowIconHtml(view) {
  if (view.icon === 'check') return '<span class="chk">✓</span>';
  if (view.icon === 'x') return '<span class="chk" style="color:#b23b3b">✕</span>';
  if (view.icon === 'spin') return '<span class="dotwait" style="background:var(--gold)"></span>';
  if (view.icon === 'dot') return '<span class="dotwait" style="background:var(--ink)"></span>';
  return '<span class="dotwait"></span>';
}
function runHandshakeWizard({ senderProfileIds = [], primaryUrl, primarySource = 'local-browser', autoAcceptAllPending = false }) {
  return new Promise((resolve) => {
    const nameOf = (id) => {
    const picked = (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || '';
    if (picked) return picked;
    // profileLabel() falls back to the raw id, so guard against handing the
    // operator a 24-hex hash where an account name belongs (2026-09-01: the
    // handshake wizard named a sender "6a5f1605f264c576fd2fcabf").
    const label = (typeof profileLabel === 'function' ? profileLabel(id) : '') || '';
    return (label && label !== id) ? label : 'this account';
  };
    const total = senderProfileIds.length;
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    back.innerHTML = `
      <div class="modal-card" role="dialog" aria-modal="true" aria-label="Connecting senders to the primary">
        <h3 class="modal-title">Connecting your senders to the primary</h3>
        <div class="modal-body">
          <div class="hs-panel">
            <div class="hs-eyebrow">Phase 0 · Primary handshake<span class="cnt"><span class="hs-wiz-count">0</span> / ${total} accepted</span></div>
            <div class="hs-steps">
              <div class="hs-step hs-step1"><div class="n">Step 1</div><div class="l">Senders invite the primary</div></div>
              <div class="hs-step hs-step2"><div class="n">Step 2</div><div class="l">Primary accepts the invites</div></div>
            </div>
            <div class="hs-bar"><i class="hs-wiz-bar" style="width:0%"></i></div>
            <div class="hs-wiz-now" role="status">
              <span class="hs-wiz-now-label">NOW</span>
              <strong class="hs-wiz-now-text">Starting the handshake…</strong>
              <span class="hs-wiz-elapsed">0s</span>
            </div>
            <div class="hs-list hs-wiz-list">
              ${senderProfileIds.map((id) => `<div class="hs-row" data-hid="${escHtml(String(id))}"><span class="ic"><span class="dotwait"></span></span><span class="who">${escHtml(nameOf(id))}</span><span class="st">Waiting</span></div>`).join('')}
            </div>
            <div class="hs-wiz-log" aria-label="Handshake activity log"><div class="hs-wiz-log-line">Waiting for the first browser step…</div></div>
            <div class="hs-keep">Keep this app open — this is the only local step this campaign needs.</div>
          </div>
          <div class="hs-wiz-error intro-config-error" hidden style="margin-top:12px"></div>
        </div>
        <div class="modal-actions hs-wiz-actions" style="display:flex; gap:10px; flex-wrap:wrap">
          <button type="button" class="btn btn-primary hs-wiz-retry" style="display:none">Retry</button>
          <button type="button" class="btn hs-wiz-anyway">Dispatch anyway</button>
          <button type="button" class="btn modal-cancel-link hs-wiz-cancel">Cancel</button>
        </div>
      </div>`;
    document.body.appendChild(back);

    const $ = (sel) => back.querySelector(sel);
    let poll = null;
    let elapsedTimer = null;
    const startedAt = Date.now();
    let done = false;
    let settleStartedAt = null;
    let settleTotal = 20;
    // Senders that actually sent an invitation. A sender that was already a 1st
    // degree connection goes straight to `connected` and is never in here, and
    // then step 2 has nothing to do — the primary's browser is not opened at all.
    const everInvited = new Set();
    // Seconds left in the settle wait, or null when it is over / not running.
    const settleSecondsLeft = () => {
      if (settleStartedAt == null) return null;
      const left = settleTotal - Math.floor((Date.now() - settleStartedAt) / 1000);
      return left > 0 ? left : null;
    };
    const cleanup = () => {
      if (poll) { clearInterval(poll); poll = null; }
      if (elapsedTimer) { clearInterval(elapsedTimer); elapsedTimer = null; }
      try { back.remove(); } catch (_) { /* */ }
    };
    const finish = (result) => { if (done) return; done = true; cleanup(); resolve(result); };
    // Dismissable, but never by accident. A bare scrim-click used to resolve
    // {ok:false} and silently abandon the whole launch — one stray click outside
    // the dialog and the campaign vanished with no message (Milee, 18 Aug). The
    // operator still can't get trapped on a button-less spinner: the scrim asks,
    // and Cancel / "start anyway" are always on the card.
    back.addEventListener('click', (e) => {
      if (e.target !== back) return;
      if (confirm('Cancel this launch?\n\nThe senders will not be connected and nothing is sent to the cloud. Your campaign stays saved as a draft.')) {
        finish({ ok: false, proceedAnyway: false });
      }
    });

    const paint = (senders, lines = []) => {
      let connected = 0;
      let activeSender = null;
      for (const s of (senders || [])) {
        if (['sent', 'sent-no-identity', 'accepting'].includes(s.state)) everInvited.add(s.profileId);
        const view = handshakeRowView(s.state);
        if (view.done) connected++;
        if (!activeSender && ['connecting', 'sent', 'sent-no-identity', 'accepting'].includes(s.state)) activeSender = s;
        const row = $(`.hs-row[data-hid="${CSS.escape(String(s.profileId))}"]`);
        if (!row) continue;
        row.classList.toggle('done', view.done);
        const ic = row.querySelector('.ic'); if (ic) ic.innerHTML = _hsRowIconHtml(view);
        const st = row.querySelector('.st'); if (st) st.textContent = view.label;
        if (s.name) { const who = row.querySelector('.who'); if (who) who.textContent = s.name; }
      }
      const cnt = $('.hs-wiz-count'); if (cnt) cnt.textContent = String(connected);
      const bar = $('.hs-wiz-bar'); if (bar) bar.style.width = total ? `${Math.round((connected / total) * 100)}%` : '0%';
      // Step strip. Step 2 is the part that used to be invisible: the settle
      // wait plus the primary's own browser accepting. It stays on screen now.
      const view = handshakeStepView(senders || [], null, everInvited);
      const s1 = $('.hs-step1'); const s2 = $('.hs-step2');
      if (s1) { s1.classList.toggle('did', view.step1Done); s1.classList.toggle('on', !view.step1Done); }
      if (s2) {
        const skipped = view.step === 2 && view.needsAccept === false;
        s2.classList.toggle('on', view.step === 2 && !skipped && !view.step2Done);
        s2.classList.toggle('did', view.step2Done && !skipped);
        s2.classList.toggle('skip', skipped);
        const l = s2.querySelector('.l');
        if (l) l.textContent = skipped ? 'Nothing to accept, they were already connected' : 'Primary accepts the invites';
      }

      const now = $('.hs-wiz-now-text');
      if (now) {
        const left = settleSecondsLeft();
        if (activeSender && activeSender.state === 'connecting') {
          now.textContent = `Opening ${activeSender.name || nameOf(activeSender.profileId)} in an off-screen GoLogin browser…`;
        } else if (activeSender && activeSender.state === 'accepting') {
          now.textContent = `Your primary Chrome is open, accepting ${activeSender.name || nameOf(activeSender.profileId)}'s invitation. Leave it alone, it closes itself.`;
        } else if (left != null) {
          now.textContent = `Waiting ${left}s for the invitations to land in the primary's invitations, then your primary Chrome opens to accept them.`;
        } else if (activeSender) {
          now.textContent = `Checking ${activeSender.name || nameOf(activeSender.profileId)} against the primary…`;
        } else if (view.step === 2 && view.needsAccept === false) {
          now.textContent = 'Every sender was already connected to the primary, so there is nothing to accept and your primary Chrome does not need to open.';
        } else if (view.step === 2) {
          now.textContent = 'Opening your primary Chrome to accept the invitations…';
        } else {
          now.textContent = 'Preparing the next sender browser…';
        }
      }
      // The handshake logs "…reach the primary's invites (20s) before accepting…"
      // right before it sleeps. That sleep is where the wizard used to look
      // frozen, so turn it into a countdown the operator can watch.
      if (Array.isArray(lines)) {
        for (const raw of lines) {
          const m = /reach the primary's invites \((\d+)s\)/.exec(String(raw));
          if (m && settleStartedAt == null) { settleStartedAt = Date.now(); settleTotal = Number(m[1]) || 20; }
        }
      }
      const log = $('.hs-wiz-log');
      if (log && Array.isArray(lines) && lines.length) {
        log.innerHTML = lines.slice(-8).map((line) => `<div class="hs-wiz-log-line">${escHtml(String(line).replace(/^\[handshake\]\s*/, ''))}</div>`).join('');
        log.scrollTop = log.scrollHeight;
      }
      // Mirror the same per-sender states onto the card + board so the modal is
      // no longer the ONLY place this is visible — and so closing it (or its
      // 700ms auto-close on success) doesn't drop the operator into a blank UI.
      try { updateCloudLaunchSenders(senders); } catch (_) { /* */ }
    };

    // On error, reveal Retry. When another handshake is already running (409),
    // hide "Dispatch anyway" — dispatching now would run the campaign with
    // un-handshaked senders while the other campaign drives the local browsers.
    // The invites are out but the primary never accepted them HERE — usually
    // because its Chrome would not launch. Dispatching now is allowed, but it
    // costs those senders their introductions until the accept happens, so the
    // wizard says so instead of auto-closing on a "done" that accepted nothing.
    const showPartial = (outcome) => {
      if (elapsedTimer) { clearInterval(elapsedTimer); elapsedTimer = null; }
      const panel = $('.hs-panel'); if (panel) panel.classList.add('partial');
      const eyebrow = $('.hs-eyebrow');
      if (eyebrow) eyebrow.innerHTML = `Phase 0 · Primary handshake<span class="cnt">${escHtml(outcome.headline)}</span>`;
      const s2 = $('.hs-step2');
      if (s2) { s2.classList.remove('on', 'did'); s2.classList.add('failed'); s2.querySelector('.l').textContent = 'The primary did not accept here'; }
      const label = $('.hs-wiz-now-label'); if (label) label.textContent = 'WHAT NOW';
      const now = $('.hs-wiz-now-text'); if (now) now.textContent = outcome.detail;
      const el = $('.hs-wiz-elapsed'); if (el) el.textContent = '';
      const retry = $('.hs-wiz-retry'); if (retry) { retry.style.display = ''; retry.textContent = 'Try the primary again'; retry.dataset.acceptOnly = '1'; }
      const anyway = $('.hs-wiz-anyway'); if (anyway) { anyway.style.display = ''; anyway.textContent = 'Send anyway'; }
      const cancel = $('.hs-wiz-cancel'); if (cancel) cancel.textContent = 'Cancel launch';
    };

    const showError = (msg, { is409 = false } = {}) => {
      const err = $('.hs-wiz-error'); if (err) { err.hidden = false; err.textContent = msg; }
      const retry = $('.hs-wiz-retry'); if (retry) retry.style.display = '';
      const anyway = $('.hs-wiz-anyway'); if (anyway) anyway.style.display = is409 ? 'none' : '';
    };

    const start = async ({ acceptOnly = false } = {}) => {
      const err = $('.hs-wiz-error'); if (err) { err.hidden = true; err.textContent = ''; }
      const retry = $('.hs-wiz-retry'); if (retry) { retry.style.display = 'none'; delete retry.dataset.acceptOnly; }
      const anyway = $('.hs-wiz-anyway'); if (anyway) anyway.style.display = '';
      const panel = $('.hs-panel'); if (panel) panel.classList.remove('partial');
      const label = $('.hs-wiz-now-label'); if (label) label.textContent = 'NOW';
      settleStartedAt = null;
      try {
        const res = await fetch('/api/campaign/cloud-preflight-handshake', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            senderProfileIds, primaryUrl, primarySource,
            // A retry after a partial has nothing left to send: the invitations
            // are already sitting on the primary, so force the accept sweep or
            // the run would skip Phase 2 entirely and change nothing.
            autoAcceptAllPending: acceptOnly ? true : autoAcceptAllPending,
          }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) { showError(data.error || `Could not start the handshake (${res.status}).`, { is409: res.status === 409 }); return; }
      } catch (e) { showError('Could not reach the app to start the handshake: ' + e.message); return; }

      poll = setInterval(async () => {
        try {
          const snap = await fetch('/api/campaign/cloud-preflight-handshake/status').then((r) => r.json());
          if (snap && snap.active) paint(snap.senders, snap.lines);
          if (snap && snap.done) {
            clearInterval(poll); poll = null;
            const outcome = handshakeOutcome({ senders: snap.senders, summary: snap.summary, error: snap.error, nameFor: nameOf });
            if (outcome.kind === 'error') { showError('Handshake error: ' + outcome.detail); return; }
            if (outcome.kind === 'partial') { showPartial(outcome); return; }
            // Success — brief beat so the operator sees the ✓s, then dispatch.
            setTimeout(() => finish({ ok: true }), 700);
          }
        } catch (_) { /* transient poll error — keep polling */ }
      }, 800);
    };

    elapsedTimer = setInterval(() => {
      const el = $('.hs-wiz-elapsed');
      if (!el) return;
      const seconds = Math.max(0, Math.floor((Date.now() - startedAt) / 1000));
      el.textContent = seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
    }, 1000);

    $('.hs-wiz-retry').addEventListener('click', (e) => start({ acceptOnly: e.currentTarget.dataset.acceptOnly === '1' }));
    $('.hs-wiz-anyway').addEventListener('click', () => finish({ ok: false, proceedAnyway: true }));
    $('.hs-wiz-cancel').addEventListener('click', () => finish({ ok: false, proceedAnyway: false }));
    start();
  });
}
window.runHandshakeWizard = runHandshakeWizard;

// ── Start-time preflight gate (Task 7) ──────────────────────────────────────
// Every account on the campaign is blocked, so say so before the operator
// walks away expecting sends. Same contract as runHandshakeWizard — resolve
// {ok, proceedAnyway} and let the caller decide. Unlike the handshake wizard,
// the scrim click needs no confirm() guard: nothing has been dispatched yet
// and the draft is untouched, so a dismissal costs the operator nothing.
function runPreflightPrompt({ accounts = [], earliest = null }) {
  return new Promise((resolve) => {
    const nameOf = (id) => {
    const picked = (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || '';
    if (picked) return picked;
    // profileLabel() falls back to the raw id, so guard against handing the
    // operator a 24-hex hash where an account name belongs (2026-09-01: the
    // handshake wizard named a sender "6a5f1605f264c576fd2fcabf").
    const label = (typeof profileLabel === 'function' ? profileLabel(id) : '') || '';
    return (label && label !== id) ? label : 'this account';
  };
    const label = (a) => {
      if (a.reason === 'needslogin') return 'Needs re-login in GoLogin';
      if (a.reason === 'proxy') return 'Proxy — fix the profile';
      // A dead session is an ACTION, not a wait. It used to render as "Capped
      // until Saturday", which sends the operator away for four days from a
      // problem one re-login clears.
      if (a.reason === 'session') return 'Session expired — re-login';
      if (a.reason === 'dailycap') return `Daily limit spent — resets ${_wakeWhenText(new Date(a.until).getTime())}`;
      if (a.reason === 'cooldown') return 'Cooling down between batches';
      if (a.until) return `Capped until ${_wakeWhenText(new Date(a.until).getTime())}`;
      return 'Blocked';
    };
    // Fixable first: those are the only rows with an action behind them.
    const rows = accounts.slice().sort((x, y) => Number(!!y.fixable) - Number(!!x.fixable));
    const when = earliest ? _wakeWhenText(new Date(earliest).getTime()) : 'later';
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    back.innerHTML = `
      <div class="modal-card" role="dialog" aria-modal="true" aria-label="No account can send yet">
        <h3 class="modal-title">Nothing can send yet</h3>
        <div class="modal-body">
          <p>All <b>${accounts.length}</b> account${accounts.length === 1 ? '' : 's'} on this campaign are blocked. The earliest any of them can send a connection request is <b>${escHtml(when)}</b>.</p>
          <div class="pf-list">
            ${rows.map((a) => `<div class="pf-row${a.fixable ? ' fixable' : ''}"><span class="who">${escHtml(String(nameOf(a.id)))}</span><span class="st">${escHtml(label(a))}</span></div>`).join('')}
          </div>
          <p class="pf-note">Starting anyway is not pointless: <b>acceptance checking still runs</b> on the capped accounts, and intros still fire. Only <b>sending</b> is on hold.</p>
        </div>
        <div class="modal-actions" style="display:flex; gap:10px; flex-wrap:wrap">
          <button type="button" class="btn btn-primary pf-fix">Fix accounts</button>
          <button type="button" class="btn pf-anyway">Start anyway</button>
          <button type="button" class="btn modal-cancel-link pf-back">Back</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    const done = (r) => { try { back.remove(); } catch (_) { /* */ } resolve(r); };
    back.querySelector('.pf-anyway').addEventListener('click', () => done({ ok: false, proceedAnyway: true }));
    back.querySelector('.pf-back').addEventListener('click', () => done({ ok: false, proceedAnyway: false }));
    back.querySelector('.pf-fix').addEventListener('click', () => done({ ok: false, proceedAnyway: false, fix: true }));
    // Scrim click = Back. Safe here (unlike the handshake wizard, which guards it
    // with a confirm) because nothing has been dispatched yet and the draft is
    // untouched — the operator loses nothing by dismissing.
    back.addEventListener('click', (e) => { if (e.target === back) done({ ok: false, proceedAnyway: false }); });
  });
}
window.runPreflightPrompt = runPreflightPrompt;

// server reads the sheet into leads and hands off to the engine; the campaign
// then runs in the cloud and survives the laptop closing.
// Re-entrancy guard: a slow multi-account CC+IC start (it runs the primary
// handshake wizard, reads the sheet, builds leads, then POSTs) left the Start
// button looking dead, so operators re-clicked — spawning duplicate campaigns
// over the SAME leads + accounts, which then contended and stranded most leads
// in "pending" (Sam's 3× "Poop" incident, 2026-07-24). Set synchronously before
// the first await so JS's single thread makes it airtight against re-clicks.
let _cloudSubmitInFlight = false;
// "Fri 8 Aug, 09:00" — the operator's own timezone. The engine speaks UTC ISO
// everywhere; nothing operator-facing should.
function _fmtCloudStartAt(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso || '');
  return d.toLocaleString(undefined, { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
}
if (typeof window !== 'undefined') window._fmtCloudStartAt = _fmtCloudStartAt;

async function _submitCloudCampaign(body) {
  if (_cloudSubmitInFlight) return; // ignore re-clicks while a start is dispatching
  _cloudSubmitInFlight = true;
  // Idempotency backstop: a stable id per launch attempt so any duplicated POST
  // (network retry, second app window) collapses to ONE campaign engine-side.
  // The engine dedupes on `id`; the client always documented this — it was just
  // never wired through the server. Belt-and-suspenders on a double-outreach path.
  if (!body.launchId) {
    body.launchId = (globalThis.crypto && crypto.randomUUID)
      ? crypto.randomUUID()
      : ('lnch_' + Date.now() + '_' + Math.random().toString(36).slice(2));
  }
  if (typeof showCampaignToast === 'function') showCampaignToast('☁︎ Starting cloud campaign…', 4000);
  // Publish the launch on the card + board for its WHOLE duration — the
  // handshake AND the dispatch. Cleared in the finally below, by which point
  // either a real campaign row exists or the launch was abandoned.
  // Operator ask, 2026-08-27: a VM CC+IC launch must ASK where the connections to
  // the primary are sent from, instead of silently running the local handshake.
  // Asked before beginCloudLaunch so a cancel here leaves no launch card behind,
  // and only when the handshake would otherwise have run unasked.
  if (needsHandshakeFromBody(body)) {
    const where = await askPrimaryHandshakeLocation({
      senderCount: (body.profileIds || []).length,
      // Whatever the campaign settings already say — the modal is a second
      // place to change it at the moment it applies, not a separate setting.
      acceptAll: !!(body.templates || {}).autoAcceptAllPending,
    });
    if (!where) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast('Launch cancelled — nothing was sent, and your campaign is still saved as a draft.', 6000);
      }
      _cloudSubmitInFlight = false;
      return;
    }
    body.templates = {
      ...(body.templates || {}),
      primaryHandshakeOn: where.where,
      autoAcceptAllPending: !!where.acceptAll,
    };
  }
  const _hsHere = needsHandshakeFromBody(body);
  beginCloudLaunch({ name: body.name, profileIds: body.profileIds, handshake: _hsHere });
  launchLog(`▶ Launch started — ${(body.profileIds || []).length} account${(body.profileIds || []).length === 1 ? '' : 's'}, Cloud VM`);
  if (body.mode === 'connect_and_introduce') {
    launchLog(_hsHere
      ? '🤝 Connecting your senders to the primary — sender browsers open next'
      : '🤝 No primary handshake needed for this campaign');
  }
  try {
    // Path A: run the primary handshake locally BEFORE dispatch when this is a
    // cloud CC+IC campaign with auto-accept and a local-only primary. Otherwise
    // the senders never connect to the primary (the engine's connect is lazy and
    // only fires after a lead is accepted — 0 accepted = primary gets nothing).
    if (needsHandshakeFromBody(body)) {
      const t = body.templates || {};
      const hs = await runHandshakeWizard({
        senderProfileIds: body.profileIds || [],
        primaryUrl: t.primaryUrl,
        primarySource: t.primarySource || 'local-browser',
        autoAcceptAllPending: !!t.autoAcceptAllPending,
      });
      launchLog(hs.ok
        ? '🤝 Handshake complete — every sender is connected to the primary'
        : (hs.proceedAnyway ? '🤝 Handshake skipped — dispatching anyway, as you chose' : '🤝 Handshake cancelled'));
      if (!hs.ok && !hs.proceedAnyway) {
        // Never exit silently. This return abandons the launch AND the finally
        // below wipes the board card, so without a word on screen the campaign
        // simply disappeared — the operator's read was that the app ate it.
        if (typeof showCampaignToast === 'function') {
          showCampaignToast('Launch cancelled at the primary handshake — nothing was sent, and your campaign is still saved as a draft.', 7000);
        }
        return;
      }
    }
    // Handshake over (or never needed). The next step reads the whole lead sheet
    // and POSTs — the step that used to be two silent minutes with the modal gone
    // and the board still showing a draft.
    // Preflight gate (Task 7). FAIL OPEN on every uncertainty: a campaign that
    // cannot launch because a diagnostic endpoint is down is worse than one
    // that launches into a wait. Only a PROVEN usable===0 stops here.
    try {
      const ids = body.profileIds || [];
      if (ids.length) {
        setCloudLaunchPhase('preflight');
        launchLog(`🔎 Pre-flight check on ${ids.length} account${ids.length === 1 ? '' : 's'}…`);
        // 3s and no longer. This proxies to the engine through requestWithRetry
        // (3 attempts × 20s + 1s + 2s backoff), so a 502 or a hung engine held
        // Start for ~63s between the handshake and 'dispatching' with no phase on
        // screen — the exact silence that produced a triple-submit once already.
        // Aborting lands in the catch below, which fails open and dispatches.
        const dl = Number(body.dailyLimit) > 0 ? '&dailyLimit=' + Math.floor(Number(body.dailyLimit)) : '';
        const pf = await (await fetch(
          '/api/campaign/cloud-preflight?profiles=' + encodeURIComponent(ids.join(',')) + dl,
          { signal: AbortSignal.timeout(3000) },
        )).json();
        // usable===null means the engine was unreachable — NOT that nothing can
        // send. Only a hard 0 fires the prompt.
        if (pf && typeof pf.usable === 'number') {
          launchLog(pf.usable === 0
            ? '🔎 Pre-flight — no account can send yet'
            : `🔎 Pre-flight passed — ${pf.usable} account${pf.usable === 1 ? '' : 's'} usable`);
        }
        if (pf && pf.usable === 0) {
          const verdict = await runPreflightPrompt({ accounts: pf.accounts || [], earliest: pf.earliest });
          if (!verdict.proceedAnyway) {
            if (typeof showCampaignToast === 'function') {
              showCampaignToast('Launch held — no account can send yet. Your campaign is still saved as a draft.', 6000);
            }
            return;
          }
        }
      }
    } catch (_) { /* fail open — never block a launch on this check */ }
    // Cancelled during the handshake — nothing has been dispatched, so this one
    // really is a clean stop.
    if (_cloudLaunch && _cloudLaunch.stopRequested) {
      launchLog('■ Launch cancelled before it reached the VM — nothing was dispatched.');
      if (typeof showCampaignToast === 'function') {
        showCampaignToast('Launch cancelled — nothing reached the VM, and your campaign is still saved as a draft.', 6000);
      }
      return;
    }
    setCloudLaunchPhase('dispatching');
    // The long one. The server reads the whole lead sheet here, so say so BEFORE
    // it blocks — this await is what produced the silent minute.
    launchLog('📄 Reading your lead sheet and handing the campaign to the VM…');
    // Backstop for the server hop. Every await inside handleStartCloud is now
    // bounded, but an unbounded request here means ANY future unbounded await
    // shows up as a card that spins forever instead of an error the operator
    // can read. 4 minutes clears the worst honest case (a big sheet: 30s x2 for
    // the CSV, plus GoLogin, plus a 20s engine call) with room to spare.
    const res = await fetch('/api/campaign/start-cloud', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(4 * 60 * 1000),
    });
    const txt = await res.text();
    let data; try { data = JSON.parse(txt); } catch { data = { error: txt }; }
    if (res.status === 409 && txt.includes('OPERATOR_EMAIL_REQUIRED')) {
      openOperatorEmailModal({ mandatory: true }); return;
    }
    if (!res.ok || data.error) {
      const why = String(data.error || txt).split('\n')[0];
      launchLog(`✗ Launch failed — ${why}`);
      // No native alert: it blocks the whole app, says nothing about what to do
      // next, and the card underneath it was being torn down anyway.
      failCloudLaunch(why, (data.diagnostic && data.diagnostic.fixes) || []);
      if (typeof showCampaignToast === 'function') showCampaignToast(`✗ ${why}`, 8000);
      return;
    }
    // The strip's last two steps: the sheet is read, and the campaign is now
    // the engine's. Without this the strip stayed on "reading your leads" while
    // the headline said the VM had already accepted it.
    // Cancelled while the server was working. The campaign now exists on the
    // engine, so the only honest thing is to stop it at once and say so.
    if (_cloudLaunch && _cloudLaunch.stopRequested) {
      launchLog(`☁︎ The campaign reached the VM before the cancel landed — stopping it now.`);
      let stopped = false;
      if (data.id) {
        try {
          const sr = await fetch(`/api/campaign/cloud/${encodeURIComponent(data.id)}/stop`, { method: 'POST' });
          stopped = sr.ok;
        } catch (_) { /* reported below */ }
      }
      launchLog(stopped
        ? '■ Cancelled — the campaign was stopped on the VM. No lead was sent.'
        : '⚠ Cancelled, but the VM did not confirm the stop — open the campaign and stop it by hand.');
      if (typeof showCampaignToast === 'function') {
        showCampaignToast(stopped
          ? 'Launch cancelled — the campaign reached the VM and was stopped straight away. Nothing was sent.'
          : 'Launch cancelled, but the VM did not confirm. Open the campaign and stop it by hand.', 9000);
      }
      if (!stopped) failCloudLaunch('The campaign reached the VM but the stop was not confirmed. Open it and stop it by hand.');
      return;
    }
    if (_cloudLaunch) _cloudLaunch.leadsRead = Number(data.leadsAdded) || 0;
    setCloudLaunchPhase('accepted');
    launchLog(`☁︎ Campaign accepted by the VM — ${data.leadsAdded || 0} lead(s) loaded`);
    // Draft consumed on launch, same as the local path.
    try {
      const draftId = getActiveDraftId();
      if (draftId) await fetch('/api/drafts/' + encodeURIComponent(draftId), { method: 'DELETE' }).catch(() => {});
      clearActiveDraft();
    } catch { /* non-fatal */ }
    // Scheduled on the VM: the engine holds it in 'scheduled' and wakes itself at
    // the chosen time. Nothing is live yet, so there's no live card to open —
    // land back on the dashboard where the campaign shows with its start time.
    if (data.scheduled) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast(`⏰ Scheduled on the VM for ${_fmtCloudStartAt(data.startAt)} — ${data.leadsAdded} lead(s) loaded. The laptop can stay shut.`, 7000);
      }
      if (typeof goDashboard === 'function') goDashboard();
      return;
    }
    if (typeof showCampaignToast === 'function') showCampaignToast(`☁︎ Cloud campaign started — ${data.leadsAdded} lead(s) dispatched. It keeps running in the cloud even if you close the app.`, 6000);
    // Parity with a local launch: drop straight onto the live status CAMPAIGN
    // card (card #2) for the new VM campaign. See feedback_two_live_status_cards.
    if (data.id) { try { await openCloudLive(data.id); } catch (_) { /* */ } }
  } catch (e) {
    launchLog(`✗ Launch stopped — ${e.name === 'TimeoutError' || e.name === 'AbortError' ? 'it did not finish within 4 minutes' : e.message}`);
    // Name the reason. A timeout here is not "could not reach the engine" — the
    // request may never have got past reading the sheet — and saying so sent
    // operators looking at the wrong thing.
    failCloudLaunch(e.name === 'TimeoutError' || e.name === 'AbortError'
      ? 'The launch did not finish within 4 minutes. It stalled before the VM was reached, and the usual causes are the Google Sheet or the GoLogin account list not answering.'
      : `Could not start the cloud campaign: ${e.message}`);
  } finally {
    _cloudSubmitInFlight = false;
    // A dispatch is the only moment the primary-recall list can change while
    // the app is open, so drop the cache and let the next keystroke refetch.
    try { if (typeof window.primaryRecallInvalidate === 'function') window.primaryRecallInvalidate(); } catch (_) { /* */ }
    // Runs on every exit path — success, cancel, and error — so the synthetic
    // strip/card can never outlive the launch and strand the board.
    endCloudLaunch();
  }
}

async function submitStartCampaign(body, opts = {}) {
  // Ortus Basics: cloud is disabled — never dispatch to the cloud engine.
  const _cloudDisabled = typeof isCloudRunOn === 'function' && !isCloudRunOn();
  // Cloud edit mode: the wizard is re-launching an EDITED (paused) cloud
  // campaign — divert the body to edit-redispatch instead of a fresh launch.
  if (!_cloudDisabled && _cloudEdit && _cloudEdit.paused) return _submitCloudEditRedispatch(body);
  // "Run in cloud" toggle → hand off to the engine and return; local path below
  // stays exactly as-is for normal (local) launches.
  if (!_cloudDisabled && opts.cloud) return _submitCloudCampaign(body);
  // v2.59.x — Add to Queue routes to /api/campaign/queue-only, which always
  // queues and never auto-drains. The regular Start path is unchanged: it
  // hits /api/campaign/start which fires immediately if idle, queues if a
  // campaign is already running.
  const url = opts.queueOnly ? '/api/campaign/queue-only' : '/api/campaign/start';
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const txt = await res.text();
      // v2.106.0 — mandatory operator-identity gate. Server 409s with this code
      // when this machine's operator email isn't set; show the modal, not a raw alert.
      if (res.status === 409 && txt.includes('OPERATOR_EMAIL_REQUIRED')) {
        openOperatorEmailModal({ mandatory: true });
        return;
      }
      // Pre-flight gate: findings changed between preflight and launch (race). Ask operator to retry.
      let _parsed409; try { _parsed409 = JSON.parse(txt); } catch { _parsed409 = {}; }
      if (res.status === 409 && _parsed409.preflight) {
        showCampaignToast('Lead sheet changed since pre-flight check — press Start again to re-run the check.', 8000);
        return;
      }
      if (_parsed409.launchRejected || res.status === 400) {
        let parsed; try { parsed = JSON.parse(txt); } catch { parsed = null; }
        if (parsed?.launchRejected && parsed.diagnostic) { showLaunchDiagnostic(parsed.diagnostic); return; }
      }
      alert(`Could not ${opts.queueOnly ? 'queue' : 'start'} campaign:\n\n${txt}`);
      return;
    }

    const data = await res.json();
    if (data.error) { alert(`Error: ${data.error}`); return; }
    if (!data.ok) { alert(data.message || `Could not ${opts.queueOnly ? 'queue' : 'start'} campaign.`); return; }

    // Whether the campaign starts now or gets queued, the draft has been
    // consumed. Drop it from the Drafts list and clear the active id.
    // Also clear the new-campaign flag — once Start is pressed, the live
    // status / log gates should stop blanking and show the running data.
    try {
      const draftId = getActiveDraftId();
      if (draftId) {
        await fetch('/api/drafts/' + encodeURIComponent(draftId), { method: 'DELETE' }).catch(() => {});
      }
      clearActiveDraft();
      localStorage.removeItem('wizardStoppedFromContext');
      // v2.71: if we entered via Edit pencil on a stopped past row, that
      // source row is now superseded by the freshly-launched resume — drop
      // it from history so the dashboard doesn't accumulate duplicates.
      // Matches resumeWithSameSettings's same-FIFO behaviour.
      try {
        const srcRaw = localStorage.getItem('editResumeSourceIdx');
        const srcIdx = srcRaw != null ? parseInt(srcRaw, 10) : NaN;
        if (Number.isInteger(srcIdx) && srcIdx >= 0) {
          await fetch('/api/history/delete-batch', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ indexes: [srcIdx] }),
          }).catch(() => {});
        }
        localStorage.removeItem('editResumeSourceIdx');
      } catch {}
      // Hide the edit-resume banner now that the resume has launched.
      const banner = document.getElementById('wizard-resume-banner');
      if (banner) banner.style.display = 'none';
    } catch {}
    wizardDirty = false;
    _runningEditWarningShown = false;

    // Server queued the campaign — either explicit queue-only, or because
    // another campaign was already running on the regular start path.
    if (data.queued) {
      alert(data.message || 'Added to queue.');
      if (typeof saveLastUsedPreset === 'function') saveLastUsedPreset();
      goDashboard();
      return;
    }
    setCampaignButtons(true);
    if (typeof saveLastUsedPreset === 'function') saveLastUsedPreset();
    // Post-launch tips modal — fires once per mode after a successful start.
    // Operator can tick "Don't show again" to silence per-mode.
    try { maybeShowPostLaunchTipsModal(body); } catch (err) { console.warn('[tips] modal failed:', err.message); }
    startPolling();
    // ⑤+①: signal an immediate LOCAL start so startCampaign keeps the launch
    // popup up until pollStatus sees the new run flip `running` true.
    return { started: true };
  } catch (e) {
    alert(`Network error starting campaign:\n\n${e.message}`);
  }
}

function closeLaunchDiagnostic() { document.getElementById('launch-diagnostic-modal')?.classList.add('hidden'); }
window.closeLaunchDiagnostic = closeLaunchDiagnostic;
function resolveLaunchDiagnostic(code) {
  closeLaunchDiagnostic();
  const target = code === 'accounts' ? 'nav-accounts' : 'nav-sheet';
  if (typeof scrollToSection === 'function') scrollToSection(target);
  if (code === 'sender') setTimeout(() => document.getElementById('ic-sender-col-select')?.focus(), 350);
  if (code === 'sheet') setTimeout(() => document.getElementById('sheet-url')?.focus(), 350);
  if (code === 'rows') window.openRunningSheet?.();
}
window.resolveLaunchDiagnostic = resolveLaunchDiagnostic;
function showLaunchDiagnostic(diagnostic = {}) {
  const modal = document.getElementById('launch-diagnostic-modal');
  const copy = document.getElementById('launch-diagnostic-copy');
  const actions = document.getElementById('launch-diagnostic-actions');
  if (!modal || !actions) return alert(diagnostic.message || 'Campaign not started.');
  if (copy) copy.textContent = `${diagnostic.message || 'Campaign not started.'} Nothing was sent.`;
  actions.replaceChildren(...(diagnostic.fixes || []).map((fix, index) => {
    const button = document.createElement('button');
    button.type = 'button'; button.className = index === 0 ? 'btn btn-start' : 'btn btn-secondary';
    button.textContent = fix.label; button.onclick = () => resolveLaunchDiagnostic(fix.code);
    return button;
  }));
  modal.classList.remove('hidden');
}

// ── v2.106.0 — Mandatory per-machine operator identity ──────────────────
// Every operator's app logs in with the SAME shared dashboard credential, so
// the login can't say who's actually operating. This email is the authoritative
// reserver stamped into the SoO 'CC User App' column, and is REQUIRED before any
// campaign can start (the server gates start/queue; this UI mirrors that).
let _operatorEmailMandatory = false;

async function initOperatorIdentity() {
  try {
    const r = await fetch('/api/operator-identity');
    const d = await r.json();
    // Populate the SHARED operator identity app-wide, not just the sidebar chip.
    // snCurrentEmail is what the campaigns board's `mine` and the Team panel's
    // "You" badge key off — previously it was loaded ONLY on the Sales Nav route
    // (loadOperatorEmail), so on the dashboard it was empty and "You" fell back
    // to the LOGIN email (ortus@) instead of the operator (e.g. antonio@).
    if (d && d.email) snCurrentEmail = d.email;
    _setOperatorChip(d && d.email);
    if (!d || !d.set) openOperatorEmailModal({ mandatory: true });
  } catch { /* offline — the server-side start gate still protects it */ }
}

function _setOperatorChip(email) {
  const el = document.getElementById('operator-chip-email');
  if (el) el.textContent = email || 'not set — click to set';
  const chip = document.getElementById('operator-chip');
  if (chip) chip.classList.toggle('operator-chip--unset', !email);
}

function openOperatorEmailModal(opts = {}) {
  _operatorEmailMandatory = !!opts.mandatory;
  const modal = document.getElementById('operator-email-modal');
  if (!modal) return;
  const cancel = document.getElementById('operator-email-cancel');
  if (cancel) cancel.style.display = _operatorEmailMandatory ? 'none' : '';
  const err = document.getElementById('operator-email-error');
  if (err) { err.hidden = true; err.textContent = ''; }
  const input = document.getElementById('operator-email-input');
  // Pre-fill with the current value when editing (non-mandatory re-open).
  if (input && !_operatorEmailMandatory) {
    const cur = document.getElementById('operator-chip-email');
    const v = cur ? cur.textContent.trim() : '';
    input.value = /@/.test(v) ? v : '';
  }
  modal.classList.remove('hidden');
  if (input) setTimeout(() => input.focus(), 50);
}

function closeOperatorEmailModal() {
  if (_operatorEmailMandatory) return; // can't dismiss the mandatory gate
  const modal = document.getElementById('operator-email-modal');
  if (modal) modal.classList.add('hidden');
}

async function saveOperatorEmail() {
  const input = document.getElementById('operator-email-input');
  const err = document.getElementById('operator-email-error');
  const email = ((input && input.value) || '').trim();
  const showErr = (m) => { if (err) { err.textContent = m; err.hidden = false; } };
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showErr('Enter a valid email address.'); return; }
  try {
    const r = await fetch('/api/operator-identity', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) { showErr((d && d.error) || 'Could not save — try again.'); return; }
    if (d.email) snCurrentEmail = d.email;   // keep the shared operator identity in sync (board `mine` + Team "You")
    _setOperatorChip(d.email);
    _operatorEmailMandatory = false;
    const modal = document.getElementById('operator-email-modal');
    if (modal) modal.classList.add('hidden');
    // Who you are decides which GoLogin workspaces you may drive, and the server
    // stamps that onto every tile as `available` at fetch time. Without this the
    // roster keeps the verdict computed for the PREVIOUS operator: change the
    // email to someone who owns Linked Velocity accounts and every one of them
    // still reads OTHER TEAM until the app is reloaded (2026-09-02).
    try { await loadProfiles(); } catch { /* the next refresh repaints it anyway */ }
  } catch {
    showErr('Network error — try again.');
  }
}

document.addEventListener('DOMContentLoaded', initOperatorIdentity);
window.openOperatorEmailModal = openOperatorEmailModal;
window.closeOperatorEmailModal = closeOperatorEmailModal;
window.saveOperatorEmail = saveOperatorEmail;

// ─────────────────────────────────────────────────────────────────────────
// Post-launch tips — modal (Variant A) + sidebar card (Variant B).
// Data + token substitution live in /js/post-launch-tips.mjs. This block
// handles UI lifecycle (show, dismiss, silence, sidebar render, collapse).
// ─────────────────────────────────────────────────────────────────────────

// Build the substitution context from the wizard body / cockpit / wizard
// inputs. Called at modal-show AND on every sidebar render so dynamic tokens
// stay in sync if the operator changes cadence mid-run (not currently
// possible, but the helper is cheap and future-proof).
function _ptmContextFromBody(body) {
  const tpl = body?.templates || {};
  return {
    dailyLimit: body?.dailyLimit ?? 50,
    delayMin: body?.delayMin ?? 10,
    delayMax: body?.delayMax ?? 20,
    checkIntervalMinutes: body?.checkIntervalMinutes ?? 60,
    primaryName: tpl.primaryName || tpl.introName || '',
  };
}
function _ptmContextFromCockpit() {
  // Sidebar reads from __cockpit (populated by pollStatus). Falls back to
  // wizard inputs when the field isn't on the server status payload.
  const tpl = (__cockpit && __cockpit.templates) || {};
  const cadenceFromWizard = parseInt(document.getElementById('check-cadence-select')?.value, 10);
  return {
    dailyLimit: 50, // server status doesn't surface dailyLimit; default fits CC tip
    delayMin: 10,
    delayMax: 20,
    checkIntervalMinutes: (__cockpit && __cockpit.checkIntervalMinutes)
      || (Number.isFinite(cadenceFromWizard) ? cadenceFromWizard : 60),
    primaryName: tpl.primaryName || document.getElementById('primary-person-name')?.value || '',
  };
}

function maybeShowPostLaunchTipsModal(body) {
  const mode = body?.mode || '';
  if (!mode) return;
  if (isTipsSilenced(mode)) return;
  const set = getTipsForMode(mode, _ptmContextFromBody(body));
  if (!set) return; // unknown mode — no tip data, no modal
  const modal = document.getElementById('post-launch-tips-modal');
  if (!modal) return;
  const titleEl = document.getElementById('ptm-title');
  const bodyEl  = document.getElementById('ptm-body');
  const silenceCheck = document.getElementById('ptm-silence-check');
  if (titleEl) titleEl.textContent = set.modalTitle;
  if (bodyEl)  bodyEl.innerHTML    = renderModalTipsHtml(mode, _ptmContextFromBody(body));
  if (silenceCheck) silenceCheck.checked = false;
  modal.dataset.mode = mode;
  modal.classList.remove('hidden');
  // Esc dismisses — bound for this lifetime only, removed on close.
  const escHandler = (ev) => { if (ev.key === 'Escape') dismissPostLaunchTipsModal(); };
  modal._escHandler = escHandler;
  document.addEventListener('keydown', escHandler);
}

function closePostLaunchTipsModal() {
  const modal = document.getElementById('post-launch-tips-modal');
  if (!modal) return;
  modal.classList.add('hidden');
  if (modal._escHandler) {
    document.removeEventListener('keydown', modal._escHandler);
    modal._escHandler = null;
  }
}

function dismissPostLaunchTipsModal() {
  const modal = document.getElementById('post-launch-tips-modal');
  const mode = modal?.dataset?.mode || '';
  const silence = !!document.getElementById('ptm-silence-check')?.checked;
  if (silence && mode) silenceTipsForMode(mode);
  closePostLaunchTipsModal();
}

// Sidebar tips card — rendered alongside the cockpit during running OR
// monitoring. Reads mode from __cockpit (server status). Hidden when idle.
function renderPostLaunchSidebar() {
  const card = document.getElementById('post-launch-tips-card');
  if (!card) return;
  const mode = (__cockpit && __cockpit.mode) || '';
  const isRunning = !!(__cockpit && __cockpit.running);
  const isMonitoring = !!(__cockpit && __cockpit.state === 'monitoring');
  // Hide when idle. The modal handled the first-time read; the sidebar is a
  // mid-run reference so operators don't need to remember tips later.
  if (!isRunning && !isMonitoring) { card.classList.add('hidden'); return; }
  const set = getTipsForMode(mode, _ptmContextFromCockpit());
  if (!set) { card.classList.add('hidden'); return; }
  const titleEl = document.getElementById('pts-title');
  const bodyEl  = document.getElementById('pts-body');
  if (titleEl) titleEl.textContent = set.sidebarTitle;
  if (bodyEl)  bodyEl.innerHTML    = renderSidebarTipsHtml(mode, _ptmContextFromCockpit());
  card.classList.remove('hidden');
}

function togglePostLaunchTipsCard() {
  const card = document.getElementById('post-launch-tips-card');
  if (!card) return;
  card.classList.toggle('collapsed');
}

// ─────────────────────────────────────────────────────────────────────────
// Onboarding tour — sidebar Help popover + inline-onclick handlers.
// Tour engine lives in /js/tour.mjs. This block wires the UI.
// ─────────────────────────────────────────────────────────────────────────

function toggleHelpPopover(ev) {
  if (ev) ev.stopPropagation();
  const pop = document.getElementById('help-popover');
  if (!pop) return;
  const isHidden = pop.classList.contains('hidden');
  // Refresh "Replay tour" visibility every open — flag may have just changed.
  const replay = document.getElementById('help-pop-replay');
  if (replay) replay.style.display = isTourCompleted() ? '' : 'none';
  pop.classList.toggle('hidden', !isHidden);
  // First open after toggling: bind a one-shot outside-click listener to dismiss.
  if (isHidden) {
    const outsideHandler = (e) => {
      const wrapper = pop.closest('.nav-help-wrapper');
      if (wrapper && !wrapper.contains(e.target)) {
        pop.classList.add('hidden');
        document.removeEventListener('click', outsideHandler);
      }
    };
    setTimeout(() => document.addEventListener('click', outsideHandler), 0);
  }
}

function _closeHelpPopover() {
  const pop = document.getElementById('help-popover');
  if (pop) pop.classList.add('hidden');
}

function onHelpTakeTour() { _closeHelpPopover(); startTour(); }
function onHelpReplayTour() { _closeHelpPopover(); replayTour(); }
function onTourNext() { tourNext(); }
function onTourBack() { tourBack(); }
function onTourSkip() { tourSkip(); }

async function stopCampaign() {
  // v2.59 resume: snapshot the running campaign's identity + totals BEFORE
  // sending the stop so the wizard's next Start can route as a resume
  // instead of spawning a fresh run. Stored by name (since stable ids
  // don't exist yet); wizard Start matches by name comparison.
  try {
    if (typeof __cockpit !== 'undefined' && __cockpit && (__cockpit.running || __cockpit.paused)) {
      const ctx = {
        name: (__cockpit.name || '').trim(),
        totalProcessed: Number(__cockpit.totalProcessed) || 0,
        savedAt: Date.now(),
      };
      if (ctx.name) localStorage.setItem('wizardStoppedFromContext', JSON.stringify(ctx));
    }
  } catch {}
  // 2.9.7: Check DMs is a separate flow with its own stop endpoint. Stop
  // both — only the running one will react, and double-stop is harmless.
  try { await fetch('/api/campaign/stop', { method: 'POST' }); } catch { /* */ }
  try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
}

// Phase 2.8.9: Stop confirmation modal — guards against accidental clicks.
// v2.14.x: for connect_and_introduce campaigns, route to the choice modal
// (stop-sending-keep-monitoring vs. stop-everything) instead of the simple
// yes/no modal. Other modes keep the original single-question modal.
function confirmStopCampaign() {
  // A launch still in flight is not a campaign yet — cancel THAT, not whatever
  // local campaign happens to be running.
  if (cancelCloudLaunch()) return;
  // Viewing a CLOUD campaign (wizard read-only Stop, runbar Stop, legacy
  // #btn-stop) → the choice belongs to the ENGINE, not the local cockpit.
  // Without this the VM campaign fell through to the local confirm modal
  // (__cockpit.mode is undefined for a cloud run) and never asked
  // "stop everything vs. keep monitoring". Same routing as dashStopActive.
  const cloudId = _activeCardCloudId();
  if (cloudId) { stopCloudCampaignUI(cloudId); return; }
  // v2.14.x: when the campaign is in monitoring state (sending finished,
  // watcher active), route to the dedicated stop-monitoring modal instead
  // of the running-campaign flow. Without this, the button was either
  // dead (the older disable rule) or would hit the wrong modal.
  if (__cockpit && !__cockpit.running && __cockpit.state === 'monitoring') {
    // v2.52.0: when a stop is already in flight, surface the same persistent
    // banner instead of letting the operator re-open the modal and fire a
    // racing second POST. The first call will finalize the sheet stamps in
    // a few seconds — the toast confirms work is happening.
    if (typeof _stoppingMonitoring !== 'undefined' && _stoppingMonitoring) {
      showCampaignToast('Still ending monitoring — hang tight, sheet stamping in progress…', 8000);
      return;
    }
    confirmStopMonitoringNow();
    return;
  }
  _stopChoiceTarget = { cloud: false, id: null };
  // A Stop click always cuts the current work. There is no second modal that
  // offers to keep working on the current person.
  confirmStopCampaignNow(true);
}

function closeStopModal() {
  const modal = document.getElementById('confirm-stop-modal');
  if (modal) modal.classList.add('hidden');
}

function closeStopChoiceModal() {
  const modal = document.getElementById('stop-choice-modal');
  if (modal) modal.classList.add('hidden');
  _stopChoiceTarget = { cloud: false, id: null }; // don't leak into a later stop
}
window.closeStopChoiceModal = closeStopChoiceModal;

// v2.14.x: Stop-monitoring modal helpers. Mirrors the stop-choice modal
// pattern so the in-app monochrome aesthetic stays consistent. The
// existing monitoringStop() in app.js:~6160 used a native browser
// confirm() — replaced by this modal when the operator hits the bottom-
// bar Stop button during monitoring.
function closeStopMonitoringModal() {
  const modal = document.getElementById('confirm-stop-monitoring-modal');
  if (modal) modal.classList.add('hidden');
}
window.closeStopMonitoringModal = closeStopMonitoringModal;

// v2.52.0 — client-side flag set true while /api/monitoring/stop is in
// flight. Suppresses re-opening the stop-monitoring modal during the
// 5–10s sheet-stamp window (so impatient operators can't fire a second
// POST and see the misleading 'not in monitoring state' alert). Cleared
// when the response lands OR after a 30s safety timeout.
let _stoppingMonitoring = false;
let _stoppingMonitoringStartedAt = 0;

async function confirmStopMonitoringNow() {
  closeStopMonitoringModal();
  if (_stoppingMonitoring) return; // already in flight — no-op
  _stoppingMonitoring = true;
  _stoppingMonitoringStartedAt = Date.now();
  // Persistent banner via the existing campaign toast — 30s duration covers
  // the worst-case sheet-stamp time. Cleared early when the fetch resolves.
  showCampaignToast('Ending monitoring — finalizing the sheet (this can take 5–10 s)…', 30000);
  try {
    const res = await fetch('/api/monitoring/stop', { method: 'POST' }).then((r) => r.json());
    if (res.ok) {
      // v2.52.0: optimistic state flip. Server confirms state='done' on
      // any ok=true response — push it into __cockpit immediately so the
      // cockpit panel stops rendering MONITORING / WATCHING FOR ACCEPTANCES
      // without waiting up to 2s for the next pollStatus tick. Then force
      // a poll so monitoringUntil/nextCheckAt clear too. The overlay fires
      // from updateCockpit's monitoring→done transition detector.
      if (typeof __cockpit !== 'undefined') {
        __cockpit.state = 'done';
        __cockpit.monitoringCheckInProgress = false;
        if (typeof renderCockpit === 'function') renderCockpit();
      }
      if (typeof pollStatus === 'function') pollStatus().catch(() => {});

      // alreadyStopped → operator double-clicked; first call already did the work.
      const msg = res.alreadyStopped
        ? 'Monitoring already ended.'
        : 'Monitoring ended. Still-pending leads kept as "Connection Request Sent".';
      showCampaignToast(msg, 6000);
      if (typeof refreshDashboardSchedules === 'function') refreshDashboardSchedules();
    } else {
      alert('Stop failed: ' + (res.error || 'unknown'));
    }
  } catch (err) {
    alert('Stop failed: ' + err.message);
  } finally {
    _stoppingMonitoring = false;
  }
}
window.confirmStopMonitoringNow = confirmStopMonitoringNow;

async function confirmStopCampaignNow(immediate = false) {
  closeStopModal();
  immediate = true;
  const target = _stopChoiceTarget;
  showCampaignToast('Stopping now — if the result is uncertain, the strip will tell you exactly what to check.', 15000);
  if (target.cloud && target.id) await _doStopCloud(target.id, { immediate });
  else {
    try { await fetch('/api/campaign/stop', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ full: true, immediate }) }); } catch { /* status polling surfaces recovery */ }
    try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
  }
}

// v2.14.x: "Stop sending, keep monitoring" — CC+IC only. Fires the
// existing /api/campaign/stop with no body, which preserves the post-
// campaign bulk-check + auto-intro monitoring path (campaign.js falls
// through to end-of-list bulk-check + transitionToMonitoring as it would
// at natural end-of-list).
async function stopAndKeepMonitoring() {
  const target = _stopChoiceTarget; // capture before close resets it
  closeStopChoiceModal();
  _soloCheckHandler = (scope) => _finishStopAndKeepMonitoring(target, scope);
  const modal = document.getElementById('solo-check-modal');
  if (modal) {
    const eyebrow = modal.querySelector('.stop-choice-eyebrow');
    const title = modal.querySelector('.stop-choice-headline');
    const sub = modal.querySelector('.stop-choice-sub');
    if (eyebrow) eyebrow.textContent = 'Stop sending · keep monitoring';
    if (title) title.textContent = 'Who should monitoring check?';
    if (sub) sub.textContent = 'This scope belongs to this sheet tab only. It never pulls senders from another tab.';
  }
  _showSoloCheckModal();
}

async function _finishStopAndKeepMonitoring(target, scope) {
  if (target.cloud && target.id) {
    const chooseMachine = async (where) => {
      const stopped = await _doStopCloud(target.id, { keepMonitoring: true, scope, immediate: true });
      if (!stopped) return;
      if (where === 'local') {
        await window.campaignHandover(target.id, 'local', null, 'monitoring');
      } else {
        await cloudCheckNow(String(target.id), null, scope);
      }
    };
    const whereModal = document.getElementById('check-where-modal');
    if (!whereModal) {
      // An older cached shell must still complete safely. Keep monitoring on
      // the current VM rather than silently doing nothing after scope choice.
      await chooseMachine('vm');
      return;
    }
    _checkWhereHandler = chooseMachine;
    const eyebrow = whereModal.querySelector('.stop-choice-eyebrow');
    const title = whereModal.querySelector('.stop-choice-headline');
    const sub = whereModal.querySelector('.stop-choice-sub');
    const pills = whereModal.querySelectorAll('.stop-choice-pill');
    if (eyebrow) eyebrow.textContent = 'Stop sending · keep monitoring';
    if (title) title.textContent = 'Where should monitoring run?';
    if (sub) sub.textContent = 'The selected machine checks connections and sends introduction messages. It starts one check immediately.';
    if (pills[0]) {
      const head = pills[0].querySelector('.stop-choice-pill-headline');
      const detail = pills[0].querySelector('.stop-choice-pill-sub');
      if (head) head.textContent = 'Cloud VM';
      if (detail) detail.textContent = 'Checks and introductions continue in the cloud. You can close the app.';
    }
    if (pills[1]) {
      const head = pills[1].querySelector('.stop-choice-pill-headline');
      const detail = pills[1].querySelector('.stop-choice-pill-sub');
      if (head) head.textContent = 'This Mac';
      if (detail) detail.textContent = 'Moves monitoring here and checks immediately. Keep the app open.';
    }
    _showCheckWhereModal();
    return;
  }
  showCampaignToast(`Stopping new sends — monitoring ${scope === 'sheet' ? 'all senders in this tab' : 'this campaign’s accounts'} for 7 days.`, 6000);
  try {
    await fetch('/api/campaign/stop', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ full: false, monitoringScope: scope === 'sheet' ? 'tab' : 'campaign', immediate: true }),
    });
  } catch { /* */ }
  try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
}
window.stopAndKeepMonitoring = stopAndKeepMonitoring;
window.closePostLaunchTipsModal   = closePostLaunchTipsModal;
window.dismissPostLaunchTipsModal = dismissPostLaunchTipsModal;
window.togglePostLaunchTipsCard   = togglePostLaunchTipsCard;
window.toggleHelpPopover          = toggleHelpPopover;
window.onHelpTakeTour             = onHelpTakeTour;
