function v3Ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

function v3FormatScheduledAt(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const now = Date.now();
  const ms = d.getTime() - now;
  if (ms < 60 * 1000) return 'starting…';
  if (ms < 24 * 3600 * 1000) {
    const hours = Math.round(ms / 3600 / 1000);
    return hours <= 0 ? 'soon' : `in ${hours}h`;
  }
  const days = Math.round(ms / 86400 / 1000);
  if (days === 1) return `tomorrow ${v3FmtClock(d)}`;
  return `in ${days}d`;
}

function v3BuildQueueDock(q, isScheduled) {
  const dockId = 'dock-queue-' + (q.id || Math.random().toString(36).slice(2));
  const safeId = (typeof escHtml === 'function' ? escHtml(q.id || '') : (q.id || ''));
  const safeName = (typeof escHtml === 'function' ? escHtml(q.name || '') : (q.name || ''));
  const primaryTip = isScheduled ? 'Reschedule' : 'Start now';
  const primarySvg = isScheduled ? V3_SVG_CAL : V3_SVG_PLAY;
  const primaryFn = isScheduled ? 'dashRescheduleQueueItem' : 'dashStartQueueItem';
  const otherTip = isScheduled ? 'Start now' : 'Reschedule';
  const otherSvg = isScheduled ? V3_SVG_PLAY : V3_SVG_CAL;
  const otherFn = isScheduled ? 'dashStartQueueItem' : 'dashRescheduleQueueItem';
  return `
    <div class="dock" id="${dockId}" role="toolbar" aria-label="${safeName} actions">
      <button class="dock-btn" data-tip="${primaryTip}" aria-label="${primaryTip}" onclick="window.${primaryFn}('${safeId}')">${primarySvg}</button>
      <div class="dock-actions">
        <button class="dock-btn" data-tip="${otherTip}" aria-label="${otherTip}" onclick="window.${otherFn}('${safeId}')">${otherSvg}</button>
        <button class="dock-btn" data-tip="Edit" aria-label="Edit" onclick="window.dashEditQueueItem('${safeId}')">${V3_SVG_PENCIL}</button>
        <button class="dock-btn" data-tip="Duplicate" aria-label="Duplicate" onclick="window.dashDuplicateQueueItem('${safeId}')">${V3_SVG_COPY}</button>
        <button class="dock-btn danger" data-tip="Remove" aria-label="Remove" onclick="window.dashRemoveQueueItem('${safeId}')">${V3_SVG_TRASH}</button>
      </div>
    </div>
  `;
}

window.renderUpNextDeck = async function() {
  const list = document.getElementById('queueList');
  if (!list) return;
  let queue = [];
  try {
    const r = await fetch('/api/queue');
    const data = await r.json();
    queue = Array.isArray(data?.queue) ? data.queue : [];
  } catch (err) {
    console.error('[v3] renderUpNextDeck fetch:', err);
  }
  v3SetText('queueCount', String(queue.length));
  // Bug 13: "Clear all" only when there's something to clear.
  const clearBtn = document.getElementById('queue-clear-btn');
  if (clearBtn) clearBtn.hidden = queue.length === 0;

  if (queue.length === 0) {
    list.innerHTML = '<div class="vc-empty" style="padding:24px;color:var(--gray);font-size:13px">No queued campaigns.</div>';
    return;
  }

  const safe = (s) => (typeof escHtml === 'function' ? escHtml(s) : String(s || ''));

  const parts = ['<div class="vc-stack">'];
  queue.forEach((q, idx) => {
    const id = safe(q.id || '');
    const name = safe(q.name || '(unnamed)');
    const badge = v3ModeBadge(q.mode);
    const modeLabel = safe((typeof dashboardModeLabel === 'function' ? dashboardModeLabel(q.mode) : q.mode) || '');
    const accountCount = (q.profileIds || []).length;
    const isScheduled = !!q.scheduledAt;
    const whenText = isScheduled ? v3FormatScheduledAt(q.scheduledAt) : '';
    const eyebrowText = isScheduled
      ? `Scheduled · ${whenText}`
      : (idx === 0 ? 'Queued · Next up' : `Queued · ${v3Ordinal(idx + 1)}`);
    const dockHtml = v3BuildQueueDock(q, isScheduled);

    if (idx === 0) {
      // Showcase card — top of deck
      const queuedAt = q.queuedAt ? safe((typeof _humanAgo === 'function' ? _humanAgo(new Date(q.queuedAt).getTime()) : q.queuedAt)) : '';
      const sheetLabel = q.sheetUrl ? safe((q.sheetUrl.match(/#gid=\d+/) ? (q.sheetUrl.split('/').slice(-1)[0] || q.sheetUrl) : q.sheetUrl).slice(0, 60)) : '—';
      parts.push(`
        <div class="vc-card-top${isScheduled ? ' is-scheduled' : ''}" data-queue-id="${id}" draggable="true">
          <div class="vc-handle" aria-label="Drag to reorder" title="Drag to reorder"></div>
          <div class="vc-top-glyph">${safe(badge)}</div>
          <div class="vc-top-body">
            <div class="vc-top-eyebrow${isScheduled ? ' is-scheduled' : ''}">
              <span class="dot"></span>${safe(eyebrowText)}
            </div>
            <div class="vc-top-name">${name}</div>
            <div class="vc-top-preview-dense">
              <div class="row"><span class="k">Mode</span><span class="v"><b>${safe(badge)}</b> · ${modeLabel}</span></div>
              <div class="row"><span class="k">Sheet</span><span class="v">${sheetLabel}</span></div>
              <div class="row"><span class="k">Accounts</span><span class="v"><b>${accountCount}</b></span></div>
              ${queuedAt ? `<div class="row"><span class="k">Queued</span><span class="v">${queuedAt}</span></div>` : ''}
            </div>
          </div>
          ${dockHtml}
        </div>
      `);
    } else {
      const depth = idx === 1 ? 'depth-2' : 'depth-3';
      const whenHtml = isScheduled
        ? `${V3_SVG_CLOCK_INLINE}<b>${safe(whenText)}</b>`
        : `Queued · ${v3Ordinal(idx + 1)}`;
      parts.push(`
        <div class="vc-mini ${depth}${isScheduled ? ' is-scheduled' : ''}" data-queue-id="${id}" draggable="true">
          <div class="vc-handle" aria-label="Drag to reorder" title="Drag to reorder"></div>
          <div class="vc-mini-glyph">${safe(badge)}</div>
          <div class="vc-mini-name">${name}</div>
          <div class="vc-mini-when">${whenHtml}</div>
          ${dockHtml}
        </div>
      `);
    }
  });
  parts.push('</div>');
  list.innerHTML = parts.join('');

  v3EnableQueueDnD();
};

function v3EnableQueueDnD() {
  const rows = document.querySelectorAll('#queueList [data-queue-id]');
  let dragId = null;
  rows.forEach(row => {
    row.addEventListener('dragstart', (e) => {
      dragId = row.getAttribute('data-queue-id');
      row.classList.add('is-dragging');
      try { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', dragId || ''); } catch {}
    });
    row.addEventListener('dragover', (e) => {
      e.preventDefault();
      try { e.dataTransfer.dropEffect = 'move'; } catch {}
    });
    row.addEventListener('dragend', () => {
      row.classList.remove('is-dragging');
    });
    row.addEventListener('drop', async (e) => {
      e.preventDefault();
      const dropId = row.getAttribute('data-queue-id');
      if (!dragId || dropId === dragId) { dragId = null; return; }
      // Compute the new ordering: pull dragId out, insert before dropId.
      const allRows = Array.from(document.querySelectorAll('#queueList [data-queue-id]'));
      const ids = allRows.map(r => r.getAttribute('data-queue-id')).filter(Boolean);
      const fromIdx = ids.indexOf(dragId);
      if (fromIdx === -1) { dragId = null; return; }
      ids.splice(fromIdx, 1);
      const toIdx = ids.indexOf(dropId);
      if (toIdx === -1) ids.push(dragId);
      else ids.splice(toIdx, 0, dragId);
      dragId = null;
      try {
        const r = await fetch('/api/queue/reorder', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ids }),
        });
        if (!r.ok) {
          const body = await r.json().catch(() => ({}));
          if (typeof showCampaignToast === 'function') showCampaignToast('Reorder failed: ' + (body.error || r.statusText));
        }
      } catch (err) {
        console.error('[v3] queue reorder:', err);
      }
      if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
    });
  });
}

window.dashStartQueueItem = async function(id) {
  try {
    const r = await fetch('/api/queue');
    const data = await r.json();
    const queue = Array.isArray(data?.queue) ? data.queue : [];
    const ids = queue.map(q => q.id);
    const fromIdx = ids.indexOf(id);
    if (fromIdx === -1) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Queue item not found');
      return;
    }
    if (fromIdx > 0) {
      ids.splice(fromIdx, 1);
      ids.unshift(id);
      await fetch('/api/queue/reorder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids }),
      });
    }
    const launchR = await fetch('/api/queue/run-next', { method: 'POST' });
    const body = await launchR.json().catch(() => ({}));
    if (launchR.ok && body.ok) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Started ' + (queue[fromIdx]?.name || ''));
    } else {
      if (typeof showCampaignToast === 'function') showCampaignToast('Cannot start: ' + (body.message || body.reason || body.error || 'busy'));
    }
    if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
  } catch (err) { console.error('[v3] dashStartQueueItem:', err); }
};

window.dashRescheduleQueueItem = async function(id) {
  let when;
  if (typeof promptModal === 'function') {
    when = await promptModal({ label: 'Reschedule to ISO timestamp (e.g. 2026-05-28T10:00:00Z):' });
  } else {
    when = window.prompt('Reschedule to ISO timestamp (e.g. 2026-05-28T10:00:00Z):');
  }
  if (!when) return;
  try {
    const r = await fetch('/api/queue/' + encodeURIComponent(id), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scheduledAt: when }),
    });
    if (r.ok) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Rescheduled');
    } else {
      const body = await r.json().catch(() => ({}));
      if (typeof showCampaignToast === 'function') showCampaignToast('Reschedule failed: ' + (body.error || r.statusText));
    }
    if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
  } catch (err) { console.error('[v3] dashRescheduleQueueItem:', err); }
};

window.dashEditQueueItem = async function(id) {
  try {
    const r = await fetch('/api/queue/' + encodeURIComponent(id));
    const entry = await r.json();
    if (!entry || !entry.config) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Queue entry not found');
      return;
    }
    // Open the wizard. The existing applyPresetConfig path is the cleanest
    // hydrate hook — used by editPastCampaign as well.
    if (typeof applyPresetConfig === 'function') {
      applyPresetConfig({ name: entry.name, ...entry.config });
    }
    if (typeof goCreateCampaign === 'function') goCreateCampaign();
    else window.location.hash = '#/new';
  } catch (err) { console.error('[v3] dashEditQueueItem:', err); }
};

window.dashDuplicateQueueItem = async function(id) {
  try {
    const r = await fetch('/api/queue/' + encodeURIComponent(id));
    const entry = await r.json();
    if (!entry || !entry.config) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Queue entry not found');
      return;
    }
    await fetch('/api/campaign/queue-only', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...entry.config, name: (entry.name || 'Campaign') + ' (copy)' }),
    });
    if (typeof showCampaignToast === 'function') showCampaignToast('Duplicated');
    if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
  } catch (err) { console.error('[v3] dashDuplicateQueueItem:', err); }
};

window.dashRemoveQueueItem = async function(id) {
  if (!confirm('Remove from queue?')) return;
  try {
    await fetch('/api/queue/' + encodeURIComponent(id), { method: 'DELETE' });
    if (typeof showCampaignToast === 'function') showCampaignToast('Removed');
    if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
  } catch (err) { console.error('[v3] dashRemoveQueueItem:', err); }
};

// ─────────────────────────────────────────────────────────────────────────────
// v3 dashboard — Calendar grid (This Week)
// Builds a Monday→Sunday grid for the visible week. Today is highlighted.
// Chips: running campaign (today), monitoring sweep (nextCheckAt's day),
// scheduled cron entries (simple 5-field parser; non-trivial expressions skip
// with console.warn). Week navigation via _v3CalWeekOffset.
// ─────────────────────────────────────────────────────────────────────────────
let _v3CalWeekOffset = 0; // 0 = current week, +1 = next, -1 = prev

window.renderCalendarGrid = async function() {
  const grid = document.getElementById('calGrid');
  if (!grid) return;

  const today = new Date();
  const monday = v3StartOfWeek(today, _v3CalWeekOffset);
  const range = document.getElementById('calRange');
  if (range) range.textContent = v3FormatWeekRange(monday);

  let schedules = [];
  let status = {};
  try {
    const [sr, str] = await Promise.all([
      fetch('/api/schedules'),
      fetch('/api/campaign/status'),
    ]);
    if (sr.ok) {
      const sBody = await sr.json();
      schedules = Array.isArray(sBody) ? sBody : (sBody && sBody.schedules) || [];
    }
    if (str.ok) status = await str.json();
  } catch (err) {
    console.error('[v3] renderCalendarGrid fetch:', err);
  }

  // Build 7 day cells (Monday → Sunday)
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = v3AddDays(monday, i);
    days.push({ date: d, isToday: v3SameDay(d, today), chips: [] });
  }

  // Running campaign chip on today (only if we're viewing the current week)
  if (status && status.running && _v3CalWeekOffset === 0) {
    const todayCell = days.find(x => x.isToday);
    if (todayCell) {
      todayCell.chips.push({
        mode: v3ModeBadge(status.mode),
        name: status.name || '',
        running: true,
        kind: 'running',
      });
    }
  }

  // Monitoring next-sweep chip on nextCheckAt's day
  if (status && status.state === 'monitoring' && status.nextCheckAt) {
    try {
      const next = new Date(status.nextCheckAt);
      const cell = days.find(x => v3SameDay(x.date, next));
      if (cell) {
        cell.chips.push({
          mode: 'SW',
          name: 'Sweep · ' + (status.name || ''),
          time: v3FormatTime(next),
          faded: false,
          kind: 'sweep',
        });
      }
    } catch (err) { /* ignore malformed nextCheckAt */ }
  }

  // Scheduled cron entries — only fires within visible week
  const weekEnd = v3AddDays(monday, 7);
  for (const sched of schedules) {
    if (!sched || sched.enabled === false) continue;
    try {
      const fireDates = v3ExpandSimpleCronInRange(sched.cron, monday, weekEnd);
      for (const fd of fireDates) {
        const cell = days.find(x => v3SameDay(x.date, fd));
        if (cell) {
          cell.chips.push({
            mode: v3ModeBadge(sched.mode),
            name: sched.name || 'Scheduled',
            time: v3FormatTime(fd),
            faded: true,
            kind: 'scheduled',
            scheduleId: sched.id,
          });
        }
      }
    } catch (err) {
      console.warn('[v3] calendar cron parse skipped:', sched && sched.cron, err && err.message);
    }
  }

  // Render cells
  grid.innerHTML = '';
  const dowLabels = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT', 'SUN'];
  days.forEach((day, idx) => {
    const cell = document.createElement('div');
    cell.className = 'cal-cell' + (day.isToday ? ' today' : '');
    cell.dataset.calDate = day.date.toISOString().slice(0, 10);
    if (!day.isToday) cell.addEventListener('click', () => window.dashCalDayClick(cell));

    const head = '<div class="cal-head"><div class="cal-dow">' + dowLabels[idx] + '</div><div class="cal-date">' + day.date.getDate() + '</div></div>';
    const chipsHtml = day.chips.slice(0, 3).map(c => v3CalChipHtml(c)).join('');
    const moreHtml = day.chips.length > 3
      ? '<div class="cal-more" style="margin-top:6px;font-family:var(--mono);font-size:0.56rem;color:var(--gray);">+ ' + (day.chips.length - 3) + ' more</div>'
      : '';
    const hint = day.isToday ? '' : '<div class="cal-hint">+ Schedule</div>';
    cell.innerHTML = head + chipsHtml + moreHtml + hint;
    grid.append(cell);
  });
};

function v3CalChipHtml(c) {
  const safe = (s) => (typeof escHtml === 'function' ? escHtml(s) : String(s == null ? '' : s));
  const cls = 'cal-chip' + (c.running ? ' running' : '') + (c.faded ? ' faded' : '');
  const time = c.time ? '<span class="time">' + safe(c.time) + '</span>' : '';
  return '<div class="' + cls + '" data-chip-kind="' + safe(c.kind || '') + '" data-chip-name="' + safe(c.name) + '" onclick="window.dashCalChipClick(this, event)"><span class="badge">' + safe(c.mode) + '</span>' + time + '<span class="name">' + safe(c.name) + '</span></div>';
}

// Date helpers — Monday-based start of week
function v3StartOfWeek(d, weekOffset) {
  const base = new Date(d);
  const day = base.getDay(); // 0=Sun … 6=Sat
  const diff = (day === 0 ? -6 : 1 - day); // shift back to Monday
  base.setDate(base.getDate() + diff + ((weekOffset || 0) * 7));
  base.setHours(0, 0, 0, 0);
  return base;
}
function v3SameDay(a, b) {
  return a.getFullYear() === b.getFullYear()
    && a.getMonth() === b.getMonth()
    && a.getDate() === b.getDate();
}
function v3AddDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}
function v3FormatTime(d) {
  return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}
function v3FormatWeekRange(monday) {
  const sunday = v3AddDays(monday, 6);
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  if (monday.getMonth() === sunday.getMonth()) {
    return monday.getDate() + ' — ' + sunday.getDate() + ' ' + months[sunday.getMonth()];
  }
  return monday.getDate() + ' ' + months[monday.getMonth()] + ' — ' + sunday.getDate() + ' ' + months[sunday.getMonth()];
}

// Simple cron expander — "M H D M W" with literal numbers or "*".
// Skips comma lists, ranges, /steps with a console.warn (called by renderer).
function v3ExpandSimpleCronInRange(cronExpr, start, end) {
  if (!cronExpr || typeof cronExpr !== 'string') return [];
  const parts = cronExpr.trim().split(/\s+/);
  if (parts.length !== 5) { console.warn('[v3] cron not 5-field, skipping:', cronExpr); return []; }
  const [mP, hP, domP, monP, dowP] = parts;
  const isSimple = (p) => p === '*' || /^\d+$/.test(p);
  if (![mP, hP, domP, monP, dowP].every(isSimple)) { console.warn('[v3] cron has non-simple parts, skipping:', cronExpr); return []; }
  const minute = mP === '*' ? null : parseInt(mP, 10);
  const hour = hP === '*' ? null : parseInt(hP, 10);
  const dom = domP === '*' ? null : parseInt(domP, 10);
  const mon = monP === '*' ? null : parseInt(monP, 10);
  const dow = dowP === '*' ? null : parseInt(dowP, 10); // 0=Sun, 6=Sat
  const dates = [];
  const cursor = new Date(start);
  while (cursor < end) {
    if ((dom === null || cursor.getDate() === dom)
      && (mon === null || (cursor.getMonth() + 1) === mon)
      && (dow === null || cursor.getDay() === dow)) {
      const fire = new Date(cursor);
      if (hour !== null) fire.setHours(hour);
      if (minute !== null) fire.setMinutes(minute);
      fire.setSeconds(0);
      fire.setMilliseconds(0);
      if (fire >= start && fire < end) dates.push(fire);
    }
    cursor.setDate(cursor.getDate() + 1);
  }
  return dates;
}

window.dashCalPrev = function() { _v3CalWeekOffset--; window.renderCalendarGrid(); };
window.dashCalNext = function() { _v3CalWeekOffset++; window.renderCalendarGrid(); };
window.dashCalToday = function() { _v3CalWeekOffset = 0; window.renderCalendarGrid(); };

window.dashCalDayClick = function(cell) {
  const d = cell && cell.dataset && cell.dataset.calDate;
  if (typeof showCampaignToast === 'function') showCampaignToast('Schedule on ' + (d || 'day') + ' — open wizard');
  if (typeof window.startNewCampaign === 'function') window.startNewCampaign();
};

window.dashCalChipClick = function(chip, event) {
  if (event && event.stopPropagation) event.stopPropagation();
  const kind = (chip && chip.dataset && chip.dataset.chipKind) || '';
  if (kind === 'running') {
    const active = document.getElementById('active-card');
    if (active && active.scrollIntoView) active.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } else if (kind === 'sweep') {
    const monSect = document.getElementById('monitoring-section');
    if (monSect && monSect.scrollIntoView) monSect.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } else {
    if (typeof window.startNewCampaign === 'function') window.startNewCampaign();
  }
};

/* ── Past section ───────────────────────────────────────────────────────── */

let _v3PastEntries = []; // cached for handlers (display order: newest-first)

window.renderPastSection = async function() {
  const collapsedEl = document.getElementById('pastCollapsed');
  const listEl = document.getElementById('pastList');
  const countEl = document.getElementById('pastCount');
  if (!collapsedEl || !listEl) return;

  let all = [];
  try {
    // Fetch the full history (including archived rows) so onDiskIdx aligns
    // with history.json's actual indexing — server-side filtering would
    // make the per-row idx point to a different (possibly already-archived)
    // record, which is the "delete does nothing" bug. Archived rows are
    // filtered out below AFTER the on-disk idx is recorded.
    const r = await fetch('/api/history');
    if (r.ok) all = await r.json();
  } catch (err) {
    console.error('[v3] renderPastSection fetch:', err);
  }
  if (!Array.isArray(all)) all = [];

  // Display newest-first. Record each entry's actual on-disk idx FIRST,
  // then drop archived rows. /api/history/:idx/{archive,relaunch,log}
  // operate by on-disk index — getting this wrong silently mutates the
  // wrong record.
  _v3PastEntries = all.map((entry, onDiskIdx) => ({ ...entry, _originalIdx: onDiskIdx }))
                      .filter((entry) => !entry.archived)
                      .slice().reverse();

  if (countEl) countEl.textContent = String(_v3PastEntries.length);

  // Collapsed summary (default state)
  const pcCount = document.getElementById('pcCount');
  const pcSummary = document.getElementById('pcSummary');
  if (_v3PastEntries.length === 0) {
    if (pcCount) pcCount.innerHTML = '0<span class="pc-lbl">past</span>';
    if (pcSummary) pcSummary.innerHTML = 'no finished campaigns yet';
  } else {
    const latest = _v3PastEntries[0];
    const ago = (typeof _humanAgo === 'function' && latest.date) ? _humanAgo(new Date(latest.date).getTime()) : '';
    const isStopped = (latest.endReason === 'stopped' || latest.fullStop);
    let rate;
    if (isStopped) {
      rate = '<b>stopped early</b>';
    } else if (latest.totalProcessed && latest.totalProcessed > 0) {
      const r = ((latest.successCount || 0) / latest.totalProcessed) * 100;
      rate = '<b>' + r.toFixed(1) + '%</b> success rate';
    } else {
      rate = '<b>—</b>';
    }
    const safe = (typeof escHtml === 'function') ? escHtml : (s) => String(s || '');
    if (pcCount) pcCount.innerHTML = _v3PastEntries.length + '<span class="pc-lbl">past</span>';
    if (pcSummary) pcSummary.innerHTML = 'last finished <b>' + safe(latest.name || '') + '</b> · ' + safe(ago) + ' · ' + rate;
  }

  // Expanded list (rendered always; visibility toggled by togglePastExpanded)
  const safe = (typeof escHtml === 'function') ? escHtml : (s) => String(s || '');
  const rows = _v3PastEntries.map((p, displayIdx) => v3RenderPastRow(p, displayIdx, safe)).join('');
  listEl.innerHTML = '<div class="pa-list">' + rows + '</div>';
  // Bug 13: reflect manage ("Select") mode + refresh the bulk-delete bar.
  listEl.classList.toggle('is-managing', pastManageMode);
  _v3UpdatePastBulkBar();
};

// ─────────────────────────────────────────────────────────────────────────
// Resume-draft badge — variant F (2026-05-27 drafts-isolation v2). Small
// gold count on the New-campaign button. Click badge → resume the draft.
// Visible only when getActiveDraftId() points at a draft that still
// exists server-side. Kept the name `renderResumeDraftPill` so existing
// call sites keep working; aliased as renderResumeDraftBadge too.
// ─────────────────────────────────────────────────────────────────────────
window.renderResumeDraftPill = async function() {
  const badge = document.getElementById('resume-draft-badge');
  const nameEl = document.getElementById('resume-draft-name');
  if (!badge) return;
  const id = getActiveDraftId();
  if (!id) { badge.style.display = 'none'; return; }
  try {
    const r = await fetch('/api/drafts/' + encodeURIComponent(id));
    if (!r.ok) {
      if (r.status === 404) clearActiveDraft();
      badge.style.display = 'none';
      return;
    }
    const draft = await r.json();
    const nm = (draft && draft.name ? String(draft.name) : '').trim() || 'Untitled draft';
    if (nameEl) nameEl.textContent = nm.slice(0, 32);
    badge.setAttribute('data-tip', `Resume draft — ${nm}`);
    badge.style.display = 'inline-flex';
  } catch (err) {
    console.warn('[drafts] resume-badge fetch:', err);
    badge.style.display = 'none';
  }
};
window.renderResumeDraftBadge = window.renderResumeDraftPill;

window.dashResumeDraft = function() {
  const id = getActiveDraftId();
  if (!id) return;
  // editDraft already navigates via goCreateCampaign() and hydrates the
  // form. Call it directly so the hash change + draft load happen in
  // sequence (router would also fire updateEditingBanner via applyRoute).
  if (typeof editDraft === 'function') editDraft(id);
  else window.location.hash = '#/new';
};

// Delete the active draft from the dashboard resume-pill. Same call as the
// drafts-list delete, just rooted at the pill so the operator doesn't need
// to navigate anywhere to throw away an unfinished draft.
window.dashDeleteDraftFromPill = async function() {
  const id = getActiveDraftId();
  if (!id) return;
  // Pull the name for the confirm prompt — falls back to the pill text if
  // the network call fails.
  let name = '';
  try {
    const r = await fetch('/api/drafts/' + encodeURIComponent(id));
    if (r.ok) {
      const d = await r.json();
      name = d?.name || '';
    }
  } catch {}
  if (!name) name = document.getElementById('resume-draft-name')?.textContent?.trim() || 'this draft';
  if (!confirm(`Delete draft "${name}"? This can't be undone.`)) return;
  try {
    await fetch('/api/drafts/' + encodeURIComponent(id), { method: 'DELETE' });
  } catch (err) {
    console.warn('[drafts] delete from pill:', err);
  }
  clearActiveDraft();
  if (typeof window.renderResumeDraftPill === 'function') window.renderResumeDraftPill();
  if (typeof showCampaignToast === 'function') showCampaignToast('Draft deleted');
};

function v3RenderPastRow(p, displayIdx, safe) {
  const oIdx = p._originalIdx;
  const ago = (typeof _humanAgo === 'function' && p.date) ? _humanAgo(new Date(p.date).getTime()) : '';
  const isStopped = (p.endReason === 'stopped' || p.fullStop);
  const sent = p.totalProcessed || 0;
  // Bug 10: "replies" removed from the dashboard. successCount still drives the
  // success-rate %, just no longer labelled "replies".
  const succeeded = p.successCount || 0;
  let rateHtml;
  if (isStopped) {
    rateHtml = '<div class="pa-stopped">Stopped early</div>';
  } else if (sent > 0) {
    const r = (succeeded / sent) * 100;
    rateHtml = `<div class="pa-rate">${r.toFixed(1)}<span class="pct">%</span></div>`;
  } else {
    rateHtml = `<div class="pa-rate">—</div>`;
  }
  const dockId = 'dock-past-' + oIdx;
  const selected = pastSelectedIdxs.has(oIdx) ? ' is-selected' : '';
  const checkedAttr = pastSelectedIdxs.has(oIdx) ? 'checked' : '';
  return `
    <div class="pa-row${selected}">
      <input type="checkbox" class="pa-check" ${checkedAttr} onclick="event.stopPropagation()" onchange="window.togglePastSelect(${oIdx}, event)" aria-label="Select campaign" />
      <div class="glyph">${safe(v3ModeBadge(p.mode))}</div>
      <div class="pa-name">${safe(p.name || '(unnamed)')}</div>
      <div class="pa-when">${safe(ago)}</div>
      <div class="pa-stats"><b>${sent}</b> sent</div>
      ${rateHtml}
      <div class="pa-actions">
      ${soloCheckChipHtml(oIdx, p)}
      ${monitoringChipHtml(oIdx, p)}
      <div class="dock" id="${dockId}" role="toolbar" aria-label="${safe(p.name || '')} actions">
        ${isStopped && p.settings ? `<button class="dock-btn" data-tip="Resume" aria-label="Resume" onclick="window.dashResumePast(${oIdx})">${V3_SVG_PLAY}</button>` : ''}
        <button class="dock-btn" data-tip="Rerun" aria-label="Rerun" onclick="window.dashRerunPast(${oIdx})">${V3_SVG_RESTART}</button>
        <div class="dock-actions">
          <button class="dock-btn" data-tip="Open log" aria-label="Open log" onclick="window.dashOpenPastLog(${oIdx})">${V3_SVG_DOC}</button>
          ${isStopped && p.settings ? `<button class="dock-btn" data-tip="Edit &amp; resume" aria-label="Edit and resume" onclick="window.dashEditResumePast(${oIdx})">${V3_SVG_PENCIL}</button>` : ''}
          <button class="dock-btn" data-tip="Copy to queue" aria-label="Copy to queue" onclick="window.dashCopyPastToQueue(${oIdx})">${V3_SVG_COPY}</button>
          <button class="dock-btn" data-tip="Export CSV" aria-label="Export CSV" onclick="window.dashExportPast(${oIdx})">${V3_SVG_DOWNLOAD}</button>
          <button class="dock-btn danger" data-tip="Delete" aria-label="Delete" onclick="window.dashArchivePast(${oIdx})">${V3_SVG_ARCHIVE}</button>
        </div>
      </div>
      </div>
    </div>
  `;
}

window.togglePastExpanded = function() {
  // v2.61: V3 expand pattern — the bordered frame (#pastFrame) contains
  // both the header (#pastCollapsed) and the list (#pastList). Toggling
  // .is-expanded on the frame rotates the chevron, slides the list into
  // view, and keeps the header visible at the top. No more display:none
  // swap between two visually-different containers.
  const frame = document.getElementById('pastFrame');
  const header = document.getElementById('pastCollapsed');
  const btn = document.getElementById('past-toggle-btn');
  if (!frame) return;
  const isExpanded = frame.classList.toggle('is-expanded');
  if (btn) btn.textContent = isExpanded ? 'Collapse' : 'Show all';
  if (header) header.setAttribute('aria-expanded', String(isExpanded));
};

// v2.71: Resume a stopped past campaign from where it stopped (no edits).
// Wires the dock's Resume icon to the existing resumeFromPastRow flow.
// The `_originalIdx` from v3 = the on-disk history idx, which matches
// `pastCampaignsCache[i].idx` in the legacy renderer too — both paths
// resolve to the same /api/campaign/start with resumeContext.
window.dashResumePast = async function(originalIdx) {
  // Build the legacy pastCampaignsCache shape so resumeWithSameSettings can
  // look up the entry. v3 caches in _v3PastEntries by _originalIdx; the
  // legacy code expects { idx, c } entries in pastCampaignsCache.
  const entry = (_v3PastEntries || []).find(p => p._originalIdx === originalIdx);
  if (!entry) {
    if (typeof showCampaignToast === 'function') showCampaignToast('Past entry not found');
    return;
  }
  pastCampaignsCache = (pastCampaignsCache || []);
  if (!pastCampaignsCache.find(e => e.idx === originalIdx)) {
    pastCampaignsCache.push({ idx: originalIdx, c: entry });
  }
  if (typeof resumeFromPastRow === 'function') resumeFromPastRow(originalIdx);
};

// v2.71: Edit + resume flow. Prefill the wizard with the past campaign's
// settings, set localStorage hooks so:
//   • the existing startCampaign auto-attaches resumeContext.totalProcessed
//     (via the wizardStoppedFromContext mechanism — name-match required)
//   • submitStartCampaign's success block knows which source past entry to
//     delete after the resume launches (editResumeSourceIdx)
// Then shows the wizard's resume banner with the "Save edits & resume"
// button so the operator has a clearly-labelled commit action.
window.dashEditResumePast = async function(originalIdx) {
  const entry = (_v3PastEntries || []).find(p => p._originalIdx === originalIdx);
  if (!entry || !entry.settings) {
    if (typeof showCampaignToast === 'function') showCampaignToast('No saved settings on this row');
    return;
  }
  const s = entry.settings;
  const config = {
    mode: entry.mode,
    sheetUrl: s.sheetUrl || '',
    dailyLimit: s.dailyLimit ?? 50,
    delayMin: s.delayMin ?? 10,
    delayMax: s.delayMax ?? 20,
    linkedinColumn: s.linkedinColumn || '',
    messageOpenProfiles: !!s.messageOpenProfiles,
    addNote: !!(s.templates && s.templates.connectionNote),
    templates: s.templates || {},
    profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
    concurrency: s.concurrency ?? 1,
    senderFirstNames: s.senderFirstNames || {},
  };
  // Seed the resume hooks BEFORE navigation so the wizard view picks them up.
  try {
    localStorage.setItem('wizardStoppedFromContext', JSON.stringify({
      name: entry.name || '',
      totalProcessed: Number(entry.totalProcessed) || Number(entry.successCount) || 0,
    }));
    localStorage.setItem('editResumeSourceIdx', String(originalIdx));
  } catch {}
  if (typeof goCreateCampaign === 'function') goCreateCampaign();
  setTimeout(() => {
    if (typeof applyPresetConfig === 'function') applyPresetConfig(config);
    // Restore the original name UNMODIFIED — resume requires name match.
    const nameInput = document.getElementById('campaign-name-input');
    if (nameInput) nameInput.value = (entry.name || '').trim();
    // Show the resume banner with the labelled commit button.
    const banner = document.getElementById('wizard-resume-banner');
    if (banner) banner.style.display = '';
  }, 100);
};

// v2.71: explicit commit button for the edit-resume flow. Functionally the
// same as the wizard Start button (resumeContext is auto-attached from
// wizardStoppedFromContext), just labelled clearly so the operator knows
// this is the persist-changes-and-resume action vs. a fresh launch.
window.saveEditsAndResume = async function() {
  if (typeof startCampaign === 'function') {
    await startCampaign({});
  }
};

window.dashRerunPast = async function(originalIdx) {
  try {
    const r = await fetch('/api/history/' + originalIdx + '/relaunch', { method: 'POST' });
    const body = await r.json().catch(() => ({}));
    if (r.ok && body.ok) {
      if (typeof showCampaignToast === 'function') showCampaignToast(body.message || 'Queued rerun');
      if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
      // When the server fired the campaign immediately (idle path), kick
      // the 2s pollStatus loop + a direct active-card paint so the tile
      // populates without waiting up to 5s for the dashboard timer.
      if (body.started) {
        if (typeof startPolling === 'function') startPolling();
        try {
          const s = await fetch('/api/campaign/status').then(r => r.json());
          if (typeof window.renderActiveCard === 'function') window.renderActiveCard(s);
        } catch { /* best-effort */ }
      }
    } else {
      if (typeof showCampaignToast === 'function') showCampaignToast('Rerun failed: ' + (body.error || r.statusText));
    }
  } catch (err) { console.error('[v3] dashRerunPast:', err); }
};

window.dashOpenPastLog = async function(originalIdx) {
  try {
    const r = await fetch('/api/history/' + originalIdx + '/log');
    const body = await r.json().catch(() => ({}));
    if (!r.ok) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Log fetch failed: ' + (body.error || r.statusText));
      return;
    }
    v3ShowLogModal(body.name || ('Campaign ' + originalIdx), body.lines || []);
  } catch (err) { console.error('[v3] dashOpenPastLog:', err); }
};

function v3ShowLogModal(name, lines) {
  let modal = document.getElementById('v3-log-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'v3-log-modal';
    modal.className = 'modal-shade';
    modal.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9000;align-items:center;justify-content:center;';
    modal.innerHTML = `
      <div class="modal-card" style="background:var(--bg);border:1px solid var(--hairline);color:var(--ink);width:min(720px, 92vw);max-height:80vh;display:flex;flex-direction:column;font-family:var(--mono);">
        <div style="padding:14px 18px;border-bottom:1px solid var(--hairline);display:flex;justify-content:space-between;align-items:center;">
          <div id="v3-log-title" style="font-family:var(--display);font-size:1.2rem;letter-spacing:0.02em;"></div>
          <button type="button" onclick="document.getElementById('v3-log-modal').style.display='none'" style="background:transparent;border:1px solid var(--hairline);color:var(--ink);padding:6px 12px;font-family:var(--mono);font-size:0.6rem;letter-spacing:0.22em;text-transform:uppercase;cursor:pointer;border-radius:9999px;">Close</button>
        </div>
        <pre id="v3-log-body" style="flex:1;overflow:auto;padding:14px 18px;font-family:'JetBrains Mono', 'SF Mono', Menlo, monospace;font-size:0.72rem;line-height:1.5;color:var(--gray);white-space:pre-wrap;word-break:break-word;margin:0;background:var(--bg-soft);"></pre>
      </div>
    `;
    document.body.appendChild(modal);
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.style.display = 'none'; });
  }
  const title = document.getElementById('v3-log-title');
  const body = document.getElementById('v3-log-body');
  const safe = (typeof escHtml === 'function') ? escHtml : (s) => String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  if (title) title.textContent = name;
  if (body) {
    if (Array.isArray(lines) && lines.length > 0) {
      body.innerHTML = lines.map(l => safe(l)).join('\n');
    } else {
      body.textContent = 'No log lines found for this campaign.';
    }
  }
  modal.style.display = 'flex';
}

window.dashCopyPastToQueue = async function(originalIdx) {
  try {
    const r = await fetch('/api/history');
    const all = await r.json();
    if (!Array.isArray(all) || !all[originalIdx]) {
      if (typeof showCampaignToast === 'function') showCampaignToast('History entry not found');
      return;
    }
    const entry = all[originalIdx];
    if (!entry.settings) {
      if (typeof showCampaignToast === 'function') showCampaignToast('No settings to copy');
      return;
    }
    await fetch('/api/campaign/queue-only', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...entry.settings,
        name: (entry.name || 'Campaign') + ' (copy)',
        mode: entry.mode,
      }),
    });
    if (typeof showCampaignToast === 'function') showCampaignToast('Copied to queue');
    if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
  } catch (err) { console.error('[v3] dashCopyPastToQueue:', err); }
};

window.dashExportPast = function(originalIdx) {
  // /api/export/csv exports state.json processed leads (existing endpoint, not per-entry).
  try {
    window.open('/api/export/csv', '_blank');
  } catch (err) { console.error('[v3] dashExportPast:', err); }
};

window.dashArchivePast = async function(originalIdx) {
  if (!confirm('Delete this campaign? It will be removed from the list.')) return;
  try {
    // Soft-delete on the server (history record kept for audit), shown as
    // a hard "Delete" in the UI because "Archive" was confusing operators.
    const r = await fetch('/api/history/' + originalIdx + '/archive', { method: 'PATCH' });
    if (r.ok) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Deleted');
      if (typeof window.renderPastSection === 'function') window.renderPastSection();
    } else {
      const body = await r.json().catch(() => ({}));
      if (typeof showCampaignToast === 'function') showCampaignToast('Delete failed: ' + (body.error || r.statusText));
    }
  } catch (err) { console.error('[v3] dashArchivePast:', err); }
};

// ── Bug 13: Past bulk delete (manage / "Select" mode) ────────────────────────
// Reuses the module-scoped pastManageMode + pastSelectedIdxs state. Selection is
// keyed on _originalIdx (on-disk history index). Delete = soft-archive, the same
// endpoint the single-row Delete uses; archive never reindexes history.json, so
// a whole batch of indexes stays valid.
window.togglePastManage = function() {
  pastManageMode = !pastManageMode;
  if (!pastManageMode) pastSelectedIdxs.clear();
  const btn = document.getElementById('past-manage-btn');
  if (btn) btn.textContent = pastManageMode ? 'Done' : 'Select';
  // Entering Select mode auto-expands the list so rows + checkboxes are visible.
  if (pastManageMode) {
    const frame = document.getElementById('pastFrame');
    if (frame && !frame.classList.contains('is-expanded') && typeof window.togglePastExpanded === 'function') {
      window.togglePastExpanded();
    }
  }
  if (typeof window.renderPastSection === 'function') window.renderPastSection();
};

window.togglePastSelect = function(oIdx, event) {
  if (event && event.stopPropagation) event.stopPropagation();
  if (pastSelectedIdxs.has(oIdx)) pastSelectedIdxs.delete(oIdx);
  else pastSelectedIdxs.add(oIdx);
  const row = event && event.target && event.target.closest && event.target.closest('.pa-row');
  if (row) row.classList.toggle('is-selected', pastSelectedIdxs.has(oIdx));
  _v3UpdatePastBulkBar();
};

function _v3UpdatePastBulkBar() {
  const bar = document.getElementById('past-bulk-bar');
  if (!bar) return;
  if (!pastManageMode) { bar.hidden = true; return; }
  bar.hidden = false;
  const n = pastSelectedIdxs.size;
  const countEl = document.getElementById('past-bulk-count');
  const delBtn = document.getElementById('past-bulk-delete-btn');
  if (countEl) countEl.textContent = `${n} selected`;
  if (delBtn) {
    delBtn.disabled = n === 0;
    delBtn.textContent = n > 0 ? `Delete ${n}` : 'Delete selected';
  }
}

async function _v3ArchivePastIdxs(indexes) {
  let ok = 0;
  for (const idx of indexes) {
    try {
      const r = await fetch('/api/history/' + idx + '/archive', { method: 'PATCH' });
      if (r.ok) ok++;
    } catch (err) { console.warn('[v3] archive idx', idx, err); }
  }
  return ok;
}

function _v3ExitPastManage() {
  pastSelectedIdxs.clear();
  pastManageMode = false;
  const btn = document.getElementById('past-manage-btn');
  if (btn) btn.textContent = 'Select';
}

window.bulkDeletePastSelected = async function() {
  const idxs = [...pastSelectedIdxs];
  if (idxs.length === 0) return;
  if (!confirm(`Delete ${idxs.length} campaign${idxs.length === 1 ? '' : 's'}? They'll be removed from the list.`)) return;
  const ok = await _v3ArchivePastIdxs(idxs);
  _v3ExitPastManage();
  if (typeof showCampaignToast === 'function') showCampaignToast(`Deleted ${ok}`);
  if (typeof window.renderPastSection === 'function') window.renderPastSection();
};

window.deleteAllPast = async function() {
  const all = (Array.isArray(_v3PastEntries) ? _v3PastEntries : []).map((p) => p._originalIdx);
  if (all.length === 0) return;
  if (!confirm(`Delete ALL ${all.length} past campaign${all.length === 1 ? '' : 's'}? This clears the Past list.`)) return;
  const ok = await _v3ArchivePastIdxs(all);
  _v3ExitPastManage();
  if (typeof showCampaignToast === 'function') showCampaignToast(`Deleted ${ok}`);
  if (typeof window.renderPastSection === 'function') window.renderPastSection();
};

// Bug 13: clear the whole queue (per-item Remove already exists on each card).
window.dashClearQueue = async function() {
  let items = [];
  try {
    const r = await fetch('/api/queue');
    const data = await r.json();
    items = Array.isArray(data?.queue) ? data.queue : [];
  } catch (err) { console.warn('[v3] dashClearQueue fetch', err); }
  if (items.length === 0) return;
  if (!confirm(`Clear all ${items.length} queued campaign${items.length === 1 ? '' : 's'}?`)) return;
  for (const q of items) {
    if (!q || !q.id) continue;
    try { await fetch('/api/queue/' + encodeURIComponent(q.id), { method: 'DELETE' }); }
    catch (err) { console.warn('[v3] dashClearQueue delete', q.id, err); }
  }
  if (typeof showCampaignToast === 'function') showCampaignToast('Queue cleared');
  if (typeof window.renderUpNextDeck === 'function') window.renderUpNextDeck();
};

// toggleDock — shared dock open/close + click-outside dismissal. Used by Active,
// Monitoring, Up Next item docks, and Past row docks.
if (typeof window.toggleDock !== 'function') {
  window.toggleDock = function(idOrEl, e) {
    if (e && e.stopPropagation) e.stopPropagation();
    const dock = typeof idOrEl === 'string' ? document.getElementById(idOrEl) : (idOrEl && idOrEl.closest && idOrEl.closest('.dock'));
    if (!dock) return;
    const opening = dock.getAttribute('data-open') !== 'true';
    document.querySelectorAll('.dock[data-open="true"]').forEach(d => {
      if (d !== dock) {
        d.setAttribute('data-open', 'false');
        const trig = d.querySelector('.dock-trigger');
        if (trig) trig.setAttribute('aria-expanded', 'false');
      }
    });
    dock.setAttribute('data-open', opening ? 'true' : 'false');
    const trig = dock.querySelector('.dock-trigger');
    if (trig) trig.setAttribute('aria-expanded', opening ? 'true' : 'false');
  };
  // Click-outside dismissal
  document.addEventListener('click', (e) => {
    document.querySelectorAll('.dock[data-open="true"]').forEach(dock => {
      if (!dock.contains(e.target)) {
        dock.setAttribute('data-open', 'false');
        const trig = dock.querySelector('.dock-trigger');
        if (trig) trig.setAttribute('aria-expanded', 'false');
      }
    });
  });
}

/* ── Global tooltip for [data-tip] attributes ──────────────────────────
   v0.3 markup decorates dock buttons / toggles with data-tip="…". This
   listener pops a small fixed-position bubble on hover so the tip text
   shows up. CSS at body[data-dashboard='v3'] .global-tip in
   dashboard-v0.3.css. */
if (!window.__v3TipWired) {
  window.__v3TipWired = true;
  const _v3Tip = document.createElement('div');
  _v3Tip.className = 'global-tip';
  document.body.appendChild(_v3Tip);
  function _v3ShowTip(target) {
    const t = target.getAttribute && target.getAttribute('data-tip');
    if (!t) return;
    const r = target.getBoundingClientRect();
    _v3Tip.textContent = t;
    _v3Tip.style.left = (r.left + r.width / 2) + 'px';
    _v3Tip.style.top = r.top + 'px';
    _v3Tip.classList.add('show');
  }
  function _v3HideTip() { _v3Tip.classList.remove('show'); }
  document.addEventListener('mouseover', (e) => {
    const t = e.target && e.target.closest && e.target.closest('[data-tip]');
    if (t) _v3ShowTip(t); else _v3HideTip();
  });
  document.addEventListener('mouseout', (e) => {
    const t = e.target && e.target.closest && e.target.closest('[data-tip]');
    if (t && (!e.relatedTarget || !e.relatedTarget.closest || !e.relatedTarget.closest('[data-tip]'))) _v3HideTip();
  });
  document.addEventListener('scroll', _v3HideTip, true);
}

// ─────────────────────────────────────────────────────────────────────────
// Floating live console — DOM glue. Pure helpers live in /js/live-console.mjs.
// Hooked into pollStatus() so it shares the existing 2s poll cadence.
// ─────────────────────────────────────────────────────────────────────────
function renderLiveConsole(s) {
  const root = document.getElementById('live-console');
  if (!root) return;
  s = localCampaignViewStatus(s);
  // A draft owns no runtime history until it starts. Keep the old campaign's
  // server state intact, but don't present it as this draft's activity.
  if (isOnNewCampaignView() && !_launchCheckPending) {
    const name = (document.getElementById('campaign-name-input')?.value || '').trim();
    if (!name || !sameCampaign(s, { campaignId: _openedCampaignId, name })) {
      s = { name, running: false, state: 'draft', logs: [], profileNames: [],
        currentAction: { label: 'Not started yet' } };
    }
  }


  const running = !!(s && s.running);
  const hasRoster = !!(s && Array.isArray(s.profileNames) && s.profileNames.length);
  const visible = shouldShowConsole({
    running,
    paused: !!(s && (s.paused || s.pauseRequested)),
    state: s && s.state,
    hasRoster,
  });

  if (!visible) {
    root.hidden = true;
    // Visibility changes must not change the operator's open/closed choice.
    return;
  }
  root.hidden = false;

  const pill = computePillState(s);

  // Helper: only write text if it changed, to avoid layout thrash.
  const setText = (sel, value) => {
    const el = root.querySelector(sel);
    if (!el) return;
    const cached = _lcWriteCache[sel];
    if (cached === value) return;
    el.textContent = value;
    _lcWriteCache[sel] = value;
  };
  const setAttr = (sel, attr, value) => {
    const el = root.querySelector(sel);
    if (!el) return;
    const key = `${sel}@${attr}`;
    if (_lcWriteCache[key] === value) return;
    if (value == null) el.removeAttribute(attr);
    else el.setAttribute(attr, value);
    _lcWriteCache[key] = value;
  };
  const setHidden = (sel, hide) => {
    const el = root.querySelector(sel);
    if (!el) return;
    const key = `${sel}@hidden`;
    const v = hide ? '1' : '0';
    if (_lcWriteCache[key] === v) return;
    if (hide) el.setAttribute('hidden', '');
    else el.removeAttribute('hidden');
    _lcWriteCache[key] = v;
  };

  // ── v2.59.26 redesign: state class drives lip/head colours; drawer body is
  // a mini dashboard card (shared buildLiveActivity live line + countdown). ──
  const isChecking = !!s.monitoringCheckInProgress;
  const isMon = !isChecking && !s.running && s.state === 'monitoring';
  const isPaused = !isChecking && !!(s.paused || s.pauseRequested);
  const isRunning = isChecking || (!!s.running && !isPaused);
  const isWarn = !!((s.throttle && s.throttle.active) || (Array.isArray(s.parked) && s.parked.length));
  const stateClass = isMon ? 'lc-monitoring'
    : isPaused ? 'lc-paused'
    : isWarn ? 'lc-warn'
    : isRunning ? 'lc-running'
    : 'lc-idle';
  ['lc-monitoring', 'lc-running', 'lc-paused', 'lc-warn', 'lc-idle'].forEach((c) => {
    root.classList.toggle(c, c === stateClass);
  });

  // Head — status label + campaign name + mode badge.
  const statusLabel = isMon ? 'Monitoring' : isPaused ? 'Paused' : isRunning ? 'Running' : (pill.state || 'idle');
  setText('[data-lc="hstatus"]', statusLabel.charAt(0).toUpperCase() + statusLabel.slice(1));
  setText('[data-lc="title"]', (pill.name && pill.name !== '—') ? pill.name.toUpperCase() : 'Loading campaign…');
  // Short mode tag ("C+D") — pill.mode can be the full mode string for modes
  // missing from MODE_LABELS, which overflowed the badge into the × button.
  setText('[data-lc="badge"]', (typeof v3ModeBadge === 'function') ? v3ModeBadge(s.mode) : pill.mode);

  // Mini card — the same live line as the dashboard card + big number.
  const la = buildLiveActivity(s);
  setText('[data-lc="live-ico"]', la.icon);
  setText('[data-lc="live-l1"]', la.l1);
  setText('[data-lc="live-l2"]', la.l2);
  let bigN = '—', bigU = '';
  if (isMon) {
    bigN = s.nextCheckAt ? v3FmtCountdown(new Date(s.nextCheckAt).getTime() - Date.now()) : '—';
    bigU = 'next check';
  } else if (isRunning || isPaused) {
    bigN = pill.total > 0 ? `${Math.round((pill.processed / pill.total) * 100)}%` : String(pill.processed);
    bigU = pill.total > 0 ? 'done' : 'sent';
  }
  setText('[data-lc="live-n"]', bigN);
  setText('[data-lc="live-u"]', bigU);

  // Mini stats line.
  const _sent = Number(s.totalProcessed) || pill.processed || 0;
  const _accepted = (s.acceptedCount != null ? s.acceptedCount : '—');
  let _statsHTML = `<b>${_sent}</b> sent · <b>${_accepted}</b> accepted`;
  if (isMon && s.monitoringUntil) {
    const _ends = new Date(s.monitoringUntil).toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' });
    _statsHTML += ` · ends <b>${_ends}</b>`;
  } else {
    const _acc = (Array.isArray(s.profileNames) ? s.profileNames.length : 0);
    _statsHTML += ` · <b>${_acc}</b> account${_acc === 1 ? '' : 's'}`;
  }
  const _statsEl = root.querySelector('[data-lc="mini-stats"]');
  if (_statsEl && _lcWriteCache['__mini_stats'] !== _statsHTML) {
    _statsEl.innerHTML = _statsHTML;
    _lcWriteCache['__mini_stats'] = _statsHTML;
  }

  // Selected GoLogin account roster — "who we selected", with the currently
  // acting account marked. Re-render only when the roster signature changes.
  const acctEl = root.querySelector('[data-lc="accounts"]');
  if (acctEl) {
    const accts = pill.accounts || [];
    const sig = accts.map((a) => (a.active ? '*' : '') + a.name).join('|');
    if (_lcWriteCache['__acct_sig'] !== sig) {
      acctEl.innerHTML = '';
      if (!accts.length) {
        acctEl.textContent = '—';
      } else {
        accts.forEach((a) => {
          const span = document.createElement('span');
          span.className = 'live-console__acct' + (a.active ? ' is-active' : '');
          span.textContent = a.name;
          acctEl.appendChild(span);
        });
      }
      _lcWriteCache['__acct_sig'] = sig;
    }
  }
  const sentStr = `${pill.processed} / ${pill.total}` +
    (pill.errSegment ? ` ${pill.errSegment}` : '') +
    (pill.parkedSegment ? ` ${pill.parkedSegment}` : '');
  setText('[data-lc="sent"]', sentStr);
  setText('[data-lc="state"]', `state · ${pill.state}`);

  // Cockpit ring (Variant B): fill % = sent / total, gold while running and
  // blue while monitoring. Center = processed count, caption = "of total".
  const ringEl = root.querySelector('[data-lc="ring"]');
  if (ringEl) {
    const pct = pill.total > 0
      ? Math.max(0, Math.min(100, Math.round((pill.processed / pill.total) * 100)))
      : 0;
    const accent = pill.state === 'monitoring' ? 'var(--blue)' : 'var(--gold)';
    const bg = `conic-gradient(${accent} 0 ${pct}%, rgba(255,255,255,0.10) ${pct}% 100%)`;
    if (_lcWriteCache['__ring_bg'] !== bg) {
      ringEl.style.background = bg;
      _lcWriteCache['__ring_bg'] = bg;
    }
  }
  setText('[data-lc="ring-num"]', String(pill.processed));
  setText('[data-lc="ring-cap"]', `of ${pill.total}`);

  // Log tail (3 lines)
  const logEl = root.querySelector('[data-lc="log"]');
  if (logEl) {
    const lines = pill.logs;
    const sig = lines.join('|');
    if (_lcWriteCache['__log_sig'] !== sig) {
      logEl.innerHTML = '';
      lines.forEach((line, i) => {
        const span = document.createElement('span');
        span.className = 'live-console__log-line' + (i === lines.length - 1 ? ' is-latest' : '');
        span.textContent = line;
        logEl.appendChild(span);
      });
      _lcWriteCache['__log_sig'] = sig;
    }
  }

  // Keep the console open after a stop or completed check until explicitly closed.
}

// ── Live console: expand / collapse interaction ───────────────────────────
// Remember the operator's choice for this app window, including after a stop
// or a UI reload. Campaign lifecycle changes never collapse the console.

function _lcApplyState(expanded) {
  const root = document.getElementById('live-console');
  if (!root) return;
  root.classList.toggle('is-expanded', expanded);
  root.classList.toggle('is-collapsed', !expanded);
  try { sessionStorage.setItem('ortus-console-expanded', String(expanded)); } catch (_) {}
}

function _lcExpand()   { _lcApplyState(true);  }
function _lcCollapse() { _lcApplyState(false); }

function _lcInit() {
  const root = document.getElementById('live-console');
  if (!root) return;

  let expanded = false;
  try { expanded = sessionStorage.getItem('ortus-console-expanded') === 'true'; } catch (_) {}
  _lcApplyState(expanded);

  // Click lip → expand. Click × (collapse) button → back to lip.
  // Click dashboard link → goDashboard() (defined elsewhere in app.js).
  const pillBtn = root.querySelector('[data-lc="pill"]');
  if (pillBtn) pillBtn.addEventListener('click', _lcExpand);

  const collapseBtn = root.querySelector('[data-lc="collapse"]');
  if (collapseBtn) collapseBtn.addEventListener('click', _lcCollapse);

  const dashLink = root.querySelector('[data-lc="dash"]');
  if (dashLink) dashLink.addEventListener('click', (ev) => {
    ev.preventDefault();
    if (typeof goDashboard === 'function') goDashboard();
    else window.location.hash = '#/';
  });

  // Console visibility is route-independent now (it's a persistent monitor),
  // so the route change no longer toggles it — the 2s poll owns visibility.
  window.addEventListener('hashchange', () => {
    // v2.61: Live Status section also reacts to hash changes — switching
    // away from #/new or into a draft view must hide it immediately,
    // not wait for the next 2s poll tick.
    try { syncLiveStatusVisibility(); } catch {}
  });

  // v2.61: Initial sync so we don't flash the Live Status section on load
  // before the first 2s poll tick decides whether to hide it.
  try { syncLiveStatusVisibility(); } catch {}
}

// Initialize once DOM is ready.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _lcInit);
} else {
  _lcInit();
}


// ── Check DMs / reply-check (A3 split) controller ────────────────────────────
let _rsweepTimer = null;
let _rsweepSel = null;     // threadId of the reply shown in the read pane
let _rsweepLast = null;    // last status, so list clicks can re-render the pane

function rsweepEsc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

// Flat, ordered list of every reply (campaign first, then unmatched) for selection.
function rsweepAll(s) {
  return [...(s.campaignReplies || []).map((r) => ({ ...r, group: 'campaign' })),
          ...(s.unmatched || []).map((r) => ({ ...r, group: 'unmatched' }))];
}

function rsweepListItem(r) {
  const tag = r.suspected ? `<span class="rsweep-suspect">same-name</span>` : '';
  const sel = r.threadId && r.threadId === _rsweepSel ? ' sel' : '';
  return `<div class="rsweep-item${sel}" data-tid="${rsweepEsc(r.threadId)}">
    <div class="rsweep-item-nm">${rsweepEsc(r.leadName)}${tag}</div>
    <div class="rsweep-item-snip">${rsweepEsc(r.snippet)}</div></div>`;
}

function rsweepPane(r) {
  if (!r) return `<div class="rsweep-empty">Run a check, then pick a reply to read it here.</div>`;
  const when = r.timestamp ? new Date(r.timestamp).toLocaleString() : '';
  const tag = r.suspected ? `<span class="rsweep-suspect">same-name</span>` : '';
  // Full message text (untruncated) — fall back to the 160-char snippet for old payloads.
  const body = (r.fullText && r.fullText.length) ? r.fullText : (r.snippet || '');
  // Open-thread opens the SENDER's own GoLogin browser when we know its profile;
  // otherwise fall back to a system-browser link.
  const canGoLogin = !!(r.accountPid && (r.threadId || r.profileUrl));
  const webUrl = (r.threadId ? `https://www.linkedin.com/messaging/thread/${rsweepEsc(r.threadId)}/` : '') || r.linkedinUrl || r.profileUrl || '';
  const openChip = canGoLogin
    ? `<button type="button" class="rsweep-chip" data-rsweep-open data-pid="${rsweepEsc(r.accountPid)}" data-tid="${rsweepEsc(r.threadId || '')}" data-purl="${rsweepEsc(r.profileUrl || '')}" title="Opens ${rsweepEsc(r.account || 'the sender')}'s GoLogin browser">↗ open thread in ${rsweepEsc(r.account || 'gologin')}</button>`
    : (webUrl ? `<a class="rsweep-chip" href="${rsweepEsc(webUrl)}" target="_blank" rel="noopener">↗ open thread in linkedin</a>` : '');
  return `<div class="rsweep-pane-head"><div class="rsweep-pane-nm">${rsweepEsc(r.leadName)}${tag}</div>
      <div class="rsweep-pane-meta">${rsweepEsc(r.account || '')}${when ? ` · ${rsweepEsc(when)}` : ''}</div></div>
    <div class="rsweep-bubble">${rsweepEsc(body)}</div>
    ${openChip}
    <span class="rsweep-chip" title="Stage write-back happens during a non-preview sweep">✓ mark replied in sheet</span>`;
}

// Open a reply's thread in the sender's GoLogin browser via the backend.
async function rsweepOpenThread(btn) {
  const pid = btn.getAttribute('data-pid');
  const tid = btn.getAttribute('data-tid') || '';
  const purl = btn.getAttribute('data-purl') || '';
  if (!pid) return;
  const prev = btn.textContent;
  btn.disabled = true; btn.textContent = '↗ opening browser…';
  try {
    const resp = await fetch('/api/reply-sweep/open-thread', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ profileId: pid, threadId: tid, profileUrl: purl }),
    });
    if (!resp.ok) { const e = await resp.json().catch(() => ({})); showCampaignToast(e.error || 'Could not open the browser', 3500); }
  } catch (e) { showCampaignToast(`Open failed: ${e.message}`, 3500); }
  finally { btn.disabled = false; btn.textContent = prev; }
}

function rsweepRender(s) {
  if (!s) return;
  _rsweepLast = s;
  const eyebrow = document.getElementById('rsweep-eyebrow');
  const runBtn = document.getElementById('rsweep-run');
  const stopBtn = document.getElementById('rsweep-stop');
  if (!eyebrow) return;
  const camp = s.campaignReplies || [], unm = s.unmatched || [];
  if (s.running) {
    eyebrow.style.display = '';
    eyebrow.textContent = `Scanning ${rsweepEsc(s.currentProfile || '…')} · ${s.doneProfiles || 0}/${s.totalProfiles || 0} accounts`;
    if (runBtn) runBtn.disabled = true;
    if (stopBtn) stopBtn.style.display = '';
  } else {
    eyebrow.style.display = (s.phase === 'done' || s.phase === 'error') ? '' : 'none';
    if (s.phase === 'done') eyebrow.textContent = `Done · ${camp.length} reply(ies), ${unm.length} unmatched${s.dryRun ? '' : ` · ${s.wrote || 0} written`}`;
    if (s.phase === 'error') eyebrow.textContent = `Error — ${rsweepEsc(s.error || '')}`;
    if (runBtn) runBtn.disabled = false;
    if (stopBtn) stopBtn.style.display = 'none';
  }
  // Live log card — same component the other campaigns use (v3RenderLogLine).
  const logBody = document.getElementById('rsweep-logbody');
  const logHead = document.getElementById('rsweep-loghead');
  const logs = Array.isArray(s.logs) ? s.logs : [];
  if (logBody) {
    const lastN = logs.slice(-30);
    logBody.innerHTML = lastN.length
      ? lastN.map((l) => v3RenderLogLine(l)).join('')
      : '<div class="vj-log-empty">Pick a sheet + account, then run a check — events stream here, one account at a time.</div>';
    logBody.scrollTop = logBody.scrollHeight;
  }
  if (logHead) {
    logHead.textContent = s.running
      ? `Live log · scanning ${s.currentProfile || '…'} · ${s.doneProfiles || 0}/${s.totalProfiles || 0} accounts`
      : (logs.length ? `Live log · last ${Math.min(logs.length, 30)} events (finished)` : 'Live log');
  }

  // Per-account live status card (who's scanning / done / closed / errored).
  rsweepRenderAccts(s);

  const all = rsweepAll(s);
  if (!_rsweepSel && all.length) _rsweepSel = all[0].threadId; // auto-select first
  const list = document.getElementById('rsweep-list');
  if (list) list.innerHTML =
    `<div class="rsweep-grp">Campaign replies · ${camp.length}</div>` +
    (camp.length ? camp.map(rsweepListItem).join('') : `<div class="rsweep-empty">None</div>`) +
    `<div class="rsweep-grp">Unmatched · ${unm.length}</div>` +
    (unm.length ? unm.map(rsweepListItem).join('') : `<div class="rsweep-empty">None</div>`);
  const pane = document.getElementById('rsweep-pane');
  if (pane) pane.innerHTML = rsweepPane(all.find((r) => r.threadId === _rsweepSel) || all[0] || null);
}

async function rsweepPoll() {
  try {
    const s = await fetch('/api/reply-sweep/status').then((r) => r.json());
    rsweepRender(s);
    if (!s.running && _rsweepTimer) { clearInterval(_rsweepTimer); _rsweepTimer = null; }
  } catch (_) { /* transient */ }
}

async function rsweepStart() {
  const dryRun = document.getElementById('rsweep-dryrun')?.checked !== false;
  // Sheet: the panel's own field first, falling back to the global #sheet-url / running campaign.
  const sheetUrl = (document.getElementById('rsweep-sheet')?.value?.trim())
    || (document.getElementById('sheet-url')?.value?.trim()) || '';
  // Accounts: checked boxes = sweep those; zero checked = all sender accounts in the sheet.
  const boxes = Array.from(document.querySelectorAll('#rsweep-accounts .rsweep-acct-cb'));
  const checked = boxes.filter((b) => b.checked).map((b) => b.value);
  const profileIds = (checked.length && checked.length < boxes.length) ? checked : undefined;
  if (!sheetUrl) { showCampaignToast('Paste the Google Sheet URL first', 3000); return; }
  _rsweepSel = null; // re-select first reply of the new run
  try {
    const resp = await fetch('/api/reply-sweep/start', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sheetUrl, profileIds, dryRun }),
    });
    if (!resp.ok) { const e = await resp.json().catch(() => ({})); showCampaignToast(e.error || 'Could not start reply sweep', 3500); return; }
    if (_rsweepTimer) clearInterval(_rsweepTimer);
    _rsweepTimer = setInterval(rsweepPoll, 700);
    rsweepPoll();
  } catch (e) { showCampaignToast(`Reply sweep failed: ${e.message}`, 3500); }
}

async function rsweepStop() { try { await fetch('/api/reply-sweep/stop', { method: 'POST' }); } catch (_) {} }

// Populate the panel's sheet field + account dropdown when entering check_dms mode.
// Sheet pre-fills from the global #sheet-url; accounts come from /api/profiles (same
// source the LinkedIn Accounts section uses). Safe to call repeatedly.
async function rsweepInitControls() {
  const sheetField = document.getElementById('rsweep-sheet');
  if (sheetField && !sheetField.value) {
    const global = document.getElementById('sheet-url')?.value?.trim() || '';
    if (global) sheetField.value = global;
  }
  await rsweepLoadAccounts();
}

let _rsweepAcctSheet = null; // sheet URL the list is currently populated for
// Populate the multi-select account list with ONLY the accounts that have reply-eligible
// leads in the chosen sheet (sheet-scoped + lead counts) — not all 400+ GoLogin profiles.
// Pick one, some, or all; zero checked = sweep all.
async function rsweepLoadAccounts() {
  const listEl = document.getElementById('rsweep-accounts');
  const countEl = document.getElementById('rsweep-acct-count');
  if (!listEl) return;
  const url = document.getElementById('rsweep-sheet')?.value?.trim() || '';
  if (!url) {
    listEl.innerHTML = '';
    if (countEl) countEl.textContent = 'Paste a sheet URL to list accounts…';
    _rsweepAcctSheet = null; rsweepUpdateAcctCount(); return;
  }
  if (url === _rsweepAcctSheet) return; // already populated for this sheet
  if (countEl) countEl.textContent = 'Loading accounts…';
  listEl.innerHTML = '';
  try {
    const res = await fetch(`/api/reply-sweep/accounts?sheetUrl=${encodeURIComponent(url)}`);
    const data = await res.json();
    const accounts = Array.isArray(data.accounts) ? data.accounts : [];
    if (!accounts.length) {
      listEl.innerHTML = '';
      if (countEl) countEl.textContent = 'No accounts with eligible leads in this sheet';
      _rsweepAcctSheet = url; rsweepUpdateAcctCount(); return;
    }
    // Default: all checked (matches the old "All accounts" default).
    listEl.innerHTML = accounts.map((a) => `
      <label class="rsweep-acct-item">
        <input type="checkbox" class="rsweep-acct-cb" value="${rsweepEsc(a.id)}" checked />
        <span class="rsweep-acct-nm">${rsweepEsc(a.name)}</span>
        <span class="rsweep-acct-ct">${a.leadCount} lead${a.leadCount === 1 ? '' : 's'}</span>
      </label>`).join('');
    _rsweepAcctSheet = url;
    // Wire each checkbox to refresh the count label + CTA.
    listEl.querySelectorAll('.rsweep-acct-cb').forEach((cb) => cb.addEventListener('change', rsweepUpdateAcctCount));
    rsweepUpdateAcctCount();
  } catch (_) {
    listEl.innerHTML = '';
    if (countEl) countEl.textContent = 'Could not load accounts — check the sheet URL';
    _rsweepAcctSheet = null; rsweepUpdateAcctCount();
  }
}

// Reflect the current checkbox selection in the header count + the CTA label.
function rsweepUpdateAcctCount() {
  const boxes = Array.from(document.querySelectorAll('#rsweep-accounts .rsweep-acct-cb'));
  const checked = boxes.filter((b) => b.checked);
  const countEl = document.getElementById('rsweep-acct-count');
  const runBtn = document.getElementById('rsweep-run');
  if (countEl && boxes.length) countEl.textContent = `${checked.length} of ${boxes.length} selected`;
  if (runBtn) {
    const n = checked.length || boxes.length; // zero checked = all
    runBtn.textContent = boxes.length ? `Check replies · ${n} account${n === 1 ? '' : 's'}` : 'Check replies now';
  }
}

// Render the per-account live status card from status.perProfile[].
function rsweepRenderAccts(s) {
  const card = document.getElementById('rsweep-acctcard');
  const rowsEl = document.getElementById('rsweep-acctrows');
  const sumEl = document.getElementById('rsweep-acctsum');
  if (!card || !rowsEl) return;
  const accts = Array.isArray(s.perProfile) ? s.perProfile : [];
  if (!accts.length) { card.style.display = 'none'; return; }
  card.style.display = '';
  const cell = (a) => {
    const st = a.status || 'waiting';
    if (st === 'running') return { ico: '<span class="acct-spin"></span>', cls: 's-scan', txt: 'scanning inbox…' };
    if (st === 'error')   return { ico: '✕', cls: 's-err', txt: `error — ${a.error || 'failed'}` };
    if (st === 'skipped') return { ico: '⊘', cls: 's-wait', txt: a.error === 'stopped' ? 'stopped' : 'skipped' };
    if (st === 'done') {
      const r = a.replies || 0;
      return { ico: '✓', cls: a.closed ? 's-closed' : 's-done', txt: `${a.closed ? 'closed · ' : ''}${r} repl${r === 1 ? 'y' : 'ies'}` };
    }
    return { ico: '<span class="acct-dot"></span>', cls: 's-wait', txt: 'waiting' };
  };
  rowsEl.innerHTML = accts.map((a) => {
    const c = cell(a);
    return `<div class="acct-row"><span class="acct-ico">${c.ico}</span>`
      + `<span class="acct-name">${rsweepEsc(a.profileName || '')}</span>`
      + `<span class="acct-state ${c.cls}">${rsweepEsc(c.txt)}</span></div>`;
  }).join('');
  const done = accts.filter((a) => a.status === 'done' || a.status === 'error' || a.status === 'skipped').length;
  const scanning = accts.filter((a) => a.status === 'running').length;
  if (sumEl) sumEl.textContent = `${done} / ${accts.length} done${scanning ? ` · ${scanning} scanning` : ''}`;
}

function rsweepBind() {
  const run = document.getElementById('rsweep-run');
  const stop = document.getElementById('rsweep-stop');
  const list = document.getElementById('rsweep-list');
  const copy = document.getElementById('rsweep-copy');
  const sheet = document.getElementById('rsweep-sheet');
  if (sheet && !sheet._rsweepBound) {
    sheet._rsweepBound = true;
    let _t;
    sheet.addEventListener('input', () => { clearTimeout(_t); _t = setTimeout(() => { rsweepLoadAccounts(); }, 600); });
  }
  if (run && !run._rsweepBound) { run._rsweepBound = true; run.addEventListener('click', rsweepStart); }
  if (stop && !stop._rsweepBound) { stop._rsweepBound = true; stop.addEventListener('click', rsweepStop); }
  const allBtn = document.getElementById('rsweep-acct-all');
  const noneBtn = document.getElementById('rsweep-acct-none');
  const setAll = (v) => { document.querySelectorAll('#rsweep-accounts .rsweep-acct-cb').forEach((cb) => { cb.checked = v; }); rsweepUpdateAcctCount(); };
  if (allBtn && !allBtn._rsweepBound) { allBtn._rsweepBound = true; allBtn.addEventListener('click', () => setAll(true)); }
  if (noneBtn && !noneBtn._rsweepBound) { noneBtn._rsweepBound = true; noneBtn.addEventListener('click', () => setAll(false)); }
  if (copy && !copy._rsweepBound) {
    copy._rsweepBound = true;
    copy.addEventListener('click', async () => {
      const logs = (_rsweepLast && Array.isArray(_rsweepLast.logs)) ? _rsweepLast.logs : [];
      try { await navigator.clipboard.writeText(logs.join('\n')); showCampaignToast('Log copied', 1500); }
      catch (_) { /* clipboard blocked — ignore */ }
    });
  }
  if (list && !list._rsweepBound) {
    list._rsweepBound = true;
    list.addEventListener('click', (e) => {           // pick a reply → read pane
      const item = e.target.closest('.rsweep-item');
      if (!item || !_rsweepLast) return;
      _rsweepSel = item.getAttribute('data-tid');
      rsweepRender(_rsweepLast);
    });
  }
  const pane = document.getElementById('rsweep-pane');
  if (pane && !pane._rsweepBound) {
    pane._rsweepBound = true;
    pane.addEventListener('click', (e) => {            // open thread in sender's GoLogin browser
      const btn = e.target.closest('[data-rsweep-open]');
      if (btn) { e.preventDefault(); rsweepOpenThread(btn); }
    });
  }
}
document.addEventListener('DOMContentLoaded', rsweepBind);
if (document.readyState !== 'loading') rsweepBind();
window.rsweepStart = rsweepStart;
window.rsweepStop = rsweepStop;


// ── Operation Magellan ───────────────────────────────────────────────────────
// Collect the team's LinkedIn connections and put them in HubSpot. The picker
// reuses the campaign account grid's markup, but none of its state: Magellan
// only reads a connections list, so credits, passover, assignment and in-use
// are all irrelevant here. The only state a tile carries is whether we already
// hold that account's connections.

// Every Magellan call goes through this. Without it, a server running older
// code than the page returns the SPA's HTML for an unknown route and res.json()
// dies with `Unexpected token '<'` — which tells the operator nothing. This
// names the actual problem: the app needs restarting.
// 30s, because a request that never settles is worse than one that fails: the
// caller's catch never runs, so its button stays disabled with no error on
// screen and every later click is silently ignored. Measured 2026-08-13 — the
// app was killed mid-POST and the Collect button sat dead for over three
// minutes while the card read "Not running". Every Magellan route answers in
// well under a second; the picker's own slow leg is capped server-side.
const MG_FETCH_TIMEOUT_MS = 30000;

async function mgFetch(url, opts) {
  const res = await fetch(url, { signal: AbortSignal.timeout(MG_FETCH_TIMEOUT_MS), ...opts })
    .catch((err) => {
      if (err.name === 'TimeoutError' || err.name === 'AbortError') {
        throw new Error('The app did not answer. It may have restarted — reload with Cmd+R and try again.');
      }
      throw err;
    });
  const body = await res.text();
  if (body.trim().startsWith('<')) {
    throw new Error('This needs a restart — quit Ortus Basics and open it again to finish updating.');
  }
  let json;
  try {
    json = JSON.parse(body);
  } catch {
    throw new Error(`The app returned something unreadable (${res.status}).`);
  }
  if (!res.ok || json.error) throw new Error(json.error || `Request failed (${res.status})`);
  return json;
}

let mgAccounts = [];
let mgSelected = new Set();
let mgFilter = 'todo';
// Whether the HubSpot token can edit property options. Set from the accounts
// response; gates the "add to the HubSpot list" button.
let mgCanEditOptions = false;
let mgPoll = null;

function setConnTab(tab) {
  const warm = tab !== 'magellan';
  document.getElementById('cx-warm-pane').hidden = !warm;
  document.getElementById('cx-magellan-pane').hidden = warm;
  document.getElementById('cx-tab-warm').classList.toggle('is-active', warm);
  document.getElementById('cx-tab-magellan').classList.toggle('is-active', !warm);
  if (!warm && !mgAccounts.length) loadMagellanAccounts();
}

// `keepSelection` is for the refresh button: the list is re-fetched, but what
// the operator has already ticked survives it. Only the first load — and a load
// after a sweep, when the DONE badges have changed — resets to the default.
async function loadMagellanAccounts({ keepSelection = false, fresh = false } = {}) {
  try {
    const previous = keepSelection ? new Set(mgSelected) : null;
    // `fresh` is what the refresh button means: skip the server's SoO and
    // HubSpot caches. Ordinary tab visits take the cached answer, which is what
    // makes them instant.
    // The response is an object, not a bare array: it carries `canEditOptions`
    // alongside the accounts so the picker knows whether the HubSpot-list fix
    // button can work at all.
    const payload = await mgFetch(`/api/magellan/accounts${fresh ? '?fresh=1' : ''}`);
    mgAccounts = payload.accounts || [];
    mgCanEditOptions = Boolean(payload.canEditOptions);
    if (previous) {
      // A profile that has since disappeared from GoLogin must not stay ticked —
      // it would be sent to a collect that cannot open it.
      const live = new Set(mgAccounts.map((a) => a.profileId));
      mgSelected = new Set([...previous].filter((id) => live.has(id)));
    } else {
      // Nothing is ticked that the operator did not tick. This used to
      // pre-select every collected account carrying LinkedIn member ids —
      // fourteen of them on 2026-08-12 — and the search box hides rows without
      // unticking them, so someone who typed "edlor", ticked the one row they
      // could see and pressed Check got fifteen accounts and 31,191 people
      // instead of 437. A default that grows by one every time you collect
      // something, and is invisible behind a filter, is not a convenience.
      mgSelected = new Set();
    }
    renderMagellanAccounts();
    refreshMagellanState();
    return true;
  } catch (err) {
    showMagellanError(err.message);
    return false;
  }
}

// The list is one fetch away from three services — GoLogin, the SoO sheet and
// HubSpot — so a network blip empties it and leaves "fetch failed" under the
// card with no way back except restarting the app. This is that way back.
async function refreshMagellanAccounts(btn) {
  showMagellanError('');
  if (btn) btn.disabled = true;
  try {
    const ok = await loadMagellanAccounts({ keepSelection: true, fresh: true });
    if (ok && !mgAccounts.length) {
      showMagellanError('No GoLogin profiles came back. Check that GoLogin is running, then refresh again.');
    }
  } finally {
    if (btn) btn.disabled = false;
  }
}
window.refreshMagellanAccounts = refreshMagellanAccounts;

function magellanVisible() {
  const q = (document.getElementById('mg-search')?.value || '').trim().toLowerCase();
  return mgAccounts.filter((a) => {
    if (q && !a.account.toLowerCase().includes(q)) return false;
    if (mgFilter === 'fixable') return a.resolved && a.importable === false;
    if (mgFilter === 'todo') return !a.collected;
    if (mgFilter === 'done') return a.collected;
    if (mgFilter === 'selected') return mgSelected.has(a.profileId);
    return true;
  });
}

function renderMagellanAccounts() {
  const grid = document.getElementById('mg-grid');
  if (!grid) return;
  const rows = magellanVisible();
  grid.innerHTML = '';

  for (const a of rows) {
    const on = mgSelected.has(a.profileId);
    const item = document.createElement('label');
    item.className = 'profile-item jt ' + (a.collected ? 'is-done' : 'free') + (on ? ' selected' : '');
    const when = a.collectedAt ? new Date(a.collectedAt).toLocaleDateString() : '';
    // Whether we have collected it, and whether it can be imported at all, are
    // two different questions. The tile used to answer only the first, so a
    // green DONE could sit on an account HubSpot would refuse — two accounts
    // were already in exactly that hole. tileState decides which one wins.
    const st = tileState(a);
    let sub = a.collected
      ? `${mgNum(a.count || 0)} collected on ${when}. Tick to collect again.`
      : 'Never collected.';
    // The label on the GoLogin profile, when it isn't the address itself —
    // that's how the operator recognises the account.
    if (a.resolved && a.profile && a.profile !== a.account) sub = `${a.profile} · ${sub}`;
    // No SoO address means nothing to write in HubSpot's Linkedin 1st
    // Connections field, so say so here rather than at import time.
    if (st.kind === 'nosoo') {
      sub = a.ambiguous
        ? `Two SoO accounts match this name — can't tell which. ${sub}`
        : `No email found in the SoO for this profile — it can be collected, but not imported. ${sub}`;
    } else if (st.kind === 'fixable') {
      sub = `Not on the HubSpot "Linkedin 1st Connections" list yet — one click below fixes it. ${sub}`;
    } else if (st.kind === 'unknown') {
      sub = `HubSpot didn't answer in time, so we don't know if this one can be imported. ${sub}`;
    }
    // Blocked accounts stay tickable on purpose: collecting still writes the
    // connections to the operator's Google Sheet tab, only the HubSpot import
    // is held up. Amber warns, it does not wall.
    item.className += (st.kind === 'nosoo' ? ' is-nosoo' : '')
      + (st.kind === 'fixable' ? ' is-fixable' : '');
    item.innerHTML = `
      <div class="jt-stat ${st.band}">
        <span class="jt-dot"></span>
        <span class="jt-word ${a.collected ? 'w-done' : 'w-todo'}">${st.word}</span>
      </div>
      <div class="jt-det">
        <div class="jt-top">
          <input type="checkbox" ${on ? 'checked' : ''} />
          <span class="jt-email">${escHtml(a.account)}</span>
        </div>
        <div class="jt-sub">${sub}</div>
      </div>`;
    item.querySelector('input').addEventListener('change', (e) => {
      if (e.target.checked) mgSelected.add(a.profileId); else mgSelected.delete(a.profileId);
      item.classList.toggle('selected', e.target.checked);
      updateMagellanCounts();
    });
    grid.appendChild(item);
  }
  updateMagellanCounts();
}

function updateMagellanCounts() {
  const set = (id, n) => { const el = document.getElementById(id); if (el) el.textContent = n; };
  const done = mgAccounts.filter((a) => a.collected).length;
  set('mg-count-todo', mgAccounts.length - done);
  set('mg-count-done', done);
  set('mg-count-all', mgAccounts.length);
  set('mg-count-selected', mgSelected.size);
  // Accounts with a real address that HubSpot will nonetheless refuse — the set
  // the fix button clears. Measured 170 of 568 on 2026-08-18.
  set('mg-count-fixable', mgAccounts.filter((a) => a.resolved && a.importable === false).length);
  set('mg-stat-accounts', mgAccounts.length);
  set('mg-stat-collected', done);
  set('mg-stat-todo', mgAccounts.length - done);
  set('mg-sel-count', mgSelected.size);
  const sub = document.getElementById('mg-sel-sub');
  if (sub) {
    sub.textContent = mgSelected.size === 1
      ? 'account selected · about a minute'
      : 'accounts selected · one at a time, roughly a minute each';
  }

  // What pressing Check would actually run. The HubSpot allowlist drops accounts
  // it has no option for; that used to surface only as a log line after the run.
  const chosen = mgAccounts.filter((a) => mgSelected.has(a.profileId));
  const sel = selectionSummary(chosen);
  const split = document.getElementById('mg-sel-split');
  if (split) {
    // Unknown (the portal could not be asked) or nothing to say — stay quiet
    // rather than guess which colleague's account is about to be skipped.
    const show = sel.known && sel.total > 0 && sel.blocked.length > 0;
    split.hidden = !show;
    if (show) {
      // MG_SPLIT_NAME_CAP: the brief's example (`join(', ')`) assumed one
      // blocked account, but a real "Select all visible" against the full
      // roster can put hundreds of names here — a wall of text that buries
      // the two counts the operator actually needs. Show a handful and count
      // the rest instead; the full list already lands in the post-run log
      // line, so this isn't the only place it's readable. 6 fits two lines
      // at this font size and covers the realistic case (a dozen accounts).
      const MG_SPLIT_NAME_CAP = 6;
      const shown = sel.blocked.slice(0, MG_SPLIT_NAME_CAP).map(escHtml).join(', ');
      const rest = sel.blocked.length - MG_SPLIT_NAME_CAP;
      const names = shown + (rest > 0 ? `, …and ${rest} more` : '');
      split.innerHTML = `<b>${sel.usable}</b> can go into HubSpot · `
        + `<b>${sel.blocked.length} need${sel.blocked.length === 1 ? 's' : ''} adding</b> to the `
        + '"Linkedin 1st Connections" list first: '
        + `<span class="blk">${names}</span>`;
    } else {
      split.innerHTML = '';
    }
  }

  const fix = document.getElementById('mg-fix-hs');
  if (fix) {
    // Hidden when there is nothing to fix, and when the token cannot edit
    // properties at all. In that second case the split sentence above still
    // names the blocked accounts, so the operator knows what to ask for.
    const canShow = sel.known && sel.blocked.length > 0 && mgCanEditOptions;
    fix.hidden = !canShow;
    if (canShow) {
      fix.textContent = `Add ${sel.blocked.length} to the HubSpot list`;
      fix.dataset.accounts = JSON.stringify(sel.blocked);
    }
  }
}

// Adds the selected blocked addresses to HubSpot's option list. The server does
// the read-modify-verify; this only reports. It never says "Added" off a 200 —
// the server has already proved the values are on the list by reading it back.
async function magellanAddHubspotOptions(btn) {
  const accounts = JSON.parse(btn.dataset.accounts || '[]');
  if (!accounts.length) return;
  const label = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Adding…';
  try {
    // Through mgFetch, not bare fetch: it carries the 30s cap, so a stalled
    // POST surfaces as an error instead of leaving this button disabled with
    // nothing on screen.
    const j = await mgFetch('/api/magellan/hubspot-options/add', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ accounts }),
    });
    btn.textContent = `Added ${j.added.length} ✓`;
    // Deliberately NOT `fresh`. The server already cleared its option-list
    // cache when the write landed, so an ordinary reload recomputes
    // `importable` and the amber tiles turn green — in about a second.
    // `fresh` additionally forces a blocking SoO re-read (server.js:2808),
    // which measured 16s here and blew mgFetch's 30s timeout on slower
    // laptops: the write succeeded, then the reload behind it reported
    // "The app did not answer", which read as the add having failed.
    await loadMagellanAccounts({ keepSelection: true });
  } catch (err) {
    btn.textContent = label;
    showMagellanError(`Could not add to the HubSpot list — ${err.message}`);
  } finally {
    btn.disabled = false;
  }
}
window.magellanAddHubspotOptions = magellanAddHubspotOptions;

function setMagellanFilter(f) {
  mgFilter = f;
  document.querySelectorAll('#mg-chips .chip').forEach((c) => {
    c.classList.toggle('active', c.dataset.filter === f);
  });
  renderMagellanAccounts();
}

function magellanSelectAllVisible() {
  magellanVisible().forEach((a) => mgSelected.add(a.profileId));
  renderMagellanAccounts();
}

function magellanDeselectAll() {
  mgSelected.clear();
  renderMagellanAccounts();
}

function showMagellanError(msg) {
  const el = document.getElementById('mg-error');
  if (!el) return;
  el.textContent = msg || '';
  el.hidden = !msg;
}

async function startMagellanCollect() {
  showMagellanError('');
  const accounts = mgAccounts
    .filter((a) => mgSelected.has(a.profileId))
    .map((a) => ({ profileId: a.profileId, account: a.account }));
  if (!accounts.length) return showMagellanError('Pick at least one account first.');

  const btn = document.getElementById('mg-collect-btn');
  if (btn) btn.disabled = true;
  try {
    const j = await mgFetch('/api/magellan/collect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ accounts }),
    });
    if (!j.started) throw new Error(j.reason || 'Could not start');
    startMagellanPolling();
  } catch (err) {
    showMagellanError(err.message);
  } finally {
    // Always hand the button back. It used to be re-enabled only in the catch,
    // so anything that left the request unsettled — the app restarting mid-POST
    // is the one measured here — killed the button permanently, with no error
    // beside it. Every click after that did nothing at all.
    // Handing it back early is safe: renderMagellanState re-disables it on the
    // next poll tick while a run is live, and the server refuses a second
    // collect with "Magellan is already running" rather than starting one.
    if (btn) btn.disabled = false;
  }
}

// A job takes a moment to mark itself running — Check spends its first second
// asking HubSpot about properties before it touches any state. Polling used to
// stop on the first "not running" it saw, which was always that gap, so the
// card froze at 0% for the whole run. Wait until we have actually seen it run,
// or until it is clear nothing is going to.
let mgSawRunning = false;
let mgPollStarted = 0;
const MG_POLL_GRACE_MS = 20000;

function startMagellanPolling() {
  if (mgPoll) clearInterval(mgPoll);
  mgSawRunning = false;
  mgPollStarted = Date.now();
  mgPoll = setInterval(refreshMagellanState, 2000);
  refreshMagellanState();
}

async function refreshMagellanState() {
  try {
    const res = await fetch('/api/magellan/state');
    if (!res.ok) return;
    const s = await res.json();
    renderMagellanState(s);
    if (s.running) mgSawRunning = true;
    const settled = mgSawRunning || Date.now() - mgPollStarted > MG_POLL_GRACE_MS;
    if (!s.running && settled && mgPoll) {
      clearInterval(mgPoll);
      mgPoll = null;
      const btn = document.getElementById('mg-collect-btn');
      if (btn) btn.disabled = false;
      // An import started from this page has just finished. Its outcome comes
      // from here now, not from the response to the request that started it.
      if (mgImportPending) {
        mgImportPending = false;
        renderMagellanImportOutcome(s);
      }
      // Counts and DONE badges change once a sweep lands. keepSelection,
      // because this reload exists to update badges — discarding the ticks is
      // not its job. It used to, and the "check whatever the last collect
      // touched" fallback in previewMagellan was papering over it: collect one
      // account, and by the time it finished the tick was gone, so Check had an
      // empty selection and silently ran a batch instead.
      loadMagellanAccounts({ keepSelection: true });
    }
  } catch { /* transient — the next tick retries */ }
}

// The account pills and which one is expanded. Kept out of renderMagellanState
// so the 5-second poll can redraw without collapsing what you are reading.
let mgPerAccount = [];
let mgOpenAccount = null;

function showMagellanAccount(i) {
  mgOpenAccount = (mgOpenAccount === i) ? null : i;
  document.querySelectorAll('#mg-accts .stg-acct').forEach((b, n) => b.classList.toggle('sel', n === mgOpenAccount));
  renderMagellanAccountDetail();
}
window.showMagellanAccount = showMagellanAccount;

function renderMagellanAccountDetail() {
  const box = document.getElementById('mg-acct-detail');
  if (!box) return;
  const a = mgOpenAccount == null ? null : mgPerAccount[mgOpenAccount];
  if (!a) { box.hidden = true; box.innerHTML = ''; return; }
  box.hidden = false;
  document.querySelectorAll('#mg-accts .stg-acct').forEach((b, n) => b.classList.toggle('sel', n === mgOpenAccount));

  // An import row: what landed, and for anything that did not, HubSpot's own
  // words. A "problem" is one skipped detail, not a skipped person — say so,
  // because the number alone reads like lost data.
  if (a.isImport) {
    const errs = a.errors || [];
    box.innerHTML = `<div class="mg-det-h">${escHtml(a.account)}`
      + `${errs.length ? ` — ${errs.length} problem${errs.length === 1 ? '' : 's'}` : ''}</div>`
      + `<div class="mg-det-why">${mgNum(a.created || 0)} added · `
      + `${mgNum(a.updated || 0)} updated · `
      + `${mgNum(a.extraEmails || 0)} email addresses attached</div>`
      + (errs.length
        ? '<div class="mg-det-fix">Everyone here was written and now lists this account. '
          + 'What failed is one extra detail — usually a second email address that another '
          + 'contact already holds, which means that person exists twice in HubSpot.</div>'
          + `<div class="mg-det-raw">${escHtml(errs.slice(0, 3).map((e) => `${e.stage}: ${e.error}`).join(' · '))}`
          + `${errs.length > 3 ? ` · and ${errs.length - 3} more` : ''}</div>`
        : '');
    return;
  }

  if (!a.error) {
    box.innerHTML = `<div class="mg-det-h">${escHtml(a.account)}</div>`
      + `<div class="mg-det-why">${mgNum(a.total || 0)} connections · `
      + `${mgNum(a.withMemberId || 0)} with a LinkedIn ID`
      + `${a.hidden ? ` · ${a.hidden} hidden by LinkedIn` : ''}</div>`;
    return;
  }
  const d = a.diagnosis || {};
  // The raw error is shown, always. When the explanation above it is wrong,
  // this line is the only thing that says so.
  box.innerHTML = `<div class="mg-det-h">${escHtml(a.account)} — ${escHtml(d.what || 'failed')}</div>`
    + `<div class="mg-det-why">${escHtml(d.why || '')}</div>`
    + `<div class="mg-det-fix">${escHtml(d.fix || '')}</div>`
    + `<div class="mg-det-raw">${escHtml(d.raw || a.error || '')}</div>`;
}

function renderMagellanState(s) {
  const el = (id) => document.getElementById(id);
  const set = (id, v) => { const e = el(id); if (e) e.textContent = v; };

  const ok = (s.perAccount || []).filter((a) => !a.error);
  const failed = (s.perAccount || []).length - ok.length;
  const people = ok.reduce((n, a) => n + (a.total || 0), 0);
  const matched = ok.reduce((n, a) => n + (a.withMemberId || 0), 0);
  // The only percentage in this card. Computing it twice — once here from whole
  // accounts and again below with the in-account fraction blended in — is what put 92% in
  // the hero and 83% on the Check button at the same moment.
  const pct = magellanPct(s);

  // Importing reuses this card, so say which half is running — "Collecting"
  // over a HubSpot write is a lie the operator has no way to see through.
  const importing = s.phase === 'importing';
  const checking = s.phase === 'checking';
  set('mg-eyebrow', s.running ? (importing ? 'Importing' : checking ? 'Checking' : 'Collecting')
    : (s.perAccount || []).length || s.imported ? 'Finished' : 'Not running');
  set('mg-when', s.startedAt ? new Date(s.startedAt).toLocaleTimeString() : '');
  set('mg-pct', pct);
  set('mg-done', s.done || 0);
  set('mg-total', s.total || 0);
  // An import-only run never fills the collect counters, so the hero used to
  // read "0 people · 0 with a LinkedIn ID" directly above a log saying 24,607
  // people moved. When the import is what ran, the hero counts the import.
  const imp = s.imported;
  // Which run the hero is counting is decided by which run happened, never by
  // inferring it from whether some OTHER run's counters happen to be empty.
  // `!ok.length` meant an Import in the same session as a collect fell through
  // to the collect branch: "24,607 people · 9,102 with a LinkedIn ID" in the
  // hero, "4,102 added · 20,505 updated" in the outcome line under it. perAccount
  // survives a run change on purpose, so it can never be the discriminator.
  const heroIsImport = Boolean(imp) && !s.running;
  // A Check that has finished. Its own numbers, not the collect's that preceded
  // it — the two live side by side in the state on purpose (the Check reports a
  // collect's failures in its problem list) and used to bleed into each other
  // here. An Import supersedes it: newest run wins, same rule the outcome uses.
  const heroIsCheck = Boolean(s.preview) && !imp && !s.running;
  if (checking && s.running) {
    // Nothing is decided yet, so the only honest number is how far along we
    // are: people asked about, out of accounts done.
    set('mg-people', mgNum(s.checked || 0));
    set('mg-people-lbl', 'people checked');
    set('mg-matched', (s.total || 0) - (s.done || 0));
    set('mg-matched-lbl', 'accounts to go');
    set('mg-failed', 0);
    set('mg-failed-lbl', 'failed');
  } else if (heroIsImport) {
    set('mg-people', mgNum((imp.created || 0) + (imp.updated || 0)));
    set('mg-people-lbl', 'people imported');
    set('mg-matched', mgNum(imp.created || 0));
    set('mg-matched-lbl', 'added');
    set('mg-failed', mgNum(imp.updated || 0));
    set('mg-failed-lbl', 'updated');
  } else if (heroIsCheck) {
    // A finished Check used to fall through to the collect branch, so the hero
    // read "27 people · 27 with a LinkedIn ID · 3 failed" from the COLLECT while
    // the percentage beside it said "0 of 0 accounts" from the CHECK — two runs
    // in one hero (operator screenshot 2026-08-12). A Check counts what a Check
    // did.
    const pv = s.preview || {};
    const skipped = (pv.blocked || []).length;
    set('mg-people', mgNum(s.checked || 0));
    set('mg-people-lbl', 'people checked');
    set('mg-matched', mgNum(s.done || 0));
    set('mg-matched-lbl', 'accounts checked');
    set('mg-failed', mgNum(skipped));
    set('mg-failed-lbl', skipped === 1 ? 'account skipped' : 'accounts skipped');
  } else {
    set('mg-people', mgNum(people));
    // "so far" is a promise of more to come. Once a run has ended there is no
    // more, and the outcome block below is where the real answer lives.
    set('mg-people-lbl', s.running ? 'people so far' : 'people');
    set('mg-matched', mgNum(matched));
    set('mg-matched-lbl', 'with a LinkedIn ID');
    set('mg-failed', failed);
    set('mg-failed-lbl', 'failed');
  }
  set('mg-phase-lbl', s.running ? 'Working' : 'Idle');
  const bar = el('mg-bar');
  if (bar) bar.style.width = `${pct}%`;
  el('mg-card')?.classList.toggle('is-live', !!s.running);
  const stopBtn = el('mg-stop-btn');
  if (stopBtn) {
    // Only the collect loop reads the stop flag (magellan-run.js `_stopRequested`).
    // Showing Stop during a Check or an Import logged "Stop requested", disabled
    // the button, and then ran every remaining account to completion — the one
    // control on this card that is supposed to be believable, lying.
    stopBtn.hidden = !s.running || importing || checking;
    if (s.running && s.step !== 'Stopping') {
      stopBtn.disabled = false;
      stopBtn.textContent = 'Stop';
    }
  }
  const collectBtn = el('mg-collect-btn');
  if (collectBtn) collectBtn.disabled = !!s.running;
  // A button that says "Checking…" for three minutes is indistinguishable from
  // one that has hung. A number moving on it is not.
  const prevBtn = el('mg-preview-btn');
  if (prevBtn && checking) prevBtn.textContent = s.running ? `Checking… ${pct}%` : 'Check what would happen';
  if (s.stopped) set('mg-eyebrow', 'Stopped');

  // What happened. Only ever drawn from the run's own outcome record, which the
  // engine writes at the moment the run ends — so there is no way to render a
  // half-finished run's numbers as a final answer.
  const ocBox = el('mg-outcome');
  if (ocBox) {
    const oc = s.outcome;
    ocBox.hidden = !oc || !!s.running;
    ocBox.classList.toggle('is-bad', !!oc && oc.ok === false);
    ocBox.innerHTML = (oc && !s.running)
      ? `<div class="oc-sum">${escHtml(oc.summary)}</div>`
        + (oc.problems && oc.problems.length
          ? `<ul class="oc-list">${oc.problems.map((p) => `<li>${escHtml(p)}</li>`).join('')}</ul>`
          : '')
      : '';
  }

  // Stage block — the account being worked on and what is happening to it.
  const stage = el('mg-stage');
  if (stage) {
    stage.hidden = !s.running && !s.account;
    if (s.account) {
      set('mg-stage-verb', s.step || 'Working');
      set('mg-stage-name', s.account);

      // Within-account progress. A 7,000-connection account is ~175 pages, so
      // without this the card sits still for minutes and looks hung.
      const c = s.current;
      const ids = c && c.stage === 'ids';
      let sub = `Account ${Math.min((s.done || 0) + 1, s.total)} of ${s.total}`;
      if (c && typeof c.count === 'number') {
        if (c.stage === 'check') {
          // Check asks HubSpot in batches of 100. Count people, not batches —
          // "2,300 of 5,945 people" is the thing being waited on.
          sub += ` · ${mgNum(c.count)} of ${mgNum(c.total || 0)} people`;
        } else if (ids) {
          // Second half: the list is already in hand, this resolves each
          // person's LinkedIn ID. Say so, or it looks like the count reset.
          sub += ` · looking up LinkedIn IDs, ${mgNum(c.count)} of ${mgNum(c.total || 0)}`;
        } else {
          sub += c.total
            ? ` · ${mgNum(c.count)} of ${mgNum(c.total)} connections`
            : ` · ${mgNum(c.count)} connections so far`;
        }
      }
      set('mg-stage-sub', sub);
      set('mg-stage-fix', '');
      set('mg-beat-txt', 'Reading only — nothing is being sent');
      set('mg-beat-right', ids
        ? 'looking up IDs'
        : (c && c.pages ? `page ${c.pages}` : `${mgNum(people)} collected`));
    }
  }

  // One pill per account — the same .stg-acct / .cap-badge row a campaign uses.
  // Green with a count when it worked, red when it didn't; click a red one and
  // its reason appears under the row.
  const pbox = el('mg-accts');
  if (pbox) {
    // After an import-only run the collect list is empty, so show what the
    // import did per account instead — otherwise the row vanishes exactly when
    // there is most to report.
    const list = (s.perAccount || []).length
      ? s.perAccount
      : (imp && imp.perAccount || []).map((r) => ({ ...r, isImport: true }));
    pbox.hidden = list.length === 0;
    pbox.innerHTML = list.map((a, i) => {
      const probs = (a.errors || []).length;
      const cls = a.error ? 'bad' : (probs ? 'warn' : 'ok');
      const n = a.error ? 'failed'
        : a.isImport
          ? `${mgNum(a.created || 0)} added · ${mgNum(a.updated || 0)} updated`
            + (probs ? ` · ${probs} problem${probs === 1 ? '' : 's'}` : '')
          : mgNum(a.total || 0);
      return `<button type="button" class="stg-acct" onclick="showMagellanAccount(${i})">`
        + `<span class="cap-badge ${cls}"><span class="nm">${escHtml(a.account)}</span>`
        + `<span class="n">${escHtml(n)}</span></span></button>`;
    }).join('');
    mgPerAccount = list;
    // Keep an open reason in step with the poll, and open the first failure
    // automatically — a red pill nobody clicks explains nothing. Same for an
    // account whose import hit problems.
    if (mgOpenAccount == null) {
      const bad = list.findIndex((a) => a.error || (a.errors || []).length);
      mgOpenAccount = bad;
    }
    renderMagellanAccountDetail();
  }

  renderMagellanLog(s.log || []);
  // "N added" here duplicated the hero once it started counting the import.
  // The one number the hero does not carry is how much needs a human.
  if (s.imported && !s.running) {
    const probs = (s.imported.errors || []).length;
    set('mg-phase-lbl', probs ? `${probs} problem${probs === 1 ? '' : 's'}` : 'no problems');
  }
  if (s.error) showMagellanError(s.error);
}

// The server stores lines as "[iso] <glyph> text". The card's log is the
// campaign's own three-column grid (time · event · what), so split them the
// same way rather than dumping the raw string.
const MG_LOG_EVENTS = [
  ['▶', 'START', ''],
  ['■', 'DONE', 'is-ok'],
  ['◼', 'STOP', 'is-warn'],
  ['✓', 'READ', 'is-ok'],
  ['✗', 'FAILED', 'is-err'],
  ['⚠', 'WARN', 'is-warn'],
  ['◦', 'OPEN', ''],
];

export function parseMagellanLogLine(line) {
  const m = /^\[([^\]]+)\]\s?([\s\S]*)$/.exec(line || '');
  const rest = m ? m[2] : String(line || '');
  let time = '';
  if (m) {
    const d = new Date(m[1]);
    time = Number.isNaN(d.getTime()) ? m[1] : d.toTimeString().slice(0, 8);
  }
  const hit = MG_LOG_EVENTS.find(([glyph]) => rest.startsWith(glyph));
  return hit
    ? { time, evt: hit[1], cls: hit[2], what: rest.slice(hit[0].length).trim() }
    : { time, evt: 'LOG', cls: '', what: rest };
}

function renderMagellanLog(lines) {
  const box = document.getElementById('mg-log');
  if (!box) return;
  if (!lines.length) {
    box.innerHTML = '<div class="vj-log-empty">Waiting to start — events appear here, one account at a time.</div>';
    return;
  }
  const atBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 40;
  box.innerHTML = lines.map((l) => {
    const p = parseMagellanLogLine(l);
    return `<div class="vj-log-line ${p.cls}"><span class="time">${escHtml(p.time)}</span>`
      + `<span class="evt">${escHtml(p.evt)}</span>`
      + `<span class="what">${escHtml(p.what)}</span></div>`;
  }).join('');
  // Only follow the tail when the operator is already at it — otherwise
  // scrolling back to read a failure yanks you away every poll.
  if (atBottom) box.scrollTop = box.scrollHeight;
}

async function copyMagellanLog(btn) {
  const box = document.getElementById('mg-log');
  if (!box) return;
  try {
    await navigator.clipboard.writeText(box.innerText);
    if (btn) { const t = btn.textContent; btn.textContent = 'Copied'; setTimeout(() => { btn.textContent = t; }, 1200); }
  } catch { /* clipboard blocked — nothing useful to do */ }
}
window.copyMagellanLog = copyMagellanLog;

async function stopMagellanCollect() {
  const btn = document.getElementById('mg-stop-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Stopping…'; }
  try {
    const j = await mgFetch('/api/magellan/stop', { method: 'POST' });
    if (!j.stopped) throw new Error(j.reason || 'Could not stop');
    refreshMagellanState();
  } catch (err) {
    showMagellanError(err.message);
    if (btn) { btn.disabled = false; btn.textContent = 'Stop'; }
  }
}

function toggleMagellanLog() {
  const card = document.getElementById('mg-card');
  const btn = document.getElementById('mg-log-btn');
  if (!card) return;
  const shown = card.classList.toggle('is-detailed');
  if (btn) btn.textContent = shown ? 'Hide log' : 'Show log';
  if (shown) refreshMagellanState();
}

// The run writes three tabs (Magellan Accounts / Log / Import) into the app's
// own Google Sheet. Same sheet the FG side uses, so the URL comes from there.
async function openMagellanSheet() {
  try {
    const j = await mgFetch('/api/magellan/sheet-url');
    if (j.url) return window.open(j.url, '_blank');
    showMagellanError(j.error || 'Could not find the sheet.');
  } catch (err) {
    showMagellanError(`Could not find the sheet — ${err.message}`);
  }
}
window.openMagellanSheet = openMagellanSheet;

async function previewMagellan() {
  showMagellanError('');
  // What is ticked, and nothing else. This used to fall back to "whatever the
  // last collect touched" when nothing was ticked — a second way for the card
  // to check accounts nobody asked about, quietly.
  // Unique by account: two profiles can point at one email, and previewing it
  // twice reads the same file twice and doubles that account's numbers.
  const accounts = [...new Set(mgAccounts
    .filter((a) => mgSelected.has(a.profileId))
    .map((a) => a.account))];
  if (!accounts.length) return showMagellanError('Pick at least one account first.');

  const btn = document.getElementById('mg-preview-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
  // Three minutes of HubSpot calls. Drive the card so it visibly works.
  startMagellanPolling();
  try {
    const j = await mgFetch('/api/magellan/preview', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ accounts }),
    });
    const t = j.totals || {};
    document.getElementById('mg-led-new').textContent = mgNum(t.created || 0);
    // `existing`, not `updated`: a contact HubSpot already holds complete needs
    // no property written, so it is in neither the creates nor the updates.
    document.getElementById('mg-led-existing').textContent = mgNum(t.existing || 0);
    document.getElementById('mg-led-hidden').textContent = mgNum(t.hidden || 0);
    document.getElementById('mg-ledger').hidden = false;
    document.getElementById('mg-confirm-t').innerHTML =
      '<b>Nothing has gone into HubSpot yet.</b> The numbers above are what will happen when you press Import.';
    const imp = document.getElementById('mg-import-btn');
    imp.hidden = false;
    imp.textContent = `Import ${mgNum(t.created || 0)} people`;
    // Only once Check has produced a plan — a link to an empty sheet is worse
    // than no link.
    const rev = document.getElementById('mg-review');
    if (rev) rev.hidden = false;

    // Accounts HubSpot will not accept. "Linkedin 1st Connections" is a fixed
    // list of Ortus emails; anything else — a GoLogin profile NAME, a typo —
    // has no option to write to, so its people cannot be imported at all.
    const bbox = document.getElementById('mg-blocked');
    const blocked = j.blocked || [];
    if (bbox) {
      bbox.hidden = blocked.length === 0;
      bbox.innerHTML = blocked.length
        ? `<div class="mg-det-h">${blocked.length} account${blocked.length === 1 ? '' : 's'} cannot be imported</div>`
          + '<div class="mg-det-why">HubSpot\'s "Linkedin 1st Connections" field is a fixed list of Ortus account '
          + 'emails. These names are not on it, so there is nothing to write their connections to.</div>'
          + '<div class="mg-det-fix">Rename them to the account\'s email address and collect again, or ask for the '
          + 'email to be added as an option in HubSpot.</div>'
          + `<div class="mg-det-raw">${blocked.map(escHtml).join(', ')}</div>`
        : '';
    }

  } catch (err) {
    showMagellanError(err.message);
    // A failed re-check must not leave a stale Import button or review link
    // up — either would point at a plan from a run that never finished.
    const impErr = document.getElementById('mg-import-btn');
    if (impErr) impErr.hidden = true;
    const revErr = document.getElementById('mg-review');
    if (revErr) revErr.hidden = true;
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Check what would happen'; }
  }
}

// Merging duplicates was removed from the screen on purpose. It cannot be undone
// in HubSpot, and for a few hundred people it silently picks between two real
// email addresses (Alecx Bagatsolon: alecx@ vs alecx.bagatsolon@) — rendered
// identically to the harmless one-real-one-synthetic case. The import never
// needed it: lookupByMemberIds already writes the connection to the record with
// a real email address. Duplicates are stated in the run's outcome instead.
// mergeDuplicates() and POST /api/magellan/merge-duplicates are still there,
// with their tests, if this is ever wanted back.

async function importMagellan() {
  const btn = document.getElementById('mg-import-btn');
  if (!confirm('This adds people to HubSpot for real. Continue?')) return;
  if (btn) { btn.disabled = true; btn.textContent = 'Importing…'; }
  // The write takes minutes on a real sweep. Poll the same state the collect
  // half does so the card, the progress bar and the log move while it runs
  // instead of the page sitting dead until the final response lands.
  startMagellanPolling();
  try {
    const j = await mgFetch('/api/magellan/import', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ confirm: true }),
    });
    // The server answers as soon as the run has started — a refusal comes back
    // here, the outcome does not. Waiting for the write itself is what made a
    // finished import print "The app did not answer" at the 30s mark.
    if (j.ok === false) throw new Error(j.reason);
    mgImportPending = true;
    refreshMagellanState();
  } catch (err) {
    showMagellanError(err.message);
    if (btn) { btn.disabled = false; btn.textContent = 'Import'; }
  }
}

// Set while an import this page started is in flight, so the poller knows the
// run that just settled was an import and not a collect — state.imported can
// be left over from an earlier run, and is not on its own evidence that THIS
// run wrote anything.
let mgImportPending = false;

// The sentence that used to be built from the import's HTTP response, now built
// from the state the card polls. Same wording.
function renderMagellanImportOutcome(s) {
  const btn = document.getElementById('mg-import-btn');
  if (s.phase === 'error' || s.error) {
    showMagellanError(s.error || 'The import stopped.');
    if (btn) { btn.disabled = false; btn.textContent = 'Import'; }
    return;
  }
  const imp = s.imported || {};
  const probs = (imp.errors || []).length;
  const el = document.getElementById('mg-confirm-t');
  if (el) {
    el.innerHTML =
      `<b>Done.</b> ${mgNum(imp.created || 0)} people added, `
      + `${mgNum(imp.updated || 0)} existing people updated`
      + (imp.extraEmails ? `, ${mgNum(imp.extraEmails)} email addresses attached` : '')
      + (probs
        ? ` · <b>${probs} problem${probs === 1 ? '' : 's'}</b> — press Show log to see which, and why. `
          + 'A problem means one detail was skipped, not that the person was missed.'
        : ' · no problems.');
  }
  if (btn) btn.hidden = true;
}

// Inline onclick handlers need these on window — app.js is a module, so
// function declarations alone are not global (see the block above at ~19501).
window.setConnTab = setConnTab;
window.renderMagellanAccounts = renderMagellanAccounts;
window.setMagellanFilter = setMagellanFilter;
window.magellanSelectAllVisible = magellanSelectAllVisible;
window.magellanDeselectAll = magellanDeselectAll;
window.startMagellanCollect = startMagellanCollect;
window.previewMagellan = previewMagellan;
window.importMagellan = importMagellan;
window.toggleMagellanLog = toggleMagellanLog;
window.stopMagellanCollect = stopMagellanCollect;

// ── Sidebar campaign name (Ortus Basics 1.0) ────────────────────────────────
// The sidebar no longer navigates; it names the campaign being looked at.
// #campaign-name-input is written from several paths (launch, preset load,
// duplicate, restore) and a programmatic .value assignment fires no input
// event, so mirror on an interval as well as on typing. Reading one input is
// far cheaper than trying to patch every writer.
function syncSidebarCampaignName() {
  const out = document.getElementById('sidebar-campaign-name');
  if (!out) return;
  const raw = (document.getElementById('campaign-name-input')?.value || '').trim();
  const text = raw || 'Untitled campaign';
  if (out.textContent !== text) out.textContent = text;
  out.classList.toggle('is-empty', !raw);
}
if (typeof window !== 'undefined') {
  window.syncSidebarCampaignName = syncSidebarCampaignName;
  document.getElementById('campaign-name-input')?.addEventListener('input', syncSidebarCampaignName);
  syncSidebarCampaignName();
  setInterval(syncSidebarCampaignName, 700);
}

// ── Wizard state persistence (Ortus Basics 1.0) ─────────────────────────────
// The sheet URL and the picked GoLogin accounts were the two things the wizard
// never remembered: nothing wrote a value back into #sheet-url, and
// startNewCampaign() clears selectedProfileIds outright. Local campaigns also
// never got a launch-config snapshot — saveCloudLaunchConfig() is only called
// from the cloud dispatch path — so "open a campaign" had nothing to restore
// from either. Keep our own copy, written on Save and on Start.
const _WIZ_KEY = 'ortus-basics-wizard';

function saveWizardState() {
  try {
    if (typeof collectCurrentConfig !== 'function') return;
    localStorage.setItem(_WIZ_KEY, JSON.stringify({ at: Date.now(), config: collectCurrentConfig() }));
  } catch (_) { /* storage blocked — persistence is best-effort */ }
}

function restoreWizardState() {
  try {
    const raw = localStorage.getItem(_WIZ_KEY);
    if (!raw) return false;
    const saved = JSON.parse(raw);
    if (!saved?.config) return false;
    // Only fill what the operator has not already typed: a restore must never
    // overwrite a sheet URL or a selection made in this session.
    const urlEl = document.getElementById('sheet-url');
    const hasUrl = !!(urlEl && urlEl.value.trim());
    const hasAccounts = Array.isArray(selectedProfileIds) && selectedProfileIds.length > 0;
    if (hasUrl && hasAccounts) return false;
    const cfg = { ...saved.config };
    if (hasUrl) delete cfg.sheetUrl;
    if (hasAccounts) { delete cfg.profileIds; delete cfg.profileNames; }
    if (typeof applyPresetConfig === 'function') applyPresetConfig(cfg);
    return true;
  } catch (_) { return false; }
}

if (typeof window !== 'undefined') {
  window.saveWizardState = saveWizardState;
  window.restoreWizardState = restoreWizardState;

  // Save on the two moments the operator expects to be a commit point.
  for (const fn of ['launchSaveAsDraft', 'launchSaveChanges', 'launchStartNow', 'launchQueueIt', 'launchScheduleIt']) {
    const orig = window[fn];
    if (typeof orig !== 'function') continue;
    window[fn] = function(...args) {
      try { saveWizardState(); } catch (_) { /* */ }
      return orig.apply(this, args);
    };
  }

  // Restore once the profile grid exists, so the tiles can paint as selected.
  setTimeout(() => { try { restoreWizardState(); } catch (_) { /* */ } }, 1500);
}

// ── Run check now, from the Launch panel (Ortus Basics 1.0) ─────────────────
// Operator ask: on Connect + Introduce Back the acceptance check had to be
// reached through a running campaign, so checking meant starting a send you did
// not want. This drives the same sweep the live card's ⚡ Check now uses
// (/api/bulk-check-now — opens each selected account, reads who accepted, and
// fires any due introductions), but takes its inputs from the WIZARD instead of
// a running campaign's status.
function refreshLaunchCheckBtn() {
  const btn = document.getElementById('btn-launch-check');
  if (!btn) return;
  const mode = document.getElementById('campaign-mode')?.value || '';
  btn.hidden = mode !== 'connect_and_introduce';
}
if (typeof window !== 'undefined') window.refreshLaunchCheckBtn = refreshLaunchCheckBtn;

// The scope question is the SAME modal the live-card check uses
// (#solo-check-modal → runSoloCheck('campaign'|'sheet')), driven through the
// same _soloCheckHandler slot, so the two checks ask identically rather than
// having a lookalike of their own.
window.launchCheckNow = function() {
  const toast = (m) => { if (typeof showCampaignToast === 'function') showCampaignToast(m); };
  const sheetUrl = (document.getElementById('sheet-url')?.value || '').trim();
  if (!sheetUrl) return toast('Paste the Google Sheet URL first.');
  _soloCheckHandler = (scope) => _launchCheckRun(scope);
  _showSoloCheckModal();
};

async function _launchCheckRun(scope) {
  if (_launchCheckPending) return;
  const btn = document.getElementById('btn-launch-check');
  const toast = (m) => { if (typeof showCampaignToast === 'function') showCampaignToast(m); };
  const sheetUrl = (document.getElementById('sheet-url')?.value || '').trim();
  if (!sheetUrl) return toast('Paste the Google Sheet URL first.');

  const body = {
    sheetUrl,
    linkedinColumn: document.getElementById('linkedin-col-select')?.value || '',
    primaryName: (document.getElementById('primary-person-name')?.value || '').trim(),
    primaryUrl: (document.getElementById('primary-person-url')?.value || '').trim(),
    primaryIntroBody: document.getElementById('primary-intro-body')?.value || '',
    introTitle: document.getElementById('intro-title')?.value || '',
    // Ortus Basics 1.0: automatic acceptance is removed, so a check never asks
    // the primary to accept anything.
    autoAcceptPrimary: false,
  };
  if (scope === 'sheet') {
    // Server derives the account set from this tab's Sender column.
    body.allSenders = true;
  } else {
    if (!selectedProfileIds || !selectedProfileIds.length) return toast('Pick at least one account first.');
    body.profileIds = [...selectedProfileIds];
  }

  const prev = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
  toast(scope === 'sheet'
    ? 'Checking all senders in this tab…'
    : `Checking ${body.profileIds.length} account(s)…`);
  _launchCheckPending = true;
  startPolling();
  try {
    const r = await fetch('/api/bulk-check-now', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const d = await r.json().catch(() => ({}));
    if (r.status === 409) toast(d.error || 'A check is already running.');
    else if (d.ok) {
      const res = d.result || {};
      toast(`Check done — ${res.matched || 0} newly accepted, ${res.introduced || 0} introduced.`);
    } else toast('Check failed: ' + (d.error || `HTTP ${r.status}`));
  } catch (e) {
    toast('Check failed: ' + e.message);
  } finally {
    _launchCheckPending = false;
    // Fetch terminal lines even if the stopped campaign normally stops polling.
    await pollStatus();
    if (btn) { btn.disabled = false; btn.textContent = prev || '⚡ Run check now'; }
  }
}

// Keep it in step with the mode picker, and paint the right state on load.
if (typeof window !== 'undefined') {
  document.getElementById('campaign-mode')?.addEventListener('change', refreshLaunchCheckBtn);
  setTimeout(refreshLaunchCheckBtn, 800);
  // renderModeSelector() sets #campaign-mode.value programmatically, which fires
  // no change event, so a listener alone goes stale. Re-checking one select is
  // cheap — same approach as the sidebar campaign name.
  setInterval(refreshLaunchCheckBtn, 700);
}

// ── Settings: GoLogin workspace tokens (Ortus Basics 1.0) ──────────────────
// The app ships with no secrets, so this is where a fresh install becomes
// usable. Which workspaces an operator can drive follows entirely from which
// tokens they paste: GL_ACCOUNTS gates each workspace on its env var, so an
// absent Linked Velocity token means those accounts are simply not offered.
let _credOthers = [];
async function renderCredentialsModal() {
  const wrap = document.getElementById('cred-fields');
  if (!wrap) return;
  wrap.innerHTML = '<div class="cred-loading">Loading…</div>';
  let creds = [];
  try {
    const r = await fetch('/api/credentials');
    const d = await r.json();
    creds = d.credentials || [];
    _credOthers = d.others || [];
  } catch (e) {
    wrap.innerHTML = `<div class="cred-msg is-bad">Could not read settings: ${escHtml(e.message)}</div>`;
    return;
  }
  wrap.innerHTML = creds.map((c) => {
    const state = c.set
      ? `<span class="cred-state is-set">set · ${escHtml(c.hint)}</span>`
      : `<span class="cred-state is-unset">${c.required ? 'required' : 'not set'}</span>`;
    const envNote = c.fromEnvironment
      ? '<div class="cred-note">Currently supplied by the environment (dev launcher). Saving here overrides it.</div>'
      : '';
    return `<div class="cred-row">
      <label class="cred-label" for="cred-${escHtml(c.id)}">${escHtml(c.label)} ${state}</label>
      <input type="password" class="cred-input" id="cred-${escHtml(c.id)}"
             data-env="${escHtml(c.env)}" autocomplete="off" spellcheck="false"
             placeholder="${c.set ? 'Leave blank to keep the saved token' : 'Paste the GoLogin API token'}">
      ${envNote}
    </div>`;
  }).join('');

  // ── Other workspaces ────────────────────────────────────────────────────
  // Any GoLogin workspace this codebase does not know by name. A token pasted
  // here becomes a selectable workspace with no domain gate and no mode
  // restriction — the rule for this build is "a token you hold is a workspace
  // you can drive". Saved rows show only the last four characters.
  const rows = _credOthers.map((o) => `<div class="cred-other-row" data-id="${escHtml(o.id)}">
      <span class="cred-other-name">${escHtml(o.label)}</span>
      <span class="cred-state is-set">${escHtml(o.hint)}</span>
      <button type="button" class="cred-other-del" title="Remove this workspace" onclick="removeCredOther('${escHtml(o.id)}')">Remove</button>
    </div>`).join('');
  wrap.insertAdjacentHTML('beforeend', `
    <div class="cred-other">
      <div class="cred-other-head">Other workspaces</div>
      <div class="cred-other-sub">Hold a token for a GoLogin workspace not listed above? Add it and its accounts appear in the picker.</div>
      ${rows || '<div class="cred-other-empty">None added.</div>'}
      <div class="cred-other-add">
        <input type="text" id="cred-other-label" class="cred-input" placeholder="Name (e.g. Client X)" autocomplete="off">
        <input type="password" id="cred-other-token" class="cred-input" placeholder="GoLogin API token" autocomplete="off" spellcheck="false">
        <button type="button" class="btn btn-secondary" onclick="addCredOther()">Add</button>
      </div>
    </div>`);
}

// The list is replaced wholesale on save, so both add and remove rebuild it
// from what is on screen plus the change being made. Saved tokens are never
// echoed to the browser, so an existing row is preserved by id, not by value.
async function _saveCredOthers(list) {
  const r = await fetch('/api/credentials', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ others: list }),
  });
  const d = await r.json().catch(() => ({}));
  if (!d.ok) throw new Error(d.error || `HTTP ${r.status}`);
  return d;
}

async function addCredOther() {
  const labelEl = document.getElementById('cred-other-label');
  const tokEl = document.getElementById('cred-other-token');
  const label = (labelEl?.value || '').trim();
  const token = (tokEl?.value || '').trim();
  const msg = document.getElementById('cred-msg');
  const show = (t, bad) => { if (msg) { msg.textContent = t; msg.className = 'cred-msg' + (bad ? ' is-bad' : ' is-ok'); msg.hidden = false; } };
  if (!token) return show('Paste the token for the new workspace.', true);
  try {
    // Existing rows must be re-sent with their tokens, which the browser does
    // not have — so ask the server to keep them by id.
    await _saveCredOthers([
      ..._credOthers.map((o) => ({ keep: o.id, label: o.label })),
      { label: label || 'Other', token },
    ]);
    if (labelEl) labelEl.value = ''; if (tokEl) tokEl.value = '';
    show('Workspace added.', false);
    await renderCredentialsModal();
    if (typeof loadProfiles === 'function') { try { await loadProfiles(); } catch (_) { /* */ } }
  } catch (e) { show('Could not add: ' + e.message, true); }
}

async function removeCredOther(id) {
  const msg = document.getElementById('cred-msg');
  try {
    await _saveCredOthers(_credOthers.filter((o) => o.id !== id).map((o) => ({ keep: o.id, label: o.label })));
    if (msg) { msg.textContent = 'Workspace removed.'; msg.className = 'cred-msg is-ok'; msg.hidden = false; }
    await renderCredentialsModal();
    if (typeof loadProfiles === 'function') { try { await loadProfiles(); } catch (_) { /* */ } }
  } catch (e) {
    if (msg) { msg.textContent = 'Could not remove: ' + e.message; msg.className = 'cred-msg is-bad'; msg.hidden = false; }
  }
}

function openCredentialsModal() {
  const m = document.getElementById('credentials-modal');
  if (!m) return;
  const msg = document.getElementById('cred-msg');
  if (msg) { msg.hidden = true; msg.textContent = ''; }
  m.classList.remove('hidden');
  renderCredentialsModal();
}
function closeCredentialsModal() {
  document.getElementById('credentials-modal')?.classList.add('hidden');
}

async function saveCredentialsFromModal() {
  const btn = document.getElementById('cred-save');
  const msg = document.getElementById('cred-msg');
  const show = (text, bad) => {
    if (!msg) return;
    msg.textContent = text;
    msg.className = 'cred-msg' + (bad ? ' is-bad' : ' is-ok');
    msg.hidden = false;
  };
  // Blank means "leave the saved token alone", so only send what was typed.
  const body = {};
  document.querySelectorAll('#cred-fields .cred-input').forEach((el) => {
    const v = (el.value || '').trim();
    if (v) body[el.dataset.env] = v;
  });
  if (!Object.keys(body).length) return show('Nothing to save — paste a token first.', true);

  const prev = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  try {
    const r = await fetch('/api/credentials', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const d = await r.json().catch(() => ({}));
    if (!d.ok) throw new Error(d.error || `HTTP ${r.status}`);
    show('Saved. Reloading the account list…', false);
    await renderCredentialsModal();
    // Tokens are read per call server-side, so the roster only needs re-reading.
    if (typeof loadProfiles === 'function') { try { await loadProfiles(); } catch (_) { /* */ } }
    if (typeof showCampaignToast === 'function') showCampaignToast('GoLogin tokens saved');
  } catch (e) {
    show('Could not save: ' + e.message, true);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = prev || 'Save tokens'; }
  }
}

if (typeof window !== 'undefined') {
  window.openCredentialsModal = openCredentialsModal;
  window.closeCredentialsModal = closeCredentialsModal;
  window.saveCredentialsFromModal = saveCredentialsFromModal;
  window.renderCredentialsModal = renderCredentialsModal;
  window.addCredOther = addCredOther;
  window.removeCredOther = removeCredOther;

  // A fresh install has no tokens and an empty picker explains nothing — open
  // Settings once, unprompted, so the first thing seen is the thing to do.
  setTimeout(async () => {
    try {
      const r = await fetch('/api/credentials');
      const d = await r.json();
      const ortus = (d.credentials || []).find((c) => c.id === 'ortus');
      if (ortus && !ortus.set) openCredentialsModal();
    } catch (_) { /* offline / early boot — Settings is still in the sidebar */ }
  }, 2000);
}

// ── Campaign settings by name (Ortus Basics 1.0) ───────────────────────────
// Two problems, one cause. Settings were stored against an engine campaign id,
// which local runs never had and which did not survive a restart — so reopening
// a campaign lost everything. They are now stored against the campaign's NAME,
// which is the operator's own key for it. That only works if names are unique,
// so a clash is refused outright rather than silently overwriting.
let _knownCampaignNames = [];

async function refreshKnownCampaignNames() {
  try {
    const r = await fetch('/api/campaign-configs');
    const d = await r.json();
    _knownCampaignNames = (d.configs || []).map((c) => String(c.name || '').trim().toLowerCase());
  } catch (_) { /* offline — uniqueness is re-checked server-side on save anyway */ }
  return _knownCampaignNames;
}

function closeDupeNameModal() {
  document.getElementById('dupe-name-modal')?.classList.add('hidden');
}
function _showDupeNameModal(name) {
  const el = document.getElementById('dupe-name-value');
  if (el) el.textContent = name;
  document.getElementById('dupe-name-modal')?.classList.remove('hidden');
}

/** The name currently being edited, if it is already taken by ANOTHER campaign. */
async function _nameIsTaken(name) {
  const key = String(name || '').trim().toLowerCase();
  if (!key) return false;
  // Editing an existing campaign keeps its own name — that is not a clash.
  if (typeof _editingExistingCampaign !== 'undefined' && _editingExistingCampaign
      && key === String(_openedCampaignName || '').trim().toLowerCase()) return false;
  await refreshKnownCampaignNames();
  return _knownCampaignNames.includes(key);
}

/** Write the wizard's settings against this campaign's name. */
async function saveCampaignConfigByName(name) {
  const n = String(name || '').trim();
  if (!n || typeof collectCurrentConfig !== 'function') return false;
  try {
    const r = await fetch('/api/campaign-configs', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: n, campaignId: _openedCampaignId, config: collectCurrentConfig() }),
    });
    const d = await r.json().catch(() => ({}));
    if (d.ok) { _openedCampaignId = d.saved.campaignId; _openedCampaignName = n; await refreshKnownCampaignNames(); }
    return !!d.ok;
  } catch (_) { return false; }
}

/** Put a saved campaign's settings back into the wizard. */
let _openedCampaignName = '';
let _openedCampaignId = null;
async function loadCampaignConfigByName(name, campaignId = null) {
  const n = String(name || '').trim();
  if (!n) return false;
  try {
    const r = await fetch(campaignId ? `/api/campaign-configs/by-id/${encodeURIComponent(campaignId)}` : `/api/campaign-configs/${encodeURIComponent(n)}`);
    if (!r.ok) return false;
    const d = await r.json();
    if (!d.ok || !d.config) return false;
    _openedCampaignId = d.campaignId || d.config.campaignId || null;
    _openedCampaignName = d.name || n;
    const nameEl = document.getElementById('campaign-name-input');
    if (nameEl) nameEl.value = _openedCampaignName;
    bindWizardTo(_openedCampaignName);
    if (typeof applyPresetConfig === 'function') applyPresetConfig(d.config);
    if (typeof showCampaignToast === 'function') showCampaignToast(`Loaded settings for "${_openedCampaignName}"`);
    return true;
  } catch (_) { return false; }
}

if (typeof window !== 'undefined') {
  window.closeDupeNameModal = closeDupeNameModal;
  window.saveCampaignConfigByName = saveCampaignConfigByName;
  window.loadCampaignConfigByName = loadCampaignConfigByName;
  window.refreshKnownCampaignNames = refreshKnownCampaignNames;

  // Gate every commit point: refuse a duplicate name, otherwise save the
  // settings under it. Wrapping rather than editing each handler keeps this in
  // one place, so a new launch path cannot quietly skip the check.
  for (const fn of ['launchStartNow', 'launchQueueIt', 'launchScheduleIt', 'launchSaveAsDraft', 'launchSaveChanges', 'launchSaveButton']) {
    const orig = window[fn];
    if (typeof orig !== 'function') continue;
    window[fn] = async function(...args) {
      const name = (document.getElementById('campaign-name-input')?.value || '').trim();
      // Renaming an OPEN campaign is a rename, not a new campaign. Because
      // settings are keyed by name, saving under a new name used to write a
      // second record and leave the first — so the campaign existed twice and
      // the dashboard, which reads its name from the run history, kept showing
      // the old one (operator, 2026-09-04). Move the campaign first, then save
      // the form onto the name it now has.
      const opened = String(_openedCampaignName || '').trim();
      if (name && opened && opened.toLowerCase() !== name.toLowerCase()) {
        try {
          const rr = await fetch('/api/campaign-configs/rename', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ from: opened, to: name, campaignId: _openedCampaignId }),
          });
          if (rr.ok) {
            _openedCampaignName = name;
            if (typeof bindWizardTo === 'function') bindWizardTo(name);
            await refreshKnownCampaignNames();
          } else if (rr.status === 409) {
            // Another campaign already owns that name. Say so and stop, rather
            // than silently creating a duplicate under it.
            const j = await rr.json().catch(() => ({}));
            if (typeof showCampaignToast === 'function') {
              showCampaignToast(j.error || `A campaign named "${name}" already exists.`, 6000);
            }
            return;
          }
        } catch (err) {
          console.warn('[rename] failed:', err);
        }
      }
      // The name IS the campaign's identity, so saving or starting under an
      // existing name UPDATES that campaign — which is what Save means.
      if (name) {
        if (!await saveCampaignConfigByName(name)) { showCampaignToast('Could not save this campaign. Please retry.'); return; }
        // saveCampaignConfigByName adds the name to _knownCampaignNames.
        // Mark as "editing own campaign" so the inline dedup check in the
        // original function recognises this name as its own, not a clash.
        _editingExistingCampaign = true;
      }
      return orig.apply(this, args);
    };
  }

  refreshKnownCampaignNames();
}

// Every path that opens a campaign — dashboard OPEN, re-run, duplicate, draft,
// queue entry — ends up in applyPresetConfig. Wrapping it once means none of
// them can miss the name-keyed fallback. A function declaration's binding is
// mutable, so this reassignment rebinds all existing callers too.
{
  const _origApplyPresetConfig = applyPresetConfig;
  let _restoring = false;                    // loadCampaignConfigByName calls back in
  applyPresetConfig = function(config) {
    if (config?.campaignId) _openedCampaignId = config.campaignId;
    const out = _origApplyPresetConfig.call(this, config);
    // Every path that opens a campaign lands here, so this is where the wizard
    // learns which campaign it is now editing. Without it the binding would
    // still describe the campaign opened before this one, and the autosave
    // would write this form into that one's record.
    bindWizardTo(_currentWizardName());
    if (_restoring) return out;
    // A snapshot that carries no sheet URL is an empty one — the old id-keyed
    // store had nothing for local campaigns. Fall back to the settings saved
    // against this campaign's name.
    const hasSheet = !!(config && String(config.sheetUrl || '').trim());
    const name = (document.getElementById('campaign-name-input')?.value || '').trim();
    if (!hasSheet && name) {
      _restoring = true;
      Promise.resolve(loadCampaignConfigByName(name, config?.campaignId || _openedCampaignId))
        .catch(() => {})
        .finally(() => { _restoring = false; });
    } else if (name) {
      _openedCampaignName = name;            // opened by its own snapshot
    }
    return out;
  };
}

// Typing (or restoring) a campaign name that has saved settings should fill the
// wizard in. Without this the settings existed but nothing ever asked for them:
// the only trigger was applyPresetConfig, which a fresh wizard never calls.
if (typeof window !== 'undefined') {
  const _nameEl = document.getElementById('campaign-name-input');
  const _maybeLoadByName = async () => {
    const name = (_nameEl?.value || '').trim();
    if (!name) return;
    if (String(_openedCampaignName || '').trim().toLowerCase() === name.toLowerCase()) return;
    // Never overwrite work in progress — only fill a wizard with no sheet yet.
    const sheet = (document.getElementById('sheet-url')?.value || '').trim();
    if (sheet) return;
    await loadCampaignConfigByName(name);
  };
  _nameEl?.addEventListener('change', _maybeLoadByName);
  _nameEl?.addEventListener('blur', _maybeLoadByName);
  // And once on load, for a name restored from a draft or the last session.
  setTimeout(_maybeLoadByName, 2500);
}
